The following result due to van der Kallen, cf. \cite[Lemma 3.22]{van1983group} shows that the row vector obtained by adding a constant multiple of the $i$-th coordinate, $i \geq 2$ to any other coordinate can also be obtained by a sequence of relative elementary operations. 
\begin{lemma}\label{VK}
	Let $I$ be an ideal of a ring $R$ and $\v \in \Um_n(R, I), n \geq 2$. If $i \geq 2$, then for any $r \in R$
	\[\v \sim_{\E_n(R, I)} \v e_{ij}(r) .\]
\end{lemma}


The following result is well-known. In the absence of an appropriate reference, we include a proof for completeness.
\begin{lemma}\label{pnil}
	Let $P$ be a projective $R$-module of rank $r \geq 2$ and $p \in \Um(P)$. Assume that overline denotes the quotient modulo $Nil(R)$. Then we have $\Um(R \oplus P, I)= e_1 \ET(R \oplus P, I)$  if and only if $\Um({\overline{R}} \oplus \overline{P},\overline{I})= e_1\ET(\overline{R}\oplus \overline{P}, \overline {I})$.
\end{lemma}

\begin{proof}
	The "only if" part is straightforward. For the "if" part, we choose $(a,p)\in \Um(R\oplus P,I)$ such that $(\overline{a},\overline{p}) \sim_{\ET(\overline R \oplus \overline P, \overline I)} (1,0)$. By lifting elementary operations, we get 
	$(a,p) \sim_{\ET(R \oplus P, I )}(1+n, p')$ where $n \in J$ and $p' \in JP$ for $J = I\cap Nil(R)$. Clearly $(1+n, p') \sim_{\ET(R \oplus P,  I)} (1+n,0)$ since $(1 + n)$ is a unit. It remains to show that $(1+n,0)\sim_{\ET(R \oplus P, I)}(1,0)$.


	Let $v(T)=(1+nT,0)\in \Um(R[T]\oplus P[T], JR[T])$. We show that $v(T) \sim_{\ET(R \oplus P, I)} v(0)$. Due to the local-global principle for transvection groups, cf. \cite[Theorem 4.8]{chattopadhyay2015equality}, it is enough to assume that $R$ is local and $P$ is free. In this case $v(T)\in \Um_{r + 1}(R[T], JR[T])$. We reduce $v(T)$ to $v(0)$ by a sequence of elementary operations as below. (We set forth the case when $r = 2$ for clarity)
	\begin{align*}
		v(T) \xrightarrow{C_2' = C_2 + nT(1 + nT)^{-1}C_1} (1 + nT, nT, 0) \xrightarrow{C_1' = C_1 - C_2} (1, nT, 0) \xrightarrow{C_2' = C_2 - nTC_1} (1, 0, 0) = v(0)
	\end{align*}
	All operations above correspond to an $\E_3(R[T], JR[T])$-action. The correspondence for the
	middle operation follows from Lemma \ref{VK}. Therefore $v(T) \sim_{\ET(R \oplus P, I)} v(0)$. 

	Putting $T = 1$, we obtain $v(1) \sim_{\ET(R \oplus P, J )} (1, 0)$ and therefore the proof follows.
\end{proof}


The next result is well-known. One can prove this by using the fact that every finitely generated projective module is isomorphic to the image of an idempotent endomorphism on a free module of finite rank.

\begin{lemma}\label{pidem}
	Let $A$ be a graded $R$-algebra, $P$ be a finitely generated projective module over $A$ of rank r and $p \in P$. 
	Then there exists a finitely generated graded $R$-subalgebra $A' \subset A$, a finitely generated projective module $P'$ over $A'$ of rank $r$ and an element $p' \in P'$ such that $P = P' \otimes_{A'} A$ and $p= 1 \otimes_{A'}p'$. If $\p \in \Um(P)$, we may further assume that  $p' \in \Um(P')$.
\end{lemma}

