\section  {Elementary completion of Unimodular rows over Graded rings}


In this section, we show that a unimodular row over a graded $R$-subalgebra $A$ of $R[t,1/t]$ can be completed to an elementary matrix. If $A = R[t]$ or $A = R[t, 1/t]$, the result is due to Suslin, cf. \cite[Theorem 7.2]{suslin1977structure}. We begin by proving a lemma which concerns the special case $A \subset R[t]$. The proof follows by using the local-global principle and the concept of generalized dimension functions. 

\begin{lemma}\label{T31}
	Let $R$ be a ring of dimension $d$ and  $A$ be a graded $R$-subalgebra of $R[t]$. Then $\Um_n(A) = e_1\E_n(A)$ for all $ n\geq \max \{3,d+2\}$. 
\end{lemma}

\begin{proof}
	We begin with the observation that $R/Nil(R) \hookrightarrow A/Nil(A)  \hookrightarrow  R/Nil(R)[t]$. We may assume that $R$ is reduced, see Lemma \ref{pnil}. Let $\v,\w \in \Um_n(A)$ such that $\v\w^t=1$. We show that $\v \in e_1\E_n(A)$. Replacing $A$ by the $R$-algebra generated by the homogeneous components of coordinates of $\v$ and $\w$, we may further assume that $A$ is Noetherian. Applying dimension inequality, cf. \cite[Theorem 15.5]{matsumura1989commutative} on different extensions $R / \p \hookrightarrow A/ A \cap \p R[t]$ where $\p$ is a minimal prime of $R$, we obtain  $\dim A \leq d + 1$. 


 If $\dim R = 0$, then $\dim A \leq 1$. It follows by Theorem \ref{bass} that $\v \sim_{\E_n(A)} e_1$.  
	Now we consider the case when $\dim R \geq 1$. Let $A_{+} = \oplus_{i \geq 1} A_i$ denote the irrelevant ideal of $A$. Since $A/ A_{+} = R$ and $n \geq \dim R  + 2$, the image $\overline{\v} \in \Um_n(R)$ of $\v$ modulo $A_{+}$ can be reduced to $e_1$ by applying elementary operations. Lifting these operations, we obtain $\v \sim_{\E_n(A)} \v'$ for some $\v' \in \E_n(A, A_{+})$.

	We need to show that  $\v' \sim_{\E_n(A)} e_1$. 
	Due to the local-global principle of graded rings, see Lemma \ref{lg},  it is enough to assume that $R$ is a local ring. Since $R$ is reduced and  $\dim R  \geq 1$, the maximal ideal contains a nonzero divisor $s$. We observe that  $\spec A =V(s)\sqcup D(s)$ where each of $V(s) = \{\p \in \spec A : s \in \p\}$ and $D(s) =  \{\p \in \spec A : s \not\in \p\}$ has dimension at most $d$, so $\spec A $ admits a generalized dimension function $\partial : \spec A \rightarrow \NN$ such that $\partial(\p) \leq d$ for all $\p \in \spec A$. Therefore, $\v' \sim_{\E_n(A)} e_1$ by \cite[Theorem A]{eisenbud1973generating}, \cite[p. 1420]{plumstead1983conjectures} and the result follows.
\end{proof}


\begin{lemma}\label{t31a}
	Let $R$ be a ring of dimension $d$,  $A$ be a graded $R$-subalgebra of $R[t]$ and $I = \oplus_{i \geq 1} I_i$ be a  homogeneous ideal of $A$. Then $\Um_n(A, I) = e_1\E_n(A, I)$ for all $ n\geq max \{3,d+2\}$. 
\end{lemma}
\begin{proof}
	Let $\v \in \Um_n(A, I)$. We get a $\w \in  \Um_n(A, I)$ such that $\v \w^t = 1$ by a result of Vaserstein, cf. \cite[Lemma 2]{vaserstein1969stabilization}. We consider the graded $R$-subalgebra $A' = R \oplus (\oplus_{i \geq 1} I_i) \subset R[t]$. We observe that $I \subset A'$ and both $\v, \w$ are row vectors in  $A'^n$, therefore $\v \in \Um_n(A', I)$. 

	By Lemma \ref{T31} there exists $\alpha \in \E_{n}(A')$ such that $\v = e_1 \alpha$. Comparing the images of both sides modulo $I$, we get $e_1 = e_1\overline{\alpha}$. Since $R = A' / I$ is a retract of $A'$, we have $\overline{\alpha} \in \E_{n}(R) \subset \E_{n}(A')$. Replacing $\alpha$ by $\overline{\alpha}^{-1}\alpha$, we obtain $\v = e_1 \alpha$ for $\alpha \in  \E_{n}(A') \cap  \SL_{n}(A', I)$. Since $R = A' / I$ is a retract of $A'$, we have $\E_{n}(A') \cap  \SL_{n}(A', I) = \E_{n}(A', I)$, cf. \cite[p. 204, Lemma 1.5]{lam2006serre}, so $\v \sim_{\E_n(A', I)} e_1$.
	The proof is completed here 
	since $\E_{n}(A', I) \subset \E_{n}(A, I)$.
\end{proof}

The following is a wide generalization of a result of Banerjee, cf. \cite[Lemma 4.4]{banerjee2024subrings}. It plays a vital role in the proof of Lemma \ref{mainid}.


\begin{lemma}\label{sb}
	Let $R \subset S$ be rings of dimension at most $d \geq 2$ and $x \in R$ be a nonzero divisor in $S$ such that $R_x = S_x$. Then the canonical map 
	\[\frac{\Um_{d + 1}(R, x^n)}{\E_{d + 1}(R, x^n)} \rightarrow \frac{\Um_{d + 1}(S, x^n)}{\E_{d + 1}(S, x^n)}\]
	is surjective for all $n \geq 0$.
\end{lemma}

\begin{proof}
	Let $\v = (v_1, \ldots, v_{d+1}) \in \Um_{d + 1} (S, x^n)$. We need to find $\alpha \in \E_{d + 1} (S, x^n)$ such that $$\v \alpha \in   {\Um}_{d + 1} (R, x^n).$$
	The proof falls into two cases.\\
	\noindent
	{\bf Case - 1} : ($n \geq 1$)\\
	Let $y = x^n \in R$ and $v_1 = 1 - sy$ for some $s\in S$. Note that $(v_1, \ldots, v_{d }, yv_{d+1}) \in \Um_{d + 1} (S, y)$. We choose $s_1, \ldots, s_{d} \in S$ such that $\Ht (v_1 + s_1yv_{d+1}, \ldots, v_{d} + s_{d}yv_{d+1}) \geq d$, cf. \cite[Chapter III, Lemma 3.4]{lam2006serre}.
	Therefore, right multiplying $\v$ by elementary matrices of type $e_{{d +1}\,j}(ys_j) \in \E_{d + 1}(S, y)$, $j = 1, \ldots, d$ we may assume that $ht(v_1, \ldots, v_d) \geq d$. Since $\dim S  \leq d$, two possibilities arise. If $\Ht (v_1, \ldots, v_d) \geq d + 1$, then $(v_1, \ldots, v_d)\in \Um_d(S, y)$. Consequently  $\v \alpha = e_1$ for some $\alpha \in \E_{d + 1} (S, y)$ and the result follows. 

	Therefore we assume that $ht(v_1, \ldots, v_d) = d$ which forces $\dim S = d$.
	Let $\n$ be a minimal prime ideal over $(v_1, \ldots, v_d)$. Then $ht(\n) = d$. Let $\m = \n \cap R$. Since $v_1 = 1 - sy \in \n$, we have $y \not\in \n$ and consequently $y \not\in \m$.

	By our given hypothesis, we have $R_y = S_y$ which implies that for any $s \in S$ there exists $n \in \NN$ such that $y^ns \in R$. We have the inclusion of local rings $R_{\m} \hookrightarrow  S_{\n}$. If $\frac{u}{v} \in S_{\n}$, then we may choose $n \in \NN$ large enough such that $y^nu, y^n v \in R$ and so $\frac{u}{v}  = \frac{y^nu}{y^nv} \in R_{\m}$. Therefore this inclusion is an isomorphism. It follows that $\Ht \m  = \dim R_{\m} = \dim S_{\n} = \Ht \n = d$. 
	%It follows that $\dim R \geq d$. 
	Since by our hypothesis $\dim R \leq d$, we must have $\dim R = d$. The ideal $(v_1, \ldots, v_d)$ is comaximal to $y$. By Lemma \ref{pbhat1}, we obtain $r \in R$ such that 
	\[1 - ry \in (v_1, \ldots, v_d).\]

	Let $v_1 = 1 - t_1y, v_2 = t_2y, \ldots, v_{d + 1} = t_{d + 1}y$ for some $t_1, \ldots t_{d + 1} \in S$.
	We choose $n \in \NN$ large enough such that $y^nt_i \in R$ for $i = 1, \ldots, d + 1$. We observe that $y(1 - ry) -  v_{d + 1}(1 - r^{n + 1}y^{n + 1})$ is divisible by $y(1 - ry)$. 
	Furthermore,
	$$y(1 - ry) - v_{d + 1}(1 - r^{n + 1}y^{n + 1}) = y( 1 - ry) - v_{d + 1}  + r^{n + 1}y^{n + 2}t_{d +1}= y - y^2(r - r^{ n + 1}y^n t_{d + 1}) - v_{d + 1} $$

	If we set $z = r - r^{ n + 1}y^n t_{d + 1}$, then $z \in R$ and $y - y^2z - v_{d + 1} \in (yv_1, \ldots, yv_d)$.
	Right multiplying $\v$ by elementary matrices of type $e_{i \ d + 1}(ys), i \geq 2, s \in S$, we obtain
	$$\v \sim_{\E_{d + 1}(S, y)} (v_1, v_2, \ldots, v_d, y - y^2z ) =(1 - t_1y, t_2y, \ldots, t_dy, y - y^2z ).$$
	%
	%
	%
	%
	%Now we rewrite $\v$ as $\v = (1 - t_1y, t_2y, \ldots, t_{d + 1}y)$ for some $t_1, \ldots t_{d + 1} \in S$. Let $y^nt_i \in R$ for $i = 1, \ldots, d + 1$. We observe that $(y - ry^2 +  t_{d + 1} r^ny^{n + 1}) - y t_{d + 1}  = y(1 - ry) - y t_{d + 1} (1 - r^ny^n)$ is divisible by $y(1 - ry)$. Let $z = r -  t_{d + 1} r^ny^{n -1}$, then $yz =  r -  t_{d + 1} r^ny^n \in R$ and 
	%$$y - y^2 z  - y t_{d + 1}  = (y - ry^2 +  t_{d + 1} r^ny^{n + 1}) - y t_{d + 1}  \in (y(1 - ry)) \subset (yv_1, \ldots, yv_d).$$ Let $y - y^2 z  - y t_{d + 1}  = u_1yv_1 + \ldots + u_dyv_d$ for $u_1, \ldots, u_d \in S$.
	%By elementary column operations of type $C'_{d + 1} = C_{d + 1} + yu_jC_j$ for $j = 1, \ldots, d$, we can reduce $\v$ to $(1 - t_1y, t_2y, \ldots, t_dy, y - y^2z )$. This implies that 
	%$$\v \sim_{\E_{d + 1}(S, y)} (1 - t_1y, t_2y, \ldots, t_dy, y - y^2z ).$$
