	One observes that $t_jy - t_jy^{n+1}z^n = yt_j(1 - y^nz^n)$ is divisible by $y - y^2z$. Therefore, by column operations of type  $C_j' = C_j + sC_{d + 1}, s \in S, j = 1, \ldots ,d$, we may reduce $(1 - t_1y, t_2y, \ldots, t_dy, y - y^2z )$ to
	$(1 - t_1y^{n + 1}z^n, t_2y^{n + 1}z^n, \ldots, t_dy^{n + 1}z^n, y - y^2z )$. By Lemma \ref{VK}, we obtain
	\[ (1 - t_1y, t_2y, \ldots, t_dy, y - y^2z ) \sim_{\E_{d + 1}(S, y)} (1 - t_1y^{n + 1}z^n, t_2y^{n + 1}z^n, \ldots, t_dy^{n + 1}z^n, y - y^2z ).\]
	The later row is in $ {\Um}_{d + 1} (R, y)$ since $y, z \in R$ and also $y^nt_i \in R$ for $i = 1, \ldots, n$. Hence the proof follows in this case.

	\noindent 
	{\bf Case - 2} : ($n = 0$)\\ 
	Here $\v \in \Um_{d + 1} (S)$. Since $x \in S$ is a nonzero divisor, we have $\dim S/ (x) \leq d - 1$. By Theorem \ref{bass}, the image $\overline{\v} \in \Um_{d + 1} (S/ (x))$ can be reduced to $e_1$ by elementary operations. By lifting these elementary operations, we obtain a $\alpha \in \E_{d + 1}(S)$ such that $\v \alpha \in  \Um_{d + 1} (S, (x))$. By Case - 1, we have a $\beta \in \E_{d + 1}(S, (x))$ such that $\v \alpha \beta \in \Um_{d + 1} (R, (x)) \subset \Um_{d + 1} (R)$. Therefore, the proof is completed here. 
\end{proof}

The next lemma serves a pivotal role in the proof of our main theorem.

\begin{lemma}\label{mainid}
	Let $R$ be an integral domain of dimension $d$, $A=\oplus_{n\in \Z}A_{n}t^{n}$  be a $\Z$-graded $R$-subalgebra of $R[t,1/t]$ and $I$ be an ideal of $A$ containing a homogeneous element. Then
	$${\Um}_n (A, I)=e_1\E_n(A, I)\quad \ \text{for all n} \ \geq \max\{3,d+2\}.$$
\end{lemma}

\begin{proof}

	As argued in Lemma \ref{T31}, we may assume that $A$ is Noetherian. 
	We may further assume that $R \subsetneq A$, $I \neq 0$ and $n = d + 2$  since otherwise, the result is obvious by Theorem \ref{bass}. 
	We choose a homogeneous element $x$ in $I$ of nonzero degree. Without loss of generality, we may assume that $\deg(x) > 0$. Let $A_{+} = \oplus_{n \geq 0}A_{n}t^{n}$. One  clearly observes that $A[1/ x] = A_{+}[1/ x]$. We also have that both $\dim A $ and $\dim A_{+} $ are at most $d + 1$.

	Let $\v \in {\Um}_{d+ 2} (A, I)$ and $\overline{\v} \in {\Um}_{d+2} (\overline{A},\overline{I})$ denote the image of $\v$ modulo $(x)$. Since $\dim A/ (x) \leq d$, we have $\overline{\v} \sim_{\E_{d+2} (\overline{A},\overline{I})} e_1$ by Theorem \ref{bass}. 
	Lifting elementary operations, we obtain $\v \sim_{\E_{d+2} (A, I)} \v'$ for some $\v' \in \Um_{d+ 2}(A, (x))$. By Lemma \ref{sb}, we have $\v' \sim _{\E_{d+ 2} (A, (x))} \v''$ for some $\v'' \in {\Um}_{d+2} (A_{+}, (x))$. The result follows since $\v'' \sim _{\E_{d+2} (A_{+}, (x))} e_1$ by Lemma \ref{t31a} and both $\E_{d+2} (A_{+}, (x))$, $\E_{d+2}(A,(x))$ are subset of $E_{d+ 2} (A, I)$.
\end{proof}

{Now we are in a position to prove the main result of this section.}
\begin{theorem}\label{main}
	Let $R$ be a ring {of dimension $d$}, $A=\oplus_{n\in \Z}A_{n}t^{n}$  be a $\Z$-graded $R$-subalgebra of $R[t,1/t]$ and $I$ be a homogeneous ideal {of $A$}. Then
	$${\Um}_n (A, I)=e_1\E_n(A, I) \ \text{for all n} \ \geq \max\{3,d+2\}.$$
\end{theorem}
\begin{proof}
	We may assume that the ring $R$ is reduced, see Lemma \ref{pnil}.
	We choose $\v \in {\Um}_n (A, I)$.  Let $\gamma(R)$ denote the number of minimal prime ideals of $R$. We prove the result by induction on $\gamma(R)$. For $\gamma(R) = 1$, the ring $R$ is a domain; therefore, the result follows by Lemma \ref{mainid}.

	%Let $\gamma(R) = 1$. In this case $R$ is a domain, so the result follows by Lemma \ref{mainid}.


	Now we assume $\gamma(R) = m > 1$. Let $\p_1,\p_2,\dots,\p_m$ be minimal prime ideals of $R$. Since $R$ is a reduced ring, we have $\p_1\cap \ldots \cap \p_m = 0$. Let $\mathcal{J} = \p_1 \cap \dots \cap \p_{m-1}$ and $J = A \cap \mathcal{J} R[t, 1/ t]$. We have the inclusion of rings 
	$$R/\mathcal{J}\hookrightarrow A/ J \hookrightarrow R/\mathcal{J} [t, 1/ t].$$ We observe that $\gamma(R/ \mathcal{J}) = m - 1$. Let overlines denote the image modulo $J$. By induction hypothesis, there is a $\overline{\alpha}_1 \in \E_n(\overline{A}, \overline{I})$ such that $\overline{\v}~ \overline{\alpha}_1 = e_1$. Let $\alpha_1 \in \E_n(A, I)$ be a lift of $\overline{\alpha}_1$ and  $\w = \v \alpha_1$. Then 
	$\w\in  \Um_n(A, I \cap J)$ and $\v \sim_{ \E_n(A, I)} \w$.

	Let \ $\widetilde{}$ \  denote the image modulo $\q_m = A \cap \p_m R[t, 1/ t]$. We have inclusion of rings $$R/ \p_m \hookrightarrow \widetilde{A}\hookrightarrow R/ \p_m [t, 1/ t].$$
	We consider the image $\widetilde{\w}$ of $\w$ in $\Um_n(\widetilde{A}, \widetilde{I \cap J})$. Since $R/ \p_m$ is a domain, we have $\widetilde{\w}  \sim_{\E_n(\widetilde{A}, \widetilde{I \cap J})} e_1$  by Lemma \ref{mainid}.

	Lifting the elementary operations, we have $\w \sim_{\E_n(A, I \cap J)} \w'$ where $\w' \in  \Um_n(A, I \cap J \cap \q_m)$. Now we observe that $ J \cap \q_m = 0$ since $\p_1 \cap \ldots \cap \p_m = 0$. Therefore $\w' = e_1$ and consequently $\w \sim_{\E_n(A, I \cap J)} e_1$. Hence $\v \sim_{ \E_n(A, I)} e_1$ and the proof follows.
\end{proof}
