\section{On transitive action of Elementary Transvection group $\ET(A \oplus P)$}
Let $R$ be a ring of dimension $d$. The aim of this section is to show that projective modules over graded $R$-subalgebras of $R[t, 1/t]$ of rank at least $d + 1$ have cancellation property and contain unimodular elements.

When one speaks of the cancellation property, the first question that comes to our mind is if the group of automorphisms on $A \oplus P$ acts transitively on $\Um(A \oplus P)$. 
We begin by proving the following preparatory lemma.

\begin{lemma} \label{L31}
	Let $k$ be a field and $A$ be a graded $k$-subalgebra of $k[t, 1/t]$ such that $t^m, t^{-n} \in A$ for some $ m, n \in \mathbb{N}$. Then $ A=k[t^l,t^{-l}]$ for some $l \in \NN$. 
\end{lemma}

\begin{proof} 
	We define $l=\min\{i\in \N \colon t^i\in A\}$ and $l^{\prime}=\min\{i\in \N \colon t^{-i}\in A\}$. Note that $t^{l}, t^{-l'}\in A$ and if $l^{\prime}<l $ then $t^{l-l^{\prime}} \in A$ which contradicts the minimality of $l$. So, $ l \leq l^{\prime}$ and similarly, by symmetry
	$ l^{\prime}\leq l$. Hence,  $l^{\prime}=l$ and $k[t^l, t^{-l}] \subseteq A$.

	Suppose $t^r \in A $ for some $r\in {\ZZ}$. By using the division algorithm, we have $r=lq+u$ such that either $u=0$ or $0<u<l$. If $u=0$ then $t^r \in k[t^l,t^{-l}]$ , otherwise for $0<u<l$, we have $t^u= t^{r-lq} \in A$ which is a contradiction to the minimality of $l$ . Therefore, $l$ divides $r$. Hence, $A \subseteq k[t^l, 1/t^l]$ and we are through.
\end{proof}

The method of proof of the next result is inspired by the work of Lindel and Wiemers, cf.  \cite[Theorem 2.6]{lindel1995unimodular}, \cite[Theorem 3.2]{wiemers1993cancellation}.  Their work also inspired \cite[Lemma 3.10]{dhorajia2010projective}.

\begin{lemma}\label{ord}
	Let  $R$ be an integral domain {of dimension $d$}, $A$ be a graded R-subalgebra of $R[t,1/t]$ and $I$ be an ideal of $A$ containing a homogeneous element. Let $P$ be a finitely generated projective $A$-module of rank  $r \geq \max\{d+1,2\}$. Then $\Um(A \oplus P, I)= e_1\ET(A \oplus P, I)$.
\end{lemma}
\begin{proof}

	We may assume that $A$ is Noetherian due to Lemma \ref{pidem}.
	We may further assume that $R \subsetneq A$, $I \neq 0$ and $r = d + 1$  since otherwise the result is obvious by Theorem \ref{bass}. 
	Let $S = R \setminus \{0\}$ and $k =  {S^{-1}R}$ denote the field of fractions of $R$.
	Then $S^{-1}A$  is a graded subring of $k[t, 1/ t]$. We choose a homogeneous element $u \in I$ of nonzero degree. By Lemma \ref{L31}, the localization $S^{-1}A_u$ is a PID. Consequently, the projective module $S^{-1}P_u$ over $S^{-1}A_u$ is free. Therefore, we obtain an element $s \in S$ such that $P_{su}$ is free. By Lemma \ref{P1}, we have $p _1, p_2, \ldots, p_r \in P$ and $ \phi_1, \phi_2, \ldots, \phi_r \in P^* = \Hom(P, A)$ and $m \in \NN$ such that 

	\begin{itemize}
		\item[1.] $(\phi_i(p_j))_{r \times r} = diagonal ((su)^m, (su)^m, \ldots, (su)^m)$.

		\item[2.]  $(su)^mP \subset F$ and $(su)^mP^* \subset G$ with $F = \sum_{i = 1}^r Ap_i$ and $G = \sum _{i = 1}^r A\phi_i$.
	\end{itemize}
	For notational convenience, we set $v = (su)^m$. 

	Let $(a, p) \in \Um(A \oplus P, I)$.
	We note that $\dim A/ (v^9) \leq d$. We use overlines to denote the quotient modulo the ideal $(v^9)$. Now $(\overline{a}, \overline{p}) \sim_{\ET(\overline{A} \oplus \overline{P}, \overline{I})} (1, 0)$, see Theorem \ref{bass}. Lifting the elementary operations, we obtain $$(a, p) \sim_{\ET(A \oplus P, I)} (a', p')\ \text{ for some} \  (a', p') \in \Um(A \oplus P, (v^9)).$$
	%Since $v^9 \in I$, there is no loss of generality in assuming that $(a, p) \in \Um(A \oplus P, I)$ for $I = (v^9)$.

	Now $p' \in v^9 P \subset v^8 F$, so there are $a_1, \ldots, a_r \in (v^8)$ such that 
	$p' = a_1 p_1 + \ldots + a_r p_r.$
	Since $(a', p') \in \Um(A \oplus P, (v^9))$, there are $a'' \in A$ and $\psi \in P^*$ such that $a'a'' + \psi(p') = 1$. This implies $a'a'' + a_1 \psi(p_1) + \ldots + a_r \psi(p_r) = 1$. Therefore, $$\v = (a', a_1, \ldots, a_r) \in {\Um}_{r + 1}(A , (v^8)).$$
	By Theorem \ref{main}, there is a matrix $\alpha \in \E_{r + 1} (A, (v^8))$ such that $\v \alpha = e_1$.  	

	For any ideal $I$ of a ring $R$, one has  $\E_n(R, I^4) \subset \E_n(I^2), n \geq 3$, cf.\cite[Lemma 2.7.(b)]{vasersteinSuslin1976serre}. %\cite[Theorem 3]{nica2016true}. 
	Therefore, we have $\alpha \in \E_{r + 1} (A, (v^8)) \subset \E_{r + 1} (v^4A)$. Due to the  commutator relations : $e_{ij}(xy) = [e_{i1}(x), e_{1j}(y)]$ for $i, j \neq 1$, we have the decomposition
	\[\alpha = \tau_1 \tau_2 \cdots \tau_k,\]
	where each $\tau_l$ equals an elementary matrix of type either $e_{1j}(xv^2)$ or  $e_{i1}(yv^2)$ for $x, y \in A$. Now we construct a sequence of transvections $\tilde{\tau_1}, \ldots, \tilde{\tau_k} \in \ET(v(A \oplus P)) \subset \ET(A \oplus P, I)$ as follows :
	\begin{enumerate}
		\item 
		If $\tau_l$ is the matrix $e_{i1}(yv^2)$ , then $(b_0, b_1, \ldots, b_{r})\tau_l =  (b_0 + yv^2 b_{i- 1}, b_1, \ldots, b_{r})$. We define $\tilde{\tau_l}$ as the  transvection given by $(b_0, q ) \xrightarrow{\tilde{\tau_l}} (b_0 + yv \phi_{i - 1}(q), q).$ We observe that 
		$$\tilde{\tau_l}(b_0, b_1p_1 + \ldots + b_r p_r) = (b_0 + yv^2 b_{i - 1},  b_1p_1 + \ldots + b_r p_r).$$

		\item
		If $\tau_l$ is the matrix $e_{1j}(xv^2)$, then $(b_0, b_1, \ldots, b_{r})\tau_l =  (b_0, b_1, \ldots, b_{j - 1} + xv^2b_0, \ldots, b_{r})$. We define $\tilde{\tau_l}$ as the  transvection given by $(b_0, q ) \xrightarrow{\tilde{\tau_l}} (b_0, q + xv^2b_0 p_{j -1}).$ We observe that 
		$$\tilde{\tau_l}(b_0, b_1p_1 + \ldots + b_r p_r) = (b_0,  b_1p_1 + \ldots +  (b_{j - 1} + xv^2b_0)p_{j -1} + \ldots + b_r p_r).$$
	\end{enumerate}

	Since $\v \alpha = e_1$, one clearly observes that $\tilde{\tau_k} \circ \cdots \circ \tilde{\tau_1}  (a', p') = (1, 0)$ which implies 
	$$(a', p')\sim_{\ET(A \oplus P, I)} e_1.$$ Hence the proof is completed. 
\end{proof}

The theorem below can be proved by using Lemma \ref{ord} above and by induction on the number of minimal prime ideals following the method of the proof of Theorem \ref{main} verbatim. We skip the details.

\begin{theorem}{\label{43}}
	Let  $R$ be a ring {of dimension d}, $A$ be a graded R-subalgebra of $R[t,1/t]$ and $I$ be a homogeneous ideal of $A$. Let $P$ be a finitely generated projective $A$-module of rank  $r \geq \max\{d+1,2\}$. Then $\Um(A \oplus P, I)= e_1\ET(A \oplus P, I)$.
\end{theorem}

A projective module of rank $1$ over a ring is always cancellative, cf. \cite [Chapter I, Proposition 6.6]{lam2006serre}. The cancellation property of a projective module $P$ of rank at least $2$ over a ring $A$ ($Q \oplus A \cong P\oplus A$ $\implies$ $Q \cong P$) is tantamount to transitive action of  $\Aut(A\oplus P)$ on $\Um(A \oplus P)$, cf. \cite[Corollary 3.5]{BassH}. Therefore, the previous theorem yields the following:

\begin{corollary}\label{cancel}
	Let $R$ be a ring of dimension $d$ and $A$ be a graded $R$-subalgebra of $R[t,1/t]$. Let $P$ and $Q$ be projective $A$-modules of rank $r\geq d + 1$ satisfying $Q \oplus A \cong P\oplus A$. Then $Q \cong P$.  
\end{corollary}

We recall the definition of Isotopy subgroups, cf. \cite[\S2, 2.2]{bhatwadekar1982stability}.

\begin{definition}{\rm(Isotopy Subgroups)}
	Let $I$ be an ideal of a ring $R$ and  {$n\geq 2$}. We define 
	\[{\h}_n(R, I) = \{M \in \GL_n(R, I) : \text{there is an $\alpha(x) \in \GL_n(R[x], IxR[x])$ such that $\alpha(1) = M$}\}.\]
	It is easy to check that $\h_n(R, I)$ is a normal subgroup of $\GL_n(R, I)$. The group $\h_n(R, I)$ is called the isotopy subgroup of $\GL_n(R, I)$. If $I = R$, then $\h_n(R, I)$ is abbreviated as $\h_n(R)$. If $R$ is a reduced ring, then one easily observes $\h_n(R, I) \subset \SL_n(R, I)$.
\end{definition}	

We state some important facts about isotopy groups.
Let $I$ be an ideal of a ring $A$.
\begin{Fact}

	The group $\E_n(A, I)$ is a subgroup of $\h_n(A, I)$. Let $M \in \E_n(A, I)$. If $M = \prod_{l = 1}^m \gamma_l^{-1} e_{i_l j_l}(a_l) \gamma_l$  for  $\gamma_l \in \GL_n(A)$, $a_l \in I$, then we define $\alpha(x) = \prod_{l = 1}^m \gamma_l^{-1} e_{i_l j_l}(a_l x) \gamma_l$. Clearly, $\alpha(x) \in \SL_n(R[x], IxR[x])$ such that $\alpha(1) = M$, so $M \in \h_n(R, I)$.
\end{Fact}


\begin{Fact}\label{F1}

	If $A$ is a graded $k$-subalgebra of $k[t, 1/ t]$ where $k$ is a field, then $SL_n(A) = \h_n(A)$. Let $M \in \SL_n(A)$. We show that $M \in \h_n(A)$ considering several cases. 
	Suppose $A \subset k[t]$ and consider $M = (a_{ij}(t))_{n \times n}$ for $a_{ij}(t) \in k[t]$. We define $\alpha(x) = (a_{ij}(tx))_{n \times n} \in \SL_n(A[x])$. We have $\alpha(1) = M$ and $\alpha(0) \in \SL_n(k) = \E_n(k)$. We choose $\beta(x) \in \E_n(k[x])$ such that $\beta(1) = \alpha(0)$ and $\beta(0) = I_n$. Then $\gamma(x) = \alpha(x)[\beta(1 - x)]^{-1} \in \SL_n(A[x], (x))$ such that $\gamma(1) = M$. Therefore, $M \in \h_n(A)$. If $A \subset k[1/ t]$, then one  similarly shows that $M \in \h_n(A)$. If $A \not\subset k[t] \cup k[1 / t]$, then $A$ is a Euclidean domain by Lemma \ref{L31}. In this case we have $SL_n(A) = \E_n(A) = \h_n(A)$, so $M \in \h_n(A)$. Therefore, we get $\SL_n(A) \subset \h_n(A)$. Since the reverse inclusion is obvious, our claim follows.
\end{Fact}

\begin{Fact}\label{F2}
	If $R$ is an  Artinian ring and $A$ is a graded $R$-subalgebra of $R[t, 1/ t]$, then  $\SL_n(A) \subset \h_n(A)$. Let $M \in \SL_n(A)$. Let overline denote the quotient modulo the nil radical. 
	Note that $\overline{R} = R/ Nil(R)$ is a finite product of fields, so $\h_n(\overline{A}) = \SL_n(\overline{A})$ by the previous  fact. Therefore, we obtain $\overline{\alpha}(x) \in \SL_n(\overline{A}[x], (x))$ such that $\overline{\alpha}(1) = \overline{M}$. Since units modulo a nilpotent ideal can be lifted to units, we get $\alpha(x) \in \GL_n(A[x], (x))$ which is a preimage of $\overline{\alpha}(x)$. Then $P = \alpha(1) -  M$ is a matrix whose all entries are nilpotent. We observe that $\alpha(1) = M + P = M(I_n + N)$ where $N = M^{-1} P$ is a nilpotent matrix as all the entries of $N$ are nilpotent elements. We define $\beta(x) = \alpha(x) (I_n + x N)^{-1}$, then we have $\beta(x) \in \GL_n(A[x], (x))$ and $\beta(1) = M$. It follows that $M \in \h_n(A)$, consequently $SL_n(A) \subset \h_n(A)$.
\end{Fact}

