%We recall the definition of a retract map. A surjective homomorphism $f:R \rightarrow S$ is said to be a retract map if there exists a homomorphism $g: S \rightarrow R$ such that $f \circ g= Id_C.$
Before stating the next lemma, we set the following convention:
if $f : R \rightarrow S$ is a ring homomorphism, we denote the induced maps $R[x] \rightarrow S[x]$, $\sum_{i = 0}^na_ix^n \mapsto  \sum_{i = 0}^nf(a_i)x^n$;  $\Um_n(R) \rightarrow \Um_n(S)$, $(a_i)_{1 \times n} \mapsto (f(a_i))_{1 \times n}$ and $\GL_n(R) \rightarrow \GL_n(S)$, $(a_{ij})_{n \times n} \mapsto (f(a_{ij}))_{n \times n}$  all by $f$ for the sake of notational convenience.  


\begin{lemma}\label{F4}
	{If} $f: R \rightarrow R/I$ is a retract map, then ${\h}_n(R, I)= {\h}_n(R) \cap \SL_n(R,I)$.
\end{lemma}
\begin{proof}	
	We choose $g: R/I \rightarrow R$ such that $f \circ g = {Id_{R/I}}$.
	Let $\beta \in {\h}_n(R) \cap \SL_n(R,I)$. We choose $F(x) \in \GL_n(R[x], (x))$  such that $F(1) = \beta$. Let $\widetilde{F}(x) = F(x) [g \circ f(F(x))]^{-1}$. It is clear that $\widetilde{F}(x) \in \GL_n(R[x], (x))$. 
	We observe that $f(\widetilde{F}(x)) = I_n$, which implies  $\widetilde{F}(x) \in \GL_n(R[x], IR[x])$. Therefore, $\widetilde{F}(x) \in \GL_n(R[x], IxR[x])$. Note that
	$$\widetilde{F}(1) = F(1) [g \circ f(F(1))]^{-1} = \beta [g \circ f(\beta)]^{-1} = \beta [g(I_n)]^{-1}= \beta.$$ 
	Therefore, $\beta \in \h_n(R, I)$ and consequently ${\h}_n(R) \cap \SL_n(R,I) \subset {\h}_n(R, I)$. As the reverse inclusion is clear, the proof follows.
\end{proof}


\begin{lemma} \label{uni1}
	Let $I$ be an ideal of a ring $R$ such that the quotient map $f: R \rightarrow R/ I$ is a retract map.
	Assume $\Um_n(R)= e_1\h_n(R), n \geq 2$. If $\v_1, \v_2 \in \Um_n(R)$ are such that $\v_1 \equiv \v_2 \vpmod I$, then $\v_1 \sim_{\h_n(R, I)} \v_2$.
\end{lemma}

\begin{proof}
	We choose a ring homomorphism $g: R/I \rightarrow R$  such that $ f\circ g = Id_{R/I}$.
	Let $$\u = f(\v_1) = f(\v_2) \in {\Um}_n(R/ I)\ \text{and} \  \v = g(\u) \in  {\Um}_n(R).$$ 
	If we show that $\v_1 \sim_{\h_n(R, I)} \v$ and $\v_2 \sim_{\h_n(R, I)} \v$, then we are through. We only show that $\v_1 \sim_{\h_n(R, I)} \v$ as the other one follows similarly.

	Both  $\v, \v_1$ are in $\Um_n(R)$. By the given hypothesis, there is an $\alpha \in \h_n(R)$ such that $\v_1 = \v \alpha$. Applying $g \circ f$ on both sides, we get $\v = \v [g \circ f(\alpha)]$. 
	Let $\beta = [g \circ f(\alpha)]^{-1} \alpha$.
	We observe
	\[f(\beta) = f([g \circ f(\alpha)]^{-1} \alpha) = [f \circ g \circ f(\alpha)]^{-1} [f(\alpha)] = [f(\alpha)]^{-1} [f(\alpha)] = I_n.
	\]
	This implies $\beta \in \SL_n(R, I)$. Since $\alpha \in \h_n(R)$, we have $g \circ f(\alpha) \in \h_n(R)$. Consequently we obtain $\beta = [g \circ f(\alpha)]^{-1} \alpha \in \h_n(R) \cap \SL_n(R, I)$.
	By Lemma \ref{F4}, we have $\beta \in \h_n(R, I)$. An easy computation yields  $\v_1 = \v \beta$. This implies $\v_1 \sim_{\h_n(R, I)} \v$ and hence the proof is completed here.
\end{proof}




\begin{proposition}\label{uni2}
	Let $I$ be an ideal of a ring $R$ such that the quotient map $f: R \rightarrow R/ I$ is a retract map. Let $P$ be a projective $R$-module of rank $n \geq 2$. Assume $s \in R$ and $T$ is a multiplicatively closed subset of $R$ such that 
	\begin{enumerate}
		\item
		for any $t \in T$, we have $R=sR+tR$. 
		\item 
		the localization $P_{sT}$ is a free $R_{sT}$ module,
		\item
		$\Um_n(R_{sT})= e_1\h_n(R_{sT})$. 
	\end{enumerate}
	Then the natural map $\Um(P)\rightarrow \Um(P/IP)$ is surjective if both the natural maps $\Um(P)_s\rightarrow \Um(P/IP)_s$ and $\Um(P_{T})\rightarrow \Um(P_T/IP_T)$ are surjective.
\end{proposition}

\begin{proof}
	Let $\overline p \in \Um(P/IP)$ where $p \in P$. Consider the following patching diagram,
	$$\xymatrix{
		& P \ar[d] \ar[r]
		& P_s \ar[d] \\
		& P_{T} \ar[r] & P_{sT} }$$

	Under given hypothesis, we can find $q_1 \in \Um (P_s)$ and $q_2 \in  \Um (P_{T})$ such that $ q_{1} \equiv p_{s} \pmod{IP_{s}}$ and  $q_{2} \equiv p_{T}\pmod{IP_{T}}$. Note that 
	\[(q_1)_{T}, (q_2)_{s} \in \Um(P_{sT}) = {\Um}_n(R_{sT})\ \text{and} \ (q_1)_{T} \equiv (q_2)_{s} \equiv{p_{sT}} \vpmod {IP_{sT}}.\]
	By  Lemma \ref{uni1}, there exists $ \tau \in \h_{n}(R_{sT}, I)$ such that $\tau(q_1)_{T}= (q_{2})_{s}$.
	We know that $P_{T} = {\small \underset{t \in T}{\varinjlim}} P_t$. We may choose $t \in T$ such that 
	$q_2 \in  \Um (P_{t})$ satisfying  $q_{2} \equiv p_{t}\pmod{IP_{t}}$ and $ \tau \in \h_{n}(R_{st}, I)$ satisfying $\tau(q_1)_{t}= (q_{2})_{s}$. 




	Now $\tau = (\tau_2)_s (\tau_1)_ {t}$ for some $\tau_1 \in \Aut(P_{s}, IP_{s})$ and $\tau_2 \in \Aut(P_{t}, IP_{t})$, cf. \cite[\S 2]{plumstead1983conjectures}. Then we have $\tau_1(q_1)_t = \tau_2^{-1}(q_2)_s$. Patching these elements, we obtain $q \in \Um(P)$ such that $q_t = \tau_2^{-1}(q_2)$ and $q_s = \tau_1(q_1)$. We observe that $q_t \equiv q_2 \equiv p_t \vpmod I$ and $q_s \equiv q_1 \equiv p_s \vpmod I$. Hence $q \equiv p \vpmod I$ and the proof follows.
\end{proof}

If $ {A}$ is a Noetherian ring of dimension $1$ and $P$ is a projective ${A}$-module of rank $r$, then $P \cong {A}^{r - 1} \oplus \det P$, where $\det P = \wedge^r P$ , cf. \cite[Theorem 1]{serre1958modules}. This fact is crucial to our next result.

\begin{theorem}\label{uni3}
	Let $R$ be a ring of dimension $d$ and $A$ be a graded $R$-subalgebra of $R[t, 1/ t]$. Let $P$ be a projective $A$-module of rank $r \geq d + 1$ such that $\det P$ is extended from $R$.  
	Let $\phi: A \rightarrow R$ be an $R$-algebra homomorphism and $I= Ker(\phi)$. Then the natural map $\pi: \Um(P) \rightarrow \Um(P/IP)$ is surjective.\end{theorem}  

\begin{proof} 
	We may assume that $A$ is Noetherian due to Lemma \ref{pidem}.
	We begin with the observation that $\pi$ is surjective whenever $P$ is free.
	%since $\phi$ is a retract map. 
	We may assume that $R$ is reduced. If $\dim R = 0$, then $R$ is a product of fields and $\dim A \leq 1$. We have $P \cong \det P \oplus A^{r-1}$. Note that $\det P$ is a free $A$-module since it is extended from $R$. Therefore, $P$ is free and the result follows.

	We assume that $\dim R  \geq 1$ and $r \geq 2$. Let $S$ denote the set of nonzero divisors of $R$. We observe that $\dim S^{-1}R =0$ and $\det S^{-1}P$ is extended from $S^{-1}R$.
	By the argument in the last paragraph, $S^{-1}P$ is a free $S^{-1}A$ module.
	Since $P$ is finitely generated, we get $s \in S$ such that $P_s$ is a free $ A_s$-module, so the natural map $\Um(P_s) \rightarrow \Um(P_s/IP_s)$ is surjective.

	Let $T = 1 + sR$. Note that $\spec A_{T} = V(s) \sqcup D(s)$. Since $s$ is a nonzero divisor, we have  $\dim V(s) \leq d$. We observe $\dim R_{sT} \leq d - 1$ and ${R_{sT}} \subset A_{sT}  \subset R_{sT}[t, 1/ t]$, so $\dim D(s) \leq d$.

	Let $\overline p \in  \Um (P/IP)_T$, where $p \in P_T$. Then we have $a \in IA_T$ such that $(a, p) \in \Um(A_T \oplus P_T)$. By a standard argument using generalised dimension functions, cf.  \cite[Theorem A]{eisenbud1973generating}, \cite[p. 1420]{plumstead1983conjectures}, there exists $q \in P_T$ such that $p + aq \in \Um(P_T)$. We observe that $p + aq \equiv p  \vpmod {IP_T}$. Therefore, the natural map $\Um(P_{T})\rightarrow \Um(P_T/IP_{T})$ is a surjection. 

	Now $\dim A_{sT} \leq d \leq r - 1$. If $r \geq 3$, then we have  $\Um_r(A_{sT})=e_1 \E_r(A_{sT}) = e_1\h_r(A_{sT})$ by Theorem \ref{main}. If $r = 2$, then $d \leq 1$ and $\dim R_{sT} = 0$, therefore  $\Um_2(A_{sT}) = e_1\SL_2(A_{sT}) = e_1\h_2(A_{sT})$ by Fact \ref{F2}. Hence the result follows by Proposition \ref{uni2} as $\phi$ is a retract map.
\end{proof}


Any graded $R$-subalgebra $A$ of $R[t, 1/ t]$ admits an $R$-algebra homomorphism $\phi : A \rightarrow R$ given by  $t \mapsto 1$. 
%A graded $R$-subslgebra $A$ of $R[t, 1/ t]$ admits a retract map $\phi : A \rightarrow R$ obtained by restricting the $R$-algebra homomorphism $R[t, 1/ t] \rightarrow R$ defined by $t \mapsto 1$. 
Therefore, the next corollary follows from Theorem \ref{uni3} and \cite[Theorem 1]{serre1958modules}.

\begin{corollary}\label{eum}
	Let $R$ be a ring of dimension $d$ and $A$ be a graded $R$-subalgebra of $R[t, 1/ t]$. Let $P$ be a projective $A$-module of rank $r \geq d + 1$ such that its determinant is extended from $R$. Then $P$ has a unimodular element.
\end{corollary}


In conclusion, we state the following example due to Bhatwadekar et al., cf. \cite{bhatwadekar2017some}.
%which shows that answer to Question \ref{Q3} may be negative without the assumptions that $A$ is grarded or that $A$ is a subalgebra of $k[X_1^{\pm 1}, \ldots, X_m^{\pm1}]$.
%


\begin{example}\label{bhatex}
	Let $F = Z^3 - T^2 \in k[Z, T]$, then $\frac{k[Z, T]}{(F)} = k[W^2, W^3]$. Let $ \phi : k[X_1, Y, Z, T] \rightarrow k[X_1, \ldots, X_4]$ be a $k[X_1]$-algebra homomorphism defined by $\phi(Z) = X_2^2 - X_1X_3$, $\phi(T) = X_2^3 - X_1X_4$, $\phi(Y) = \frac{1}{X_1} F(\phi(Z), \phi(T)) = - 3X_2^4 X_3 + 3X_1X_2^2 X_3^2  - X_1^2 X_3^3  + 2X_2^3 X_4 - X_1X_4^2$. By \cite[Theorem 5.4]{bhatwadekar2017some}, $\phi$ induces an isomorphism between $A = \frac{k[X_1, Y, Z, T]}{(X_1Y - F)}$ and $B = k[X_1, \phi(Y), \phi(Z), \phi(T)]$. Let $\n = B \cap \m$ for $\m = (X_1,\ldots, X_4)$. Then $\mu(\n) = \mu(\overline{X_1}, \overline{Y}, \overline{Z}, \overline{T}) = 4$. 
	If $B$ were a graded subalgebra of $k[X_1, \ldots, X_4]$, $\deg(X_i) = 1$, we would have $B = k[X_1, X_2^2 - X_1X_3, X_1X_4,  X_2^3, X_1X_4^2,  X_2^3 X_4,  - 3X_2^4 X_3 + 3X_1X_2^2 X_3^2  - X_1^2 X_3^3]$ 
	which is absurd as $\mu(\n) = 7$ in this case. However $A$ is graded with $\deg(X_1) = \deg(Y) = \deg(T) = 3$ and $\deg(Z) = 2$.
	By \cite[Theorem 5.4]{bhatwadekar2017some},  $A (\cong B)$ is a UFD, $Pic(A) = Pic(B) = 0$ and $K_0(A)  = K_0(B) \not= \ZZ$. Therefore, both $A$ and $B$ admit non-free projective modules of trivial determinant.
\end{example}
