Notice that the passage to empirical bounds incurs an additional constant
factors only in the bound for the last term.
\subsection{Proofs}
\textbf{\textit{Sketch of proof}} (detailed in the supplementary file). As explained in Section \ref{sec:mixing_blocks} the method of blocks provides a tool to port bounds from the independent to the dependent case, so we first establish inequalities for independent data.

A concentration inequality of \citep[Theorem 3.8]{McDiarmid98} quite easily leads to the
following Bernstein-type inequality for independent, centered vectors $Y_{i}$
in Hilbert space, satisfying $\left\Vert Y_{i}-\mathbb{E}%
 [Y_{i}]\right\Vert \leq c$.%
\begin{equation}
\begin{aligned}
\Pr \biggl\{ \left\Vert \sum_{k}Y_{k}-\mathbb{E}\left[ Y_{k}\right]
\right\Vert >\sqrt{\sum_{k}\mathbb{E}\left\Vert Y_{k}-\mathbb{E}\left[ Y_{k}%
\right] \right\Vert ^{2}}\left(1+\sqrt{2\ln \left( 1/\delta \right) }%
\right) +\frac{4c}{3}\ln \left( 1/\delta \right) \biggl\} <\delta .
\end{aligned}
\label{template thm 1}
\end{equation}

The additional 1 in $1+\sqrt{2\ln{(\frac{1}{\delta})}}$ arises from a bound of the expected norm by the root of the variance. To obtain empirical bounds, we want to combine this with
estimates of the variance term. Without additional assumptions, we obtain
from a concentration inequality for real-valued functions that

\begin{equation*}
\begin{aligned}
\sqrt{\sum_{k}\mathbb{E}\left\Vert Y_{k}-\mathbb{E}\left[ Y_{k}\right]
\right\Vert ^{2}}&\leq \sqrt{\sum_{k}\left\Vert Y_{k}\right\Vert ^{2}}+c\sqrt{2\ln \left(
1/\delta \right) }.
\end{aligned}
\end{equation*}

Combining this with (\ref{template thm 1}) in a union bound gives, with probability at least $%
1-\delta $ 
\begin{equation*}
\begin{aligned}
\Pr \biggl\{ \left\Vert \sum_{k}Y_{k}-\mathbb{E}\left[ Y_{k}\right]
\right\Vert >\sqrt{\sum_{k}\left\Vert Y_{i}\right\Vert ^{2}}\left( 1+\sqrt{%
2\ln \left( 2/\delta \right) }\right) +\frac{16c}{3}\ln \left( 2/\delta
\right) \biggl\} <\delta .  \label{template thm 2}
\end{aligned}
\end{equation*}%
This is our independent template for Theorem 2.

To obtain Theorem 3, we can use stationarity of the process, which means that
the $Y_{k}$ (or the $Y_{k}^{\prime }$) can now be assumed to have identical
distribution. In this case, a slightly more involved argument gives the
estimate
\begin{equation*}
\begin{aligned}    
\sqrt{\sum_{k}\mathbb{E}\left\Vert Y_{k}-\mathbb{E}\left[ Y_{k}\right]
\right\Vert ^{2}}\leq \sqrt{\frac{1}{2\left( m-1\right) }\sum_{k,l:k\neq
l}\left\Vert Y_{k}-Y_{l}\right\Vert ^{2}}+4c\sqrt{2\ln \left( 1/\delta
\right) }.
\end{aligned}
\end{equation*}

Again, a union bound with (\ref{template thm 1}) gives the independent template for Theorem 3. 

Now we port these inequalities to the dependent case using Lemma \ref{lem:blocking}. For Theorem 1, we define
\begin{equation*}
\begin{aligned}
F\left( \mathbf{X}\right)  =\sqrt{\sum_{k=1}^{m}\mathbb{E}\left\Vert
Y_{k}-\mathbb{E}\left[ Y_{k}%
\right]\right\Vert ^{2}}\left( 1+\sqrt{2\ln \left( 2/\delta \right) }\right) +\frac{4\tau c}{3}\ln \left( 2/\delta \right)  
\end{aligned}
\end{equation*}
with $F^{\prime }\left( \mathbf{X}\right)$ defined analogously, replacing $\overline{Y}_{k}$ by $Y^\prime_k$. 
Substitution of these definitions in the body of Lemma \ref{lem:blocking} , using  (\ref{template thm 1}) to bound the two independent probabilities, 
some algebraic simplifications and reinsertion of the overall factor of $1/n=1/\left(
2m\tau \right) $\ give Theorem 1.

Above $F$ and $F^{\prime }$ were simply constant functions. This is
different for the empirical bounds, where they contain the variance
estimates. To obtain Theorem 2, we let  
\[
F\left( \mathbf{X}\right) =\sqrt{\sum_{k=1}^{m}\left\Vert Y_{k}\right\Vert
^{2}}\left( 1+\sqrt{2\ln \left( 4/\delta \right) }\right) +\frac{16c\tau}{3}\ln
\left( 4/\delta \right) ,
\]%
which is $\Sigma \left( I_{1}\cup ...\cup I_{m}\right) $-measurable, and
replace $Y_{k}$ by $Y_{k}^{\prime }$ for the analogous definition of $%
F^{\prime }\left( \mathbf{X}\right) $. Then, using Lemma \ref{lem:blocking} and (%
\ref{template thm 2}), unraveling the definitions, and some simplifications give Theorem 2. Similarly, 
\begin{equation*}
\begin{aligned}
F\left( \mathbf{X}\right) =\sqrt{\frac{1}{2\left( m{-}1\right) }\sum_{k,l:k\neq
l}\left\Vert Y_{k}-Y_{l}\right\Vert ^{2}}\left( 1{+}\sqrt{2\ln \left( 4/\delta
\right) }\right) +11c\tau\ln \left( 4/\delta \right),
\end{aligned}
\end{equation*}
and the corresponding $F^{\prime }\left( \mathbf{X}\right) $ give Theorem 3.

\section{Applications}
In this section, we address two important fields of study where our bound can lead to new advances. First, we note that the concentration inequality is naturally linked to covariance estimation, which plays an important role in machine learning and statistics \citep{markowitz1952portfolio,vonstorch1999principal,schäfer2005shrinkage, mollenhauer2022kernel}. 
The second application concerns data-driven dynamical systems and, in particular, transfer operators, which are also widely used in science and engineering~\cite[see e.g.][and references therein]{Brunton2022,tuckerman2023statistical}. 


%\subsection{Covariance estimation}
%\label{sec:cov_est}
{\bf Covariance estimation~}
We apply our results to the estimation of covariance operators on the Reproducing Kernel Hilbert Space (RKHS) $\RKHS$ with an associated kernel function $k:\X\times\X \to \R$. Letting $\phi:\X \to \RKHS$ be a {\em feature map} such that $k(x,x^\prime) {=} \scalarp{\phi(x), \phi(x^\prime)}$ for all $x, x^\prime \in \X$, we aim to bound the Hilbert-Schmidt norm  estimation error. Hence, in this setting, the observed vectors are operators, and to apply our bounds, one needs to replace $X_{t}$ by the rank-one operator $Y_t {=}\phi(X_{t})\otimes \phi(X_{t})$. Then, $\BECorrtau{Y}$ and $\UECorrtau{Y}$ can be easily computed by using entries of the kernel matrix.
%
If the process is not stationary,
we can only estimate the ergodic average of covariance operators, that is 
$\left( 1/n\right) \sum_{t}\mathbb{E}\left[  \phi(X_{t})\otimes
\phi(X_{t}) \right] $, which becomes $C{=}\mathbb{E}\left[
\phi(X_{1})\otimes \phi(X_{1}) \right] $ for stationary processes. 
The transcription of the previous results fortunately, is affected by simply replacing all
$\Cxy{=} 
% \EM{lim_{n\rightarrow \infty}}
\left( 1/n\right) \sum_{t}\mathbb{E}%
\left[  \phi(X_{t})\otimes \phi(X_{t+1}) \right] $ because the
inner products change; the block variables are then only separated by $\tau
-1$ instead of $\tau $, and we also need to observe one more point on the
trajectory.

To demonstrate the application of our empirical Bernstein's inequalities to estimate the covariance and the improvements it introduces, we first adapt Pinelis and Sakhanenko's concentration inequality for random variables in a separable Hilbert space (see \citep[][Proposition 2]{caponnetto2007}) to trajectory data, using the method of blocks and $\beta$-mixing, as it was suggested in \citep{kostic2023sharp}, see Appendix \ref{app:cov_est}
% C.1.
%\EM{We repeated the same process for the Theorem ?? . For seeing the proofs, please see the propositions in the Section C.1 in the supplementary file.}

Assuming that the data is sampled from the stationary distribution, our bounds in Theorems   \ref{thm:empirical-Bernstein-biased} and \ref{thm:empirical-Bernstein-unbiased} apply. Compared to worst-case bounds, the improvement lies in the correlation factors $\UECorrtau{X}$ and $\BECorrtau{X}$ 
in \eqref{eq:Ecorr} and \eqref{eq:BEcorr}, respectively, affecting the slow term in the bound. Before we illustrate this improvement empirically, we discuss a related application. 

%\subsection{Learning dynamical systems} % with transfer operators}
{\bf Learning dynamical systems~} 
Recent advances in the statistical theory for Koopman operator learning have highlighted the significant impact of covariance estimation on the ability to generalize when forecasting and interpreting dynamical systems from data-driven models~\citep{Kostic2022, Philipp2024}. While statistical learning theory has been thoroughly developed for kernel methods~\citep{kostic2023sharp,kostic2024consistent} under $\beta$-mixing assumptions, an important gap remains between the learning rates and generalization bounds, and the practical performance of the methods. This is particularly interesting when comparing recent deep learning advances with kernel methods~\citep{kostic2024dpnets}. Here, we briefly review the transfer operator learning and then present novel contributions to this field based on our EBI.

For a {\em time-homogeneous} Markov chain with an invariant (stationary) distribution $\im$ the (stochastic) \textit{Koopman operator} $\Koop \colon \Lii\to\Lii$  is given by \\
\(
%\begin{equation*}\label{eq:Koopman_app}
\mbox{ }\quad[\Koop f](x) {:=} \displaystyle{\int_{\X}} p(x, dy)f(y) {= }\mathbb{E}\left[f(X_{t {+} 1}) \middle | X_{t} = x\right],
%\end{equation*}
\)
where $\quad f\in\Lii,x\in\X$.

In many practical cases, $\Koop$ is unknown, but data from one or multiple system trajectories are available. A framework for operator regression learning was introduced in~\citep{Kostic2022} to estimate the Koopman operator on $\Lii$ within an RKHS using an associated feature map $\fH:\X \to \RKHS$. In this vector-valued regression, the risk functional is defined as %defined through the joint distribution $\rho(\dx,\dy) = p(dy\vert x) \pi(dx)$
\(
    \Risk(G) = \textstyle{\EE_{X\sim\pi,X^+\sim p(\cdot\vert X))} \norm{\phi(Y) - G^{*}\phi(X)}^{2}}_\RKHS,
\)
and the task is to learn $\Koop$ by minimizing the risk over some class of operators $G\colon{\RKHS\to\RKHS}$ using a dataset of consecutive states  $\Data := (x_{i}, x^+_{i})_{i = 1}^{n}$. Typical scenario is to obtain the states from a single trajectory of the process after reaching the equilibrium distribution, that is $X_0\sim \pi$, $X^+_i\equiv X_{i+1} \sim p(\cdot\,\vert\,X_i)$, $i=2,\ldots,n$, and the popular estimator in this setting is the Reduced Rank Regression (RRR) one $\ERRR$ obtained by minimizing regularized empirical risk \(
    {\ERisk}_\lambda(\Estim) := \textstyle{\tfrac{1}{n}\sum_{i \in[n]}} \norm{\phi(x^+_{i}) - \Estim^{*}\phi(x_i)}^{2}_{\RKHS} {+} \lambda\|\Estim\|^2_{\text{HS}},
\) over operators $\Estim$ of rank at most $r$, that is $\ERRR = \ECreg^{-1/2}\SVDr{\ECreg^{-1/2}\ECxy}$ is computed via $r$-truncated SVD $\SVDr{\cdot}$ and  {\em input} and {\em cross} empirical covariances $\ECx \,= \,\textstyle{\tfrac{1}{n}\sum_{i \in[n]}}\, \phi(x_{i}){\otimes} \phi(x_{i})$
and
$\ECxy\,= \,\textstyle{\tfrac{1}{n}\sum_{i \in[n]}}\, \phi(x_{i}){\otimes }\phi(x^+_{i})$, respectively, while
$\ECx_{\reg} = \ECx + \reg I_{\RKHS}$, c.f. \citep{Kostic2022,kostic2023sharp}.

The recent works \citep{Li2022, kostic2023sharp} on the mini-max optimal learning rate for Koopman operator regression in i.i.d. setting crucially rely on Pinelis and Sakhanenko's Inequality.  %\cite[][Prop. 15]{kostic2023sharp}. 
As observed above, applying the method of blocks and $\beta$-mixing extends the i.i.d. analysis of transfer operator regression to realistic scenarios of learning from data trajectories of a stationary process. However, the overall approach relies on several (in practice unverifiable) assumptions and results in an unfavorable impact of mixing on the learning rates.

In the following, we present a novel risk bound for the reduced-rank Tikhonov estimator that circumvents the need for regularity assumptions, in \citep{Li2022,kostic2023sharp,kostic2024consistent,kostic2024learning}.

\begin{restatable}{theorem}{TikhonovRiskBound}
\label{thm:tikhonov_risk_bound}
Let $\mathbf{X}=(X_{t})_{t=1}^{n}$ be a stationary Markov chain with distribution $\mu$, and the risk definitions as above noting that $\pi=\mu_{1}$. Denote $\EEstim_{r, \lambda}$ be a minimizer of reduced-rank Tikhonov regularized empirical risk
and $\mathbf{Y} = (\fH(X_{t})\otimes\fH(X_{t}))_{t=1}^{n}$, $\mathbf{Z} = (\fH(X_{t})\otimes\fH(X_{t+1}))_{t=1}^{n}$, and $\mathbf{W} = (\|\fH(X_{t})\|^2)_{t=1}^{n}$. Assume $n =2m\tau$, and exists $\bcon\,>\,0$  such that $\norm{\fH(X_t)}^2{\leq }\bcon$ a.s. for all $t$. Let $\delta {\geq} 0$ and assume $\widehat{\delta}_{\mu}(\tau,\lambda) := 0.5\,\delta/\|\EEstim_{r, \lambda}\|{-}2(\frac{n}{2\tau}{-}1)\beta _{\mu}(\tau) > 0$. \\
Then, with probability at least $1 {-} \delta$ we have for every $\EEstim_{r, \lambda}$ such that $\|\EEstim_{r, \lambda}\|_{HS} {\geq} 1$
\begin{equation*}\label{eq:tikhonov_bound}
\begin{aligned}
|\Risk(\EEstim_{r, \lambda}){-}\ERisk(\EEstim_{r, \lambda})| &{\leq }
\frac{128\bcon\tau\|\EEstim_{r, \lambda}\|(\sqrt{r}{+} \|\EEstim_{r, \lambda}\|)}{3n}\ln{\frac{12}{\widehat{\delta}_{\mu}(\tau,\lambda)}}{+}\frac{14\bcon\tau^2
%7\bcon\tau
}{3n-2\tau
%(\frac{n}{2\tau}-1)
}\ln{\frac{12}{\widehat{\delta}_{\mu}(\tau,\lambda)}} \\
&{+} \sqrt{\frac{32\|\EEstim_{r, \lambda}\|^4\BECorrtau{Y}\tau}{n}\left(1
{+}2\ln\frac{12}{\widehat{\delta}_{\mu}(\tau,\lambda)}\right)} 
{+} \sqrt{\frac{2\overline{V}_{\tau}(\mathbf{W})\tau}{n}\ln{\frac{12}{\widehat{\delta}_{\mu}(\tau,\lambda)}}}
\\
&{+} \sqrt{\frac{8r\|\EEstim_{r, \lambda}\|^2\BECorrtau{Z}\tau}{n}\left(1{+}2\ln\frac{12}{\widehat{\delta}_{\mu}(\tau,\lambda)}\right)} ,
\end{aligned}
\end{equation*}

where $\overline{V}_{\tau}(\mathbf{W}) = \frac{1}{m(m-1)\tau^2} \sum_{1\leq i< j\leq m} (\overline{W}_{i} - \overline{W}_{j})^2 + (\overline{W'}_{i} - \overline{W'}_{j})^2$, $\overline{W}_{j}=\sum_{i\in I_{j}}W_i$ and $\overline{W'}_{j}=\sum_{i\in I_{j}^{\prime }}W_i$. $\BECorrtau{\mathbf{Y}}$ and $\BECorrtau{\mathbf{Z}}$ were defined before.

\end{restatable}

