\left[ \left( f\left( S_{X_{k}}^{k}\mathbf{x}\right) {-}f\left(
S_{X_{k}^{\prime }}^{k}\mathbf{x}\right) \right) ^{2}\right] \leq \frac{1}{2}%
\sum_{k=1}^{m}\mathbb{E}\left[ \left\Vert X_{k}{-}X_{k}^{\prime }\right\Vert
^{2}\right] =\sum_{i=1}^{m}\mathbb{E}\left\Vert X_{i}\right\Vert ^{2}.
\end{equation*}%
By Bernstein's inequality, Theorem \ref{thm:Bernstein-inequality}, for $%
t>0$,%
\begin{equation*}
\Pr \left\{ \left\Vert \sum_{i}X_{i}\right\Vert {-}\mathbb{E}\left[ \left\Vert
\sum_{i}X_{i}\right\Vert \right] >t\right\} \leq \exp \left( \frac{-t^{2}}{%
2\sum_{i}\mathbb{E}\left\Vert X_{i}\right\Vert ^{2}{+}4ct/3}\right) .
\end{equation*}%
Solving for $t$ gives for $\delta >0$%
\begin{equation*}
\Pr \left\{ \left\Vert \sum_{i}X_{i}\right\Vert \leq \mathbb{E}\left[
\left\Vert \sum_{i}X_{i}\right\Vert \right] {+}\sqrt{2\sum_{i}\mathbb{E}%
\left\Vert X_{i}\right\Vert ^{2}\ln \left( 1/\delta \right) }{+}\frac{4c}{3}%
\ln \left( 1/\delta \right) \right\} \leq \delta \text{.}
\end{equation*}%
Using Jensen's inequality, independence, and the mean-zero assumption to
bound $\mathbb{E}\left[ \left\Vert \sum_{i}X_{i}\right\Vert \right] \leq 
\sqrt{\sum_{i}\mathbb{E}\left\Vert X_{i}\right\Vert ^{2}}$ completes the
proof.
\end{proof}

\subsection{Empirical bounds}\label{app:emp_bounds}

If we drop the mean-zero assumption, then the inequality in Theorem \ref{thm:vector-concentration} reads%
\begin{equation*}
\left\Vert \sum_{i}\left( X_{i}-\mathbb{E}\left[ X_{i}\right] \right)
\right\Vert \leq \sqrt{\sum_{i}\mathbb{E}\left\Vert X_{i}-\mathbb{E}\left[
X_{i}\right] \right\Vert ^{2}}\left( 1{+}\sqrt{2\ln \left( 1/\delta \right) }%
\right) {+}\frac{4c}{3}\ln \left( 1/\delta \right) .
\end{equation*}%
In many applications, we observe the $X_{i}$, but we do not know the
expectations and wish to use the inequality to estimate $\sum_{i}\mathbb{E}%
\left[ X_{i}\right] $. In this case, it is useful to have an empirical
estimate of the variance term on the right-hand side. We give two such
estimates, a simple biased one, and an unbiased one for i.i.d data. Both use
the following concentration inequality, which can be found in \citep%
[Corollary 10]{maurer2018empirical}.


\begin{theorem}
\label{thm:selfbound} 
Define an operator $D^{2}$ acting on measurable
functions $f:\mathcal{X}^{m}\rightarrow 
%TCIMACRO{\U{211d} }%
%BeginExpansion
\mathbb{R}
%EndExpansion
$ by 
\begin{equation*}
D^{2}f\left( \mathbf{x}\right) =\sum_{k}\left( f\left( \mathbf{x}\right)
-\inf_{y\in \mathcal{X}}f\left( S_{y}^{k}\mathbf{x}\right) \right) ^{2},
\end{equation*}%
and let $\mathbf{X}=\left( X_{1},...,X_{m}\right) $ be a vector of
independent variables with values in $\mathcal{X}$. Now suppose $f:\mathcal{X%
}^{m}\rightarrow 
%TCIMACRO{\U{211d} }%
%BeginExpansion
\mathbb{R}
%EndExpansion
$ satisfies $f\left( \mathbf{x}\right) -\inf_{y\in \mathcal{X}}f\left(
S_{y}^{k}\mathbf{x}\right) \leq b$ for all $k\in \left\{ 1,...,m\right\} $
and all $\mathbf{x}\in \mathcal{X}^{m}$, and for some $a>0$%
\begin{equation}
D^{2}f\left( \mathbf{x}\right) \leq af\left( \mathbf{x}\right) ,\forall 
\mathbf{x}\in \mathcal{X}^{m}\text{.}  \label{selfbound condition}
\end{equation}%
Then for all $\delta >0$ with probability at least $1-\delta $%
\begin{equation*}
\sqrt{\mathbb{E}\left[ f\left( \mathbf{X}\right) \right] }\leq \sqrt{f\left( 
\mathbf{X}\right) }{+}\sqrt{2\max \left\{ a,b\right\} \ln \left( 1/\delta
\right) }.
\end{equation*}
\end{theorem}
\bigskip
For the simple biased estimate, we use the elementary inequality 
\begin{equation}
\sqrt{\sum_{i}\mathbb{E}\left\Vert X_{i}-\mathbb{E}\left[ X_{i}\right]
\right\Vert ^{2}}=\sqrt{\sum_{i}\left( \mathbb{E}\left\Vert X_{i}\right\Vert
^{2}-\left\Vert \mathbb{E}\left[ X_{i}\right] \right\Vert ^{2}\right) }\leq 
\sqrt{\sum_{i}\mathbb{E}\left\Vert X_{i}\right\Vert ^{2}}.
\label{elementary variance estimate}
\end{equation}%
Let $f\left( \mathbf{x}\right) =\sum_{i}\left\Vert x_{i}\right\Vert ^{2}$.
The minimizer in $y$ of $f\left( S_{y}^{k}\mathbf{x}\right) $ is clearly $%
y=0 $. Thus $f\left( \mathbf{x}\right) -\inf_{y\in \mathcal{X}}f\left(
S_{y}^{k}\mathbf{x}\right) \leq \left\Vert x_{k}\right\Vert ^{2}\leq c^{2}$
and 
\begin{equation*}
D^{2}f\left( \mathbf{x}\right) \leq \sum_{k}\left\Vert x_{k}\right\Vert
^{4}\leq c^{2}\sum_{k}\left\Vert x_{k}\right\Vert ^{2}=c^{2}f\left( \mathbf{x%
}\right) .
\end{equation*}%
The theorem above, with $a=b=c^{2}$ gives with probability at least $%
1-\delta $ that%
\begin{equation*}
\sqrt{\sum_{i}\mathbb{E}\left\Vert X_{i}\right\Vert ^{2}}\leq \sqrt{%
\sum_{i}\left\Vert X_{i}\right\Vert ^{2}}{+}c\sqrt{2\ln \left( 1/\delta
\right) }.
\end{equation*}%
A union bound with Theorem \ref{thm:vector-concentration} gives

\begin{proposition}
\label{prop:empirical-biased}Under the conditions of Theorem \ref%
{thm:vector-concentration}, but with uncentered $X_{i}$, we have for $%
0<\delta <1$ with probability at least $1-\delta $ in $\mathbf{X}$%
\begin{equation*}
\left\Vert \sum_{i}\left( X_{i}-\mathbb{E}\left[ X_{i}\right] \right)
\right\Vert \leq \sqrt{\sum_{i}\left\Vert X_{i}\right\Vert ^{2}}\left( 1{+}%
\sqrt{2\ln \left( 2/\delta \right) }\right) {+}\frac{16c}{3}\ln \left(
2/\delta \right).
\end{equation*}
\end{proposition}

% \erfan[]{The summation is on both i and j? can you hint at this equality?}\andreas{expand all squares and use independence and the fact that they are not mean zero any more}
For identically distributed $X_{i}$ we can do better, since then%
\begin{equation}
\sqrt{\sum_{i}\mathbb{E}\left\Vert X_{i}-\mathbb{E}\left[ X_{i}\right]
\right\Vert ^{2}}=\sqrt{\frac{1}{2\left( m-1\right) }\mathbb{E}\sum_{i,j:i\neq
j}\left\Vert X_{i}-X_{j}\right\Vert ^{2}},
\label{unbiased variance estimator}
\end{equation}%
and we can apply Theorem \ref{thm:selfbound} to 
\begin{equation*}
f\left( \mathbf{x}\right) =\sum_{i,j:i\neq j}\left\Vert x_{i}-x_{j}\right\Vert
^{2}.
\end{equation*}%
Then for any $k\in \left[ m\right] $ and $y\in \mathcal{X}$ we have 
\begin{equation*}
f\left( \mathbf{x}\right) -f\left( S_{y}^{k}\mathbf{x}\right)
=2\sum_{i:i\neq k}\left( \left\Vert x_{i}-x_{k}\right\Vert ^{2}-\left\Vert
x_{i}-y\right\Vert ^{2}\right) .
\end{equation*}%
It is easy to see that the minimizer in $y$ of $f\left( S_{y}^{k}\mathbf{x}%
\right) $ is the average $y_{k}=1/\left( m-1\right) \sum_{j:j\neq k}x_{j}$.
A computation gives \begin{equation*}
\sum_{i:i\neq k}\left\Vert x_{i}-y_{k}\right\Vert ^{2}=\sum_{i:i\neq
k}\left\Vert x_{i}-x_{k}\right\Vert ^{2}-\frac{1}{m-1}\left\Vert
\sum_{i:i\neq k}\left( x_{i}-x_{k}\right) \right\Vert ^{2}
\end{equation*}%
Thus%
\begin{equation*}
f\left( \mathbf{x}\right) -\inf_{y}f\left( S_{y}^{k}\mathbf{x}\right) =\frac{%
2}{m-1}\left\Vert \sum_{i:i\neq k}\left( x_{i}-x_{k}\right) \right\Vert
^{2}\leq 8\left( m-1\right) c^{2},
\end{equation*}%
Thus, $b = 8\left( m-1\right) c^{2}$, and%
\begin{eqnarray*}
D^{2}f\left( \mathbf{x}\right)  &=&\frac{4}{\left( m-1\right) ^{2}}%
\sum_{k}\left\Vert \sum_{i:i\neq k}\left( x_{i}-x_{k}\right) \right\Vert ^{4}
\\
&=&\frac{4\left( m-1\right) ^{4}}{\left( m-1\right) ^{2}}\sum_{k}\left(
\left\Vert \frac{1}{m-1}\sum_{i:i\neq k}\left( x_{i}-x_{k}\right)
\right\Vert ^{2}\right) ^{2} \\
&\leq &\frac{4\left( m-1\right) ^{4}}{\left( m-1\right) ^{2}}\sum_{k}\left( 
\frac{1}{m-1}\sum_{i:i\neq k}\left\Vert x_{i}-x_{k}\right\Vert ^{2}\right)
^{2} \\
&\leq &16c^{2}\left( m-1\right) \sum_{k}\sum_{i:i\neq k}\left\Vert
x_{i}-x_{k}\right\Vert ^{2}.
\end{eqnarray*}%
The first inequality follows from Jensen's inequality, the second is
obtained by bounding $1/\left( m-1\right) \sum_{i:i\neq k}\left\Vert
x_{i}-x_{k}\right\Vert ^{2}\leq 4c^{2}$. Thus $D^{2}f\left( \mathbf{x}%
\right) \leq 16\left( m-1\right) c^{2}f\left( \mathbf{x}\right)$ where $a = 16\left( m-1\right) c^{2}$.


It follows from Theorem \ref{thm:selfbound} that with probability at
least $1-\delta $%
\begin{equation*}
\sqrt{\sum_{i}\mathbb{E}\left\Vert X_{i}-\mathbb{E}\left[ X_{i}\right]
\right\Vert ^{2}}\leq \sqrt{\frac{1}{2\left( m-1\right) }\sum_{i,j:i\neq
j}\left\Vert X_{i}-X_{j}\right\Vert ^{2}}{+}4c\sqrt{\ln \left( 1/\delta
\right) }
\end{equation*}%
and the union bound with Theorem \ref{thm:vector-concentration} gives
(with some rather crude estimates) for $\delta <2/e$ with probability at
least $1-\delta $%
\begin{eqnarray*}
\left\Vert \sum_{i}\left( X_{i}-\mathbb{E}\left[ X_{i}\right] \right)
\right\Vert  &>&\sqrt{\frac{1}{2\left( m-1\right) }\sum_{i,j:i\neq j}\left\Vert
X_{i}-X_{j}\right\Vert ^{2}}\left( 1{+}\sqrt{2\ln \left( 2/\delta \right) }%
\right)  \\
&&{+}(4\sqrt{2}+4+\frac{4}{3}) c\ln \left( 2/\delta \right) .
\end{eqnarray*}%
Using $4\sqrt{2}+4+\frac{4}{3} = 10.99<11 $ we obtain


\begin{proposition}
\label{Proposition empirical unbiased}Let $\mathbf{X}=\left(
X_{1},...,X_{m}\right) $ be a vector of i.i.d. random variables with values in
a Hilbert space, satisfying $\left\Vert X_{1}\right\Vert \leq c$ almost
surely. Then for $0<\delta <2/e$ with probability at least $1-\delta $ in $%
\mathbf{X}$%
\begin{equation*}
\left\Vert \sum_{i}\left( X_{i}-\mathbb{E}\left[ X_{i}\right] \right)
\right\Vert \leq \sqrt{\frac{1}{2\left( m-1\right) }\sum_{i,j:i\neq j}\left\Vert
X_{i}-X_{j}\right\Vert ^{2}}\left( 1{+}\sqrt{2\ln \left( 2/\delta \right) }%
\right) {+}11c\ln \left( 2/\delta \right) .
\end{equation*}
\end{proposition}

\subsection{Mixing and its consequences} \label{app:mixing}

Let $\mathbf{X}:=\left\{ X_{t}\right\} _{t\in \mathbb{N}}$ be a sequence of
random variables with values in some measurable space $\mathcal{X}$. For a
set $I\subseteq $ $\mathbb{N}$ use $\Sigma \left( I\right) $ for the $\sigma 
$-field generated by $\left\{ X_{i}\right\} _{i\in I}$ and $\mu _{I}$ for
the joint distribution of $\left\{ X_{i}\right\} _{i\in I}$. Then the
definition of the mixing coefficients $\beta_{\mu} \left( \tau \right) $ for $\tau
\in \mathbb{N}$ reads \citep{bradley2005basic}%
\begin{equation*}
\beta_{\mu}\left( \tau \right) :=\sup_{j\in \mathbb{N}}\sup_{B\in
\Sigma \left( \left[ 1,j\right] \cup \left[ j{+}\tau ,\infty \right) \right)
}\left\vert \mu _{\left[ 1,j\right] \cup \left[ j{+}\tau ,\infty \right)
}\left( B\right) -\mu _{\left[ 1,j\right] }\times \mu _{\left[ j{+}\tau
,\infty \right) }\left( B\right) \right\vert .
\end{equation*}

In the sequel, we let $T,m,\tau \in \mathbb{N}$ with $T=2m\tau $ the length
of the trajectory observed. We call $\tau $ the "mixing time" with the
intuitive understanding that events separated by more than $\tau $ can be
regarded as independent, with a penalty in probability of order $\beta_{\mu}\left( \tau \right) $.

For $j\in \left[ m\right] $ define the index sets $I_{j}=\left\{ 2\left(
j-1\right) \tau {+}1,...,\left( 2j-1\right) \tau \right\} $ and $I_{j}^{\prime
}=\left\{ \left( 2j-1\right) \tau {+}1,...,2j\tau \right\} $. Then $\left[ T%
\right] =\bigcup_{k=1}^{m}I_{k}\cup I_{k}^{\prime }$. We also set

\begin{lemma}
\label{lem:betamix_nonstationary}For $m\in \mathbb{N}$ and $B\in \Sigma \left( I_{1}\cup
...\cup I_{m}\right) $%
\begin{equation*}
\left\vert \mu _{I_{1}\cup ...\cup I_{m}}\left( B\right) -\mu _{I_{1}}\times
...\times \mu _{I_{m}}\left( B\right) \right\vert \leq \left( m-1\right)
\beta_{\mu}\left( \tau \right) ,
\end{equation*}%
and for $B^{\prime }\in \Sigma \left( I_{1}^{\prime }\cup ...\cup
I_{m}^{\prime }\right) $%
\begin{equation*}
\left\vert \mu _{I_{1}^{\prime }\cup ...\cup I_{m}^{\prime }}\left(
B^{\prime }\right) -\mu _{I_{1}^{\prime }}\times ...\times \mu
_{I_{m}^{\prime }}\left( B^{\prime }\right) \right\vert \leq \left(
m-1\right) \beta_{\mu}\left( \tau \right) ,
\end{equation*}
\end{lemma}

\begin{proof}
By Fubini's Theorem and the definition of the mixing coefficients, we have
for $1\leq k<m$, that%
\begin{equation*}
\left\vert \mu _{I_{1}}\times ...\times \mu _{I_{k}\cup ...\cup I_{m}}\left(
B\right) -\mu _{I_{1}}\times ...\times \mu _{I_{k}}\times \mu _{I_{k{+}1}\cup
...\cup I_{m}}\left( B\right) \right\vert \leq \beta_{\mu}\left(\tau \right).
\end{equation*}%
Then with a telescopic expansion,
\begin{eqnarray*}
&&\left\vert \mu _{I_{1}\cup ...\cup I_{m}}\left( B\right) -\mu
_{I_{1}}\times ...\times \mu _{I_{m}}\left( B\right) \right\vert \\
& = &\left\vert \sum_{k=1}^{m-1} \mu _{I_{1}}\times ...\times \mu
_{I_{k}\cup ...\cup I_{m}}\left( B\right) -\mu _{I_{1}}\times ...\times \mu
_{I_{k}}\times \mu _{I_{k{+}1}\cup ...\cup I_{m}}\left( B\right) \right\vert \\
&\leq &\sum_{k=1}^{m-1}\left\vert \mu _{I_{1}}\times ...\times \mu
_{I_{k}\cup ...\cup I_{m}}\left( B\right) -\mu _{I_{1}}\times ...\times \mu
_{I_{k}}\times \mu _{I_{k{+}1}\cup ...\cup I_{m}}\left( B\right) \right\vert \\
&\leq &\left( m-1\right) \beta_{\mu}\left( \tau \right) .
\end{eqnarray*}%
The argument for $B^{\prime }$ is analogous.\bigskip
\end{proof}

In the sequel we write $\Pr_{I}$ for the probability measure $\mu
_{I_{1}}\times ...\times \mu _{I_{m}}$ on $\Sigma \left( I_{1}\cup ...\cup
I_{m}\right) $ and $\Pr_{I^{\prime }}$ for $\mu _{I_{1}^{\prime }}\times
...\times \mu _{I_{m}^{\prime }}$ on $\Sigma \left( I_{1}^{\prime }\cup
...\cup I_{m}^{\prime }\right) $. The previous lemma can then be stated more
concisely as $\left\vert \Pr_{I}\left( B\right) -\Pr \left( B\right)
\right\vert \leq \left( m-1\right) \beta_{\mu}\left( \tau \right) $
for $B\in \Sigma \left( I_{1}\cup ...\cup I_{m}\right) $ and $\left\vert
\Pr_{I^{\prime }}\left( B\right) -\Pr \left( B\right) \right\vert \leq
\left( m-1\right) \beta_{\mu}\left( \tau \right) $ for $B\in \Sigma
\left( I_{1}^{\prime }\cup ...\cup I_{m}^{\prime }\right) $.

