\subsection{Concentration for dependent variables}\label{app:con_ineq_dependent}

Now let $X_{i}$ be a possibly dependent sequence of mean-zero random vectors
in $H$. Write $Y_{j}=\sum_{i\in I_{j}}X_{i}$ and $Y_{j}^{\prime }=\sum_{i\in
I_{j}^{\prime }}X_{i}$. Note the bounds $\left\Vert Y_{k}\right\Vert \leq
\tau c$ and $\left\Vert Y_{k}^{\prime }\right\Vert \leq \tau c$ and that the 
$Y_{k}$ are independent under $\Pr_{I}$, as are the $Y_{k}^{\prime }$ under $%
\Pr_{I^{\prime }}$. Define 
\begin{eqnarray*}
F\left( \mathbf{X}\right)  &=&\sqrt{\sum_{k=1}^{m}\mathbb{E}\left\Vert
Y_{k}\right\Vert ^{2}}\left( 1{+}\sqrt{2\ln \left( 2/\delta \right) }\right) {+}%
\frac{4\tau c}{3}\ln \left( 2/\delta \right)  \\
F^{\prime }\left( \mathbf{X}\right)  &=&\sqrt{\sum_{k=1}^{m}\mathbb{E}%
\left\Vert Y_{k}^{\prime }\right\Vert ^{2}}\left( 1{+}\sqrt{2\ln \left(
2/\delta \right) }\right) {+}\frac{4\tau c}{3}\ln \left( 2/\delta \right) .
\end{eqnarray*}%

Lemma \ref{lem:blocking} gives%
\begin{eqnarray*}
\Pr \left\{ \left\Vert \sum_{i=1}^{n}X_{i}\right\Vert >F\left( \mathbf{X}%
\right) {+}F^{\prime }\left( \mathbf{X}\right) \right\}  &\leq &\Pr_{I}\left\{
\left\Vert \sum_{j=1}^{m}Y_{j}\right\Vert >F\left( \mathbf{X}\right)
\right\} {+}\Pr_{I^{\prime }}\left\{ \left\Vert \sum_{j=1}^{m}Y_{j}^{\prime
}\right\Vert >F^{\prime }\left( \mathbf{X}\right) \right\} {+}2\left(
m-1\right) \beta_{\mu}\left( \tau \right)  \\
&\leq &\delta /2{+}\delta /2{+}2\left( m-1\right) \beta_{\mu}\left( \tau
\right),
\end{eqnarray*}%
where the second inequality follows from Theorem \ref{thm:vector-concentration}. Substitution of the expressions for $F\left( \mathbf{X}%
\right) $ and $F^{\prime }\left( \mathbf{X}\right) $ and using $\sqrt{a}{+}%
\sqrt{b}\leq \sqrt{2}\sqrt{a{+}b}$, we obtain%
\begin{eqnarray*}
&&\Pr \left\{ \left\Vert \sum_{i=1}^{n}X_{i}\right\Vert >\sqrt{%
\sum_{k=1}^{m}\left( \mathbb{E}\left\Vert Y_{k}\right\Vert ^{2}{+}\mathbb{E}%
\left\Vert Y_{k}^{\prime }\right\Vert ^{2}\right) }\left( \sqrt{2}{+}2\sqrt{%
\ln \left( 2/\delta \right) }\right) {+}\frac{8\tau c}{3}\ln \left( 2/\delta
\right) \right\}  \\
&<&\delta {+}2\left( m-1\right) \beta_{\mu}\left( \tau \right) \text{.}
\end{eqnarray*}%
Now $\mathbb{E}\left\Vert Y_{k}\right\Vert ^{2}=\sum_{\left( t,s\right) \in
I_{k}\times I_{k}}\mathbb{E}\left[ \left\langle X_{t},X_{s}\right\rangle %
\right] $ and $\mathbb{E}\left\Vert Y_{k}^{\prime }\right\Vert
^{2}=\sum_{\left( t,s\right) \in I_{k}^{\prime }\times I_{k}^{\prime }}%
\mathbb{E}\left[ \left\langle X_{t},X_{s}\right\rangle \right] $. Thus 
\begin{equation*}
\sum_{k=1}^{m}\left( \mathbb{E}\left\Vert Y_{k}\right\Vert ^{2}{+}\mathbb{E}%
\left\Vert Y_{k}^{\prime }\right\Vert ^{2}\right) =\sum_{\left( t,s\right)
\in S_{\tau}}\mathbb{E}\left[ \left\langle X_{t},X_{s}\right\rangle \right] ,
\end{equation*}%
where $S_\tau$ is the set of index pairs%
\begin{equation}
S_\tau=\bigcup_{k=1}^{m}\left( I_{k}\times I_{k}\right) \cup \left( I_{k}^{\prime
}\times I_{k}^{\prime }\right) ,  \label{Define S}
\end{equation}%
which is a disjoint union of $\tau \times \tau $-squares along the diagonal
of the $T\times T$ matrix. If $\left( t,s\right) \in S_\tau$ then the times $s$
and $t$ are never more than $\tau $ apart. We have proved 


\begin{theorem}
\label{Theorem Dependent Bernstein}Let $m,\tau \in \mathbb{N}$, $T=2m\tau $,
and let $\mathbf{X}=\left( X_{1},...,X_{T}\right) $ be a vector of mean zero
random variables in a separable Hilbert-space $H$, satisfying $\left\Vert
X_{t}\right\Vert \leq c$. Let $\delta >0$. Then with a probability of at least $%
1-\delta -2\left( m-1\right) \beta_{\mu}\left( \tau \right) $ we have%
\begin{equation*}
\left\Vert \sum_{t=1}^{T}X_{t}\right\Vert \leq \sqrt{\sum_{\left( t,s\right)
\in S_{\tau}}\mathbb{E}\left[ \left\langle X_{t},X_{s}\right\rangle \right] }\left( 
\sqrt{2}{+}2\sqrt{\ln \left( 2/\delta \right) }\right) {+}\frac{8\tau c}{3}\ln
\left( 2/\delta \right) ,
\end{equation*}%
where $S_{\tau}\subseteq \left[ T\right] \times \left[ T\right] $ is given by (\ref%
{Define S}).
\end{theorem}

\begin{enumerate}
\item If we drop the mean-zero assumption, this becomes Theorem \ref{thm:Data-dependent-Bernstein}.

\item To interpret the first term on the right-hand side, note the
similarity to the variance of $\sum X_{t}$, which would be%
\begin{equation*}
\mathbb{E}\left\Vert \sum X_{t}\right\Vert ^{2}=\sum_{\left( t,s\right) \in %
\left[ T\right] \times \left[ T\right] }\mathbb{E}\left[ \left\langle
X_{t},X_{s}\right\rangle \right] .
\end{equation*}

\item If the $X_{t}$ are independent, we can set $\tau =1$ and $\beta _{%
\mathbf{X}}\left( \tau \right) =0$, and we recover Theorem \ref{thm:vector-concentration} up to a constant factor of $\sqrt{2}$ on the first,
and $2$ on the second term.
\end{enumerate}

In the proof above, the functions $F\left( \mathbf{X}\right) $ and $F^{\prime
}\left( \mathbf{X}\right) $ were constants. But let 
\begin{equation*}
F\left( \mathbf{X}\right) =\sqrt{\sum_{k=1}^{m}\left\Vert \sum_{i\in
I_{k}}X_{i}\right\Vert ^{2}}\left( 1{+}\sqrt{2\ln \left( 4/\delta \right) }%
\right) {+}\frac{16c\tau}{3}\ln \left( 4/\delta \right) ,
\end{equation*}%
which is $\Sigma \left( I_{1}\cup ...\cup I_{m}\right) $-measurable, and
replace $I_{k}$ by $I_{k}^{\prime }$ for the analogous definition of $%
F^{\prime }\left( \mathbf{X}\right) $. Then Lemma \ref{lem:blocking} and
Proposition \ref{prop:empirical-biased} give a proof of Theorem \ref%
{thm:empirical-Bernstein-biased}. In the same way, defining 
\begin{equation*}
F\left( \mathbf{X}\right) =\sqrt{\frac{1}{2\left( m-1\right) }\sum_{k,l:k\neq
l}\left\Vert \sum_{i\in I_{k}}X_{i}-\sum_{j\in I_{l}}X_{j}\right\Vert ^{2}}%
\left( 1{+}\sqrt{2\ln \left( 4/\delta \right) }\right) {+}11c\tau\ln \left( 4/\delta
\right) ,
\end{equation*}%
together with the corresponding $F^{\prime }\left( \mathbf{X}\right) $,
yields the proof of Theorem \ref{thm:empirical-Bernstein-unbiased}.

\section{Theoretical result for learning dynamical systems} \label{app:LDS_theory}
In this section, we begin by briefly reviewing the notations and definitions pertinent to learning dynamical systems. Next, we establish bounds on the deviation of the true risk from the empirical risk, uniformly across a prescribed set of HS operators on $\RKHS$. Finally, we demonstrate how this analysis, originally formulated for Ivanov regularization, can be extended to Tikhonov regularization.
\subsection{Notation and background}
Let us first review some fundamental concepts related to Markov chains and Koopman operators. Consider $\mathbf{X}:= \left\{X_{t} \colon t\in \mathbb{N} \right\}$, a collection of random variables taking values in a measurable space $(\mathcal{X}, \Sigma_{\mathcal{X}})$, known as the state space. We define $\mathbf{X}$ as a {\em Markov chain} if $\ensuremath{\mathbb P}\{ X_{t+1} \in B \vert X_{[t]} \} = \ensuremath{\mathbb P}\{X_{t + 1} \in B \vert X_t \}$. Additionally, $\mathbf{X}$ is termed {\em time-homogeneous} if there exists a function $p\colon \mathcal{X} \times \Sigma_{\mathcal{X}} \to [0,1]$, known as the {\it transition kernel}, such that for all $(x, B) \in \mathcal{X} \times \Sigma_{\mathcal{X}}$ and each $t \in \mathbb{N}$,
\[
\mathbb{P}\left\{X_{t + 1} \in B \middle| X_{t} = x \right\} = p(x,B).
\]

A broad class of Markov chains includes those with an \textit{invariant measure} $\pi$, which satisfies $\pi(B) = \int_{\mathcal{X}} \pi(dx)p(x,B)$ for $B\in\Sigma_{\mathcal{X}}$. For a {\em time-homogeneous} Markov chain with an invariant (stationary) distribution $\im$ the (stochastic) \textit{Koopman operator} $\Koop \colon \Lii\to\Lii$  is given by \\
\begin{equation}\label{eq:Koopman_app}
A_{\pi} f(x) := \int_{\mathcal{X}} p(x, dy)f(y) = \mathbb{E}\left[f(X_{t {+} 1}) \middle | X_{t} = x\right], \quad f \in L^2_{\pi}(\mathcal{X}), x \in \mathcal{X}.
\end{equation}

In many practical scenarios, the Koopman operator $\Koop$ is unknown, but data from one or more trajectories are available. The framework for operator regression learning introduced in~\citep{Kostic2022} estimates the Koopman operator on $\Lii$ within an RKHS, using an associated feature map $\fH: \X \to \RKHS$. In this vector-valued regression, the population risk functional is defined as
\begin{equation}    
\Risk(G) = \EE_{X\sim\pi,X^+\sim p(\cdot\vert X))}[\norm{\phi(X^+) - G^{}\phi(X)}^{2}_\RKHS],
\end{equation}

and the goal is to learn $\Koop$ by minimizing the risk over a class of operators $G\colon \RKHS \to \RKHS$, using a dataset of consecutive states $\Data := (x_i, x^{+}_{i})_{i=1}^{n}$. A typical setting involves obtaining these states from a single trajectory of the process after it reaches the equilibrium distribution, where $X_0 \sim \pi$ and $X^+_i \equiv X_{i+1} \sim p(\cdot,\vert,X_i)$ for $i = 2,\ldots,n$. A common estimator in this context is the Reduced Rank Regression (RRR) estimator $\EKRR$, obtained by minimizing the regularized empirical risk
\begin{equation}    
{\ERisk}_\lambda(\Estim) := \tfrac{1}{n}\sum_{i \in[n]}\norm{\phi(x^+_i) - \Estim^{}\phi(x_i)}^{2}_{\RKHS} {+} \lambda\|\Estim\|^2_{\text{HS}},
\end{equation}

over operators $\Estim$ of rank at most $r$. The estimator $\ERRR = \ECreg^{-1/2}\SVDr{\ECreg^{-1/2}\ECxy}$ is computed via an $r$-truncated SVD $\SVDr{\cdot}$, where the empirical input and cross covariances are respectively
$$\ECx \,= \,\textstyle{\tfrac{1}{n}\sum_{i \in[n]}}\, \phi(x_{i}){\otimes} \phi(x_{i}), ~~{\rm and}~~\ECxy\,{ =} \,\textstyle{\tfrac{1}{n}\sum_{i \in[n]}}\, \phi(x_{i}){\otimes }\phi(x^+_{i}).$$
In this section we denote as $\ECx_{\reg} = \ECx + \reg I_{\RKHS}$. Further, similar to the relationship between population and empirical risk, the population covariance and cross-covariance are given respectively by
$$ 
\Cx =  \EE_{X \sim \im}[\phi(X) \otimes \phi(X)], ~~{\rm and}~~ \Cxy = \EE_{X\sim\pi,X^+\sim p(\cdot\vert X))}[\phi(X) \otimes \phi(X^+)].$$

\subsection{Uniform bound for Ivanov regularization}

In view of the fact that both Tikhonov regularization and Ivanov regularization versions of the problem are equivalent, we will first focus on the Ivanov regularization formulation, which is more convenient to theoretical analysis\citep{oneto2016tikhonov, luise2019leveraging}. We first state the uniform bound for the Ivanov regularization case. Then, reformulate to Tikhonov regularization since it is more convenient from a computational standpoint. 

\begin{theorem} \label{thm:ivanov_risk_bound}
Let $\mathbf{X}=(X_{t})_{t=1}^{n}$ be a stationary Markov chain with distribution $\mu$, and the risk definitions as above, noting that $\pi=\mu_{1}$.
Denote $\mathcal{G}_{r,\gamma} = \{\Estim \in \mathrm{HS}_r(\mathcal{H}): \|\Estim\|_{\mathrm{HS}} \leq \gamma \}$ and  $\mathbf{Y}=\left( \fH(X_{0})\otimes\fH(X_{0}),...,\fH(X_{n-1})\otimes\fH(X_{n-1})\right) $, $\mathbf{Z}=\left( \fH(X_{0})\otimes\fH(X_{1}),...,\fH(X_{n-1})\otimes\fH(X_{n})\right) $, and $\mathbf{W}=\left( \|\fH(X_{1})\|^2,...,\|\fH(X_{n})\|^2\right) $. Assume $n = 2m\tau$, and exists $\bcon\,>\,0$  such that $\norm{\fH(X_t)}^2{\leq }\bcon$ a.s. for all $t$. Let $\delta > 0$ and assume $\delt = \delta{-}2(\frac{n}{2\tau}{-}1)\beta_{\mu}(\tau) > 0$ and $\deltprime = \delta{-}2(\frac{n}{2\tau}{-}1)\beta_{\mu}(\tau-1) > 0$. Then, with probability at least $1 {-} \delta$ we have for every $\EEstim \in \mathcal{G}_{r,\gamma}$

\begin{equation}
\begin{aligned}
|\Risk(\EEstim)-\ERisk(\EEstim)| &\leq 
\frac{32\gamma^2\bcon\tau}{3n}\ln{\frac{12}{\delt}} +\frac{64\sqrt{r}\gamma\bcon\tau}{3n}\ln{\frac{12}{\deltprime}}+\frac{7\bcon\tau}{3(\frac{n}{2\tau}-1)}\ln{\frac{12}{\delt}} \\
&+ \sqrt{\frac{2\gamma^4\BECorrtau{Y}\tau}{n}\left( 1
+2\ln\frac{12}{\delt}\right)} + \sqrt{\frac{2r\gamma^2\BECorrtau{Z}\tau}{n}\left( 1{+}2\ln\frac{12}{\deltprime}\right)} \\
&+ \sqrt{\frac{2\overline{V}_{\tau}(\mathbf{W})\tau}{n}\ln{\frac{12}{\delt}}}
\end{aligned}
\end{equation}
where $\overline{V}_{\tau}(\mathbf{W}) = \frac{1}{m(m-1)\tau^2} \sum_{1\leq i< j\leq m} (\overline{W}_{i} - \overline{W}_{j})^2 + (\overline{W'}_{i} - \overline{W'}_{j})^2$, $\overline{W}_{j}=\sum_{i\in I_{j}}W_i$ and $\overline{W'}_{j}=\sum_{i\in I_{j}^{\prime }}W_i$. $\BECorrtau{\mathbf{Y}}$ and $\BECorrtau{\mathbf{Z}}$ were defined before.
\end{theorem}
\begin{proof}
We can restate both risk and the empirical risk as follows:
\begin{equation*}
\begin{aligned}
\Risk(\Estim) & =\EE_{(x,y)\sim \rho} \norm{\fH(y) - \Estim^*\fH(x)}^2 \\ & =
\EE_{(x,y)\sim \rho}[\tr\left(\fH\left(X_{i+1}\right) \otimes \fH\left(X_{i+1}\right)\right)-2\left\langle\fH\left(X_{i+1}\right), \Estim^* \fH\left(x_i\right)\right\rangle_{\mathcal{H}}+\operatorname{tr}\left(\Estim \Estim^* \fH\left(x_i\right) \otimes \fH\left(x_i\right)\right)]\\ & =\tr(\Cy)+\tr\left(\Estim \Estim^* \Cx\right)-2\tr\left(\Estim^* \Cxy\right)
\end{aligned}
\end{equation*}
Similarly, we have $\ERisk(\Estim)=\tr(\ECy)+\tr\left(\Estim \Estim^* \ECx\right)-2\tr\left(\Estim^* \ECxy\right)$. 


Let $\mathcal{G}_{r,\gamma} = \{\Estim \in \mathrm{HS}_r(\mathcal{H}): \|\Estim\|_{\mathrm{HS}} \leq \gamma \}$. Then for $\forall \Estim \in \mathcal{G}_{r,\gamma}$ we can easily show:
$$
\begin{aligned}
\Risk(\Estim)-\ERisk(\Estim) & =\tr(\Cy - \ECy)+\tr\left(\Estim \Estim^* (\Cx - \ECx)\right)-2\tr\left(\Estim^* (\Cxy - \ECxy)\right) \\
& \leq \tr(\Cy-\ECy)+\gamma^2\|\Cx-\ECx\|+2 \sqrt{r} \gamma\|\Cxy-\ECxy\|
\end{aligned}
$$
where we have used Hölder's inequality to obtain the last two terms. 

First, we use an empirical Bernstein's inequality for bounded random variables, $W_i = \tr(\fH(X_{i+1})\otimes\fH(X_{i+1})) = \|\fH(X_{i+1})\|^2$ and $|W_i|\leq\bcon$ since

\begin{equation*}
\begin{aligned}
\tr(\Cy - \ECy) & = \tr(\frac{1}{n}\sum_{i=1}^{n}\fH(X_{i+1})\otimes\fH(X_{i+1}) - \EE[\fH(X_{i+1})\otimes\fH(X_{i+1})]) \\
& = \frac{1}{n}\sum_{i=1}^{n}\tr(\fH(X_{i+1})\otimes\fH(X_{i+1}) - \EE[\fH(X_{i+1})\otimes\fH(X_{i+1}))] \\
& = \frac{1}{n} \sum_{i=1}^{n}\tr(\fH(X_{i+1})\otimes\fH(X_{i+1})) - \EE[\tr(\fH(X_{i+1})\otimes\fH(X_{i+1}))].
\end{aligned}
\end{equation*}
Now, Write $\overline{W}_{j}=\sum_{i\in I_{j}}W_i$ and $\overline{W'}_{j}=\sum_{i\in I_{j}^{\prime }}W_i$. Note the bounds $\left\Vert \overline{W}_{k}\right\Vert \leq \tau \bcon$ and $\left\Vert \overline{W}_{k}^{\prime }\right\Vert \leq \tau \bcon$ since we know there exists $\bcon\,>\,0$  such that $\norm{\fH(X_t)}^2{\leq }\bcon$ a.s. for all $t$. In addition, we know that the $\overline{W}_{k}$ are independent under $\Pr_{I}$, as are the $\overline{W}_{k}^{\prime }$ under $%
\Pr_{I^{\prime }}$. 

Define 
\begin{eqnarray*}
F\left( \mathbf{W}\right)  &=& \frac{7m\bcon\tau\ln{\frac{2}{\delta'}}}{3(m-1)} + \sqrt{2mV_m(\overline{W})\ln{\frac{2}{\delta'}}}, V_m(\overline{W}) =  \frac{1}{m(m-1)} \sum_{1\leq i< j\leq m} (\overline{W}_{i} - \overline{W}_{j})^2\\
F^{\prime }\left( \mathbf{W}\right)  &=&\frac{7m\bcon\tau\ln{\frac{2}{\delta'}}}{3(m-1)} + \sqrt{2mV_m(\overline{W'})\ln{\frac{2}{\delta'}}}, V_m(\overline{W'}) =  \frac{1}{m(m-1)} \sum_{1\leq i< j\leq m} (\overline{W'}_{i} - \overline{W'}_{j})^2 .
\end{eqnarray*}%
Lemma \ref{lem:blocking} gives%

\begin{align*}
& \Pr \left\{ \left\Vert \sum_{i=1}^{n}\left( W_i-\mathbb{E}%
\left[ W_i\right] \right) \right\Vert >F\left( \mathbf{W}\right)
+F^{\prime }\left( \mathbf{W}\right) \right\}  \\
& \leq \Pr_{I}\left\{ \left\Vert \sum_{k =
1}^{m}(\overline{W}_{k}-\mathbb{E}\left[ \overline{W}_{k}\right])\right\Vert >F\left( \mathbf{W}\right) \right\} +\Pr_{I^{\prime
}}\left\{ \left\Vert \sum_{k = 1}^{m}(\overline{W}_{k}^{\prime
}-\mathbb{E}\left[ \overline{W}_{k}^{\prime
}\right])\right\Vert
>F^{\prime }\left( \mathbf{W}\right) \right\} +2\left( m-1\right) \beta _{\mathbf{W}}\left( \tau \right) , \\
&\leq \delta /2{+}\delta /2{+}2\left( m-1\right) \beta_{\mu}\left(\tau\right),
\end{align*}% 
where the second inequality follows from adapting to arbitrarily bounded random variables of Thm 4 \citep{maurer2009empirical}. Substitution of the expressions for $F\left( \mathbf{W}%
\right) $ and $F^{\prime }\left( \mathbf{W}\right) $ and using  $\sqrt{a}{+}%
\sqrt{b}\leq \sqrt{2}\sqrt{a{+}b}$, and $\delta = 2\delta'$, we obtain%
\begin{eqnarray*}
&&\Pr \left\{ \left\Vert \sum_{i=1}^{n}(W_i-\EE[W_i])\right\Vert > \frac{14m\bcon\tau\ln{\frac{4}{\delta}}}{3(m-1)} + \sqrt{4m(V_m(\overline{W})+V_m(\overline{W'}))\ln{\frac{4}{\delta}}} \right\} \\
&<&\delta+2(m-1)\beta_{\mu}(\tau) 
\end{eqnarray*}%

Let define $\overline{V}_{\tau}(\mathbf{W}) = \frac{1}{\tau^2}(V_m(\overline{W}) + V_m(\overline{W'}))$.
Now, if we divide both sides in the probability by $n$ and substitute $\frac{2\tau}{n} = m$ we have
$$
\tr(\Cy - \ECy) \leq \frac{7\bcon\tau}{3(m-1)}\ln{\frac{4}{\delta - 2(m-1)\beta_{\mu}(\tau)}} + \sqrt{\frac{\overline{V}_{\tau}(\mathbf{W})\ln{\frac{4}{\delta - 2(m-1)\beta_{\mu}(\tau)}}}{m}}.
$$

To bound the second and the third terms, we can use Theorem 2 of this paper with the description in the covariance estimation section (for further details, see propositions in the next section). The result is then followed by a union bound.
\end{proof}

\begin{remark}
Theorem \ref{thm:ivanov_risk_bound} can be used in order to derive an excess risk bound for the well-specified case, following the same reasoning as \citep{Kostic2022, luise2019leveraging}. 
\end{remark}
\subsection{Adaptation of risk bound to Tikhonov regularization}

It is known that there is an equivalence between Ivanov and Tikhonov regularization, in the sense that for each class of estimators satisfying the conditions of Ivanov regularization, there exists a corresponding Tikhonov regularization problem. However, to extend this result, we require additional techniques. The next step involves the following lemma (a restatement of Lemma 15.6 from \cite{anthony1999learning}):

\begin{lemma}\label{lem:adaptation}
Suppose $\operatorname{Pr}$ is a probability distribution and

$$
\left\{E\left(\alpha_{1}, \alpha_{2}, \delta\right): 0<\alpha_{1}, \alpha_{2}, \delta \leq 1\right\}
$$

is a set of events, such that\\
(i) For all $0<\alpha \leq 1$ and $0<\delta \leq 1$,

$$
\operatorname{Pr}\{E(\alpha, \alpha, \delta)\} \leq \delta
$$

(ii) For all $0<\alpha_{1} \leq \alpha \leq \alpha_{2} \leq 1$ and $0<\delta_{1} \leq \delta \leq 1$

$$
E\left(\alpha_{1}, \alpha_{2}, \delta_{1}\right) \subseteq E(\alpha, \alpha, \delta)
$$

Then for $0<a, \delta<1$,

$$
\operatorname{Pr} \bigcup_{\alpha \in(0,1]} E(\alpha a, \alpha, \delta \alpha(1-a)) \leq \delta
$$
\end{lemma}

