\subsection{Covariance estimation using samples from Ornstein–Uhlenbeck process}\label{app:cov_est}
\subsubsection{Theoretical results}
As mentioned in the section on covariance estimation for estimating the concentration of covariance operators in the Hilbert-Schmidt norm,  the observed vectors are operators, and $X_{t}$
should be replaced by the operator $\fH(X_{t})\otimes \fH(X_{t})$.

Recent studies have relied on Pinelis and Sakhanenko’s inequality, see \citep[][Proposition 2]{caponnetto2007}. As mentioned earlier, the method of blocks and $\beta$-mixing extends this i.i.d. analysis of transfer operator regression to more realistic settings, such as learning from data trajectories of a stationary process. We begin by restating Pinelis and Sakhanenko’s inequality for convenience.

\begin{proposition}\label{prop:con_ineq_ps}
% Let $A_i$, $i\in[n]$ be i.i.d copies of a random variable $A$ in a
Let $A_i$, $i\in[n]$ be independent random variables with values in a
separable Hilbert space with norm $\norm{\cdot}$. If there exist constants $L>0$ and $\sigma>0$ such that $\forall i \in [n]$, $\|A_i\| \leq \frac{L}{2} $ and $\EE[\|A_i\|^2] \leq \sigma^2$, 
then with probability at least $1-\delta$ 
\begin{equation}\label{eq:con_ineq_ps}
\left\|\frac{1}{n}\sum_{i\in[n]}A_i - \EE[A_i] \right\|\leq 2(\frac{L}{n}{+}\frac{\sigma}{\sqrt{n}})\log(\frac{2}{\delta})
\end{equation}
\end{proposition}

 We now aim to adapt Pinelis and Sakhanenko’s inequality for covariance estimation in data-dependent scenarios.
% \CrossCovBound*
\begin{proposition}\label{prop:Pinelis_cov}
Let $\mathbf{X}=(X_{t})_{t=1}^{n}$ be a Markov chain with distribution $\mu$ and $\mathbf{Y} = (\fH(X_{t})\otimes\fH(X_{t}))_{t=1}^{n}$. Assume $n =2m\tau$, and exists $\bcon\,>\,0$  such that $\norm{\fH(X_t)}^2{\leq }\bcon$ a.s. for all $t$. Let $\delta \geq 0$ and assume $\delt = \delta{-}2(\frac{n}{2\tau}{-}1)\beta_{\mu}(\tau) > 0$, with probability at least $1 {-} \delta$ we have
\[ 
\norm{ \ECx {-} \Cx }\leq \frac{4\bcon}{m}\ln{\frac{4}{\delt}}{+}\frac{2\bcon}{\sqrt{m}} \ln{\frac{4}{\delt}} ,
\] 

where $\ECx \,= \,\textstyle{\tfrac{1}{n}\sum_{t \in[n]}}\, \phi(x_{t}){\otimes} \phi(x_{t})$ and in general $\Cx \,= \,\textstyle{\tfrac{1}{n}\sum_{t \in[n]}}\, \EE[\phi(X_{t}){\otimes} \phi(X_{t})].$
\end{proposition}


\begin{proof}
As we mentioned before, for covariance estimation, our random variables are the rank-one operators $Y_t = \phi(X_{t})\otimes \phi(X_{t})$ instead of $X_{t}$.
To prove it, we need to use the same procedure as section \ref{app:con_ineq_dependent} with these new random variables and use Pinelis and Sakhanenko's inequality as stated above. 
% Now, Let define $\ECx = \frac{1}{n} \sum_{t=1}^{n} \phi(X_{t})\otimes \phi(X_{t}) = \frac{1}{n} \sum_{t=1}^{n} Y_t$ and $\Cx = \frac{1}{n} \sum_{t=1}^{n} \EE[\phi(X_{t})\otimes \phi(X_{t})] = \frac{1}{n} \sum_{t=1}^{n} \EE[Y_t]$.

Now, Write $\overline{Y}_{j}=\sum_{i\in I_{j}}Y_{i}$ and $\overline{Y'}_{j}=\sum_{i\in I_{j}^{\prime }}Y_{i}$. Note the bounds $\left\Vert \overline{Y}_{k}\right\Vert \leq \tau \bcon$ and $\left\Vert \overline{Y'}_{k}\right\Vert \leq \tau \bcon$ since there exists $\bcon\,>\,0$ such that $\norm{\fH(X_t)}^2{\leq }\bcon$ a.s. for all $t$ . In addition, we know that the $\overline{Y}_{k}$ are independent under $\Pr_{I}$, as are the $\overline{Y'}_{k}$ under $%
\Pr_{I^{\prime }}$. Then, we also have the following:
\begin{equation*}
\begin{aligned}
    \|\overline{Y}_k\|^{2}_{HS} = \scalarp{\sum_{i=1}^{\tau} \fH(X_i)\otimes\fH(X_i),  \sum_{j=1}^{\tau}\fH(X_j)\otimes\fH(X_j)}_{HS} \\
