\end{aligned}
\end{equation*}
% We know that also $\|A_i\|^{2}_{HS} \leq \bcon^{2}$ and 
Therefore, we can set $ L = L' = 2 \tau \bcon$ and $\sigma = \sigma' = \tau \bcon$ for using for $\overline{Y}_{k}$ and $\overline{Y'}_{k}$. 

Define 
\begin{eqnarray*}
F\left( \mathbf{Y}\right) &=& F^{\prime }\left( \mathbf{Y}\right) =(4 \tau \bcon{+}2\tau \bcon\sqrt{m})\log(\frac{2}{\delta'})
