\section*{Supplementary Information for ``Correlated Quantum Shift Vector of Particle-Hole Excitations''}

\section{Bethe-Salpeter equation in relative coordinates}
It is instructive to express the Bethe-Salpeter equation (BSE) in terms of relative coordinates. Below we use $\textbf{R}$ to denote the real coordinates of individual electrons/holes, $\textbf{R}_{\rm cm}$ to denote the center-of-mass coordinates of electron-hole pair, and $\textbf{r}$ to denote the relative coordinates between electrons and holes.

We use $c^{\dagger}$ to denote creation operators for Wannier functions, which can be represented by \begin{align}
    &\ket{n,\textbf{R}}\equiv c^{\dagger}_{n,\textbf{R}}\ket{0}=\int d\textbf{x }w_{n,\textbf{R}}(\textbf{x})a^{\dagger}_{\textbf{x}}\ket{0} ,
\end{align}
where $n$ is the band index and $a_{\textbf{x}}$ is the field operator in free space. Here $w_{n,\textbf{R}}(\textbf{x})$ is the exponentially localized Wannier functions centered around $\textbf{R}$ which decays as $e^{-|\textbf{x}-\textbf{R}|/\xi_W}$ at large $|\textbf{x}-\textbf{R}|$ and $\xi_W$ is the Wannier function extent. Using the completeness relation $\sum\limits_{n,\textbf{R}}w_{n,\textbf{R}}(\textbf{x})w^*_{n,\textbf{R}}(\textbf{x}')=\delta(\textbf{x}-\textbf{x}')$, we can expand $a^{\dagger}_{\textbf{x}}$ in terms of $c^{\dagger}_{n,\textbf{R}}$, where  $n$ is the band index:
\begin{align}
    &a^{\dagger}_{\textbf{x}}\ket{0}=\sum\limits_{n,\textbf{R}}w_{n,\textbf{R}}^*(\textbf{x})c^{\dagger}_{n,\textbf{R}}\ket{0}.
\end{align}

Starting from the eigen equation $\hat{H}\ket{\psi_{\bm{Q}}}_{\text{p}-\text{h}}=E\ket{\psi_{\bm{Q}}}_{\text{p}-\text{h}}$, we can project it onto the particle-hole basis $\ket{\textbf{R}_{\rm cm},\textbf{r}}$ to arrive at the BSE for envelope functions: $\sum\limits_{\textbf{r}'}\mathcal{H}_{\bm{Q}}(\textbf{r},\textbf{r}')\psi_{\bm{Q}}(\textbf{r}')=E\psi_{\bm{Q}}(\textbf{r})$. The BSE %Bethe-Salpeter 
Hamitonian is therefore:
\begin{align}
&\mathcal{H}_{\bm{Q}}(\textbf{r},\textbf{r}')=\frac{1}{N}\sum\limits_{\textbf{R}_{\rm cm,1},\textbf{R}_{\rm cm,2}}e^{i\textbf{Q}\cdot(\textbf{R}_{\rm cm,2}-\textbf{R}_{\rm cm,1})}\bra{\textbf{R}_{\rm cm,1},\textbf{r}}\hat{H}\ket{\textbf{R}_{\rm cm,2},\textbf{r}'}
\end{align}

\textbf{Kinetic term}: the kinetic term $\mathcal{H}_{\textbf{K}}(\textbf{r},\textbf{r}')$ of BSE Hamiltonian is obtained by projecting the kinetic part $\hat{H}_{\textbf{K}}$ of the total Hamiltonian onto the particle-hole basis, where $\hat{H}_{\textbf{K}}=\int d\textbf{x} a_{\textbf{x}}^{\dagger}(\frac{\hat{\textbf{p}}^2}{2m}+V_{\rm lattice}(\textbf{x}))a_{\textbf{x}}$. After a straightforward evaluation, we arrive at:
\begin{align}
&\mathcal{H}_{\textbf{K}}(\textbf{r},\textbf{r}')=e^{i\textbf{Q}\cdot (\textbf{r}'-\textbf{r})/2}\bra{c,\textbf{r}}\hat{H}_{\textbf{K}}\ket{c,\textbf{r}'}-e^{i\textbf{Q}\cdot(\textbf{r}-\textbf{r}')/2}\bra{v,\textbf{r}}\hat{H}_{\textbf{K}}\ket{v,\textbf{r}'},
\end{align}
where $\bra{c,\textbf{r}}\hat{H}_{\textbf{K}}\ket{c,\textbf{r}'}\equiv \int d\textbf{x } w_{c,\textbf{r}}^*(\textbf{x})(\frac{\hat{\textbf{p}}^2}{2m}+V_{\rm lattice}(\textbf{x}))w_{c,\textbf{r}'}(\textbf{x})$, 
which is of order $e^{-|\textbf{r}-\textbf{r}'|/\xi_W}$ from the exponential localization nature of Wannier functions (and similarly for $v$ bands). 

Utilizing the relation between the Bloch functions and the Wannier functions $w_{\textbf{R}}(\textbf{x})=\frac{1}{\sqrt{N}}\sum\limits_{\textbf{k}}e^{-i\textbf{k}\cdot\textbf{R}}\psi_{\textbf{k}}(\textbf{x})$, we can immediately see that the kinetic term $\mathcal{H}_{\textbf{K}}(\textbf{r},\textbf{r}')=\frac{1}{N}\sum\limits_{\textbf{p}}e^{i\textbf{p}\cdot(\textbf{r}-\textbf{r}')}[\epsilon_c(\textbf{p}+\textbf{Q}/2)-\epsilon_v(\textbf{p}-\textbf{Q}/2)]$ as discussed in the main text.

\textbf{Interaction term}: the interaction part of the Hamiltonian is of the general form $\hat{H}_{\textbf{V}}=\int d\textbf{x}_1d\textbf{x}_2V(|\textbf{x}_1-\textbf{x}_2|)a^{\dagger}_{\textbf{x}_1}a^{\dagger}_{\textbf{x}_2}a_{\textbf{x}_2}a_{\textbf{x}_1}$. The electron-electron interaction 
$V(|\textbf{x}|)$ can either be screened or un-screened and vanishes as $|\textbf{x}|\rightarrow \infty$. After projecting onto the particle-hole basis and performing Hartree-Fock contractions, we arrive at two terms, the direct term $\mathcal{V}_{D}$ and the exchange interaction term $\mathcal{V}_{X}$.

The direct interaction term:
\begin{align}\label{eq:appendix_Vdirect}
  & \mathcal{V}_{D}(\textbf{r},\textbf{r}')=-\sum\limits_{\Delta\textbf{R}_{\rm cm}}e^{i\textbf{Q}\cdot(\Delta\textbf{R}_{\rm cm})}\int d\textbf{x}_1d\textbf{x}_2 w_{c,\Delta\textbf{R}_{\rm cm}+\textbf{r}'/2}(\textbf{x}_1)w^*_{c,\textbf{r}/2}(\textbf{x}_1)V(|\textbf{x}_1-\textbf{x}_2|)w_{v,-\textbf{r}/2}(\textbf{x}_2)w^*_{v,\Delta\textbf{R}_{\rm cm}-\textbf{r}'/2}(\textbf{x}_2),
\end{align}
where the minus sign comes from electron anti-commutations and $\Delta\textbf{R}_{\rm cm}=\textbf{R}_{\rm cm,2}-\textbf{R}_{\rm cm,1}$.

Physically, each coordinate $\textbf{x}_i$ only takes significant non-zero values near the location of the Wannier functions which makes the $\mathcal{V}_D(\textbf{r},\textbf{r}')$ almost diagonal in the relative coordinate space. A simple estimate can be made by noticing that e.g., $w_{n,\textbf{R}}(\textbf{x})$ is upper bounded by $e^{-|\textbf{R}-\textbf{x}|/\xi_W}$. Therefore we have
\begin{equation}
    \begin{split}
    &|\mathcal{V}_D(\textbf{r},\textbf{r}')|<e^{-(|\Delta\textbf{R}_{\rm cm}+\textbf{r}'/2-\textbf{x}_1|+|\textbf{r}/2-\textbf{x}_1|+|-\textbf{r}/2-\textbf{x}_2|+|\Delta\textbf{R}_{\rm cm}-\textbf{r}'/2-\textbf{x}_2|)/\xi_W}\\
    &<e^{-(|(\Delta\textbf{R}_{\rm cm}+\textbf{r}'/2-\textbf{x}_1)-(\textbf{r}/2-\textbf{x}_1)+(-\textbf{r}/2-\textbf{x}_2)-(\Delta\textbf{R}_{\rm cm}-\textbf{r}'/2-\textbf{x}_2)|)/\xi_W}=e^{-(|\textbf{r}'-\textbf{r}|)/\xi_W}.        
    \end{split}
\end{equation}
This means that $\mathcal{V}_D(\textbf{r},\textbf{r}')$ is non-zero only when $\textbf{r}\sim\textbf{r}'$ (i.e., nearly diagonal in $\textbf{r}$). 

The exchange interaction is:
\begin{align}\label{eq:appendix_Vexchange}
  & \mathcal{V}_{X}(\textbf{r},\textbf{r}')=\sum\limits_{\Delta\textbf{R}_{\rm cm}}e^{i\textbf{Q}\cdot(\Delta\textbf{R}_{\rm cm})}\int d\textbf{x}_1d\textbf{x}_2 w_{c,\Delta\textbf{R}_{\rm cm}+\textbf{r}'/2}(\textbf{x}_1)w^*_{v,\Delta\textbf{R}_{\rm cm}-\textbf{r}'/2}(\textbf{x}_1)V(|\textbf{x}_1-\textbf{x}_2|)w_{v,-\textbf{r}/2}(\textbf{x}_2)w^*_{c,\textbf{r}/2}(\textbf{x}_2),
\end{align}

Since it is the exchange energy of \textbf{electron} and \textbf{hole}, the electron and hole should be close to have non negligible exchange (meaning that the relative coordinate should be small). For example if we only look at the product of Wannier functions with common coordinate $\textbf{x}_1$, then it is upper-bounded by:
\begin{align}
    &e^{-(|\Delta\textbf{R}_{cm}+\textbf{r}'/2-\textbf{x}_1|+|\Delta\textbf{R}_{\rm cm}-\textbf{r}'/2-\textbf{x}_1|)/\xi_W}<e^{-(|(\Delta\textbf{R}_{\rm cm}+\textbf{r}'/2-\textbf{x}_1)-(\Delta\textbf{R}_{\rm cm}-\textbf{r}'/2-\textbf{x}_1)|)/\xi_W}=e^{-|\textbf{r}'|/\xi_W}.
\end{align}
Similarly the product of Wannier functions with common coordinate $\textbf{x}_2$ is upper-bounded by $e^{-|\textbf{r}|/\xi_W}$:
\begin{align}
    &e^{-(|-\textbf{r}/2-\textbf{x}_2|+|\textbf{r}/2-\textbf{x}_2|)/\xi_W}<e^{-(|(-\textbf{r}/2-\textbf{x}_2)-(\textbf{r}/2-\textbf{x}_2)|)/\xi_W}=e^{-|\textbf{r}|/\xi_W}.
\end{align}

As a result, the full $\mathcal{V}_X(\textbf{r},\textbf{r}')$ is therefore upper bounded by $e^{-(|\textbf{r}|+|\textbf{r}'|)/\xi_W}$, meaning that it only concentrates near $|\textbf{r}|,|\textbf{r}'|\sim 0$. Furthermore we have $\mathcal{V}_X(\textbf{r},\textbf{r}')<e^{-(|\textbf{r}|+|\textbf{r}'|)/\xi_W}<e^{-|\textbf{r}-\textbf{r}'|/\xi_W}$, meaning $\mathcal{V}_X$ is still almost diagonal.

In summary, we have given the explicit form of Bethe-Salpeter Hamiltonian in relative coordinates as the sum of three terms $\mathcal{H}\equiv \mathcal{H}_{\textbf{K}}+\mathcal{V}_D+\mathcal{V}_X$ and verified the exponentially decaying $e^{-|\textbf{r}-\textbf{r}'|/\xi_W}$ of the off-diagonal elements $\mathcal{H}(\textbf{r},\textbf{r}')$.

\section{Flux insertion and the transformation rule of matrix elements}
Following Kohn\cite{kohn1964theory,souza2000polarization}, we introduce the following parameterized Hamiltonian on a periodic lattice with linear dimension $L$:  
\begin{equation}
   \hat{H}(\bm{\kappa})=\frac{1}{2m}\sum\limits_{i=1}^N(\hat{\textbf{p}}_i+\hbar \bm{\kappa})^2+\hat{V}_{\rm lattice}+\hat{H}_{\rm int},
\end{equation}
where $\bm{\kappa}$ is a uniform flux (units inverse length), $\hat{V}_{\rm lattice}$ is the lattice potential and $\hat{H}_{\rm int}$ describes electron-electron interactions. We label the $n$-th eigen-states of $\hat{H}(\bm{\kappa})$ as $\ket{\Phi_n(\bm{\kappa})}$. The vector $\bm{\kappa}$ can be interpreted as arising from the insertion of a flux through the ring formed along the periodic direction. Henceforth it will be referred to as a flux insertion or twisted boundary condition according to literature. 

From the free part (the sum of kinetic energy and $\hat{V}_{\rm lattice}$), we can solve for the Bloch functions and then Fourier transforming them to Wannier functions. Below we will %let's 
track the change of Wannier functions and the matrix elements of BSE Hamiltonian in the Wannier basis in response to flux insertion. As discussed in Ref.~\cite{luttinger1951effect,kohn1964theory}, the Wannier function corresponding to the free part after flux insertion is related to that before flux insertion via $w_{n,\textbf{R}}^{\bm \kappa}(\textbf{x})=e^{-i\bm{\kappa}\cdot(\textbf{x}-\textbf{R})}{w}_{n,\textbf{R}}(\textbf{x}).$ We shall denote the corresponding creation operator as $c^{\dagger}_{\bm{\kappa};n,\textbf{R}}$.

We now turn to analyzing the Hamiltonian terms under flux insertion. Any general particle-conserving one-body operator $\hat{G}\equiv \int d\textbf{x} a^{\dagger}_{\textbf{x}}G(\hat{\textbf{x}},\hat{\textbf{p}})a_{\textbf{x}}$ can be expressed in the Wannier basis as: 
\begin{align}
\hat{G}=\sum\limits_{n,m,\textbf{R},\textbf{R}'}\bra{n,\textbf{R}}\hat{G}\ket{m,\textbf{R}'}c^{\dagger}_{n,\textbf{R}}c_{m,\textbf{R}'},
\end{align}
with $\bra{n,\textbf{R}}\hat{G}\ket{m,\textbf{R}'}\equiv \int d\textbf{x}w^*_{n,\textbf{R}}(\textbf{x})G(\hat{\textbf{x}},\hat{\textbf{p}})w_{m,\textbf{R}'}(\textbf{x})$.

Upon inserting a uniform flux, the operator becomes: $\hat{G}^{\bm{\kappa}}= \int d\textbf{x} a^{\dagger}_{\textbf{x}}G(\hat{\textbf{x}},\hat{\textbf{p}}+\hbar\bm{\kappa})a_{\textbf{x}}$, and the matrix elements in the flux-inserted Wannier basis $\ket{\bm{\kappa};n,\textbf{R}}\equiv c^{\dagger}_{\bm{\kappa};n,\textbf{R}}\ket{0}$ are given by:
\begin{align}
&\int d\textbf{x}w^*_{n,\textbf{R}}(\textbf{x})e^{i\bm{\kappa}\cdot(\textbf{x}-\textbf{R})}G(\hat{\textbf{x}},\hat{\textbf{p}}+\hbar\bm{\kappa})e^{-i\bm{\kappa}\cdot(\textbf{x}-\textbf{R}')}w_{m,\textbf{R}'}(\textbf{x})=e^{-i\bm{\kappa}\cdot(\textbf{R}-\textbf{R}')}\int d\textbf{x}w^*_{n,\textbf{R}}(\textbf{x})G(\hat{\textbf{x}},\hat{\textbf{p}})w_{m,\textbf{R}'}(\textbf{x}),
\end{align}
where we have used $e^{i\bm{\kappa}\cdot\textbf{x}}G(\hat{\textbf{x}},\hat{\textbf{p}}+\hbar\bm{\kappa})e^{-i\bm{\kappa}\cdot\textbf{x}}=G(\hat{\textbf{x}},\hat{\textbf{p}})$ recalling that $(\hat{\textbf{p}} + \hbar \bm \kappa)e^{-i\bm \kappa \cdot \textbf{x}} = e^{-i\bm \kappa \cdot \textbf{x}} \hat{\textbf{p}}$. 

Thus, the full operator after flux insertion becomes : 
\begin{align}
\hat{G}^{\bm{\kappa}}=\sum\limits_{n,m,\textbf{R},\textbf{R}'}e^{-i\bm{\kappa}\cdot(\textbf{R}-\textbf{R}')}\bra{n,\textbf{R}}\hat{G}\ket{m,\textbf{R}'}c^{\dagger}_{\bm{\kappa};n,\textbf{R}}c_{\bm{\kappa};m,\textbf{R}'}
\end{align}


Similarly, for any general particle-conserving two-body operator $\hat{F}\equiv\int d\textbf{x}_1\int d\textbf{x}_2 a^{\dagger}_{\textbf{x}_1}a^{\dagger}_{\textbf{x}_2}F(\hat{\textbf{x}}_1,\hat{\textbf{x}}_2)a_{\textbf{x}_2}a_{\textbf{x}_1},$ the matrix element $\bra{\textbf{R}_1,\textbf{R}_2}\hat{F}\ket{\textbf{R}_3,\textbf{R}_4}$ in the Wannier basis transforms under flux insertion as:
\begin{equation}
\bra{\textbf{R}_1,\textbf{R}_2}\hat{F}\ket{\textbf{R}_3,\textbf{R}_4}\rightarrow e^{-i\bm{\kappa}\cdot(\textbf{R}_1+\textbf{R}_2-\textbf{R}_3-\textbf{R}_4)}\bra{\textbf{R}_1,\textbf{R}_2}\hat{F}\ket{\textbf{R}_3,\textbf{R}_4}. 
\end{equation}


For the BSE Hamiltonian, by directly substituting the flux-threaded Wannier functions into each of its terms, namely, $\mathcal{H}_{\textbf{K}}$, $\mathcal{V}_{D}$, $\mathcal{V}_{X}$, we obtain the following transformation rule of matrix elements $\mathcal{H}(\textbf{r},\textbf{r}')$ under flux insertion:
\begin{align}
   &\mathcal{H}^{\bm{\kappa}}(\textbf{r},\textbf{r}')= e^{-i\bm{\kappa}\cdot (\textbf{r}-\textbf{r}')}\mathcal{H}(\textbf{r},\textbf{r}'). 
\end{align}
where we have noted the opposite charge for electrons and holes in the BSE mean that fluxes accumulate through the relative coordinate $\textbf{r}$. 


\section{deviation estimation of the ansatz function for exciton states with flux insertion}
Let's first discuss how periodic boundary condition is implemented in BSE. To impose periodic boundary conditions, we restrict coordinates to $-L/2 < r_x < L/2$ and take $\bm{\kappa}$ along the $x$ direction. On a periodic lattice, the Bethe–Salpeter Hamiltonian is defined with the minimal distance:
\begin{align}
    \mathcal{H}(\textbf{r},\textbf{r}')\equiv \mathcal{H}(\textbf{r},\textbf{r}'+ML\textbf{e}_x), \text{ with }M \in \mathbb{Z} \text{  minimizing  } |r_x - r_x' - ML|.
\end{align}
Correspondingly, flux insertion modifies matrix elements by
\begin{align}
    \mathcal{H}^{\bm{\kappa}}(\textbf{r},\textbf{r}')=e^{-ik_x(r_x-r_x'-ML)}\mathcal{H}(\textbf{r},\textbf{r}')
\end{align}

For instance, when $r_x \lesssim L/2$ and $r_x' \gtrsim -L/2$, the minimal distance is $r_x - r_x' - L$ with $M = 1$.

We now proceed to estimate the deviation of the ansatz $\tilde{\psi}^{\bm{\kappa}}(\textbf{r}) = e^{-i\bm{\kappa} \cdot \textbf{r}} \psi(\textbf{r})$ for the exciton envelope function, we consider a bound state solution $\psi(\textbf{r})$ of the BSE at $\bm{\kappa}=0$ satisfying $\sum_{\bm r'} \mathcal{H} (\bm r,\bm r') \psi (\bm r') = E\psi (\bm r)$ and exponential decaying $|\psi(\textbf{r})| \sim e^{-|\textbf{r}|/\xi}$. Here and in what follows, we have suppressed the subscript $\bm Q$ for the center-of-mass momentum %$\bm{Q}$.  is suppressed %throughout, 
as it is conserved and decoupled from $\bm{\kappa}$. As we will see below, the key point is that the ansatz $\tilde{\psi}^{\bm{\kappa}}$ only violates the BSE near the boundaries $r_x \sim \pm L/2$, where the wavefunction is exponentially small. Thus, the deviation is exponentially suppressed in system size, making the ansatz asymptotically exact. 

%We now \addJS{proceed to confirm this intuition by} 
To see this explicitly, we quantify the deviation of the ansatz $\tilde{\psi}^{\bm{\kappa}}(\textbf{r})$ by examining the following deviation:
\begin{align}
\label{eq:SuppError}
\zeta(\textbf{r})\equiv\left| \sum_{\textbf{r}'} \mathcal{H}^{\bm{\kappa}}(\textbf{r}, \textbf{r}') \tilde{\psi}^{\bm{\kappa}}(\textbf{r}') - E \tilde{\psi}^{\bm{\kappa}}(\textbf{r}) \right|.
\end{align}
Without loss of generality, we assume $0 < r_x < L/2$. To evaluate $\zeta(\textbf{r})$, we split the sum over $\textbf{r}'$ into a \textit{bulk region} $\mathbb{R}_{\text{bulk}}$ where $|r_x - r_x'| < L/2$, and an \textit{edge region} $\mathbb{R}_{\text{edge}}$ where $|r_x - r_x'| > L/2$. The Hamiltonian matrix elements relate to those without flux as:
\[
\mathcal{H}^{\bm{\kappa}}(\textbf{r}, \textbf{r}') = 
\begin{cases}
e^{-i\bm{\kappa} \cdot (\textbf{r} - \textbf{r}')} \mathcal{H}(\textbf{r}, \textbf{r}'), & \textbf{r}' \in \mathbb{R}_{\text{bulk}}, \\
e^{-i\bm{\kappa} \cdot (\textbf{r} - \textbf{r}' - L \textbf{e}_x)} \mathcal{H}(\textbf{r}, \textbf{r}'), & \textbf{r}' \in \mathbb{R}_{\text{edge}}.
\end{cases}
\]

Inserting this into the flux-threaded equation yields:
\begin{align}
\sum_{\textbf{r}'} \mathcal{H}^{\bm{\kappa}}(\textbf{r}, \textbf{r}') \tilde{\psi}^{\bm{\kappa}}(\textbf{r}')
= e^{-i\bm{\kappa}\cdot \textbf{r}} \left[ \sum_{\mathbb{R}_{\text{bulk}}} \mathcal{H}(\textbf{r}, \textbf{r}') \psi(\textbf{r}') 
+ e^{i\kappa_x L} \sum_{\mathbb{R}_{\text{edge}}} \mathcal{H}(\textbf{r}, \textbf{r}') \psi(\textbf{r}') \right].
\end{align}
Subtracting $E\tilde{\psi}^{\bm{\kappa}} (\bm r)= e^{-i\bm{\kappa}\cdot \textbf{r}} E\psi(\textbf{r})$, we find that the deviation in Eq.~(\ref{eq:SuppError}) manifests in $\mathbb{R}_{\rm edge}$:
\begin{align}\label{appendix:error}
\zeta(\textbf{r})= \left| e^{-i\bm{\kappa} \cdot \textbf{r}} (e^{i\kappa_x L} - 1) \sum_{\mathbb{R}_{\text{edge}}} \mathcal{H}(\textbf{r}, \textbf{r}') \psi(\textbf{r}') \right|.
\end{align}

For localized exciton envelope functions, $\psi(\textbf{r}) \sim e^{-|\textbf{r}|/\xi}$ and $\mathcal{H}(\textbf{r}, \textbf{r}')$ decays with range $\xi_W$. Bounding the sum: %, we get:
\begin{align}
&\zeta(\textbf{r}) <|e^{i\kappa_xL}-1|\cdot e^{-|\textbf{r}-\textbf{r}'-L\textbf{e}_x|/\xi_W}\cdot e^{-|\textbf{r}'|/\xi}<|e^{i\kappa_xL}-1|\cdot e^{-|\textbf{r}-L\textbf{e}_x|/\xi_{M}}<|e^{i\kappa_xL}-1|\cdot e^{-L/(2\xi_{M})}
\end{align}
where $\xi_M = \max(\xi, \xi_W)$ and we used the triangular inequality and $0 < r_x < L/2$. This displays that deviation is exponentially suppressed.

As a result,  we arrive at % that $\tilde\psi^{\bm \kappa} (\bm r)$ is an exponentially good ansatz for the envelope wavefunction:} 
%Thus we arrive at the central result:
\begin{align}
\sum_{\textbf{r}'} \mathcal{H}^{\bm{\kappa}}(\textbf{r}, \textbf{r}') \tilde{\psi}^{\bm{\kappa}}(\textbf{r}') 
= E \tilde{\psi}^{\bm{\kappa}}(\textbf{r}) + \mathcal{O}(e^{-L / (2\xi_M)}),
\end{align}
or equivalently,
\begin{align}
\psi^{\bm{\kappa}}(\textbf{r}) = e^{-i\bm{\kappa} \cdot \textbf{r}} \psi(\textbf{r}) + \mathcal{O}(e^{-L / (2\xi_M)}),\qquad
E(\bm{\kappa}) = E(0) + \mathcal{O}(e^{-L / \xi_M}),
\end{align}
i.e., $\tilde{\psi}^{\bm{\kappa}}$ provides an exponentially accurate approximation to the true eigenstate $\psi^{\bm{\kappa}}$, with an energy shift that is exponentially suppressed. This mirrors the Thouless criterion for localized states vs delocalized states \cite{edwards1972numerical,thouless1974electrons,lee1985disordered}.

%By contrast, 

In contrast, note that %as for extended states such as plane waves ($|\psi(\textbf{r})| \sim L^{-d/2}$), 
Eq.~\eqref{appendix:error} remains valid for as for extended states such as plane waves envelopes ($|\psi(\textbf{r})| \sim L^{-d/2}$), when the form of the delocalized envelope for free particle-hole excitation is substituted, significant deviations occur. %However, 
Indeed, when $r_x \sim L/2$ and $r_x' \sim -L/2$, the amplitude $|\psi(\textbf{r}')| \sim L^{-d/2}$ leads to a sizable deviation:
\begin{align}
\zeta(\textbf{r}) \sim |e^{i\kappa_x L} - 1| \cdot \mathcal{O}(L^{-d/2}),
\end{align}
which constitutes a non-negligible correction for an extended envelope function. Thus, for extended states the ansatz $\tilde{\psi}_{\bm{\kappa}}$ fails to solve the flux-threaded Bethe–Salpeter equation. This %reflects 
mirrors %is often referred to as 
the breakdown of ``gauge invariance” for extended states in a periodic system~\cite{kohn1964theory}.




\section{Insensitivity of exciton transition shift vector vs. $\hat{V}$}
In this section, we first prove in general that the exciton transition shift vector is insensitive to the form of an interaction $\hat{V}$ inducing the transition from ground state to exciton state; we then extend it to show that transitions between excitonic states are also insensitive to the form of $\hat{V}$. To that end, we consider exciton shift vectors induced by two general particle-conserving interactions $\hat{V}_1$ and $\hat{V}_2$ and evaluate their differences $\delta \bm{\mathcal{R}} = \bm{\mathcal{R}}^{V_1}_{0\rightarrow {\rm ex}}-\bm{\mathcal{R}}^{V_2}_{0\rightarrow {\rm ex}}$, which amounts to proving Eq.~\eqref{eq:shift_vector_difference} of the main text.

For any particle-conserving one-body interaction $\hat{V}_1$, we can expand them in the Wannier basis as $\hat{V}_1\equiv \sum\limits_{\textbf{R},\textbf{R}'}(V_{1})_{\textbf{R},\textbf{R}'}^{n,m}c^{\dagger}_{n,\textbf{R}}c_{m,\textbf{R}'}$, where $n,m$ are band indices. (The treatment of particle-conserving two-body interaction is exactly the same.) Following the previous discussion, the matrix elements transform as $(V_1)^{n,m}_{\textbf{R},\textbf{R}'}\rightarrow e^{-i\bm{\kappa}\cdot (\textbf{R}-\textbf{R}')}(V_1)^{n,m}_{\textbf{R},\textbf{R}'}$ under flux insertion. The transformation rule holds only for particle-conserving interactions and is violated in particle-non-conserving interactions such as $c^{\dagger}c^{\dagger}$, as expected in a superconductor. 

The matrix element of $\bra{\Phi_0(\bm{\kappa})}\hat{V}_1\ket{\Phi_{\text{ex}}(\bm{\kappa})}$ can then be evaluated with Wick's theorem and yields $\sum\limits_{\textbf{R},\textbf{R}'}e^{i\textbf{Q}\cdot (\textbf{R}+\textbf{R}')/2}(V_1)_{\textbf{R},\textbf{R}'}^{v,c}\psi_{\textbf{Q}}(\textbf{R}'-\textbf{R})$, which is independent of $\bm{\kappa}$ (with a deviation $\mathcal{O}(e^{-L/(2\xi_M)})$ from the envelope function) as the phase change of $(V_1)^{v,c}_{\textbf{R},\textbf{R}'}$ and $\psi_{\textbf{Q}}(\textbf{R}'-\textbf{R})$ arising from flux insertion exactly cancels. Similarly we can show that $\bra{\Phi_{\text{ex}}(\bm{\kappa})}\hat{V}_2\ket{\Phi_0(\bm{\kappa})}$ is also independent of $\bm{\kappa}$ also with a deviation $\mathcal{O}(e^{-L/(2\xi_M)})$. Although each term $\bra{\Phi_0(\bm{\kappa})}\hat{V}_1\ket{\Phi_{\text{ex}}(\bm{\kappa})}$ and $\bra{\Phi_{\text{ex}}(\bm{\kappa})}\hat{V}_2\ket{\Phi_0(\bm{\kappa})}$ are both gauge dependent, their product is gauge invariant and is independent of $\bm{\kappa}$ with a combined deviation $\mathcal{O}(e^{-L/\xi_M})$. Therefore we arrive at Eq.~\eqref{eq:shift_vector_difference} shown in the main text:
\begin{equation}
\begin{split}
&\bm{\mathcal{R}}^{V_1}_{0\rightarrow \text{ex}}-\bm{\mathcal{R}}^{V_2}_{0\rightarrow \text{ex}}=\nabla_{\bm{\kappa}}\text{arg}(\bra{\Phi_0({\bm{\kappa}})}\hat{V}_1\ket{\Phi_{\text{ex}}({\bm{\kappa}})}\bra{\Phi_{\text{ex}}({\bm{\kappa}})}\hat{V}_2\ket{\Phi_0({\bm{\kappa}})})=\mathcal{O}(e^{-L/\xi_M}).
\end{split}
\end{equation}

Furthermore, we can establish the following relation for the shift vector between two excitons ex$_1$ and ex$_2$: 
\begin{align}
\bm{\mathcal{R}}^{V_{1 2}}_{\text{ex}_1\rightarrow \text{ex}_2}\doteq\bm{\mathcal{R}}^{V_{02}}_{0\rightarrow \text{ex}_2}-\bm{\mathcal{R}}^{V_{01}}_{0\rightarrow \text{ex}_1}. 
\end{align}
This reduces to showing that $\nabla_{\bm{\kappa}}\text{arg}(\bra{\Phi_0({\bm{\kappa}})}\hat{V}_{01}\ket{\Phi_{\text{ex}_1}({\bm{\kappa}})}\bra{\Phi_{\text{ex}_1}({\bm{\kappa}})}\hat{V}_{12}\ket{\Phi_{\text{ex}_2}({\bm{\kappa}})}\bra{\Phi_{\text{ex}_2}({\bm{\kappa}})}\hat{V}_{02}\ket{\Phi_0({\bm{\kappa}})})\doteq 0$, which can be demonstrated in the same manner as before, with a deviation of order $\mathcal{O}(e^{-2L/\xi_M})$, arising from the four appearances of the exciton envelope functions in the full Wilson loop. 

\section{Intrinsic expression for exciton transition shift vector}
We evaluate the exciton shift vector using the exciton wave function $\ket{\psi_{\bm{Q}}}=\frac{1}{\sqrt{N}}\sum\limits_{\textbf{r},\textbf{R}_{\rm cm}}\psi_{\bm{Q}}(\textbf{r})e^{i\bm{Q}\cdot\textbf{R}_{\rm cm}}\ket{\textbf{R}_{\rm cm},\textbf{r}}$ along with the definition of the shift vector:
\begin{align}
\bm{\mathcal{R}}_{0n}\equiv i\bra{\Phi_n}\nabla_{\bm{\kappa}}\ket{\Phi_n}-i\bra{\Phi_0}\nabla_{\bm{\kappa}}\ket{\Phi_0}+\nabla_{\bm{\kappa}}\text{arg}(\bra{\Phi_0}\hat{V}\ket{\Phi_n}).
\end{align}

Under flux insertion, the Wannier functions transform as $w_{\textbf{R}}(\textbf{x})\rightarrow w^{\bm{\kappa}}_{\textbf{R}}(\textbf{x})=e^{-i\bm{\kappa}\cdot(\textbf{x}-\textbf{R})}w_{\textbf{R}}(\bm{x})$. Let's denote the corresponding creation operator as $c^{\dagger}_{\bm{\kappa};\textbf{R}}$. 
%\addJS{And we have fixed a gauge where the flux-inserted envelope function transforms as $\psi_{\bm{Q}}^{\bm{\kappa}}(\textbf{r})=e^{-i\bm{\kappa}\cdot\textbf{r}}\psi_{\bm{Q}}(\textbf{r})$. It has been shown that $\nabla_{\bm{\kappa}}\text{arg}(\bra{\Phi_0}\hat{V}\ket{\Phi_n})=0$ in this gauge choice. \addJS{[{\bf JS}: why is this a gauge choice??]} Therefore we only need to evaluate the first two terms.}

Under flux insertion we can write the exciton state as % becomes:
\begin{align}
\ket{\psi^{\bm{\kappa}}_{\bm{Q}}}=\frac{1}{\sqrt{N}}\sum\limits_{\textbf{r},\textbf{R}_{\rm cm}}\psi^{\bm{\kappa}}_{\bm{Q}}(\textbf{r})e^{i\bm{Q}\cdot\textbf{R}_{\rm cm}}c^{\dagger}_{\bm{\kappa};c,\textbf{R}_{\rm cm}+\textbf{r}/2}c_{\bm{\kappa};v,\textbf{R}_{\rm cm}-\textbf{r}/2}\ket{\rm GS;\bm{\kappa}},
\end{align}
where $\ket{\text{GS};\bm{\kappa}}=\prod_{\textbf{R}}c^{\dagger}_{\bm{\kappa};v,\textbf{R}}\ket{0}$. Recalling that $\psi_{\bm{Q}}^{\bm{\kappa}}(\textbf{r})=e^{-i\bm{\kappa}\cdot\textbf{r}}\psi_{\bm{Q}}(\textbf{r})$, we find the exciton transition shift vector is 
%
%
%The contribution from $\nabla_{\bm{\kappa}}\ket{\text{GS};\bm{\kappa}}$ cancels out in the subtraction $i\bra{\Phi_n}\nabla_{\bm{\kappa}}\ket{\Phi_n}-i\bra{\Phi_0}\nabla_{\bm{\kappa}}\ket{\Phi_0}$, therefore we only need to evaluate the following:
\begin{align}
    \bm{\mathcal{R}}_{0\rightarrow \rm ex}\doteq i\bra{\psi^{\bm{\kappa}}_{\bm{Q}}}\nabla_{\bm{\kappa}}\big[\frac{1}{\sqrt{N}}\sum\limits_{\textbf{r},\textbf{R}_{\rm cm}}\psi^{\bm{\kappa}}_{\bm{Q}}(\textbf{r})e^{i\bm{Q}\cdot\textbf{R}_{\rm cm}}c^{\dagger}_{\bm{\kappa};c,\textbf{R}_{\rm cm}+\textbf{r}/2}c_{\bm{\kappa};v,\textbf{R}_{\rm cm}-\textbf{r}/2}\big]\ket{\text{GS};\bm{\kappa}},
    \label{eq:IntermediateShiftIntrinsic}
\end{align}
which, as we will see below, can be delineated into three physically meaningful terms. In obtaining Eq.~(\ref{eq:IntermediateShiftIntrinsic}) we have recalled the transformation properties from the previous section. 

\textbf{Wannier center part:} The first term is obtained by acting $\nabla_{\bm{\kappa}}$ on $\psi^{\bm{\kappa}}_{\bm{Q}}(\textbf{r})$, which yields:
\begin{align}
\sum\limits_{\textbf{r}}\textbf{r}|\psi_{\bm{Q}}(\textbf{r})|^2\equiv \sum\limits_{\textbf{r}}\rho(\textbf{r},\textbf{r})\textbf{r},
\end{align}
where we have used the exciton envelope function’s reduced density matrix $\rho(\textbf{r},\textbf{r}') = \psi^*_{\bm{Q}}(\textbf{r}) \psi_{\bm{Q}}(\textbf{r}')$. This term originates from the polarization contributions of electrons and holes localized at their respective Wannier centers and appears as a diagonal component in $\rho$. 

\textbf{Electron cloud correction:} The second term is obtained from taking derivative of $\bm{\kappa}$ with $c^{\dagger}_{\bm{\kappa};c,\textbf{R}_{cm}+\textbf{r}/2}$. After a straightforward evaluation we arrive at:
\begin{align}
&\sum\limits_{\textbf{r},\textbf{r}'}\rho(\textbf{r},\textbf{r}')e^{i\bm{Q}\cdot(\textbf{r}'-\textbf{r})/2}\int d\textbf{x}w^*_{c,\textbf{r}}(\textbf{x})(\textbf{x}-\textbf{r}')w_{c,\textbf{r}'}(\textbf{x})=\sum\limits_{\textbf{r},\textbf{r}'}\rho(\textbf{r},\textbf{r}')e^{i\bm{Q}\cdot(\textbf{r}'-\textbf{r})/2}
\bm{d}_c(\textbf{r}'-\textbf{r}),
\end{align}
where in the last equality we have noted the translational symmetry of  Wannier functions as well as 
utilized the dipole matrix element in the Wannier basis as defined in Ref.\cite{marzari1997maximally}: $\int w^*_{c,\textbf{0}}(\textbf{x})\hat{\textbf{x}}w_{c,\textbf{R}}(\textbf{x})=\bm{d}_c(\textbf{R})$.
The off-diagonal component of density matrix $\rho(\textbf{r},\textbf{r}')$ indicates the probability of electron and hole Wannier centers are $\textbf{r}$ apart and the electrons are found at $\textbf{r}'$. The $e^{i\bm{Q}\cdot(\textbf{r}'-\textbf{r})/2}$ factor is due to an effective shift of the center-of-mass coordinate due to the electron cloud. 

The physical meaning is clear: this term captures the polarization correction from the spatial spread of conduction-band Wannier orbitals with the dipole operator reflecting charge distribution. This can be confirmed by noting that if Wannier functions $w_{c,\textbf{R}}(\textbf{x})$ are strongly localized at $\textbf{R}$, this term will be vanishingly small. 

\textbf{Hole cloud correction:} The third term is obtained from taking the derivative of $\bm{\kappa}$ with $c_{\bm{\kappa};v,\textbf{R}_{cm}-\textbf{r}/2}$ producing: 
\begin{align}
&-\sum\limits_{\textbf{r},\textbf{r}'}\rho(\textbf{r},\textbf{r}')e^{i\bm{Q}\cdot(\textbf{r}-\textbf{r}')/2}\int d\textbf{x}w^*_{v,\textbf{r}}(\textbf{x})(\textbf{x}-\textbf{r})w_{v,\textbf{r}'}(\textbf{x})=-\sum\limits_{\textbf{r},\textbf{r}'} \rho(\textbf{r},\textbf{r}')e^{i\bm{Q}\cdot(\textbf{r}-\textbf{r}')/2}%\bm{\mathcal{R}}
\bm{d}_{v}(\textbf{r}'-\textbf{r}) .
\end{align}

Similar to the electron case, this term is the correction to polarization due to the spatial spreading of hole Wannier orbitals from the valence band. Similar to above, the $e^{i\bm{Q}\cdot(\textbf{r}-\textbf{r}')/2}$ factor arises from a an effective shift of center-of-mass coordinates.

Combining these three terms together, we arrive at the following compact expression for the exciton shift vector:
\begin{align}
\bm{\mathcal{R}}_{0\rightarrow ex}\doteq\sum\limits_{\textbf{r},\textbf{r}'}\rho(\textbf{r},\textbf{r}')\big[ \textbf{r}\delta_{\textbf{r},\textbf{r}'}+e^{i\bm{Q}\cdot(\textbf{r}'-\textbf{r})/2}%\bm{\mathcal{R}}
\bm{d}_c(\textbf{r}'-\textbf{r}) -e^{i\bm{Q}\cdot(\textbf{r}-\textbf{r}')/2}%\bm{\mathcal{R}}
\bm{d}_v(\textbf{r}'-\textbf{r})\big].
\label{eq:ShiftIntrinsicSupp}
\end{align}

Notice that in a periodic system, the relative position $\textbf{r}$ is inherently ambiguous due to the periodic boundary conditions. 
However, due to the localized nature of the exciton envelope function $\psi(\textbf{r})$ (and thus the reduced density matrix $\rho$), $\textbf{r}$ only needs to be defined near the origin: close to the boundaries the amplitude of the exciton envelope is small rendering any ambiguity arising from the position of $\textbf{r}$ exponentially suppressed. We emphasize that the expression above in Eq.~(\ref{eq:ShiftIntrinsicSupp}) only works for localized particle-hole excitations: it immediately fails for delocalized particle-hole excitations. This is directly connected to the ill-defined nature of the position operator under periodic boundary conditions~\cite{resta1998quantum}. 


