	\input{./festl-chap3_cntrl_plant_dc.tex} 
	\caption{Structure of the controlled system with dead time in the plant and a dead-time compensation to modify the control feedback $\boldsymbol{y}_\text{del}$.}
	\label{fig:cntrl_plant_dc} 
\end{figure}

\subsection{Nonlinear motion prediction}

For predicting the undelayed plant output $\hat{\boldsymbol{y}}$ we use a plant model to compute future states. The plant model is a kinematic singletrack model \eqref{eqn:kin0}. 
When the controller is implemented in discrete time, the steering angle $\delta$ is constant during one timestep. The plant model resembles the discrete formulation of the plant \eqref{eqn:kin_del} without dead time, thus yielding the future state predictions $\boldsymbol{\hat y}\approx \boldsymbol{y}_\text{del}\cdot q^k$. With $\dot\psi = \tan(\delta)/l\cdot v$ we can write:
\begin{subequations}
    \label{eqn:pos_approx}
    \begin{align}
    \begin{split}
\boldsymbol{\hat p}_{i+1} - \boldsymbol{\hat p}_{i} &= \int_0^{\Delta t} \begin{bmatrix}
\cos(\hat\psi_{i} +\dot\psi_i\cdot \tau)\\ \sin(\hat\psi_{i} +\dot\psi_i\cdot \tau)
\end{bmatrix} \cdot v\cdot d\tau 
= \int_0^{\Delta t} \boldsymbol{R}(\hat\psi_{i})\cdot \begin{bmatrix}
\cos(\dot\psi_i\cdot \tau)\\ \sin(\dot\psi_i\cdot \tau)
\end{bmatrix} \cdot v\cdot d\tau \\
 &= \boldsymbol{R}(\hat\psi_{i})\cdot \begin{bmatrix}
    \sin(\dot\psi_i\cdot \Delta t) \\ (1-\cos(\dot\psi_i\cdot \Delta t))
\end{bmatrix}\cdot \frac{v}{\dot\psi_i}
\end{split}\\
\hat\psi_{i+1} &= \hat\psi_{i} + \dot\psi \cdot \Delta t \\
\boldsymbol{\hat y}_{i} &= \boldsymbol{\hat x}_{i} = \begin{bmatrix}
    \boldsymbol{\hat p}_{i} & \hat\psi_{i}
\end{bmatrix}^T
\end{align}
\end{subequations}


% \begin{subequations}
%     \label{eqn:pos_approx}
%     \begin{align}
%     \begin{split}
% \boldsymbol{p}_{i+k} - \boldsymbol{p}_i &\doteq \int_0^{k\cdot\Delta t} \begin{bmatrix}
% \cos(\psi_i +\dot\psi\cdot \tau)\\ \sin(\psi_i +\dot\psi^j\cdot \tau)
% \end{bmatrix} \cdot d\tau = \sum_{j=i}_{i+k} \int_0^{\Delta t} \begin{bmatrix}
% \cos(\psi^j +\dot\psi^j \cdot \tau)\\ \sin(\psi^j +\dot\psi^j \cdot \tau)
% \end{bmatrix} \cdot d\tau \\
% &= %\sum_{j=i}_{i+k} \boldsymbol{R}(\psi^j)\cdot \int_0^{\Delta t} \begin{bmatrix}
% %\cos(\dot\psi\cdot \tau)\\ \sin(\dot\psi\cdot \tau)
% %\end{bmatrix} \cdot d\tau =
%  \sum_{j=i}_{i+k} \frac{\boldsymbol{R}(\psi^j)}{\dot\psi^j}\cdot \begin{bmatrix}
%     \sin(\dot\psi^j\cdot \Delta t) \\ (1-\cos(\dot\psi^j\cdot \Delta t))
% \end{bmatrix}
% \end{split}\\
% \psi_{i+k} - \psi_i &\doteq \sum_{j=i}_{i+k}\frac{\tan(\delta^j)}{l}\cdot\Delta t
% \end{align}
% \end{subequations}
% explain the doteq?

Where $\boldsymbol{R}$ is the rotation matrix:
\begin{equation}
    \boldsymbol{R}(\psi) = \begin{bmatrix}
        \cos(\psi) & -\sin(\psi) \\
        \sin(\psi) & \cos(\psi)
    \end{bmatrix}
\end{equation}

The plant model \eqref{eqn:pos_approx} is not internally stable (the state $\boldsymbol{\hat x}$ and output $\boldsymbol{\hat y}$ are ramp functions at steady state). In this case, a Smith predictor without modification is not applicable as $\boldsymbol{\hat y}$ will diverge \cite{smith}. There are solutions to regain internal stability as explained in \cite{hoelzl}. In this chapter, we will derive a prediction model that enables a suitable approximation of the future state despite divergence of $\boldsymbol{\hat y}$. This model is then modified to gain internal stability.

Independent of divergence of $\boldsymbol{\hat y}$, for small $k$\footnote{The error between the real vehicle dynamics and the stated kinematic approximation will accumulate over the steps $k$. Thus, for large $k$, the approximation will become inacurate.} we can state:

\begin{subequations}
\begin{align}
\boldsymbol{\hat p}_{i} - \boldsymbol{\hat p}_{i-k} &= \sum_{j=i}^{i+k}\boldsymbol{R}(\hat \psi_{j-k})\cdot \begin{bmatrix}
	\sin(\dot\psi_{j-k}\cdot\Delta t) \\ 1-\cos(\dot\psi_{j-k}\cdot\Delta t)
\end{bmatrix} \cdot \frac{v}{\dot\psi_{j-k}}\\
\boldsymbol{p}_{i+k} - \boldsymbol{p}_i &\doteq 
\sum_{j=i}^{i+k}\boldsymbol{R}(\psi_{j})\cdot \begin{bmatrix}
	\sin(\dot\psi_{j-k}\cdot\Delta t) \\ 1-\cos(\dot\psi_{j-k}\cdot\Delta t)
\end{bmatrix}\cdot \frac{v}{\dot\psi_{j-k}}\\
  \hat\psi_{i} - \hat\psi_{i-k} &= \sum_{j=i}^{i+k}\dot\psi_{j-k}\cdot \Delta t \doteq \psi_{i+k} - \psi_{i} \label{eqn:psi}
\end{align}
\end{subequations}
From \eqref{eqn:psi} follows for $j\in [i,i+k]$:
\begin{equation}
\psi_{i} - \hat\psi_{i-k} \doteq \psi_{j} - \hat\psi_{j-k} 
\end{equation}
Thus we can conclude:
\begin{equation}
\begin{split}
\boldsymbol{R}(\psi_i - \hat\psi_{i-k})\cdot\left(\boldsymbol{\hat p}_{i} - \boldsymbol{\hat p}_{i-k}\right) &\doteq \sum_{j=i}^{i+k}\boldsymbol{R}(\psi_{j} - \hat\psi_{j-k} + \hat \psi_{j-k})\cdot \begin{bmatrix}
	\sin(\dot\psi_{j-k}\cdot\Delta t) \\ 1-\cos(\dot\psi_{j-k}\cdot\Delta t)
\end{bmatrix}\cdot \frac{v}{\dot\psi_{j-k}} \\ &\doteq \boldsymbol{p}_{i+k} - \boldsymbol{p}_i,
\end{split}
\end{equation}
which leads to the state prediction:
\begin{equation}\label{eqn:statepred}
    \boldsymbol{x}_{i+k} \doteq \boldsymbol{x}_i + \begin{bmatrix}
        \boldsymbol{R}(\psi_{i} - \hat\psi_{i-k})\\ 1
    \end{bmatrix}^T \cdot (\boldsymbol{\hat x}_{i} - \boldsymbol{\hat x}_{i-k})
\end{equation}

This matches the structure of the Smith predictor except for the rotational transformation. The structure is also shown in Fig.~\ref{fig:deadtime_chart}.
However, keep in mind that the underlying assumptions are different to the Smith predictor and consequently the behavior is different. The Smith predictor requires a stable plant such that the plant model state $\boldsymbol{\hat x}$ will not diverge. In our approach, we apply the dead-time compensation on an unstable plant, resulting in a possible divergence of $\boldsymbol{\hat x}$. Due to the special structure of the plant model, we can transform the prediction $\Delta \boldsymbol{\hat x} = \boldsymbol{\hat x}_{i} - \boldsymbol{\hat x}_{i-k}$ to account for the difference $\boldsymbol{\hat x}_{i-k} - \boldsymbol{x}_i$. This concept is illustrated in Fig.~\ref{fig:smith_coordinates}. The position prediction $\Delta \boldsymbol{\hat p}$ is transformed from the prediction model coordinate frame $\hat T$ to the vehicle coordinate frame $T$.

