        Q_n^{2, 1}Q_n^{1, 0}(Q_n^{2, 1}Q_n^{0, 1}) & -3(3) & -1(1) & 0 & 0 \\ \hline
        Q_n^{1, 2}Q_n^{1, 0}(Q_n^{1, 2}Q_n^{0, 1}) & 3(-3) & -1(1) & 0 & -6(6) \\ \hline
        Q_n^{0, 3}Q_n^{1, 0}(Q_n^{0, 3}Q_n^{0, 1}) & -1(1) & 1(-1) & -1(1) & 0 \\ \hline
