        Q_n^{2, 0}Q_n^{2, 0}(Q_n^{0, 2}Q_n^{0, 2}) & 1(-1) & 1(-1) & 6(-6) \\ \hline
        Q_n^{2, 0}Q_n^{0, 2}(Q_n^{0, 2}Q_n^{2, 0}) & -1(1) & 1(-1) & 0 \\ \hline
        Q_n^{1, 1}Q_n^{2, 0}(Q_n^{1, 1}Q_n^{0, 2}) & -2(2) & 0 & -6(6) \\ \hline
        Q_n^{2, 0}Q_n^{1, 1}(Q_n^{0, 2}Q_n^{1, 1}) & 0 & -2(2) & -6(6) \\ \hline
