\title{Extracting Nonlinear Dynamical Response Functions from Time Evolution}
%\author{\mbox{Atsushi Ono}\,\orcidlink{0000-0002-8813-4470}}
\author{\mbox{Atsushi Ono}}
\affiliation{\mbox{Department of Physics, Tohoku University, Sendai 980-8578, Japan}}
