\subsection{\texorpdfstring{Abundance $\beta(M)$ and Fraction of Dark Matter}{Abundance beta(M) and Fraction of Dark Matter}}

The mass fraction collapsing at formation is
\begin{equation}
\beta(M)
  \;=\;
  \int_{\delta_{\rm c}}^{\infty}
  \frac{d\delta}{\sqrt{2\pi}\,\sigma_{S}(k)}
  \exp\!\left[-\frac{\delta^{2}}{2\sigma_{S}^{2}(k)}\right],
\label{eq:beta_def}
\end{equation}
where $\sigma_{S}^{2}(k)\equiv\lambda^{2}P_{S}(k)$,  
$k$ is related to $M$ by Eq.\,\eqref{eq:k_M_relation}, and
$\delta_{\rm c}\simeq0.3$ (Section~\ref{sec:linear}).  
Figure~\ref{fig:sigmaS} shows $\sigma_{S}(k)$ for a representative
parameter set, highlighting its steep rise toward small scales.

For a power-law imprint spectrum
$P_{S}(k)=A_{S}(k/k_{*})^{\,n_{S}^{(S)}-1}$ the variance grows on small
scales, and $\beta(M)$ becomes sharply peaked near a characteristic mass
$M_{\rm peak}$:
\begin{equation}
\beta(M)
  \;\approx\;
  \frac{\sigma_{S}(k)}{\sqrt{2\pi}\,\delta_{\rm c}}
  \exp\!\biggl[-\frac{\delta_{\rm c}^{2}}
                     {2\sigma_{S}^{2}(k)}\biggr].
\label{eq:beta_approx}
\end{equation}
The present-day PBH density fraction is
\begin{equation}
f_{\rm PBH}(M)
  \;=\;
  \frac{\Omega_{\rm PBH}(M)}{\Omega_{\rm DM}}
  \;=\;7.8\times10^{8}\,
  \!\left(\frac{\gamma}{0.2}\right)^{1/2}
  \!\!\left(\frac{g_{*}}{106.75}\right)^{-1/4}
  \!\!\left(\frac{M}{M_\odot}\right)^{-1/2}\!\!\beta(M),
\label{eq:fpbh}
\end{equation}
where the prefactor accounts for entropy dilution from $T_{\rm re}$ to
matter–radiation equality \cite{SasakiEtAl2018}.  
Consequently,

\begin{itemize}
  \item \emph{Amplitude.}  A coupling $\lambda\sim1$ and
        $A_{S}^{1/2}\sim10^{-3}$ yield $\beta\sim10^{-9}$, enough for
        PBHs to constitute the dominant dark-matter component at
        $M_{\rm PBH}\sim10^{-12}\,M_\odot$ while obeying microlensing
        limits (Figure~\ref{fig:fPBH}).
  \item \emph{Tilt.}  A blue tilt $n_{S}^{(S)}\gtrsim1.2$ shifts
        $M_{\rm peak}$ into the $10$–$100\,M_\odot$ range probed by
        LIGO–Virgo, as also illustrated in
        Figure~\ref{fig:fPBH}.
\end{itemize}
Parameter scans in Section~\ref{sec:observations} overlay these
predictions with current PTA, CMB, and microlensing constraints.

