\section{Numerical Setup for Bounce–to–PBH Simulations}
\label{app:numerics}

\subsection{\texorpdfstring{Modified Boltzmann Code (\textsc{CLASS}/\textsc{CAMB})}{Modified Boltzmann Code (CLASS/CAMB)}}

\begin{enumerate}
\item \textbf{New fluid.}  
      Add a pressureless species \texttt{qmm} with energy density
      \(\rho_{\rm QMM}(a)=\lambda(\dot S^{2}+(\nabla S)^{2}/a^{2})/2\).
\item \textbf{Perturbations.}  
      Integrate Eqs.\,( \ref{eq:delta_QMM_eom} ) for each $k$ in
      \texttt{perturb\_sources.c}, sourcing metric potentials alongside
      CDM and baryons.
\item \textbf{Initial conditions.}  
      Sample $P_{S}(k)$ at the bounce scale factor $a_{\rm B}$, rescale
      to $a_{\rm init}=10^{-8}$, and impose
      \(\delta_{\rm QMM}(k,a_{\rm init})=C_{1}(k)\,a_{\rm init}/a_{\rm B}\).
\item \textbf{Background module.}  
      Insert $\rho_{\rm QMM}(a)$ into the Friedmann integrator; ensure
      the stiff term $\dot S^{2}$ is updated with a Runge–Kutta wrapper.
\item \textbf{Validation.}  
      Recover $\Lambda$CDM spectra when \(\lambda\to0\) and replicate
      CAMB’s $\ell$–spectra within $0.1\%$ for standard parameters.
\end{enumerate}

\subsection{N-Body with Live \texorpdfstring{$S$}{S}-Grid}

\begin{itemize}
\item \textbf{Code base.}  
      Fork \textsc{Gadget-4} to include a lattice field $S$ stored on the
      same PM grid as the density assignment.
\item \textbf{Equations of motion.}  
      Advance particles with
      \(\ddot{\bm x}=-\nabla(\Phi+\Phi_{\rm QMM})\),
      where $\nabla^{2}\Phi_{\rm QMM}=4\pi G\rho_{\rm QMM}$; update
      \(\rho_{\rm QMM}\) each step via
      \(\rho_{\rm QMM}=\lambda[(\nabla S)^{2}+a^{2}\dot S^{2}]/2\).
\item \textbf{Grid resolution.}  
      $N_{\rm grid}=2048^{3}$ for a $L=500\,h^{-1}{\rm Mpc}$ box gives
      $\sim100$ cells per comoving PBH Jeans length at
      $T_{\rm re}=10^{5}\,{\rm GeV}$.
\item \textbf{Time stepping.}  
      Use a global $\Delta a=2\times10^{-3}$ until
      $a=10^{-2}$, then individual particle and field time steps
      satisfying $\Delta t\le0.02H^{-1}$.
\item \textbf{Convergence tests.}  
      Halve $\Delta a$, double $N_{\rm grid}$, and confirm PBH mass
      function changes $\le5\%$.  Compare with one-dimensional
      high-resolution collapse to verify critical exponent recovery.
\end{itemize}


