\begin{definition}
    For any $t > 0$ and instance $\mathcal{I}$ the value of the optimal omniscient policy is:
    \begin{equation}
        \offoptt = \max_{\pi} V(\pi, \m{I}, t). 
    \end{equation}
\end{definition}
For policy $\pi$, we let $X_{ij}^\pi(t)$ be a counting process that tracks the number of $(i,j)$ matches:
\begin{equation}
    X_{ij}^\pi(t) = |\{(a,b) \in \pi(\m{H}(t)) \ | \ i_a = i, i_b = j, t_a < t_b\}|.
\end{equation}



