    Given any $\beta \in (0,1)$ define $(\hat{{\bf n}}, \hat{{\bf x}}, \hat{\bm{\psi}})$ as follows:
    \begin{align}
        \hat{x}_{ij} &= \frac{x_{ij} - \beta x_{ij}^\pi}{1-\beta} & \quad \forall (i,j) \in \m{M}, \\
        \hat{n}_i &= \frac{\lambda_i - \sum_{j \in \m{T}: (i,j) \in \m{M}}\hat{x}_{ij} - \sum_{j\in\m{T} : (j,i) \in \m{M}}\hat{x}_{ji} }{\mu_i} & \quad \forall i \in \m{T},\label{eq:hatni}\\
        \hat{\psi}_{Sj} &= \lambda_j \gamma_S \sum_{i \in S} \hat{n}_i - \sum_{i \in S} \hat{x}_{ij} & \quad \forall j \in \m{T}, S \subseteq T(M,j). \label{eq:hatpsiSj}
    \end{align}
    We will show that $(\hat{{\bf n}}, \hat{{\bf x}}, \hat{\bm{\psi}})$ is feasible for all sufficiently small $\beta$. By construction we can see that constraints \eqref{eq:balance-lp-glb} and \eqref{eq:match-rate-lp-glb} of $\plpm$ hold, so it remains to show that \eqref{eq:nonnegative-lp-glb} holds: $\hat{x}_{ij}$ and $\hat{\psi}_{Sj}$ are non-negative.

     If $x_{ij} = 0$, then because $({\bf n}, {\bf x}, \bm{\psi})$  is suitable, we know for any $S$ that contains $i$, $\psi_{Sj} > 0$, and therefore in the greedy policy $\pi$, $i$ is not acceptable to $j$. Therefore $x_{ij}^\pi = 0$ and $\hat{x}_{ij} = 0$. Meanwhile, if $x_{ij} > 0$, then $\hat{x}_{ij} > 0$ for all sufficiently small $\beta$.

    It remains to show that $\hat{\psi}_{Sj} \ge 0$. We start by rewriting \eqref{eq:hatni} and \eqref{eq:hatpsiSj} as follows.
      \begin{align}
        \hat{n}_i & = \frac{n_i - \beta n_i^\pi}{1-\beta}.\label{eq:equalunmatchedrate} \\
        \hat{\psi}_{Sj} & = \frac{\psi_{Sj} - \beta(\lambda_j\gamma_S \sum_{i \in S} n_i^\pi - \sum_{i \in S} x_{ij}^\pi)}{1-\beta}. \label{eq:hatpsiSj-rewritten}
    \end{align}
        Equation \eqref{eq:equalunmatchedrate} follows because \eqref{eq:balance-lp-glb} holds for $({\bf n}, {\bf x}, \bm{\psi})$ and $(\hat{{\bf n}}, \hat{{\bf x}}, \hat{\bm{\psi}})$ and \eqref{eq:balancegreedy1} holds for $({\bf n}^\pi, {\bf x}^\pi)$ by \Cref{lemma:balance:multiple}. Meanwhile,  \eqref{eq:hatpsiSj-rewritten} follows from the definition of $\hat{x}_{ij}$ and from \eqref{eq:equalunmatchedrate}.
%    \begin{equation}
%    \hat{\psi}_{Sj} = \frac{\psi_{Sj} - \beta(\lambda_j\gamma_Sn_S^\pi - x_{Sj}^\pi)}{1-\beta}.
%    \end{equation}

Examining \eqref{eq:hatpsiSj-rewritten}, we see that if $\psi_{Sj} > 0$ then for all sufficiently small $\beta$, $\hat{\psi}_{Sj} > 0$. If $\psi_{Sj} = 0$ then by \eqref{eq:messy} in \Cref{lemma:balance:multiple} we have that $\sum_{i \in S} x_{ij}^\pi = \lambda_j\PP{\sum_{i \in S} N_i^\pi > 0}$, from which the assumption that \eqref{eq:alpha-gamma} holds implies that, \[ \lambda_j \gamma_S\sum_{i \in S} n_i^\pi -\sum_{i \in S} x_{ij}^\pi \le 0.\] Thus, $\hat{\psi}_{Sj} \ge 0$ in these cases as well. We conclude that for sufficiently small $\beta$, $(\hat{{\bf n}}, \hat{{\bf x}}, \hat{\bm{\psi}})$ is a feasible solution of $\plpm$.
\end{proof}




\begin{proof}[Proof of \Cref{prop:plplowerbound}]
    Let $({\bf n}^\pi, {\bf x}^\pi)$ be associated with the greedy policy $\pi$. By assumption, the conditions of \Cref{glb:boundedbypolicy} are satisfied and therefore, there exists a feasible solution $(\hat{{\bf n}}, \hat{{\bf x}}, \hat{\bm{\psi}})$ of $\plpm$ and a $\beta \in (0,1)$ such that  $\beta {\bf x}^\pi + (1-\beta) \hat{{\bf x}} = {\bf x}$. Because $(\hat{{\bf n}}, \hat{{\bf x}}, \hat{\bm{\psi}})$ is feasible we must have that $r \circ \hat{{\bf x}} \le r \circ {\bf x}$. Because $\beta \in (0,1)$ and $r \circ (\beta {\bf x}^\pi + (1-\beta) \hat{{\bf x}}) = r \circ {\bf x}$ it follows that $r \circ {\bf x}^\pi \ge r \circ {\bf x}$. This completes the proof, as $r \circ \bx^\pi = V(\pi, \m{I})$ and $r \circ \bx^*= \plpm$.
\end{proof}




