\end{align}
    \begin{equation}
        \offrdrel =  \left \{\min_{{\bf v}, {\bf z}}\sum_{i \in \mathcal{T}} v_i \lambda_i + \sum_{j \in \mathcal{T}} \sum_{S\subseteq \mathcal{T}} z_{Sj}\lambda_j\left(1-e^{-\sum_{i \in S}\lambda_i /\mu_i } \right) \ | \ ({\bf v}, {\bf z}) \text{ satisfies } \eqref{eq:off-dual-matchrate2}, \eqref{eq:off-dual-nonnegative2} \right\}
    \end{equation}
    \begin{align}
        v_i + v_j + \sum_{S \subseteq \m{T}} z_{Sj} {\bf 1}(i \in S)&\ge r_{ij} \quad \forall i,j \in\mathcal{T} \label{eq:off-dual-matchrate2}\\
        v_i, z_{Sj} &\ge 0 \quad \forall i,j\in\mathcal{T}, S \subseteq \mathcal{T} \label{eq:off-dual-nonnegative2}.
    \end{align}

    %Now we are going to analyze the constraints from $\dlplong$. 
    We can multiply both sides of \eqref{eq:dual-balance-cplt} by $\lambda_i/\mu_i$, add the resulting constraints across all types $i \in \m{T}$ and use the definition of $\gamma_S$ in \eqref{eq:gammadef} to get that for any feasible solution $({\bf v}, {\bf z})$ to $ \dlplong$,
   % \begin{equation}
   %     \lambda_i v_i \ge \sum_{j \in \mathcal{T}} \lambda_j \sum_{S \subseteq\m{T}}\left(1 -e^{-\sum_{k \in S} \lambda_k/\mu_k}\right)z_{Sj} {\bf 1}(i \in S)\frac{\lambda_i/\mu_i}{\sum_{k \in S} \lambda_k/\mu_k}  
   % \end{equation}
    \begin{align}
        \sum_{i \in \mathcal{T}}\lambda_i v_i  & \ge \sum_{i \in \mathcal{T}}\sum_{j \in \mathcal{T}} \sum_{S \subseteq \m{T}} \lambda_j  z_{Sj} {\bf 1}(i \in S)\left(1 -e^{-\sum_{k \in S} \lambda_k/\mu_k}\right)\frac{\lambda_i/\mu_i}{\sum_{k \in S} \lambda_k/\mu_k} \nonumber \\
         & = \sum_{j \in \mathcal{T}} \sum_{S \subseteq \mathcal{T}} \sum_{i \in S} \lambda_j  z_{Sj} \left(1-e^{-\sum_{k \in S} \frac{\lambda_k}{\mu_k}} \right) \frac{\lambda_i/ \mu_i}{ \sum_{k \in S} \lambda_k/\mu_k} \nonumber \\
 & =  \sum_{j \in \mathcal{T}} \sum_{S \subseteq \mathcal{T}} \lambda_j  z_{Sj} \left(1-e^{-\sum_{k \in S} \frac{\lambda_k}{\mu_k}} \right). \label{lemma:ineq:297}
    \end{align}
    We use this result as follows. Take an optimal solution $({\bf v^*}, {\bf z^*}) \in \argmin \dlplong$ and note that it is a feasible solution of $\offrdrel$. We then have that:
    \begin{align}
        \offrbrel & = \offrdrel \nonumber \\
        &\le \sum_{i \in \mathcal{T}} \lambda_i v^*_i + \sum_{j \in \mathcal{T}} \sum_{S\subseteq \mathcal{T}} z^*_{Sj}\lambda_j\left(1-e^{-\sum_{i \in S}\lambda_i /\mu_i } \right) \nonumber\\
        &\le 2\sum_{i \in \mathcal{T}} \lambda_i v_i^* \nonumber\\
        & = 2\cdot \dlplong  \nonumber \\
        & = 2\cdot \plpt 
    \end{align}
    where the first and last equalities come from strong duality, the first inequality comes from the fact that $({\bf v^*}, {\bf z^*})$ is a feasible solution of $\offrdrel$ and the second inequality comes from \eqref{lemma:ineq:297}.
\end{proof}



