\subsection{Proof of \Cref{prop:gammabound}}

\begin{proof}[Proof of \Cref{prop:gammabound}]
Fix a Markovian policy $\pi$, and let $N^\pi$ be sampled from its steady-state distribution, which is unique by \Cref{lemma:stationaryctmc}. Define 
\begin{equation}q_k^\pi =  \mathbb{P}(\sum_{i \in S} N_i^\pi = k)\end{equation}
to be the steady state probability that there are exactly $k$ agents with types belonging to $S$ in the system. Thus, we have 
\begin{equation} \frac{\E{\sum_{i \in S}N_i^\pi}}{\PP{\sum_{i \in S} N_i^\pi \ge 0}} =  \frac{\sum_{k \ge 1}k q_k^\pi}{\sum_{k \ge 1} q_k^\pi}  \label{eq:objective-q} \end{equation}

Define $\lambda_S = \sum_{i \in S} \lambda_i$. By assumption, $\mu_i = \mu$ for each $i \in S$. We claim that for $k \in \mathbb{N}$,
\begin{equation} q_k^\pi \lambda_S \ge q_{k+1}^\pi (k+1) \mu. \label{eq:balance-constraint}\end{equation}

To see this, define 
\begin{align}
\mathcal{N}_{k} &= \{\vec{n} \in \mathbb{N}^\mathcal{T} : \sum_{i \in S} n_i = k\} \\
\mathcal{N}_{\le k} &= \{\vec{n} \in \mathbb{N}^\mathcal{T} : \sum_{i \in S} n_i \le k\} \\
\mathcal{N}_{> k} &= \{\vec{n} \in \mathbb{N}^\mathcal{T} : \sum_{i \in S} n_i > k\}.
\end{align}
Consider the cut that separates the states $\mathcal{N}_{\le k}$ from the remaining states $\mathcal{N}_{> k}$. The balance equations imply that flow from $ \mathcal{N}_{\le k}$ to $\mathcal{N}_{> k}$ must equal flow from  $\mathcal{N}_{> k}$ to $\mathcal{N}_{\le k}$. Note that 

\begin{itemize}
\item From any state in $\mathcal{N}_{\le k-1}$, the rate of flow to $\mathcal{N}_{> k}$ is zero. \\ (We cannot have multiple simultaneous arrivals.)
\item From any state in $\mathcal{N}_{k}$, the rate of flow to $\mathcal{N}_{> k}$ is at most $\lambda_S$.\\ (This is the rate at which agents of some type $i \in S$ arrive to the system.)
\item From any state in $\mathcal{N}_{k+1}$, the rate of flow to $\mathcal{N}_{\le k}$ is at least $(k+1)\mu$. \\(This is the rate at which agents of some type $i \in S$ depart the system.)
\end{itemize}
It follows that 
\[ q_{k}^\pi \lambda_S \ge {\tt Flow}\,\, \mathcal{N}_{\le k} \to \mathcal{N}_{> k} = {\tt Flow}\,\, \mathcal{N}_{> k} \to \mathcal{N}_{\le k}  \ge q_{k+1}^\pi (k+1)\mu.  \]
%$\xi$ be its steady state distribution. That is, for $\vec{n} \in \mathbb{N}^\mathcal{T}$, $\xi(n) = \mathbb{P}(N^\pi = n)$. 

Inspired by \eqref{eq:objective-q} and \eqref{eq:balance-constraint}, we consider the problem of choosing non-negative real numbers $\{q_k\}_{k \ge 1}$ to maximize 
\[\max_{q_k}  \frac{\sum_{k \ge 1}k q_k}{\sum_{k \ge 1} q_k}\]
subject to the constraints
\begin{equation} q_{k+1} \le q_k \frac{\lambda_S}{(k+1) \mu}. \label{eq:balance-constraint-2} \end{equation}
This relaxes the original problem, as we no longer require that the $q_k$ represent steady-state probabilities induced by a policy $\pi$. Since the objective and constraints are homogeneous of degree one, we add the constraint that $q_1 = (\lambda_S/\mu) e^{-\lambda_{S}/\mu}$ without loss of generality. Furthermore, we fix $m \in \mathbb{N}$ and impose the constraint that $q_k = 0$ for $k > m$. 

For each of these optimization problems (indexed by $m$), \Cref{lemma:optbetak-2} states that the objective value is maximized when each constraint in \eqref{eq:balance-constraint-2} is tight: that is, $q_k = e^{-\lambda_S/\mu} (\lambda_S/\mu)^k/k!$ is a truncated density of a Poisson random variable with mean $\lambda_S/\mu$.

Clearly, the objective value is increasing in $m$ (as $m$ increases, we relax constraints), and as $m \rightarrow \infty$, we have that the objective value converges to $(\lambda_S/\mu)/(1-e^{-\lambda_S/\mu}) = 1/\gamma_S$. Since $q_k^\pi$ is feasible, it follows from \eqref{eq:objective-q} that 
\[\frac{\E{\sum_{i \in S}N_i^\pi}}{\PP{\sum_{i \in S} N_i^\pi \ge 0}} \le \frac{1}{\gamma_S}.\]
\end{proof}

\begin{lemma}
    \label{lemma:optbetak-2}
    For positive real numbers $\{ \beta_k \}_{k = 0}^{m-1}$, consider the following optimization problem.
    \begin{align}
         \max_{q_k \ge 0} h(q) = &\frac{\sum_{k=1}^m k q_k}{\sum_{k=1}^m q_k}\\
        \text{s.t } \quad &q_{k+1} \le \beta_k q_k  \,\, \forall k = 1, 2, \ldots, m-1\label{lemma:con:beta}\\
        & q_1 = \beta_0.
    \end{align}
    In any optimal solution, we have
    \begin{equation}
        q_k = \prod_{j=0}^{k-1} \beta_j  \quad \forall k \in 1,2, \ldots, m \label{lemma:con:q:beta:res}
    \end{equation}
\end{lemma}

\begin{proof}
First note that the feasible space is compact, and the function $h$ is continuous on this domain. Therefore, it attains its supremum.

We claim that any feasible solution $q$ in which the constraints in \eqref{lemma:con:beta} are not all tight cannot be optimal. From this, it follows that in the optimal solution, all of the constraints in \eqref{lemma:con:beta} must be tight, implying that \eqref{lemma:con:q:beta:res} holds.

Our proof will use the following observation: if $a, b, c, d$ are non-negative real numbers with $c, d > 0$ and $a/c < b/d$, then $(a+\omega b)/(c+\omega d)$ is increasing in $\omega$. There are many ways to see this; one is to note that 
\[ \frac{d}{d\omega} \frac{a+\omega b}{c+\omega d} = \frac{(c+\omega d)b - (a+\omega b)d}{(c+\omega d)^2} = \frac{bc - ad}{(c+\omega d)^2} = \frac{cd(b/d - a/c)}{(c+\omega d)^2}> 0.\]


Take a feasible solution $q$, and let $k$ be a constraint for which \eqref{lemma:con:beta} is not tight. That is, $q_{k+1} < q_k \beta_k$. We will construct a feasible solution $p$ with a strictly higher objective value. We consider the cases $q_{k+1} = 0$ and $q_{k+1} > 0$ separately.

If $q_{k+1} = 0$, then \eqref{lemma:con:beta} implies that $q_j = 0$ for all $j > k$. Choose $p_{k+1} \in (0,\beta_k q_k)$, and let $p_j = q_j$ for $j \ne k+1$. Then $p$ is clearly feasible. This choice of $p$ ensures that
\begin{equation}h(p) =  \frac{\sum_{j=1}^k j q_j + (k+1) p_{k+1}}{\sum_{j=1}^k q_j+ p_{k+1}}. \label{eq:first-fraction} \end{equation}
Let $a = \sum_{j=1}^k j q_j$, $b = (k+1)$, $c = \sum_{j=1}^k q_j$, and $d = 1$. Note that $a/c$ is at most $k$, as it is 
a weighted average of terms from $1$ through $k$. Meanwhile $b/d = k+1$. Therefore, we can apply our observation to conclude that \eqref{eq:first-fraction} is increasing in $p_{k+1}$. Since $h(q)$ is the result of evaluating \eqref{eq:first-fraction} with $p_{k+1} = 0$, it follows that $h(q) < h(p)$. In other words, $q$ is not optimal.

If $q_{k+1} > 0$, fix $\omega \in (1, \beta_k q_{k}/q_{k+1})$. Set $p_j = q_j$ for $j \le k$, and $p_j = \omega q_j$ for $j > k$. It is clear that this choice satisfies \eqref{lemma:con:beta} (that is, this choice of $p$ is feasible). Furthermore,
\begin{equation}h(p) =  \frac{\sum_{j=1}^k j q_j + \omega \sum_{j = k+1}^m j q_j}{\sum_{j=1}^k q_j+ \omega \sum_{j = k+1}^m q_j}.\label{eq:second-fraction} \end{equation}
Define $a = \sum_{j=1}^k j q_j$, $b = \sum_{j=k+1}^m j q_j$, $c = \sum_{j=1}^k q_j$, $d = \sum_{j=k+1}^m q_j$. Note that $a/c$ is at most $k$, as it is 
a weighted average of terms from $1$ through $k$. Meanwhile $b/d$ is at least $k+1$, as it is a weighted average of terms from $k+1$ through $m$. Therefore, we can apply our observation to conclude that \eqref{eq:second-fraction} is increasing in $\omega$. Since $h(q)$ is the result of evaluating \eqref{eq:second-fraction} with $\omega = 1$, it follows that $h(q) < h(p)$. In other words, $q$ is not optimal.
\end{proof}


