\begin{lemma}
    \label{lemma:boundq:generalpolicies}
    Let $\pi$ be a Markovian policy and $N^\pi$ be drawn from the steady-state of $N^\pi(t)$ and $S \subseteq \m{T}$ be a set of types. Define the $q^S_k$ as the probability there are $k$ agents of some type $i \in S$ in the system:
    \begin{equation}
        q_k^S = \sum_{n \in \mathbb{N}_0^\mathcal{T}: \sum_{i \in S}n_i = k}\mathbb{P}(N^\pi = n)
    \end{equation}
    If $\mu_i = \mu$ for all $i \in S$ and $\lambda = \sum_{i \in S} \lambda_i$ Then,
    \begin{equation}
        q_k^i \lambda \ge q_{k+1}^i (k+1) \mu \quad \forall k \in \mathbb{N}_0, i \in \mathcal{T}
    \end{equation}

\end{lemma}
    \begin{proof}
From  \Cref{lemma:stationaryctmc} we know thar $N^\pi$ exists. %We are going to focus on a particular agent type $i$.  
Let $S_k = \{n \in \mathbb{N}_0 : \sum_{i \in S}n_i = k\}$ be the states where there are $k$ agents of some type $i \in S$ in the system. Define the probability there are $k$ agents of type $i$ in steady-state:
        \begin{equation}
            q_k = \sum_{n \in S_k} \mathbb{P}(N^\pi = n) 
        \end{equation}
        We are going to show that for any Markovian policy the following equations hold:
        \begin{equation}
            q_k \lambda \ge q_{k+1} (k+1) \mu \quad \forall k \in \mathbb{N}_0 \label{eq:qsbound}
        \end{equation}

        To show \eqref{eq:qsbound}:
        Suppose that at time $t$ the system is in state $n \in S_k$. Let $t' = \inf \{\tau > t: N^\pi(\tau) \not = N^\pi(t)\}$ be the first time the system transitions out of $n$ and denote by $n' = N^\pi(t')$ the new state of the system. The possible events that lead to a transition are:
        \begin{itemize}
            \item An agent $a$ of type $i_a \in S$ arrives:
            \begin{itemize}
                \item No agent of type $i \in S$ is matched. In this case $n' \in S_{k+1}$.
                \item  $a$ is matched with some agent $b$ such that $i_b \notin S$. In this case $n' \in S_k$.
                \item $a$ is matched with some agent $b$ such that $i_b \in S$. In this case $n' \in S_{k-1}$.
                \item Multiple matches with agents of type $i \in S$ are performed. In this case $n' \in \cup_{l=0}^{k-1} S_l$.
            \end{itemize}
            \item An agent $a$ of type $i_a \notin S$ arrives:
            \begin{itemize}
                \item $a$ is not matched. In this case $n' \in S_{k}$.
                \item $a$ is matched with an agent $b$ with $i_b \notin S$. In this case  $n' \in S_{k}$.
                \item $a$ is matched with an agent $b$ with $i_b \in S$. In this case  $n' \in S_{k-1}$.
                \item Matches with agents of type $i \in S$ are performed. In this case $n' \in \cup_{l=0}^{k-1} S_l$.
            \end{itemize}
            \item An agent $a$ with type $i_a \in S$ departs unmatched. In this case  $n' \in S_{k-1}$.
            \item An agent $a$ with type $i_a \notin S$ departs unmatched. In this case  $n' \in S_{k}$.
        \end{itemize}
        % \begin{itemize}
        %     \item An agent of type $i$ arrives that is not matched to anyone in the system in which case $n' \in S_{k+1}$.
        %     \item  An agent of type $i$ arrives and is matched to some agent of type $j \not = i$ in the system and then $n' \in S_{k}$
        %     \item An agent of type $i$ arrives and is matched to some agent of type $i$ in the system and then $n' \in S_{k-1}$
        %     \item An agent of type $j \not = i$ arrives and is matched with an agent of type $j' \not = i$ and then $n' \in S_{k}$
        %     \item An agent of type $j\not = i$ arrives and is matched with an agent of type $i$ and then $n' \in S_{k-1}$
        %     \item An agent of type $i$ departs unmatched and then $n' \in S_{k-1}$.
        %     \item An agent of type $j \not =i$ departs unmatched and then $n' \in S_{k}$
        % \end{itemize}
        Let $\nu_{n n'}$ be the rate of transition between state $n$ and $n'$. From the set of possible events we can take the following facts:
        \begin{itemize}
            \item[(F1)] $n' \in \cup_{l=0}^{k+1} S_l$ %\fs{this needs changing for general markovian policies.}
            \item[(F2)] $\sum_{n' \in S_{k+1}} \nu_{n n'} = \lambda$
            \item[(F3)] $\sum_{n' \in S_{k-1}} \nu_{n n'} \ge k \mu$ %\fs{this needs changing for general markovian policies.}
        \end{itemize}
        (F1) comes from noting that all possible transitions are to states in $\cup_{l=0}^{k+1} S_l$. For (F2) note that we can only transition to a specific state $n' \in S_{k+1}$ such that $n'_j = n_j$ for all $j \in \mathcal{T} \setminus S$. Furthermore, this happens only if an agent of type $i \in S$ arrives and is not matched to anyone. Therefore 
        \begin{equation}
            \sum_{n' \in S_{k+1}} \nu_{n n'} = \lambda
        \end{equation}
        For (F3) note that there are many paths to transition to a $n' \in S_{k-1}$. One that holds for any policy is that an agent of type $i \in S$ leaves unmatched. Therefore, the rate at which system moves to $S_{k-1}$ is at least:
        \begin{align}
            \sum_{n' \in S_{k-1}} \nu_{n n'} & \ge k \mu
        \end{align} 
        From \Cref{lemma:stationaryctmc} we know that $N^\pi(t)$ has a stationary distribution and use $\phi$ to denote its steady-state probabilities:
        \begin{equation}
            \phi_n = \mathbb{P}(N^\pi = n) \quad \forall n \in \mathbb{N}_0^\mathcal{T}
        \end{equation}
        Partition the state space into two sets: $S_{k-} = \cup_{j=0}^k S_j$ and $S_{k+} = \cup_{j=1}^\infty S_{k+j}$.  Using $S_{k-}$ as a cut and because the steady-state distribution exists we know that the rate at which the system moves out of the cut is the same as the rate in which it moves into it %\fs{should I find a paper or book with this result?}:
        \begin{align}
            \sum_{n' \in S_{k+}}\sum_{n \in S_{k-}} \phi_{n}\nu_{n n'} &= \sum_{n \in S_{k-}}\sum_{n' \in S_{k+}} \phi_{n'}\nu_{n' n}\\
            \sum_{n' \in S_{k+1}}\sum_{n \in S_{k}} \phi_{n}\nu_{n n'} &= \sum_{n \in S_{k-}}\sum_{n' \in S_{k+}} \phi_{n'}\nu_{n' n} \label{eq106}\\
            \sum_{n' \in S_{k+1}}\sum_{n \in S_{k}} \phi_{n}\nu_{n n'} &\ge \sum_{n \in S_{k}}\sum_{n' \in S_{k+1}} \phi_{n'}\nu_{n' n} \label{eq107}\\
            \sum_{n \in S_{k}}\sum_{n' \in S_{k+1}} \phi_{n}\nu_{n n'} &\ge \sum_{n' \in S_{k+1}}\sum_{n \in S_{k}} \phi_{n'}\nu_{n' n} \label{eq108}\\
            \sum_{n \in S_{k}}\phi_n\sum_{n' \in S_{k+1}}\nu_{n n'} &\ge \sum_{n' \in S_{k+1}}\phi_{n'}\sum_{n \in S_{k}} \nu_{n' n} \label{eq109}\\
            \lambda \sum_{n \in S_{k}}\phi_n &\ge  (n+1)\mu \sum_{n' \in S_{k+1}} \phi_{n'} \label{eq110}\\
            \lambda q_k &\ge (k+1)\mu q_{k+1} \label{eq111}
        \end{align} 
        Where \eqref{eq106} comes from (F1) that says that we can only move to a state $n' \in S_{k+1}$ from a state $n \in S_{k}$.  \eqref{eq107} comes from noting that $S_k \subseteq S_{k-}$ and $S_{k+1} \subseteq S_{k+}$. We can change the summation order in \eqref{eq108} because $\phi$ is the steady-state distribution and therefore both sums converge. \eqref{eq110} comes from (F2) and (F3). Finally, \eqref{eq111} is by definition of $q_k$. This is shown for an arbitrary $k$ and therefore the result holds for all $k \in \mathbb{N}_0$. 

    \end{proof}

\begin{lemma}
    \label{lemma:optbetak}
    Take a sequence $\{ \beta_k > 0 \}_{k \in \mathbb{N}}$ such that there exists a $ \delta<1 $ and a $k' \in \mathbb{N}_0$ where $\beta_k \le \delta$ for all $k \ge k'$. Then the optimal solution of:
    \begin{align}
         \max_{q_k : k \in \mathbb{N}} h(q ) = &\frac{\sum_{k=1}^\infty k q_k}{\sum_{k=1}^\infty q_k}\\
        \text{s.t } \quad &q_{k+1} \le \beta_k q_k \quad \forall k \in \mathbb{N}_0 \label{lemma:con:beta}\\
        & q_k \ge 0 \label{lemma:con:q:pos} \quad \forall k\in \mathbb{N}
    \end{align}
    is
    \begin{equation}
        q_k = q_0 \prod_{l=0}^{k-1} \beta_l  \quad \forall k \in \mathbb{N}\label{lemma:con:q:beta:res}
    \end{equation}
    where $h(0)$ is defined as:
    \begin{equation}
        h(0) = 1
    \end{equation}
\end{lemma}

\begin{proof}
    If $q_0 = 0$ then the problem has a unique solution $q_k =0$ for all $k \in \mathbb{N}$ and therefore \eqref{lemma:con:q:beta:res} is true. We are going to assume that $q_0 > 0$ for the rest of the proof.
    We will show that $h(q)$ is bounded for any $q$.
    \begin{align}
        \frac{\sum_{k=1}^\infty k q_k}{\sum_{k=1}^\infty q_k} &= \frac{\sum_{k=1}^{k'} k q_k + \sum_{k=k'+1}^\infty k q_k}{\sum_{k=1}^{\infty} q_k }\\
        &\le \frac{\sum_{k=1}^{k'} k q_k + q_{k'} \sum_{k=k'+1}^\infty k \delta^{k-k'}}{\sum_{k=1}^{\infty} q_k } \label{eq122}\\
        &= \frac{\sum_{k=1}^{k'} k q_k + q_{k'}\frac{k' (1-\delta) +\delta}{(1-\delta)^2} }{\sum_{k=1}^{\infty} q_k } \label{eq123}\\
        &\le \frac{k' \sum_{k=1}^{k'} q_k}{\sum_{k=1}^{k'} q_k} + \frac{q_{k'} \frac{k' (1-\delta) +\delta}{(1-\delta)^2}}{\sum_{k=1}^{\infty} q_k } \label{eq124}\\
        & = k' + \frac{q_{k'} \frac{k' (1-\delta) + \delta}{(1-\delta)^2}}{\sum_{k=1}^{\infty} q_k }\\
        &\le k' + \frac{q_{k'} \frac{k' (1-\delta) + \delta}{(1-\delta)^2}}{q_{k'}} \label{eq126}\\
        &= k' + \frac{k' (1-\delta) + \delta}{(1-\delta)^2} < \infty
    \end{align}
    \eqref{eq122} comes from:
    \begin{align}
        q_k \le q_{k'} \prod_{l=k'}^{k-1} \beta_l \le q_{k'} \delta^{k-k'} \quad \text{ for } k > k'
    \end{align}
    where the first inequality comes from the constraint \eqref{lemma:con:beta} and the second one comes from the fact that $\beta_k \le \delta$ for all $k \ge k'$.

    \eqref{eq123} comes from the following result where we use that $\delta < 1$ and therefore the geometric series converges: 
    \begin{align}
        \sum_{k=k'+1}^\infty k \delta^{k-k'} &=\sum_{k=1}^{\infty}(k' + k)\delta^k\\
        &= k' \sum_{k=1}^\infty \delta^k + \sum_{k=1}^\infty k \delta^k\\
        &=k' \frac{\delta}{1-\delta} + \sum_{k=1}^\infty k \delta^k\\
        &= k' \frac{\delta}{1-\delta} + \frac{\delta}{(1-\delta)^2} \\
        &= \frac{k' (1-\delta) + \delta}{(1-\delta)^2}
    \end{align}
    where  the second to last equality comes from noting that:
    \begin{align}
        \sum_{k=0}^\infty \delta^{k} = \frac{1}{1-\delta}\\
        \frac{\partial }{\partial \delta} \sum_{k=0}^\infty \delta^{k} = \sum_{k=1}^\infty k \delta^{k-1} = \frac{1}{(1-\delta)^2} 
    \end{align}

    \eqref{eq124} comes from the fact that $q_k \ge 0$ for all $k \in \mathbb{N}$. Finally, \eqref{eq126} comes from $q_k \ge 0$ for all $k \in \mathbb{N}$.
    We are going to build a function $\mathcal{Q}$ that takes a feasible solution $q$ and yields new feasible solution with $h(\mathcal{Q}(q)) \ge h(q)$. We are going to use this function to show that starting from any feabible solution we can build a nondecreasing sequence that converges to the solution presented in \eqref{lemma:con:q:beta:res}.  There are three cases to consider in this function $\mathcal{Q}$. First if $q_{k+1} = \beta_k q_k$ for all $k \in \mathbb{N}$ then $\mathcal{Q}(q) = q$. In this case $\mathcal{Q}(q)$ is feasible and $\mathcal{Q}(q) \ge q$. For the other two cases suppose that there is a $k \in \mathbb{N}$ such that $q_{k+1} < \beta_{k} q_k$ (ie \eqref{lemma:con:beta} is not binding) and let $k^{\star} = \inf\{k \in \mathbb{N}_0 : q_{k+1} < \beta_{k} q_k\}$ be the first of these non-binding constraints. The two remaining cases are either $q_{k^{\star}+1} =0 $ or $q_{k^{\star}+1} >0$. We start considering the case when $q_{k^{\star} +1} = 0$.  For this case define $p = \mathcal{Q}(q)$ as follows:

    \begin{align}
        p_k = \begin{cases}
            q_k & \text{ for } k=1, 2,...,k^{\star}\\
            \beta_{k-1} q_{k-1} & \text{ for } k=k^{\star}+1, k^{\star}+2,...
        \end{cases}
    \end{align}
    And note that $p_k \ge q_k \ge 0$ for all $k \in \mathbb{N}$. Also $q_{k+1} = \beta_k q_{k}$ for all $k \in \mathbb{N}_0$ and therefore the solution is feasible. If we look at the difference in objective value between $p$ and $q$ we get:
    \begin{align}
        \frac{\sum_{k=1}^\infty kp_k}{\sum_{k=1}^\infty p_k} - \frac{\sum_{k=1}^{k^{\star}} kq_k}{\sum_{k=1}^{k^{\star}} q_k} &= \frac{\sum_{k=1}^{k^{\star}} kq_k + \sum_{k=k^{\star}+1}^{\infty} kp_k}{\sum_{k=1}^{k^{\star}} q_k + \sum_{k=k^{\star}+1}^{\infty} p_k} - \frac{\sum_{k=1}^{k^{\star}} kq_k}{\sum_{k=1}^{k^{\star}} q_k}\\
        & \ge \frac{\sum_{k=1}^{k^{\star}} kq_k + \sum_{k=k^{\star}+1}^{\infty} kp_k - \sum_{k=1}^{k^{\star}} kq_k }{\sum_{k=1}^{k^{\star}} q_k + \sum_{k=k^{\star}+1}^{\infty} p_k}\\
        &>0
    \end{align}
    Where the last inequality follows from $p_k, \beta_k >0$ for all $k \in \mathbb{N}$. Therefore $h(\mathcal{Q}(q)) = h(p) > h(q)$. Now for the case where $q_{k^{\star}+1} >0$ define $\omega$ as follows:
    \begin{equation}
        \omega = \frac{\beta_{k^{\star}} q_{k^{\star}}}{q_{k^{\star}+1}}    
    \end{equation}
    and note that $\omega > 1$. We define $p$ as follows:
    \begin{align}
        p_k = \begin{cases}
            q_k & \text{ for } k =1,2,...,k^{\star}\\
            q_k \omega & \text{ for } k =k^{\star}+1, k^{\star}+2,...
        \end{cases}
    \end{align}
    We start by showing that $p$ is a feasible solution.
    First thing to note is that $p_k \ge q_k \ge 0$ for all $k \in \mathbb{N}$. The second thing to note is that by definition of $k^{\star}$:
    \begin{equation}
        p_{k+1} = q_{k+1} = \beta_{k} q_k =  \beta_{k} p_k \quad \text{ for } k=1,2,...,k^{\star}-1
    \end{equation}
    Also, by definition of $\omega$ we have that:
    \begin{equation}
        p_{k^{\star}+1} = \omega q_{k^{\star}+1} = \beta_{k^{\star}} q_{k^{\star}} = \beta_{k^{\star}} p_{k^{\star}}
    \end{equation}
    Finally,
    \begin{equation}
        p_{k+1} = \omega q_{k+1} \le\omega \beta_{k} q_{k} = \beta_{k} p_{k} \quad \text{ for } k = k^{\star}+1, k^{\star}+2,...
    \end{equation}
    where the inequality comes from the fact that $q$ is feasible. This shows that $p$ is feasible.

    Now we are going to show that:
    \begin{equation}
        \frac{\sum_{k=1}^\infty k q_k}{\sum_{k=1}^\infty q_k} \le  \frac{\sum_{k=1}^\infty k p_k}{\sum_{k=1}^\infty p_k}
    \end{equation}
    To this end consider the following difference:
    \begin{align}
        \frac{\sum_{k=1}^\infty k p_k}{\sum_{k=1}^\infty p_k} - \frac{\sum_{k=1}^\infty k q_k}{\sum_{k=1}^\infty q_k} &= \frac{\sum_{k=1}^{k^{\star}} k p_k + \sum_{k=k^{\star}+1}^{\infty} k p_k}{\sum_{k=1}^{k^{\star}}p_k + \sum_{k=k^{\star}+1}^{\infty} p_k} - \frac{\sum_{k=1}^{k^{\star}} k q_k + \sum_{k=k^{\star}+1}^{\infty} k q_k}{\sum_{k=1}^{k^{\star}}q_k + \sum_{k=k^{\star}+1}^{\infty} q_k}\\
        &=  \frac{\sum_{k=1}^{k^{\star}} k q_k + \delta \sum_{k=k^{\star}+1}^{\infty} k q_k}{\sum_{k=1}^{k^{\star}}q_k + \delta\sum_{k=k^{\star}+1}^{\infty} q_k} - \frac{\sum_{k=1}^{k^{\star}} k q_k + \sum_{k=k^{\star}+1}^{\infty} k q_k}{\sum_{k=1}^{k^{\star}}q_k + \sum_{k=k^{\star}+1}^{\infty} q_k}
    \end{align}
    In the first step we just separated the sums using $k^{\star}$. The second one comes from applying the definition of $p_k$.
    To clean a little bit the last exression we will use the following notation:
    \begin{align}
        x_L &= \sum_{k=1}^{k^{\star}} k q_k\\
        x_H &= \sum_{k=k^{\star}+1}^{\infty} k q_k\\
        y_L &= \sum_{k=1}^{k^{\star}} q_k\\
        y_H &= \sum_{k=k^{\star}+1}^{\infty} q_k
    \end{align}
    From which we get: 
    \begin{align}
        &\frac{\sum_{k=1}^\infty k p_k}{\sum_{k=1}^\infty p_k} - \frac{\sum_{k=1}^\infty k q_k}{\sum_{k=1}^\infty q_k} =  \frac{x_L + \omega x_H}{y_L + \omega y_H} - \frac{x_L + x_H}{y_L + y_H}\\
        &= \frac{x_L y_L + x_L y_H +\omega x_H y_L + \omega x_H y_H - x_L y_L - \omega x_L  y_H - x_H y_L - \omega x_H y_H}{(y_L + \omega y_H)(y_L + y_H)}\\
        & = \frac{x_L y_H (1- \omega) + x_H y_L(\omega -1) }{(y_L + \omega y_H)(y_L + y_H)}\\
        & = \frac{(x_H y_L - x_L y_H) (\omega -1)}{(y_L + \omega y_H)(y_L + y_H)}
    \end{align}
    We want to show that the last expression is always nonnegative. We know that $\omega>1$ by definition of $\omega$ and $(y_L + \omega y_H)(y_L + y_H) \ge 0$ because $q_1\ge 0$. We just need to check that $(x_H y_L - x_L y_H) > 0$:
    \begin{align}
        x_H y_L - x_L y_H &= \sum_{k=k^{\star}+1}^\infty \sum_{j=1}^{k^{\star}} kq_k q_j - \sum_{k=k^{\star}+1}^\infty \sum_{j=1}^{k^{\star}} q_k j q_j\\
        &> k' \sum_{k=k^{\star}+1}^\infty \sum_{j=1}^{k^{\star}} q_k q_j - k'\sum_{k=k^{\star}+1}^\infty \sum_{j=1}^{k^{\star}} q_k q_j\\
        &=0 
    \end{align} 
    Where the inequality comes from the fact that in the first sum $k^{\star} < k$ and for the second sum we have that $k^{\star} \ge j$. Therefore we can conclude that:
    \begin{equation}
        \frac{\sum_{k=1}^\infty k p_k}{\sum_{k=1}^\infty p_k} - \frac{\sum_{k=1}^\infty k q_k}{\sum_{k=1}^\infty q_k}  > 0 
    \end{equation}
    And therefore $\mathcal{Q}(h(q)) \ge h(q)$. 

    Now we are going to use this function $\mathcal{Q}$ to build a sequence of feasible solutions that converges to \eqref{lemma:con:q:beta:res} and that for which the objective value $h$ is nondecreasing. Fix any arbitrary feasible $q$ and define the sequence as follows:
    \begin{align}
        a^{(l)} = \begin{cases}
            q & \text{ for } l=1\\
            \mathcal{Q}(a^{(l-1)}) & \text{ for } l=2,3,...
        \end{cases}
    \end{align}
    We showed previously that $h(a^{(1)}) \le h(a^{(2)}) \le \hdots \le h(a^{(l)}) \le \hdots $ and that all $a^{(l)}$ are feasible solutions. Furthermore, we have that the limit:
    \begin{equation}
        a^{(\infty)} = \lim_{l \to \infty} a^{(l)}
    \end{equation}
    follows the structure presented in \eqref{lemma:con:q:beta:res}. We end by showing that $h(a^{(l)})$ converges. Take any $\epsilon>0$. To simplify notation we use:
    \begin{equation}
        p_k = q_0 \prod_{l=0}^{k-1} \beta_l \quad \forall k \in \mathbb{N}
    \end{equation}
    ie $p = a^{(\infty)}$ and $y = a^{(l)}$. Where $l$ is chosen such that:
    \begin{equation}
        p_l l < \epsilon \left(\frac{(1-\delta)^3 p_1^2}{\delta^2 + \delta(1-\delta)} \right)
    \end{equation} 
    which we know it always exists because for $l > k'$ we have $p_l \le p_{k'}\delta^{l-k}$ and therefore the limit:
    \begin{equation}
        \lim_{l \to \infty } p_l l \le \lim_{l \to \infty } p_{k'} l\delta^{l-k} = 0 
    \end{equation}

    Then,
    \begin{align}
        |h(p) - h(l)| &= \left | \frac{\sum_{k=1}^\infty p_k k}{\sum_{k=1}^\infty p_k} - \frac{\sum_{j=1}^\infty y_j j}{\sum_{j=1}^\infty y_j}\right| \\
        &=\frac{1}{\left| (\sum_{k=1}^\infty p_k ) (\sum_{j=1}^\infty y_j ) \right|} \left |\sum_{k=1}^\infty \sum_{j=1}^\infty k p_k y_j  - \sum_{k=1}^\infty \sum_{j=1}^\infty j p_k y_j \right|\\
        &\le \frac{1}{p_1^2}  \left |\sum_{k=1}^\infty \sum_{j=1}^\infty k p_k y_j  - \sum_{k=1}^\infty \sum_{j=1}^\infty j p_k y_j \right|\\
        &\le \frac{1}{p_1^2} \left |\sum_{k=l+1}^\infty \sum_{j=l+1}^\infty k p_k y_j  - \sum_{k=l+1}^\infty \sum_{j=l+1}^\infty j p_k y_j \right|\\
        &\le \frac{2}{p_1^2} \left(\sum_{j=l+1}^\infty y_j \right) \left(\sum_{k=l+1}^\infty k p_k \right)\\
        &\le \frac{2}{p_1^2} \left(p_l \sum_{j=l+1}^\infty \delta^{j-l} \right) \left(p_l \sum_{k=l+1}^\infty k \delta^{j-l} \right)\\
        &\le \frac{2 p_l}{p_1^2} \frac{\delta}{1-\delta }\frac{l (1-\delta) + \delta}{(1-\delta)^2}\\
        &<\epsilon
    \end{align}
    Where the first inequality comes from removing terms from the denominator. The second one comes from the fact that for at least the first $l$ terms $y_k = p_k$ for $k \le l$. This comes from the construction of the sequence. The third inequality comes from noting that $p_k \ge y_k$ for $k>l$. The final inequality comes from the way we chose $l$. Because this was done for arbitrary starting feasible solution $q$ we can conclude that $p$ is the optimal solution.
\end{proof}

