\subsection{Competitive Ratio of $1/2$ when $|\m{T}| = 2$}
\label{sec:app:twotypes}

\begin{theorem}
    \label{thm:two-types}
    Let $\m{I}$ be an instance where $\m{T}=\{1, 2\}$ and $r_{12} = r_{21}$. Then 
    \[V(\alg,\m{I}) \ge \frac{1}{2} \offopt.\]
\end{theorem}

\begin{proof}
We have established that for {\em any} instance $\m{I}$, if $\m{M}$ is the set returned by \Cref{algo:suitability}, then
\[ \plpm \ge \plpt \ge \frac{1}{2} \offrbrel \ge \frac{1}{2} \offopt.  \]
Therefore, all that we need to show is that 
\[ V(\alg, \mathcal{I}) \ge \plpm.\]


Let $({\bf n}, {\bf x}, \bm{\psi})$ be the optimal suitable solution associated with $\m{M}$, so that $\pi = \alg$. By \Cref{prop:plplowerbound}, it suffices to show that \eqref{eq:alpha-gamma} holds for all sets $S$ such that $\psi_{Sj}$ for some $j$.




%then for any $S$ such that $\psi_{Sj} = 0$, we have 
%\begin{equation} \mathbb{P}(\sum_{i \in S} N_i^\pi > 0) \ge \gamma_S \sum_{i \in S} n_i^\pi.\label{eq:alpha-gamma} \end{equation} 
For any set $S$ of size one, \Cref{prop:gammabound} implies that \eqref{eq:alpha-gamma} holds. The only set of size greater than one is $S = \{1, 2\}$. Suppose that $\psi_{Sj} = 0$ for some $j \in \{1, 2\}$. By \Cref{lemma:value-based} this optimal solution is consistent with the values  ${\bf v}$ from the optimal solution of $\dlpm$. If $1 \succ_2 \emptyset$ then $r_{12} - v_1 - v_2 \ge 0$ and because $r_{12} = r_{21}$ we also have that $r_{21} - v_1 - v_2 \ge 0$. If $r_{21} - v_1 - v_2 > 0$ then $2\succ_1 \emptyset$. The case when  $r_{21} - v_1 - v_2 = 0$ is not interesting as this implies that $z_{Sj} = 0$ for all $S \subseteq \{1,2 \}$  and $j \in \{1,2 \}$ and therefore $v_1 = v_2 = 0$ and this can only happen if $r_{ij} = 0$ for all $i,j \in \{1,2\}$. From this we can conclude that if $\pi$ makes $(1,2)$ matches then it also makes $(2,1)$ matches.  Therefore, for corresponding greedy policy of $({\bf n}, {\bf x}, \bm{\psi})$ it follows that 
\begin{align*}\mathbb{P}(N_1^\pi + N_2^\pi  > 0)  & = \mathbb{P}(N_1^\pi > 0) + \mathbb{P}(N_2^\pi  > 0) \\
& \ge \gamma_1 n_1^\pi + \gamma_2n_2^\pi \\
& \ge \gamma_{12}( n_1^\pi + n_2^\pi).
\end{align*}
The first inequality applies \eqref{eq:alpha-gamma} for $S = \{1\}$ and $S = \{2\}$, while the second uses the fact that $\gamma_{12} \le \min(\gamma_1, \gamma_2)$. These inequalities establish that \eqref{eq:alpha-gamma} holds for $S = \{1, 2\}$. 
\end{proof}

