\subsection{Competitive Ratio of $(e-1)/(2e)$ for Bipartite Instances}
\label{sec:app:aouadguarantee}

In this section we present a proof that the result from \citet{aouad2022dynamic} can be combined with our \Cref{prop:offline-bound} and \Cref{prop:factor2} to get a new guarantee for bipartite instances.  We rewrite the result from \citet{aouad2022dynamic} that we will use.

% \begin{definition}
%     We say that an instance $\m{I}$ is bipartite if there are subsets $\m{T}_1, \m{T}_2 \subset \m{T}$ such that $\m{T}_1 \cup \m{T}_2 = \m{T}$, $\m{T}_1 \cap \m{T}_2 = \emptyset$ and $r_{ij} \le 0$ if $i,j \in \m{T}_1$ or $\m{T}_2$. That is matching types from the same set does not give positive rewards.
% \end{definition}
%\begin{definition}
%    We say that an instance $\m{I}$ is a stationary prophet if $\m{I}$ is bipartite and either $\mu_i = \infty$ for all  $i \in \m{T}_1$ or $\mu_i = \infty$ for all  $i \in \m{T}_2$.
%\end{definition}
\begin{lemma}[\citet{aouad2022dynamic}]
    \label{lemma:aouad}
    Let $({\bf n}, {\bf x})$ be a feasible solution of $\textup{LP}^{\textup{ON}}(\m{I})$ as defined in \eqref{online:lp} then there exists a Markovian policy $\pi$ such that, 
    \begin{equation}
        V(\pi, \m{I}) \ge \kappa \left(1 - 1/e \right) \sum_{i,j \in \m{T}} r_{ij} x_{ij}
    \end{equation}
    where $\kappa = 1/2$ if $\m{I}$ is a bipartite instance and $\kappa = 1/4$ otherwise. %$\kappa=1$ if $\m{I}$ is a stationary prophet, 
\end{lemma}

From this, we obtain the following result.

%\begin{lemma}
%    \label{lemma:plpfeasibleonline}
%    Let $({\bf n}, {\bf x},{\bf \psi})$ be a feasible solution of $\plpt$. Then $({\bf n}, {\bf x})$ is a feasible solution of $\textup{LP}^{\textup{ON}}(\m{I})$.
%\end{lemma}
