%    %To see why this is true consider a Poisson random variable with rate $\lambda_i/\mu_i$. Then by Markov's inequality we have $1-e^{-\lambda_i/\mu_i} \le \lambda_i/\mu_i$.
%\end{proof}

\begin{theorem}
    For any instance $\m{I}$ there exists a Markovian policy $\pi$ such that,
    \begin{equation}
        V(\pi, \m{I}) \ge \frac{\kappa}{2} \left(\frac{e-1}{e} \right)\offopt
    \end{equation}
    where $\kappa = 1/2$ if $\m{I}$ is a bipartite instance and $\kappa = 1/4$ otherwise. %$\kappa=1$ if $\m{I}$ is a stationary prophet, 
\end{theorem}
\begin{proof}
Let $({\bf n}, {\bf x},{\bf \psi})$ be a feasible solution of $\plpt$. Then it immediately follows that $({\bf n}, {\bf x})$ is a feasible solution of $\textup{LP}^{\textup{ON}}(\m{I})$. This is because \eqref{eq:xp-ub} can be thought of as a relaxation of \eqref{eq:match-rate-lp-glb} where only singleton sets are considered, and where each $\gamma_i$ is increased to 1. Then \Cref{lemma:aouad} states that there exists a Markovian policy $\pi$ such that
    %This follows from combining \Cref{lemma:aouad}, \Cref{lemma:plpfeasibleonline} and \Cref{prop:factor2}. Let $({\bf p}, {\bf x})$  be an optimal solution of $\plp$. 
    \begin{align*}
        V(\pi, \m{I}) &\ge \kappa \left(\frac{e-1}{e} \right) \sum_{i,j \in \m{T}} r_{ij} x_{ij}  \\
        &= \kappa \left(\frac{e-1}{e} \right) \plpt \\
        &\ge  \frac{\kappa}{2} \left(\frac{e-1}{e} \right) \offrbrel \\
        &\ge \frac{\kappa}{2} \left(\frac{e-1}{e} \right) \offopt,
    \end{align*}
    where the final inequalities follow from \Cref{prop:factor2} and \Cref{prop:offline-bound}, respectively. The result for general instances yields a factor of $(e-1)/(4e)$ which is below the $1/8$ proved by \citet{collina2020dynamic}, but to the best of our knowledge the result for bipartite instances is new.
\end{proof}

