\section{Characterization of four distances}
\label{sec.distances}

Any distance $I$ induces a dissimilarity ordering $\succsim_{I}$  as follows: for all $A,B,C,D \in Y, (A,B) \succsim_{I} (C,D) \iff I(A,B) \geq I(C,D)$. 
In Section~\ref{sec.orderings}, we have defined some axioms for dissimilarity orderings. We say that the distance $I$ satisfies an axiom defined for dissimilarity orderings if the induced dissimilarity ordering $\succsim_{I}$ satisfies the axiom. For instance, the ordering induced by $H$  satisfies \SYM\ and we therefore say that $H$ itself satisfies \SYM.


\subsection{Common axioms}

The four distances considered in this paper satisfy two additional common axioms. The first one  seems very uncontroversial.
\begin{ax}
\emph{\LB.} 
\label{A:LB}
For all $a \in X$,  $I(\{a\}, \{a\})=0$. 
\end{ax}
It is similar to, but weaker than the third condition in the definition of distances (Section~\ref{sec.formal.frame}).
The second common axiom is often imposed on distances, probably for practical reasons.
\begin{ax}
\emph{\Unit.} 
\label{A:Unit}
For all  $a \in X$, we have $I(\{a\}, \emptyset) =1$. 
\end{ax}
Notice that the choice of the number 1 as unit is  arbitrary and not compelling.

\subsection{The Hamming distance}

Any strictly increasing transformation of the Hamming distance $H$ induces the same ordering $\succsim_{H}$. The four axioms of Theorem~\ref{theo.char.H.ordering} are therefore too weak to characterize $H$. We need  one additional axiom.

\begin{ax}
\emph{\ADD.} 
\label{A:ADD} 
$A \cup B \neq \emptyset \Rightarrow I(A,B) =  I(A, A \cup B) + I(A \cup B, B)$. 
\end{ax}
%
This axiom imposes  that the distance between $A$ and $B$ can be additively decomposed in two parts: on the one hand the distance between $A$ and $A \cup B$, and on the other hand between $A \cup B$ and $B$.\footnote{The Hamming distance also satisfies another additivity condition: $A \cup B \neq \emptyset \Rightarrow I(A,B) =  I(A, A \cap B) + I(A \cap B, B)$.\label{f.add}}

\begin{theorem}
\label{theo.char.H.dist}
The distance $I$ satisfies  \NEU, \TR,  \ERH, \IND\ and \ADD\ iff $I$ is the Hamming distance (up to a scale factor), that is $I = \alpha H$ for some positive  $\alpha \in \RR$.
The five axioms are logically independent.
\end{theorem}
%
Most people use $H$ and not $\alpha H$, but this is just a matter of convenience. It is as arbitrary as measuring distances in inches instead of meters. For this reason, we consider Theorem~\ref{theo.char.H.dist} as a complete characterization of the Hamming distance.
If we nevertheless wish to single out the Hamming distance without the scale factor, we can impose \Unit.

\begin{corollary}
\label{theo.char.H.dist.UB}
The distance $I$ satisfies  \NEU, \TR,  \ERH, \IND, \ADD\ and \Unit\ iff $I$ is the Hamming distance.
\end{corollary}

So far, we have not used the triangle inequality.\footnote{\cite{Tversky1982similarity_traingleLaw}  criticized the triangle inequality which 
may not be applicable in many psychological studies.}
 It is not strong enough to replace \ADD, but it does the job if we combine it with a super-additivity axiom.

\begin{ax}
\emph{\SA.} 
\label{A:SA} 
$I(A,B) \geq   I(A, A \cup B) + I(A \cup B, B)$. 
\end{ax}

\begin{theorem}
\label{theo.char.H.dist.tr}
The distance $I$ satisfies  \NEU, \TR,  \ERH,  \IND, \SA\ and the triangle inequality iff $I$ is the Hamming distance (up to a scale factor), that is $I = \alpha H$ for some positive  $\alpha \in \RR$.
The six axioms are logically independent.
\end{theorem}

We will see in Section~\ref{subsec.Sorensen} and~\ref{subsec.Overlap} that the S\o rensen-Dice and Overlap distances do not satisfy \ADD. In order to characterize them, we will need  constant sensitivity axioms. We therefore find it useful to present here a second characterization of $H$ using  one of these constant sensitivity axioms. This  characterization of $H$ will be amenable to comparisons with the characterizations of $S$ and $O$.
%
\begin{ax}
\emph{\StTSES.}  
\label{A:StTSES}
If $\card{A} = \card{B}$ and $a, b \in B \setminus A$,
then $I(A,B)- I(A \cup \{a\},B) = I(A \cup \{a\},B) - I(A \cup \{a,b\},B)$.
\end{ax}
The suffix `-O' indicates that this axiom is specifically tailored to the Overlap distance, although it is also satisfied by the Hamming and Jaccard distances.\footnote{The Hamming and Jaccard distances satisfy \StTSES\ even if we drop the restriction $\card{A} = \card{B}$. The Overlap distance does not.}
\StTSES\ is weaker than A3 in \cite{Gerasimou2024}, although it also implies a constant sensitivity. It is also a strengthening of A3' in \cite{Gerasimou2024}. 


\begin{theorem}
\label{theo.char.H.dist2}
The distance $I$ satisfies  \NEU, \TR,  \ERH, \IND, \LB\ and \StTSES\ iff $I$ is the Hamming distance (up to a scale factor), that is $I = \alpha H$ for some positive  $\alpha \in \RR$.
\end{theorem}


\subsection{The Jaccard distance}

The Jaccard distance, just like the Hamming distance, satisfies \ADD.\footnote{The Jaccard distance also satisfies the alternative additivity condition presented in footnote~\ref{f.add}.}
 This leads us to Theorem~\ref{theo.char.J.dist}, which is the Jaccard analogue to Theorem~\ref{theo.char.H.dist} and therefore makes the comparison of $H$ and $J$ very easy.

\begin{theorem}
\label{theo.char.J.dist}
The distance $I$ satisfies  \NEU, \TR,  \ERJ, \TES, \StRI\ and \ADD\ iff $I$ is the Jaccard distance (up to a scale factor), that is $I = \alpha J$ for some positive  $\alpha \in \RR$.
\end{theorem}
%
As for the Hamming distance, we can impose  \Unit\ to obtain $I=J$ and we can replace \ADD\ by the conjunction of \SA\ and the triangle inequality. The formal statement of these results is omitted.

As for the Hamming distance, we present an alternative characterization using \StTSES\ instead of \ADD.

\begin{theorem}
\label{theo.char.J.dist2}
The distance $I$ satisfies  \NEU, \TR,  \ERJ, \TES, \StRI, \LB\ and \StTSES\ iff $I$ is the Jaccard distance (up to a scale factor), that is $I = \alpha J$ for some positive  $\alpha \in \RR$. 
\end{theorem}
%
We prove a stronger result (Theorem~\ref{theo.char.J.dist2.s}) with weaker and  logically independent axioms in  Section~\ref{sec.proofs}.

\subsection{The S\o rensen-Dice distance}
\label{subsec.Sorensen}

\ADD\ is violated by the S\o rensen-Dice distance, but \ADD\ is just one of the many additivity conditions that we could write. For instance, $I(A,B)=I(A, A \cap B) + I(A \cap B, B)$ or $I(A,B)=I(A \setminus B, A \cup B) + I(A \cup B, B \setminus A)$, etc. We propose the following definition of a general additivity condition.
%
\begin{ax}
\emph{\GADD.}  
\label{A:GADD}
$I$ satisfies \GADD\ if there are four mappings $\kappa, \lambda, \mu, \nu: Y^{2} \to Y$ such that,  for all $A,B \in Y$,
\begin{itemize}  
\item $\kappa(A,B)$ (resp. $\lambda, \mu, \nu$) can be written in terms of $A,B, \cup, \cap, \setminus$;
\item $I(A,B)= I\big(\kappa(A,B), \lambda(A,B) \big) + I\big(\mu(A,B), \nu(A,B) \big)$;  
\item $\min\Big(I\big(\kappa(A,B), \lambda(A,B) \big),I\big(\mu(A,B), \nu(A,B) \big)\Big)>0$ for some $A,B$.
\end{itemize}
\end{ax}
%
The third part of the definition excludes trivial additivity conditions like $I(A,B)=I(A,B)+I(A,A)$. 
 \ADD\ is an instance of \GADD, in which $\kappa(A,B)=A$, $\lambda(A,B)=A \cup B = \mu(A,B)$ and $\nu(A,B)=B$. 
Our next result shows that the S\o rensen-Dice distance does not satisfy any kind of additivity.
%
\begin{theorem}
\label{theo.S.no.add}
The S\o rensen-Dice distance violates \GADD.
\end{theorem}
%
We will therefore provide only one characterization of the S\o rensen distance, using a new constant sensitivity axiom.
%
\begin{ax}
\emph{\StTSESS.}  
\label{A:StTSESS}
If $a, b \notin A \cup B, c,d \in A \cap B$, 
then $I(A ,B) -  I(A \cup \{a\},B\setminus \{c\}) =
 I(A \cup \{a\},B\setminus \{c\}) - I(A \cup \{a,b\},B \setminus \{c,d\})$.
\end{ax}
The suffix `-S' indicates that this axiom is specifically tailored to the S\o rensen distance. It is not satisfied by $H,J$ nor $O$.


\begin{theorem}
\label{theo.char.S.dist}
The distance $I$ satisfies  \NEU, \TR,  \ERJ, \TES, \StRI, \LB\ and \StTSESS\ iff $I$ is the S\o rensen-Dice distance (up to a scale factor), that is $I = \alpha S$ for some positive $\alpha \in \RR$.
\end{theorem}
%

\subsection{The Overlap distance}
\label{subsec.Overlap}

The Overlap distance also violates \GADD\ (and, hence, \ADD).
%
\begin{theorem}
\label{theo.O.no.add}
The Overlap distance violates \GADD.
\end{theorem}
%
Yet, it satisfies \StTSES\ and this leads us to our next result.

\begin{theorem}
\label{theo.char.O.dist}
The distance $I$ satisfies  \NEU, \SYM, \StRI, \OES, \TES, \EI, \ERO, \LB\ and \StTSES\ iff $I$ is the Overlap distance (up to a scale factor), that is $I = \alpha O$ for some positive $\alpha \in \RR$.
\end{theorem}
%

