\section{Proofs}
\label{sec.proofs}

This section contains the proofs of all results presented in the paper. When a result in Sections~\ref{sec.orderings} or~\ref{sec.distances} uses axioms that are not logically independent, we first state weaker axioms  before proving the corresponding result with logically independent axioms. The name of the weakened axiom will always be identical to the original name, with an extra asterisk.


%%%%%%%%%%%%%%%%
\subsection{Preliminary lemmas}

Given a pair of sets $(A,B)$, we define its type as a vector of three non-negative integers: 
$$t^{AB}=
\begin{cases}
\big(\card{A \setminus B}, \card{A \cap B}, \card{B \setminus A } \big), & \textup {if \ }  \card{A} \geq \card{B}, \\ 
\big(\card{B \setminus A}, \card{A \cap B}, \card{A \setminus B } \big), & \textup {if \ }  \card{A} < \card{B }. 
\end{cases}$$
For instance, if $A= \{a,b,c\}$ and $B=\{c,d\}$, then $t^{AB}=(2,1,1)$ and $t^{BA}=(2,1,1)$. 

\begin{lemma}
\label{lemma.type}
If the ordering $\succsim$ satisfies \NEU\  and  \SYM, then all pairs with the same type are indifferent.
\end{lemma}

\bpr
Consider four sets $A,B,C,D$ such that $t^{AB}=t^{CD}$. By definition of the type, $\card{A}=\card{C}$ or $\card{A}=\card{D}$. Thanks to \SYM, we can assume $\card{A}=\card{C}$ without loss of generality. Hence $\card{B}=\card{D}$ and there is a permutation $\sigma$ of $X$ such that $\sigma(A)=C$ and $\sigma(B)=D$. Neutrality then imposes $(A,B) \sim (C,D)$
\epr

A consequence of this lemma is that an ordering $\succsim$ is completely defined if we order all types. This is what we will do in most proofs. We will often abuse the notation and write $(i,j,k) \succsim (i',j',k')$ when we mean that $(A,B) \succsim (C,D)$ for all sets $A,B,C,D$ such that $t^{AB}= (i,j,k)$ and $t^{CD}=(i',j',k')$. 

%
\begin{lemma}
\label{lemma.SYM}
If the ordering $\succsim$ satisfies \NEU\ and \TR, then it satisfies \SYM.
\end{lemma}

\bpr
Let $A,B \in Y$ with $\card{A \setminus B} = i, \card{A \cap  B} = j$ and $\card{B \setminus A} = k$.  If $i=k$, then \NEU\ clearly implies $(A,B) \sim (B,A)$.
Hence, suppose without loss of generality $i > k$. Using \TR\ $(i-k)$ times, we can `move' $(i-k)$ elements from $A \setminus B$ to $B \setminus A$. We obtain two sets $A',B'$ such that $\card{A' \setminus B'} = k, \card{A' \cap  B'} = j$ and $\card{B' \setminus A'} = k$. By \TR, $(A,B) \sim (A',B')$ and, by \NEU, $(A',B') \sim (B,A)$. Finally, by transitivity, $(A,B) \sim (B,A)$.
\epr

%%%%%%%%%%%
\subsection{Hamming}

\noindent {\bf Proof of Theorem~\ref{theo.char.H.ordering}.} 
The proof of necessity is simple and omitted. Let us show the sufficiency. Consider any $A,B, C,D \in Y$ with types $x=t^{AB}$ and $y = t^{CD}$ and suppose without loss of generality $H(A,B) \geq H(C,D)$.  We must show that $(A,B) \succsim (C,D)$.  By \IND, \NEU\ and \TR, we clearly have $(x_{1},x_{2},x_{3}) \sim (x_{1},0,x_{3}) \sim (x_{1}+x_{3},0,0)$. Similarly, $(y_{1},y_{2},y_{3}) \sim (y_{1},0,y_{3}) \sim (y_{1}+y_{3},0,0)$.
\begin{itemize}

\item If $H(A,B) = H(C,D)$, then $x_{1}+x_{3} = y_{1}+y_{3}$ and transitivity implies $(x_{1},x_{2},x_{3}) \sim (x_{1},0,x_{3}) \sim (x_{1}+x_{3},0,0) = (y_{1}+y_{3},0,0) \sim (y_{1},0,y_{3}) \sim (y_{1},y_{2},y_{3})$.

\item If $H(A,B) > H(C,D)$, then $x_{1}+x_{3} > y_{1}+y_{3}$. Then transitivity and \ERH\ imply $(x_{1},x_{2},x_{3}) \sim (x_{1},0,x_{3}) \sim (x_{1}+x_{3},0,0) \succ (y_{1}+y_{3},0,0) \sim (y_{1},0,y_{3}) \sim (y_{1},y_{2},y_{3})$. 

\end{itemize}
The logical independence of the axioms of Theorem~\ref{theo.char.H.ordering} will be established in the proof of Theorem~\ref{theo.char.H.dist} about the Hamming distance.
\epr

\noindent {\bf Proof of Theorem~\ref{theo.char.H.dist}.} 
It is easy to check that the Hamming distance satisfies \ADD. We turn to the sufficiency part. 
Thanks to Theorem~\ref{theo.char.H.ordering}, we know that $I$ is a numerical representation of $\succsim_{H}$. There exists therefore $\phi: \NN \cup \{0\} \to \RR$, strictly increasing, such that $I = \phi(H)$. Thanks to Lemma~\ref{lemma.type}, \ADD\ can be written as $I(i,j,k) = I(i,j+k,0) + I(k,i+j,0)$. So, 
$\phi(i+k) = \phi(i) + \phi(k)$, for all $i,k \in \NN \cup \{0\}$. Setting $i=k=0$, $\phi(0)=0$ obtains. Setting $k=1$ and $i= 1,2, 3, \ldots$, we have
\begin{align*}
\phi(1+1)  & = 2 \phi(1) , \\
\phi(2+1)  & =  \phi(2) + \phi(1) = 3 \phi(1), \\
\phi(3+1)  & =   \phi(3)+ \phi(1) = 4 \phi(1) , \\
\ldots 
\end{align*}
Hence, $\phi(i) = i \phi(1)$ for all $i \in \NN \cup \{0\}$.
Put differently, $I=\phi(1) H$.

Let us now prove the logical independence of the axioms. For each axiom, we present a distance satisfying all axioms but one.

\noindent \IND: $J$.


\noindent  \TR: 
$I_{\ref{ex.H.no.TR}}(A,B)= 2 \card{A \setminus B} + \card{B \setminus A}$. 
\refstepcounter{index} 
\label{ex.H.no.TR}


\noindent \ERH: $-H$ or 
\refstepcounter{index} 
\label{ex.H.d.no.OSE}
  $I_{\ref{ex.H.d.no.OSE}}(A,B)=0$ for all $A,B \in Y$.

\noindent \NEU:
$I_{\ref{ex.H.no.NEU}}(A,B)=\sum_{a \in A \triangle B}w(a)$ with $w:X \to \NN$  an arbitrary injection. \refstepcounter{index}  \label{ex.H.no.NEU} 

\noindent \ADD:
$H-1$. 
\epr


\noindent {\bf Proof of Theorem~\ref{theo.char.H.dist.tr}.} 
The triangle inequality implies $I(A,B) \leq  I(A, A \cup B) + I(A \cup B, B)$. This and \SA\ yields \ADD. We can therefore apply Theorem~\ref{theo.char.H.dist}.

In order to prove the logical independence of the axioms, we can use the same examples as in Theorem~\ref{theo.char.H.dist} for \NEU, \TR, \ERH\ and \IND. For the remaining two axioms, we need  new examples. 

\noindent \SA: $H^{1/2}$.

\noindent Triangle inequality: $H^{2}$.
\epr

Let us weaken \StTSES\ in order to guarantee the logical independence of the axioms in the  characterization of the Hamming distance based on a constant sensitivity condition.


\begin{ax}
\emph{\TSES.}  
\label{A:TSES}
If $\card{A} = \card{B}$, $a, b \in B \setminus A$, and
$I(\{a,b\},\{b\}) = I(\{a,b\},\{a\})$, 
then $I(A,B)- I(A \cup \{a\},B ) = I(A \cup \{a\},B ) - I(A \cup \{a,b\},B )$.
\end{ax}
%
With respect to \StTSES, the weaker \TSES\ is restricted  to cases in which $a$ and $b$ are in some sense equivalent. Without this restriction, \StTSES\ overlaps with \NEU. The next result is the analogue of Theorem~\ref{theo.char.H.dist2}, with the weak version of \StTSES. 

\begin{theorem}
\label{theo.char.H.dist2.s}
The distance $I$ satisfies  \NEU, \TR,  \ERH,  \IND, \LB\ and \TSES\ iff $I$ is the Hamming distance (up to a scale factor), that is $I = \alpha H$ for some positive  $\alpha \in \RR$. The six axioms are logically independent.
\end{theorem}

\bpr  
The necessity part is easy and is thus omitted.
 Thanks  to Lemma~\ref{lemma.type},   \TSES\ can  be rewritten as
 $I(i,j,i)-I(i,j+1,i-1) = I(i,j+1,i-1)-I(i,j+2,i-2)$.
 Thanks to Theorem~\ref{theo.char.H.ordering}, we know that $I$ is a numerical representation of $\succsim_{H}$. There exists therefore $\phi: \NN \cup \{0\} \to \RR$, strictly increasing, such that $I = \phi(H)$. Hence, 
$$\phi( i+i )- \phi(i+i-1) = \phi(i+i-1) - \phi(i+i-2),$$
for all $i,j,k \in \NN$. With $z=2i$, we have  $\phi( z ) = 2 \phi(z-1) - \phi(z-2)$. 
 Writing this condition for $z = 2, 3,  \ldots$, we find 
\begin{align*}
\phi(2)  & = 2 \phi(1) - \phi(0) = 2 \big(\phi(1) - \phi(0) \big) + \phi(0), \\
\phi(3)  & = 2 \phi(2) - \phi(1) = 3 \big(\phi(1) - \phi(0) \big) + \phi(0), \\
\phi(4)  & =  2 \phi(3) - \phi(2) = 4 \big(\phi(1) - \phi(0) \big) + \phi(0),  \\
\ldots 
\end{align*}
Hence, for all $z \in \NN \cup \{0\}$, $\phi(z)= z \big(\phi(1)-\phi(0) \big)+\phi(0)$.  By \LB, 
$\phi(0)=0$. This implies $\phi(z)= z \phi(1)$ and  $I=\phi(1)H$.


We now turn to the proof of the logical independence of the conditions.

\noindent \NEU:
$I_{\ref{ex.H.no.NEU}}$. 

\noindent \TR: $I_{\ref{ex.H.no.TR}}$.


\noindent \ERH:  $I_{\ref{ex.H.d.no.OSE}}$ or $-H$.


\noindent \IND:
$J$.

\noindent \LB:
$H+1$

\noindent \TSES:
$H^{2}$.
\epr


