\subsection{Jaccard}

One of the axioms of Theorem~\ref{theo.char.J.ordering} needs to be weakened to guarantee the logical independence of the  axioms characterizing the Jaccard ordering.

\begin{ax}
\emph{\RI.} 
\label{A:RI}
For $k \in \NN$ and $i \in \{1, \dots, k\}$, if $f_{i}: A \cup B \to X \setminus (A \cup B)$ are bijections such that 
\begin{itemize}

\item $f_{i}(A \cup B) \cap f_{j}(A \cup B) = \emptyset$ for all $i,j \in \{1, \dots, k\}$ and

\item for each $a \in A \cup B$, $(\{a, f_{i}(a)\} , \{a\}) \sim (\{a, f_{i}(a)\} , \{f_{i}(a)\})$, 

\end{itemize}
then $(A,B) \sim \left(\bigcup_{i=1}^{k} f_{i}(A) \cup A, \bigcup_{i=1}^{k} f_{i}(B) \cup B \right)$.
\end{ax}
\RI\ has one more premise (the second one) than \StRI. It restricts the axiom to cases in which each element is in some sense equivalent to its replicas. Without this restriction, \StRI\ overlaps with \NEU.



\begin{theorem}
\label{theo.char.J.ordering.s}
The ordering $\succsim$ satisfies  \NEU, \TR,  \ERJ, \TES, and \RI\  iff\, $\succsim$ is the Jaccard ordering. The five axioms are logically independent.
\end{theorem}
%
Before proving the theorem, we prove a lemma that will also be needed for the characterizations of the S\o rensen-Dice and Overlap orderings.
%
\begin{lemma}
	\label{lemma.RI}
	If the ordering $\succsim$ satisfies \NEU\ and \RI, then, for any $\theta \in \NN$, we have $(i,j,k)\sim (\theta i,\theta j,\theta k)$.
\end{lemma}

\bpr
Consider any $A,B \in Y$. By \NEU,  for any bijection $f_{i}: A \cup B \to X \setminus (A \cup B)$, we have  $(\{a, f_{i}(a)\} , \{a\}) \sim (\{a, f_{i}(a)\} , \{f_{i}(a)\})$, for each $a \in A \cup B$.  Since $X$ is infinite, we can  apply \RI\ without any restriction, and the rest of the proof follows easily.
\epr


\noindent {\bf Proof of Theorem~\ref{theo.char.J.ordering.s}.} 
Showing that the Jaccard ordering satisfies all the axioms is easy  and is  omitted. 

Now suppose that  the ordering $\succsim$ satisfies all axioms of Theorem~\ref{theo.char.J.ordering}, then we will show that $\succsim$ is the Jaccard ordering.
Consider any $A,B,C,D \in Y$ with types $x=t^{AB}$ and $y = t^{CD}$ and suppose without loss of generality $J(A,B) \geq J(C,D)$.  We must show that $(A,B) \succsim (C,D)$. 

Let us first consider the cases where $(A,B)$ or $(C,D)$ is equal to $(\emptyset,\emptyset)$. 
\begin{itemize}
\item If $(C,D)=(\emptyset,\emptyset)=(A,B)$, then obviously $(A,B) \sim (C,D)$. 

\item  If $(C,D)=(\emptyset,\emptyset)\neq (A,B)$, then $(C,D) \sim (0,0,0) \sim (0,1,0)$, by Lemma~\ref{lemma.type} and \TES. By \RI, $(0,1,0) \sim (0,x_{2},0)$. By \ERJ, $(0,x_{2},0) \precsim (x_{1}+x_{3},x_{2},0)$ (the comparison is not strict because $x_{1}+x_{3}$ can be zero). By \TR, 
$(x_{1}+x_{3},x_{2},0) \sim (x_{1},x_{2},x_{3})$. By transitivity, $(C,D) \precsim (A,B)$.


\item If $(A,B)=(\emptyset,\emptyset)\neq (C,D)$, then $J(A,B) \geq J(C,D)$ implies $J(C,D)=0$ and, hence, $C=D$. Then, by \RI\ and \NEU,
$(C,D) \sim (\{a \},\{ a \})$, with $a$ as in the statement of \TES. By \TES, $(\{ a \},\{ a \}) \sim (\emptyset,\emptyset)$. By transitivity, $(C,D) \sim (A,B)$.


\end{itemize}

The rest of the proof assumes $(A,B) \neq (\emptyset,\emptyset) \neq (C,D)$.
By \TR, $x \sim (x_{1}+x_{3},x_{2},0)$.
By \RI, if $y_{2} > 0$, then we have $x \sim (x_{1}+x_{3},x_{2},0) \sim (y_{2}(x_{1}+x_{3}),y_{2}x_{2},0)$ and, similarly, if $x_{2} > 0$, $y \sim (y_{1}+y_{3},y_{2},0)  \sim (x_{2}(y_{1}+y_{3}),x_{2}y_{2},0)$. Because $J(A,B) \geq J(C,D)$, if $x_{1}+x_{3} \neq 0 \neq y_{1}+y_{3}$, then
$$\frac{x_{2}}{x_{1}+x_{3}} \leq \frac{y_{2}}{y_{1}+y_{3}} $$
and $x_{2} (y_{1}+y_{3}) \leq y_{2} (x_{1}+x_{3}).$

\begin{itemize}

\item If $J(A,B) = J(C,D)=0$, then $A=B$ and $C=D$. Then Lemma~\ref{lemma.type} and \RI\ imply $(A,B) \sim (0,x_{2},0) \sim (0,y_{2},0) \sim (C,D)$.

\item If $1 > J(A,B) = J(C,D) > 0$, then $x_{2} (y_{1}+y_{3}) = y_{2} (x_{1}+x_{3})$ and, hence,
$x \sim (x_{1}+x_{3},x_{2},0) \sim (y_{2}(x_{1}+x_{3}),y_{2}x_{2},0) = (x_{2}(y_{1}+y_{3}),x_{2}y_{2},0) \sim (y_{1}+y_{3},y_{2},0) \sim y$.

\item If $J(A,B) = J(C,D)=1$, then $x_{2}  = y_{2} =0$ and \RI\ implies
$x \sim (x_{1}+x_{3},0,0) \sim (1,0,0) \sim (y_{1}+y_{3},0,0) \sim y$.

\item If $1 > J(A,B) > J(C,D)=0$, then $C=D$. By \TR\ and  successive applications of \ERJ, $(A,B) \sim (x_{1},x_{2},x_{3}) \sim (x_{1}+x_{3},x_{2},0) \succ (0, x_{2}, 0)$. By \RI, $(0, x_{2}, 0) \sim (0, y_{2}, 0) \sim (C,D)$. By transitivity, $(A,B) \succ (C,D)$.

\item If $1 > J(A,B) > J(C,D) >0$, then $x_{2} (y_{1}+y_{3}) < y_{2} (x_{1}+x_{3})$. So, by successive applications of \ERJ, $(y_{2}(x_{1}+x_{3}),y_{2}x_{2},0) \succ (x_{2}(y_{1}+y_{3}),x_{2}y_{2},0)$. By transitivity and \RI, $x \sim (y_{2}(x_{1}+x_{3}),y_{2}x_{2},0) \succ (x_{2}(y_{1}+y_{3}),x_{2}y_{2},0) \sim y$.

\item  If $1 = J(A,B) > J(C,D)=0$, then $C=D$ and $x_{2}=0$. By \TR\ and \RI, $(A,B) \sim (x_{1},0,x_{3}) \sim (x_{1} + x_{3},0, 0) \sim (y_{2},0,0)$. By \ERJ, $(y_{2},0,0) \succ (0, y_{2},0) \sim (C,D)$. By transitivity, $(A,B) \succ (C,D)$.

\item If $1 = J(A,B) > J(C,D) >0$, then $y_{2} > x_{2} =0$. By \RI, $x \sim (x_{1}+x_{3},0,0) \sim (y_{1}+y_{3}+y_{2},0,0)$. By \ERJ, $(y_{1}+y_{3}+y_{2},0,0) \succ (y_{1}+y_{3},y_{2},0) \sim y$.
By transitivity, $x \succ  y$.

\end{itemize}
The logical independence of the axioms of Theorem~\ref{theo.char.J.ordering.s} will be established  in the proof of Theorem~\ref{theo.char.J.dist.s} about the Jaccard distance.
\epr

The next result is the equivalent of Theorem~\ref{theo.char.J.dist}, with a weakening of \StRI.

\begin{theorem}
\label{theo.char.J.dist.s}
The distance $I$ satisfies  \NEU, \TR,  \ERJ, \TES, \RI\ and \ADD\ iff $I$ is the Jaccard distance (up to a scale factor), that is $I = \alpha J$ for some positive  $\alpha \in \RR$.
The six axioms are logically independent.
\end{theorem}

\bpr
It is easy to check that the Jaccard distance satisfies \ADD. We turn to the sufficiency part. 
Thanks to Theorem~\ref{theo.char.J.ordering.s}, we know that $I$ is a numerical representation of $\succsim_{J}$. There exists therefore $\phi: \RR \to \RR$, strictly increasing, such that $I = \phi(J)$. The rest of the proof of sufficiency follows that of Theorem~\ref{theo.char.H.dist}.

We now prove the logical independence of the axioms.

\noindent \NEU:
Let $w:X \to \NN$ be  an arbitrary injection and 
$$I_{\ref{ex.J.no.NEU}}(A,B)=
\begin{cases}
1- \frac{\sum_{a \in A \cap B}w(a)}{\sum_{a \in A \cup B} w(a)}, & \textup {if \ }  A \cup B  \neq \emptyset , \\ 
0,   & \textup {otherwise.} 
\end{cases}$$ 
\refstepcounter{index} 
\label{ex.J.no.NEU}

\noindent \TR:
define $I_{\ref{ex.J.no.TR2}}$  by
 $$I_{\ref{ex.J.no.TR2}}(A,B)=
\begin{cases}
\frac{2\card{A \setminus B} +  \card{B \setminus A}}{\card{A \cup B} }, & \textup {if \ }  A \cup B  \neq \emptyset , \\ 
0,   & \textup {otherwise.} 
\end{cases}$$
 \refstepcounter{index}  
 \label{ex.J.no.TR2}

\noindent \ERJ: 
$-J$ or 
  $I_{\ref{ex.H.d.no.OSE}}$.

\noindent \TES:  
$$I_{\ref{ex.J.no.ES}}(A,B)=
\begin{cases}
1 - \frac{\card{A \cap B}}{\card{A \cup B}}, & \textup {if \ }  A \cup B  \neq \emptyset , \\ 
1,   & \textup {otherwise.} 
\end{cases}$$
 \refstepcounter{index}  
 \label{ex.J.no.ES}


\noindent \RI:
$H$.

\noindent \ADD:  $S$.
\epr

The next result is the analogue of Theorem~\ref{theo.char.J.dist2}, with the weak versions of \StRI\ and of \StTSES.

\begin{theorem}
\label{theo.char.J.dist2.s}
The distance $I$ satisfies  \NEU, \TR,  \ERJ, \TES, \RI, \LB\ and \TSES\ iff $I$ is the Jaccard distance (up to a scale factor), that is $I = \alpha J$ for some positive  $\alpha \in \RR$. The seven axioms are logically independent.
\end{theorem}

\bpr
The necessity part is easy and is thus omitted.
 Thanks  to Lemma~\ref{lemma.type},   \TSES\ can  be rewritten as
 $I(i,j,i)-I(i,j+1,i-1) = I(i,j+1,i-1)-I(i,j+2,i-2)$.
 Thanks to Theorem~\ref{theo.char.J.ordering.s}, we know that $I$ is a numerical representation of $\succsim_{J}$. There exists therefore $\phi: \RR \to \RR$, strictly increasing, such that $I = \phi(J)$. Hence, 
$$\phi\left( \frac{i+i}{i+j+i} \right)- \phi\left( \frac{i+i-1}{i+j+i} \right) = \phi\left( \frac{i+i-1}{i+j+i} \right) - \phi\left( \frac{i+i-2}{i+j+i} \right),$$
for all $i,j \in \NN$ such that $i+j>0$. Let us define $z=2i+j$ and 
$\psi_{z}(h)= \phi\big((z-h)/z\big)$. So, $\psi_{z}(j) - \psi_{z}(j+1) = \psi_{z}(j+1) - \psi_{z}(j+2)$. Writing this condition for $j = 0, 1, 2, \ldots$, we find 
\begin{align*}
\psi_{z}(2)  & = 2\psi_{z}(1) - \psi_{z}(0)  = \psi_{z}(0) + 2\big(\psi_{z}(1) - \psi_{z}(0) \big), \\
\psi_{z}(3)  & = 2\psi_{z}(2) - \psi_{z}(1)  = \psi_{z}(0) + 3\big(\psi_{z}(1) - \psi_{z}(0) \big), \\
\psi_{z}(4)  & = 2\psi_{z}(3)  - \psi_{z}(2) =  \psi_{z}(0) + 4\big(\psi_{z}(1) - \psi_{z}(0) \big),\\
\ldots 
\end{align*}
Hence, for all $j \in \{0, 1, \ldots \}$,
$ \phi \left(\frac{z-j}{z}\right) = \psi_{z}(j)= s_{z} + j r_{z} ,$
with $s_{z} = \psi_{z}(0)$  and $r_{z}= \psi_{z}(1)-\psi_{z}(0)$.
Since $J(A,B)=1$ whenever $A \cap B = \emptyset$, we have  $\phi(1)=s_{z}+ 0 r_{z}$. By \LB, 
$\phi(0)=s_{z} + z r_{z}=0$. 
 This implies $s_{z}=\phi(1)$ and $r_{z}=-\phi(1)/z$. Finally, 
$$ \phi \left(\frac{z-j}{z}\right) = \phi(1) - \phi(1) \frac{j}{z},$$
or $\phi(p)=\phi(1) p$ for all  $p$ in $[0,1] \cap \QQ$. Hence, $I=\phi(1)J$.

We now turn to the proof of the logical independence of the conditions.

\noindent \NEU:
$I_{\ref{ex.J.no.NEU}}$. 

\noindent \TR: $I_{\ref{ex.J.no.TR2}}$.


\noindent \ERJ: $-J$ or $I_{\ref{ex.H.d.no.OSE}}$.

\noindent \TES: $I_{\ref{ex.J.no.ES}}$.

\noindent \RI:
$H$.

\noindent \LB:
$$I_{\ref{ex.J.d2.no.LB}}(A,B)=
\begin{cases}
1-\frac{\card{A\cap B}}{2\card{A\cup B}}, & \textup {if \ }  \card{A \cup B} \neq \emptyset, \\ 
0   & \textup {otherwise.} 
\end{cases}
$$
\refstepcounter{index} 
\label{ex.J.d2.no.LB}

\noindent \TSESJ:
$S$.
\epr

