\subsection{S\o rensen-Dice}

\noindent {\bf Proof of Theorem~\ref{theo.S.no.add}.}  When $A \cup B \neq \emptyset$, the S\o rensen-Dice distance can be written as
\begin{equation}
\label{eq.SO.add}
\frac{\card{A \setminus B} }{\card{A} + \card{B}} + \frac{ \card{B \setminus A}}{\card{A} + \card{B}}.
\end{equation}
It is the only additive decomposition (if we exclude the trivial decomposition). 
For \GADD\ to hold, $S(\kappa(A ,B) , \lambda(A,B))$ must be equal to one of the  terms in the left-hand side of \eqref{eq.SO.add}. We assume without loss of generality 
$$S(\kappa(A ,B) , \lambda(A,B)) = \frac{\card{A \setminus B} }{\card{A} + \card{B}},$$
 which implies
 %
\begin{equation}
\label{eq.SO.GA}
 \frac{ \card{\kappa(A ,B) \setminus \lambda(A,B)}}{ \card{\kappa(A ,B)} + \card{\lambda(A,B)}} + 
\frac{ \card{\lambda(A ,B) \setminus \kappa(A,B)}}{ \card{\kappa(A ,B)} + \card{\lambda(A,B)}}
 = \frac{\card{A \setminus B} }{\card{A} + \card{B}}.
 \end{equation}
Since $\card{A\setminus B}$ cannot be written as a sum, one of the terms on the left-hand side of \eqref{eq.SO.GA} must be zero. We assume without loss of generality the second one is zero, that is $\card{\lambda(A ,B) \setminus \kappa(A,B)}=0$. Hence  $\lambda(A ,B) \subseteq \kappa(A,B)$.
If $\lambda(A ,B) = \emptyset$, then \eqref{eq.SO.GA} implies $\card{\kappa(A,B)} = \card{A} + \card{B}$, which is not possible because there is no set $\kappa(A,B)$ (written in terms of $A,B, \cap, \cup, \setminus$) such that $\card{\kappa(A,B)} = \card{A} + \card{B}$. So we can assume 
$\emptyset \neq \lambda(A ,B) \subseteq \kappa(A,B)$. Since $\card{\kappa(A ,B) \setminus \lambda(A,B)} = \card{A \setminus B}$, three cases are possible.
\begin{itemize}
\item $\kappa(A ,B)= A \cup B$ and $\lambda(A,B)= B$.
%
\item $\kappa(A ,B)= A $ and $\lambda(A,B)= A \cap B$.
%
\item $\kappa(A ,B)= A \triangle B $ and $\lambda(A,B)= B \setminus A$.
\end{itemize}
In none of these cases, 
$\card{\kappa(A ,B)} + \card{\lambda(A,B)}  = \card{A} + \card{B}$. So, \eqref{eq.SO.GA} cannot hold with $\kappa(A,B)$ and $\lambda(A,B)$ written in terms of $A,B, \cap, \cup, \setminus$.
\epr


Let us weaken \StTSESS\ in order to guarantee the logical independence of the  axioms  characterizing  the S\o rensen-Dice distance.
%
\begin{ax}
\emph{\TSESS.}  
\label{A:TSESS}
If $a, b \notin A \cup B, c,d \in A \cap B$, 
$I(\{a,c\},\{c\}) = I(\{a,c\},\{a\})$, and
$I(\{c,d\},\{d\}) = I(\{c,d\},\{c\})$, 
then $I(A ,B) -  I(A \cup \{a\},B\setminus \{c\}) =
 I(A \cup \{a\},B\setminus \{c\}) - I(A \cup \{a,b\},B \setminus \{c,d\})$.
\end{ax}
%
With respect to \StTSESS, \TSESS\ is restricted  to cases in which $a$ and $c$ (resp. $c$ and $d$)  are in some sense equivalent. Without this restriction, \StTSESS\ overlaps with \NEU. The next result is the analogue of Theorem~\ref{theo.char.S.dist}, with the weak versions of \StRI\ and of \StTSESS.

\begin{theorem}
\label{theo.char.S.dist.s}
The distance $I$ satisfies  \NEU, \TR,  \ERJ, \TES, \RI, \LB\ and \TSESS\ iff $I$ is the S\o rensen-Dice distance (up to a scale factor), that is $I = \alpha S$ for some positive $\alpha \in \RR$. The seven conditions are logically independent.
\end{theorem}

\bpr
The necessity part is easy and is thus omitted.
 Thanks  to Lemma~\ref{lemma.type},   \TSESS\ can  be rewritten as
 $I(i,j,k)-I(i+2,j-1,k) = I(i+2,j-1,k)-I(i+4,j-2,k)$.
 Thanks to Theorems~\ref{theo.char.SD.ordering} and~\ref{theo.char.J.ordering.s}, we know that $I$ is a numerical representation of $\succsim_{S}$. There exists therefore $\phi: \RR \to \RR$, strictly increasing, such that $I = \phi(S)$. Hence, 
$$\phi\left( \frac{2j}{i+2j+k} \right)- \phi\left( \frac{2j-2}{i+2j+k} \right) = \phi\left( \frac{2j-2}{i+2j+k} \right) - \phi\left( \frac{2j-4}{i+2j+k} \right),$$
for all $i,j,k \in \NN$ such that $i+2j+k>0$. Let us define $m=2j$, $z=i+2j+k$ and 
$\psi_{z}(h)= \phi(h/z)$. So, $\psi_{z}(m) - \psi_{z}(m-1) = \psi_{z}(m-1) - \psi_{z}(m-2)$. Writing this condition for $m = 2, \ldots, z$, we find 
\begin{align*}
\psi_{z}(2)  & = \psi_{z}(1) + \big(\psi_{z}(1) - \psi_{z}(0) \big) = \psi_{z}(0) + 2 \big(\psi_{z}(1) - \psi_{z}(0) \big), \\
\psi_{z}(3)  & = \psi_{z}(2) + \big(\psi_{z}(1) - \psi_{z}(0) \big) = \psi_{z}(0) + 3 \big(\psi_{z}(1) - \psi_{z}(0) \big), \\
\psi_{z}(4)  & = \psi_{z}(3) + \big(\psi_{z}(1) - \psi_{z}(0) \big) =  \psi_{z}(0) + 4 \big(\psi_{z}(1) - \psi_{z}(0) \big),\\
\ldots \\
\psi_{z}(m)  & = \psi_{z}(m-1) + \big(\psi_{z}(1) - \psi_{z}(0) \big)=   \psi_{z}(0) + m \big(\psi_{z}(1) - \psi_{z}(0) \big) \\
\ldots
\end{align*}
The rest of the proof is similar to the proof of Theorem~\ref{theo.char.J.dist2}.

We now turn to the proof of the logical independence of the axioms.

\noindent \NEU:
let $w:X \to \NN$  be an arbitrary injection and 
$$I_{\ref{ex.S.ind.no.NEU}}(A,B)=
 \begin{cases}
1- \frac{ 2 \ \sum_{a \in A \cap B}w(a)}{\sum_{a \in A}w(a)+ \sum_{a \in B}w(a)}, & \textup {if \ }  A \cup B  \neq \emptyset , \\ 
0,   & \textup {otherwise.} 
\end{cases}$$
\refstepcounter{index} 
\label{ex.S.ind.no.NEU}

\noindent \TR:
$$I_{\ref{ex.S.ind.no.TR}}(A,B)= 
\begin{cases}
1 - \frac{\card{A \cap B} \min(\card{A}, \card{B})}{\card{A}^{2}+ \card{B}^{2}}, & \textup {if \ }  A \neq \emptyset \neq B, \\ 
0 , & \textup {if \ }  A = \emptyset = B, \\ 
1   & \textup {otherwise.} 
\end{cases}
$$
\refstepcounter{index} \label{ex.S.ind.no.TR}

\noindent \ERJ:
$-S$ or $I_{\ref{ex.H.d.no.OSE}}$. 

\noindent \TES: 
$$I_{\ref{ex.S.ind.no.TES}}(A,B)= 
\begin{cases}
1 - \frac{2\card{A \cap B} }{\card{A}+ \card{B}}, & \textup {if \ }  A \neq \emptyset \neq B, \\ 
0 , & \textup {if \ }  A = \emptyset = B, \\ 
1   & \textup {otherwise.} 
\end{cases}
$$
\refstepcounter{index} \label{ex.S.ind.no.TES}

\noindent \RI:  $H$.

\noindent \TSESS: $J$.

\noindent \LB: $1+S$. 
\epr


