\subsection{Overlap}


The next result is the equivalent of Theorem~\ref{theo.char.O.ordering}, with a weakening of \StRI.

\begin{theorem}
\label{theo.char.O.ordering.s}
The ordering $\succsim$ satisfies \NEU, \SYM,  \RI, \OES, \TES, \EI\  and \ERO\  iff\, $\succsim$ is the Overlap ordering. The seven axioms are logically independent.
\end{theorem}

\bpr
Consider any $A,B,C,D \in Y$ with types $x=t^{AB}$ and $y = t^{CD}$ and suppose without loss of generality $O(A,B) \geq O(C,D)$.  We must show that $(A,B) \succsim (C,D)$. 

Let us first consider the cases where $(A,B)$ or $(C,D)$ is equal to $(\emptyset,\emptyset)$. 
\begin{itemize}
\item If $(C,D)=(\emptyset,\emptyset)=(A,B)$, then obviously $(A,B) \sim (C,D)$. 

\item  If $(C,D)=(\emptyset,\emptyset)\neq (A,B)$, then, by \TES, $(C,D) \sim (\{a \},\{ a \}) \sim (0,1,0)$,  with $a$ as in the statement of \TES. By \RI, $(0,1,0) \sim (0,x_{2},0)$. By \EI, $(0,x_{2},0) \sim (x_{1},x_{2},0)$. By \ERO\ \partone,  $(x_{1},x_{2},0) \precsim (x_{1},x_{2},x_{3})\sim (A,B)$ (the comparison is not strict because $x_{3}$ can be zero).
By transitivity, $(C,D) \precsim (A,B)$.

\item  If $(A,B)=(\emptyset,\emptyset)\neq (C,D)$, then $O(A,B) \geq O(C,D)$ implies $O(C,D)=0$ and, hence, $C\subseteq D$ or $D \subseteq C$. By \SYM, we can assume without loss of generality $D \subseteq C$, which implies $(C,D) \sim (y_{1},y_{2},0)$.
Then, by \TES, 
$(A,B) = (\emptyset,\emptyset) \sim (0,0,0) \sim (0,1,0)$. By \RI, $(0,1,0) \sim (0,y_{2},0)$. By \EI, $(0,y_{2},0) \sim (y_{1},y_{2},0)$.
By transitivity, $(A,B) \sim (C,D)$.

\end{itemize}
%
The rest of the proof assumes $(A,B) \neq (\emptyset,\emptyset) \neq (C,D)$. Let us now consider the cases where exactly one of $A,B$ or exactly one of $C,D$ is empty.
\begin{itemize}
\item Suppose $A=\emptyset, B \neq \emptyset, C \neq \emptyset \neq D$. By \RI, $(A,B) \sim (x_{1},0,0) \sim (1,0,0)$. 
\begin{itemize}
\item Suppose $y_{3}>0$. \OES\ and \RI\ imply $(1,0,0) \sim (1,0,1) \sim (y_{3},0,y_{3})$. By \ERO\ \parttwo, $(y_{3},0,y_{3}) \succsim (y_{3},y_{2},y_{3})$ (the comparison is not strict because $y_{2}$ can be zero). By \EI, $(y_{3},y_{2},y_{3}) \sim (y_{1},y_{2},y_{3})$. By transitivity, $(A,B) \succsim (C,D)$.
%
\item Suppose $y_{3}=0$.  \RI\  and \ERO\ \parttwo\ imply $(1,0,0) \sim (y_{1},0,0) \succsim (y_{1}, y_{2},0)$ (the comparison is not strict because $y_{2}$ can be zero). By transitivity, $(A,B) \succsim (C,D)$.
%
\end{itemize}


\item Suppose $A\neq \emptyset, B = \emptyset, C \neq \emptyset \neq D$. By \SYM, this case is equivalent to the previous one.

\item Suppose $A \neq \emptyset \neq B, C = \emptyset, D \neq \emptyset$. Then $O(C,D)=1$ and $O(A,B) \geq O(C,D)$ imply $O(A,B)=1$. Since $(A,B) \neq (\emptyset,\emptyset)$, $A \cap B = \emptyset$ must hold. So, $(A,B) \sim (x_{1}, 0, x_{3})$ and $(C,D) \sim (y_{1},0,0)$. By \RI, $(y_{1},0,0) \sim (1,0,0)$. By \OES, $(1,0,0) \sim (1,0,1)$. By \RI, $(1,0,1) \sim (x_{3},0,x_{3})$. By \EI, $(x_{3},0,x_{3}) \sim (x_{1},0,x_{3})\sim (A,B)$. Transitivity concludes.

\item Suppose $A \neq \emptyset \neq B, C \neq \emptyset, D = \emptyset$. By \SYM, this case is equivalent to the previous one.

\item Suppose $A = \emptyset, B \neq \emptyset, C = \emptyset, D \neq \emptyset$ (or one of the three other cases that are equivalent by \SYM). By \RI, $(A,B) \sim (x_{1},0,0) \sim (y_{1},0,0) \sim (C,D)$. Transitivity concludes.

\end{itemize}
%
The rest of the proof assumes none of  $A,B,C,D$ is empty.


Note that, when $x_{2}, y_{2} >0$, we have $O(A,B) \geq O(C,D)$ iff $x_{2}/(x_{2}+x_{3}) \leq y_{2}/(y_{2}+y_{3})$ iff $x_{2}(y_{2}+y_{3}) \leq  y_{2} (x_{2}+x_{3})$ iff $x_{3}(y_{2}+y_{3}) \geq  y_{3} (x_{2}+x_{3})$. Note also that $y_{2} (x_{2}+x_{3})-x_{2}(y_{2}+y_{3}) = y_{2}x_{3}-x_{2}y_{3}$.

\begin{itemize}

\item If $O(A,B) = O(C,D)=0$, then $(A,B) \sim (x_{1},x_{2},0)$ and $(C,D) \sim (y_{1},y_{2},0)$. By \EI\ and \RI, $(x_{1},x_{2},0) \sim (x_{2},x_{2},0)  \sim (y_{2},y_{2},0)$. By \EI, $(y_{2},y_{2},0) \sim (y_{1},y_{2},0)$. By transitivity, $(A,B) \sim (C,D)$.


\item If $1>O(A,B) = O(C,D) >0$, then \RI\ and \EI\  imply $x \sim  \big(x_{1} (y_{2}+y_{3})(x_{2}+x_{3}),x_{2} (y_{2}+y_{3}),x_{3} (y_{2}+y_{3})\big) = \big(x_{1} (y_{2}+y_{3})(x_{2}+x_{3}), y_{2} (x_{2}+x_{3}), y_{3} (x_{2}+x_{3})\big) \sim \big(x_{1} (y_{2}+y_{3}), y_{2} , y_{3} \big)$. 
By transitivity, $x \sim  \big(x_{1} (y_{2}+y_{3}), y_{2} , y_{3} \big)$. 
Since $x_{1} (y_{2}+y_{3}) > y_{3}$ and $y_{1}>y_{3}$,  \EI\  implies $x \sim (y_{1},y_{2},y_{3})$.


\item If $1=O(A,B) = O(C,D)$, then $x_{2}=y_{2}=0$. By \EI, $x = (x_{1},0,x_{3}) \sim (x_{3},0,x_{3})$. By \RI, $(x_{3},0,x_{3}) \sim (y_{3},0,y_{3})$. By \EI, $(y_{3},0,y_{3}) \sim (y_{1},0,y_{3})=y$. By transitivity, all these equivalences imply $x \sim y$.


\item If $1 > O(A,B) > O(C,D) \geq 0$,  as previously, $x \sim  \big(x_{1} (y_{2}+y_{3})(x_{2}+x_{3}),x_{2} (y_{2}+y_{3}),x_{3} (y_{2}+y_{3})\big)$. 
By \ERO\ \parttwo, $\big(x_{1} (y_{2}+y_{3})(x_{2}+x_{3}),x_{2} (y_{2}+y_{3}),x_{3} (y_{2}+y_{3})\big) \succ \big(x_{1} (y_{2}+y_{3})(x_{2}+x_{3}),y_{2} (x_{2}+x_{3}),x_{3} (y_{2}+y_{3})\big)$. 
By \ERO\ \partone, $\big(x_{1} (y_{2}+y_{3})(x_{2}+x_{3}),y_{2} (x_{2}+x_{3}),x_{3} (y_{2}+y_{3})\big) \succ \big(x_{1} (y_{2}+y_{3})(x_{2}+x_{3}),y_{2} (x_{2}+x_{3}),y_{3} (x_{2}+x_{3})\big)$. By \RI, $\big(x_{1} (y_{2}+y_{3})(x_{2}+x_{3}),y_{2} (x_{2}+x_{3}),y_{3} (x_{2}+x_{3})\big) \sim \big(x_{1} (y_{2}+y_{3}),y_{2} ,y_{3} \big)$. \EI\  then implies $\big(x_{1} (y_{2}+y_{3}),y_{2} ,y_{3} \big) \sim (y_{1},y_{2},y_{3})$. Using transitivity, we can chain all these comparisons to obtain 
$x \succ (y_{1},y_{2},y_{3})$.


\item If $1 = O(A,B) > O(C,D) > 0$, then $y_{2} > x_{2} =0$. As previously, $x = (x_{1},0,x_{3}) \sim (x_{3},0,x_{3}) \sim (y_{3},0,y_{3}) \sim (y_{1},0,y_{3})$. By \ERO\ \parttwo, $(y_{1},0,y_{3}) \succ (y_{1},y_{2},y_{3})=y$. By transitivity, $x \succ y$.

\item If $1 = O(A,B) > O(C,D) = 0$, then $y_{2} > x_{2} =0$ and $y_{3}=0$. By \ERO\ \partone\ and \RI, $(A,B) \sim (x_{1},0,x_{3}) \succ (x_{1},0,0) \sim (y_{1},0,0)$. By \ERO\ \parttwo, $(y_{1},0,0) \succ (y_{1},y_{2},0)$. By transitivity, $(A,B) \succ (C,D)$.

\end{itemize}
The logical independence of the axioms of Theorem~\ref{theo.char.O.ordering.s} will be established in the proof of Theorem~\ref{theo.char.O.dist.s} about the Overlap distance.
\epr

The proof of Theorem~\ref{theo.O.no.add} is omitted because it follows that of Theorem~\ref{theo.S.no.add}.
 The next result is the analogue of Theorem~\ref{theo.char.O.dist}, with the weak versions of \StRI\ and of \StTSES.

\begin{theorem}
\label{theo.char.O.dist.s}
The distance $I$ satisfies  \NEU, \SYM, \RI, \OES, \TES, \EI, \ERO, \LB\ and \TSES\ iff $I$ is the Overlap distance (up to a scale factor), that is $I = \alpha O$ for some positive $\alpha \in \RR$.
The nine conditions are logically independent.
\end{theorem}

\bpr
The necessity part is easy and is thus omitted. 
Thanks  to Lemma~\ref{lemma.type},   \TSES\ can  be rewritten as
$I(i,j,k)-I(i,j+1,k-1) = I(i,j+1,k-1)-I(i,j+2,k-2)$. 
Thanks to Theorem~\ref{theo.char.O.ordering}, we know that $I$ is a numerical representation of $\succsim_{O}$. There exists therefore $\phi: \RR \to \RR$, strictly increasing, such that $I = \phi(O)$. Hence, 
$$\phi\left( \frac{j}{j+k} \right)- \phi\left( \frac{j+1}{j+k} \right) = \phi\left( \frac{j+1}{j+k} \right) - \phi\left( \frac{j+2}{j+k} \right),$$
for all $j,k \in \NN$. The rest of the proof is similar to that of Theorems~\ref{theo.char.J.dist2.s} and  \ref{theo.char.S.dist.s}.

We now prove the logical independence of the axioms.

\noindent \NEU: 
let $w:X \to \NN$ be an arbitrary injection and 
$$I_{\ref{ex.O.no.NEU}}(A,B)=
\begin{cases}
1-\frac{\sum_{a \in A \cap B}w(a)}{\min\left(\sum_{a \in A}w(a), \sum_{a \in B}w(a)\right)}, & \textup {if \ }  A   \neq \emptyset \neq B , \\ 
0, & \textup {if \ }  A   = \emptyset = B , \\ 
1,   & \textup {otherwise.} 
\end{cases}$$ 
\refstepcounter{index} 
\label{ex.O.no.NEU}

\noindent \SYM:
$$I_{\ref{ex.O.no.SYM}}(A,B)=
\begin{cases}
\frac{ \card{A \triangle B} - \max(\card{A} - \card{B},0)}{\card{A \cup B} - \max(\card{A} - \card{B},0)}, & \textup {if \ }  A \neq \emptyset \neq B, \\ 
0, & \textup {if \ }  A = \emptyset = B, \\ 
1,   & \textup {otherwise.} 
\end{cases}
$$
\refstepcounter{index} 
\label{ex.O.no.SYM}

\noindent \RI:
$$I_{\ref{ex.O.no.RI}}(A,B)=
\begin{cases}
 1 - \frac{\card{A \cap B}}{1+\min(\card{A} , \card{B})}, &\textrm{if} A \setminus B \neq \emptyset \neq B \setminus A, \\
 1, &\textrm{if exactly one of } A,B   \textrm{ is empty, } \\
 0, &\textrm{otherwise}.
\end{cases}
$$
\refstepcounter{index} 
\label{ex.O.no.RI}


\noindent \OES:
$$I_{\ref{ex.O.no.OES}}(A,B)=
\begin{cases}
1 - \frac{\card{A \cap B}}{\min(\card{A} , \card{ B})}, & \textup {if \ }  A  \neq \emptyset \neq B, \\ 
0,   & \textup {if \ }  A  = \emptyset  = B \\
1/2,   & \textup {otherwise.}  
\end{cases}
$$
\refstepcounter{index} 
\label{ex.O.no.OES}

\noindent \TES:
$$I_{\ref{ex.O.no.TES}}(A,B)=
\begin{cases}
1 - \frac{\card{A \cap B}}{\min(\card{A} , \card{ B})}, & \textup {if \ }  A  \neq \emptyset \neq B, \\ 
1,   & \textup {if \ }  A  = \emptyset  = B \\
1,   & \textup {otherwise.}  
\end{cases}
$$
\refstepcounter{index} 
\label{ex.O.no.TES}

\noindent \EI:
$J$.

\noindent \ERO:
$I_{\ref{ex.H.d.no.OSE}}$. 

\noindent \LB:
$1+O.$

\noindent \TSES:
$O^{2}.$
\epr





