\begin{proof}[Proof of Lemma \ref{Duhc}]We first show that the set
\[\begin{split}
D=\Big\{\kappa\in\,\Delta_\nu\big(C\times \Delta(T)\times A\big)~\Bigl\lvert~ &\kappa\textnormal{ is supported on the graph of } \mc{S}\Big\}
\end{split}\]
is closed. Now $\Gamma(\mc{S})$, the graph of $\mc{S}$, is closed by the closed graph theorem. Let $d$ be a bounded metric that metrizes $C\times \Delta(T)\times A$. Then
\[\Gamma(\mc{S})=\Big\{(c,\beta,a)\mid d\big((c,\beta,a),\Gamma(\mc{S})\big)=0\Big\}.\]
It follows that \[\begin{split}
D=\Big\{\kappa\in\,\Delta_\nu\big(C\times \Delta(T)\times A\big)~\Bigl\lvert~ & \int d\big(\cdot,\Gamma(\mc{S})\big)~\mathrm d\kappa=0\Big\}
\end{split}\]
and this set is closed as the preimage of $\{0\}$ under a continuous function. Now the graph of $\mathcal{D}_\mc{S}$ is
\[\big\{(t,\kappa)\in T\times D\mid \kappa\textnormal{ has }C\times\Delta(T)\textnormal{-marginal }\tau(t)\big\}.\]
This graph is closed since both the ``marginal-mapping'' and $\tau$ are continuous functions. It follows that $\mc{D}_\mc{S}$ is upper hemicontinuous with compact values since $T\times\Delta_\nu\big(C\times \Delta(T)\times A\big)$ is compact. That all values are nonempty is obvious.
\end{proof}

\begin{proof}[Proof of Lemma \ref{Sdef}]First note that the set
\[\begin{split}
\bigg\{(c,a,\beta,\mu)\in\, & C\times A\times\Delta(T)\times\Delta\left(T\times\Delta_\nu\big(C\times \Delta(T)\times A\big)\right)\Bigl\lvert\\  &a\in\argmax_{\mc{A}(c)} \int v\big(c,a,\sigma(t),\phi(\kappa)\big)~\mathrm d\mu(t,\kappa),\\
&\mu\textnormal{ has }T\textnormal{-marginal }\beta.
\bigg\}
\end{split}\]
is closed because expected utility is jointly continuous (see for example \citet*{MR2221405}) and the marginal function is continuous. This set is the graph of a correspondence from
$C\times\Delta(T)$ to the compact set $A\times \Delta\big(T\times\Delta_\nu(C\times \Delta(T)\times A)\big)$ and this correspondence is upper hemicontinuous by the closed graph theorem. Composing with the projection of $A\times\Delta\big(T\times\Delta_\nu(C\times \Delta(T)\times A)\big)$ onto $A$ gives us the correspondence $\mc{S}_\mc{D}$ which is therefore upper hemicontinuos by \citet[Theorem 17.23]{MR2378491}. Since forward images of compact sets under continuous functions are compact, $\mc{S}_\mc{D}$ is compact valued.
\end{proof}

\begin{proof}[Proof of Theorem \ref{selfrat}]Let $a\in\mathcal{S}(c,\beta)$. For each positive $m$, there exists $\mu_m\in\Delta\big(T\times\Delta_\nu(C\times \Delta(T)\times A)\big)$ with $T$-marginal $\beta$, supported on the graph of $\mc{D}_{m-1}$ such that $a\in\argmax_{\mathcal{A}(c)} \int v\big(c,a,\sigma(t),\phi(\kappa)\big)~\mathrm d\mu(t,\kappa).$ Since $\Delta\big(T\times\Delta_\nu(C\times \Delta(T)\times A)\big)$ is compact, there exists a subsequence converging to some $\mu$. We claim that $\mu$ is supported on the graph of $\mc{D}_\mc{S}$ and that \[a\in\argmax_{\mathcal{A}(c)} \int v\big(c,a,\sigma(t),\phi(\kappa)\big)~\mathrm{d}\mu(t,\kappa).\] Indeed, the latter part follows again from the joint continuity of expected utility.

To see that $\mu$ is supported on the graph of $\mc{D}_\mc{S}$, we note that we only have to check that the $\Delta_\nu(C\times \Delta(T)\times A)\big)$-marginal is supported on the graph of $\mc{S}$. Let $O_m$ be the complement of the graph of $\mathcal{S}_m$. Let $\mu_m^*$ and $\mu^*$ be the $\Delta_\nu(C\times\Delta(T)\times A)$-marginal of $\mu_m$ and $\mu$ respectively. Clearly, $\mu_n^*(O_m)=0$ for $n\geq m$. Therefore, $0=\liminf_n \mu_n^*(O_m)\geq \mu^*(O_m)=0$ by the Portmanteua theorem. Now $\bigcup_m O_m$ is exactly the complement of the graph of $\mathcal{S}$ and by countable subadditivity, $\mu^*(\bigcup_m O_m)=0$.

Now, if $\mathcal{R}$ rationalizes itself, it follows from a simple induction argument that $\mathcal{R}(c,\beta)\subseteq\mathcal{S}_m(c,\beta)$ for all $(c,\beta)$, so $\mathcal{S}$ is the largest correspondence that rationalizes itself.
\end{proof}

For the proof of Theorem \ref{equilibrium}, we need some preliminary work. We define $V:C\times A\times\Delta\big(S\times \Delta_\nu(C\times A)\big) \to\mathbb{R}$ by
\[V(c,a,\kappa)=\int v(c,a,s,\mu)~\mathrm d\kappa(s,\mu).\]

\begin{lemma}\label{incdiff}The function $V$ is supermodular in $A$ and has increasing differences in $A\times\Delta\big(S\times \Delta_\nu(C\times A)\big)$.
\end{lemma}
\begin{proof}Verifying that $V$ is supermodular in $A$ is straightforward. For the rest, assume that $a\succeq a'$ and $\kappa\succeq\lambda$. By the characterization of stochastic dominance in Appendix 1, there exists a probability space and random variables $k$ and $l$ defined on it with values in $S\times\Delta_\nu(C\times A)$ such that $k\succeq l$ almost surely and such that the distributions of $k$ and $l$ are $\kappa$ and $\lambda$, respectively. By assumption, we have
\[v(c,a,k)-v(c,a',k)\geq v(c,a,l)-v(c,a',l)\]
almost surely. By the change of variables formula for push-forward measures, the integral of $v(c,a,k)-v(c,a',k)$ is $V(c,a,\kappa)-V(c,a,\kappa)$ and the integral of $v(c,a,l)-v(c,a',l)$ is $V(c,a,\lambda)-V(c,a',\lambda)$, so the result follows from integrating the inequality $v(c,a,k)-v(c,a',k)\geq v(c,a,l)-v(c,a',l)$.
\end{proof}

