Suppose now that $f,f'\in K(z)$ are two cubic PCF polynomials, each satisfying Assumption~\ref{main-assumption} and having disjoint critical orbits. We will show below that, under certain divisibility conditions on the numbers $s_i,m_i, s'_i, m'_i$, $i=1,2$, characterising the respective ramification portraits, one can conjugate one of the given groups into a subgroup of the other one; see Theorem~\ref{thm-filtration}. In other words, up to conjugation, the profinite geometric iterated monodromy groups associated to PCF polynomials satisfying Assumption~\ref{main-assumption} and having disjoint critical orbits form \emph{filtrations} in $W=\Aut(T)$.






We begin with two technical propositions that will be used to establish the desired inclusion.

\begin{prop}\label{prop: moving generators}
    Let $m\geq 1$ and $s\geq 0$ be integers, and let $G$ be a {\normalfont\ref{main-assumption}}-restricted model group. Consider two sets of $s+m$ elements $a_1,\dots,a_{s+m}\in W$ and $b_1,\dots,b_{s+m}\in W$ given in of one of the following two recursive forms:
    \begin{enumerate}[label=(\roman*),font=\normalfont]
        \item\label{item: moving-1} $a_1=(a_{s+m},\one,\one)(1\,2)$ and $a_j=(a_{j-1},\one,\one)$ for $j\neq 1$; and \newline
        ${\,}b_1=(\one,\one,b_{s+m})(2\,3)$ and $b_j=(b_{j-1},\one,\one)$ for $j\neq 1$;   
    \end{enumerate}
    or
    \begin{enumerate}[label=(\roman*),font=\normalfont] 
    \setcounter{enumi}{1}
    \item\label{item: moving-2} $a_1=(1\,2)$, $a_{s+1}=(a_s,a_{s+m},\one)$, and $a_j=(a_{j-1},\one,\one)$ for $j\neq 1,s+1$; and\newline    
    ${\,}b_1=(2\,3)$, $b_{s+1}=(b_s,b_{s+m},\one)$, and $b_j=(b_{j-1},\one,\one)$ for $j\neq 1,s+1$.
    \end{enumerate}

    Then, for each $j=1,\dots, s+m$,  the group $G$ contains $a_j$ if and only if it contains $b_j$. Hence, $G$ contains the elements $a_1,\dots,a_{s+m}$ if and only if it also contains the elements $b_1,\dots,b_{s+m}$.
\end{prop}

\begin{proof}
    By Proposition \ref{Prop: G is branch over [G,G]}, we know that $G$ contains $[\Alt_3]^\infty$. We will show that for each $j=1,\dots,s+m$, there exists some $g_j\in [\mathcal A_3]^\infty$ such that $g_jb_j=a_j$, where we assume either of the two cases~\ref{item: moving-1} or \ref{item: moving-2}. First, we prove by induction that for each $n\geq 0$ we have  $g_{1,n},\dots, g_{s+m,n}\in [\Alt_3]^n$ such that $g_{j,n}\cdot b_j|_{T_n}=a_j|_{T_n}$ for each $j$. As this is clear for $n=0$, assume that it is true for some $n\geq 0$, giving us elements $g_{j,n}\in [\Alt_3]^n$ for $j=1,\dots,s+m$.

    Now set $g_{1,n+1}:=(g_{s+m,n},\one,\one)(1\,3\,2)\in [\Alt_3]^{n+1}$ if we are in Case~\ref{item: moving-1}, and $g_{1,n+1}:=(1\,3\,2)$, $g_{s+1,n+1}:=(g_{s,n},g_{s+m,n},\one)\in [\Alt_3]^{n+1}$ if we are Case~\ref{item: moving-2}. For all the remaining $j$'s, we set $g_{j,n+1}:=(g_{j-1,n},\one,\one)$ in both cases. It can then be readily verified that $$g_{j,n+1}\cdot b_j|_{T_{n+1}}=a_j|_{T_{n+1}}$$ for all $j=1,\dots, s+m$ in both cases, completing the induction step.


     Since $[\Alt_3]^n\subset [\Alt_3]^\infty$ for all $n\geq 0$ and the group $[\Alt_3]^\infty$ is compact, for each $j=1,\dots, s+m$, we can find a convergent subsequence of the constructed sequence $\{g_{j,n}\}$. Setting $g_j\in [\mathcal A_3]^\infty\subset G$ to be the respective limit, we conclude that $g_j\cdot b_j=a_j$. It then  follows immediately that $a_j\in G$ if and only if $b_j\in G$, finishing the proof of the proposition.
\end{proof}



\begin{prop} \label{Prop: main-filtration}
    Let $r,m\geq 1$ and $s\geq 0$ be integers such that $r$ divides both $s$ and $m$, and let $G$ be a {\normalfont\ref{main-assumption}}-restricted model group. Suppose $G$ contains $s+m$ elements $a_1,\dots, a_{s+m}$ of one of the following two recursive forms:
    \begin{enumerate}[label=(\roman*),font=\normalfont]
        \item\label{item: filtration-1} $a_1=(a_{s+m},\one,\one)(1\,2)$ and $a_j=(a_{j-1},\one,\one)$ for $j\neq 1$; or
        \item\label{item: filtration-2} $a_1=(1\,2)$, $a_{s+1}=(a_s,a_{s+m},\one)$, and $a_j=(a_{j-1},\one,\one)$ for $j\neq 1,s+1$.
    \end{enumerate} 
    Then, $G$ also contains the $r$ elements $b_1=(b_r,\one,\one)(1\,2),b_k=(b_{k-1},\one,\one)$, for $k\in \{2,\dots,r\}$.
\end{prop}

\begin{proof}
    In either case \ref{item: filtration-1} or \ref{item: filtration-2}, we define $c_k:=a_ka_{k+r}a_{k+2r}\cdots a_{k+(s+m-r)}\in G$ for each $k=1,\dots,r$. Then, again in both cases, we have $$c_1=(a_{s+m},a_ra_{2r}\cdots a_{s+m-r},\one)(1\,2)=(a_{s+m},c_ra_{s+m}^{-1},\one)(1\,2),$$ and for $k\neq 1$ we have $$c_k=(a_{k-1}a_{k-1+r}\cdots a_{k-1+(s+m-r)},\one,\one)=(c_{k-1},\one,\one).$$

    Now assume that for some $n\geq 0$ there exist $g_1,\dots,g_r\in G$ such that $(g_kc_kg_k^{-1})|_{T_n}=b_k|_{T_n}$ for all $k=1,\dots,r$. (This clearly holds when $n=0$.) Note that, by Lemma~\ref{lem: model-self-replicativity}, $G$ contains elements of the form $(g,\one,*)$ and $(g,g,*)$ for all $g\in G$. Hence, for $n+1$, we can choose $h_1:=(g_r,g_r,*)(c_ra_{s+m}^{-1},\one,*)\in G$ and $h_k:=(g_{k-1},\one,*)\in G$ for each $k\neq 1$. Then    $$(h_1c_1h_1^{-1})|_{T_{n+1}}=\big((g_rc_rg_r^{-1})|_{T_n},\one,\one\big)(1\,2)=(b_r|_{T_n},\one,\one)(1\,2)=b_1|_{T_{n+1}}$$ and $$(h_kc_kh_k^{-1})|_{T_{n+1}}=\big((g_{k-1}c_{k-1}g_{k-1}^{-1})|_{T_n},\one,\one\big)=(b_{k-1}|_{T_n},\one,\one)=b_k|_{T_{n+1}},$$ for $k\neq 1$. By induction, we conclude that $b_k|_{T_n}\in G_n$ for all $n\geq 0$ and $k=1,\dots, r$, and therefore $b_k\in G$ for all $k$.
\end{proof}

Let us illustrate the two propositions above by comparing several specific \ref{main-assumption}-restricted model groups. 

\begin{ex}\label{ex: filtrations-model-groups}
    Consider the elements $a,a_1,a_2,b,b_1,b_2\in W$ defined by the following recursive formulas: 
    \[
    \begin{tabular}{@{}lll}
    $a=(a,\one,\one)(1\,2)$, &$a_1=(a_2,\one,\one)(1\,2)$,  &$a_2=(a_1,\one,\one)$,\quad and\\
    $b=(\one,\one,b)(2\,3)$,  &$b_1=(\one,\one,b_2)(2\,3)$, & $b_2=(\one,\one,b_1)$. 
    \end{tabular}
    \]

    Then we have the following relations between the induced \ref{main-assumption}-restricted model groups:

    \[\llangle a,b\rrangle\subsetneq\llangle a,b_1,b_2\rrangle=\llangle a_1,a_2,b\rrangle=\llangle a_1,a_2,b_1,b_2\rrangle.\]

    All the equalities above and the non-strict inclusion $\llangle a,b\rrangle\subseteq\llangle a,b_1,b_2\rrangle$ follow directly from Propositions~\ref{prop: moving generators} and~\ref{Prop: main-filtration}. The latter inclusion can be seen to be strict using the following trick. For each $n\geq 0$, let us define a map $\Upsilon_n\colon W\to \{\pm1\}$ by $\Upsilon_n(g):=\prod_{v\in \sX^n}\sgn(g|_v)$, where $\sgn\colon W\to \{\pm1\}$ is the map sending each $h\in W$ to the sign of the permutation $h|_{T_1}\in \Sym_3$. As each $\Upsilon_n$ is a group homomorphism, the map $\Upsilon\colon W \to \{\pm1\}\times \{\pm 1\}$, $g\mapsto \big(\Upsilon_0(g),\Upsilon_1(g)\big)$, is also a group homomorphism. Now note that $\Upsilon(a)=(-1,-1)=\Upsilon(b)$, but $\Upsilon(a_1)=(-1,1)$ and $\Upsilon(a_2)=(1,-1)$. It follows that $a,b$ cannot generate $b_1,b_2$.
\end{ex}

    \begin{proof}[Proof of Theorem~\ref{thm-filtration}]
    Let $f,f'$ be the PCF cubic polynomials as in the statement, and let $(s_i,m_i), (s'_i, m'_i)$, $i=1,2$, be the corresponding sets of pairs of numbers characterizing the ramification portraits of $f,f'$, respectively. Let us further assume that these numbers satisfy the hypotheses from the theorem. By the discussion above, the profinite geometric iterated monodromy groups $G^{geom}(f)$ and $G^{geom}(f')$ are conjugate in $W$ to some \ref{main-assumption}-restricted model groups $G$ and $G'$, respectively, whose model generators follow the recursive formulas from  \eqref{Strictly pre-periodic} or \eqref{Strictly periodic}, for the appropriate values of the parameters $(s_i,m_i), (s'_i, m'_i)$, $i=1,2$. The hypotheses on these parameters imply that the group $G$ contains all the model generators of the group $G'$ by Propositions~\ref{prop: moving generators} and~\ref{Prop: main-filtration}. Hence, we have the inclusion $G'\subseteq G$ of the model groups, and thus $wG^{geom}(f')w^{-1}\subseteq G^{geom}(f)$ for some element $w \in W$.
    \end{proof}

\begin{ex}
    In the setting of Theorem~\ref{thm-filtration}, suppose that $s_1=s_2=s_1'=s_2'=0$. If $m_1=2$ and $m_2=m_1'=m_2'=1$, then we have seen that $wG^{geom}(f')w^{-1} \subseteq G^{geom}(f)$ for some $w\in W$. Moreover, this inclusion is strict for all such $w$ by Example~\ref{ex: filtrations-model-groups}. Now, if we take instead, say, $m_1=m_2=m_1'=2$ and $m_2'=1$, then we have the equality $wG^{geom}(f')w^{-1} = G^{geom}(f)$ for some $w\in W$ by the same example. 
\end{ex}

