\section{The spectrum for essentially finite families}\label{sec:spcfinite}

The first goal of this section is to determine the Balmer spectrum of $\D{\cat{U}}^c$ for essentially finite collections $\cat{U}$ (see \cref{not-families}) satisfying \cref{hyp2}. We show that it is a discrete space consisting only of group primes. Based on this computation, we then establish a number of consequences for more general collections. A special feature of essentially finite families is that the ``characteristic function'' objects of \cref{def-chi-objects} are compact in the derived category:

\begin{Lem}\label{lem:chi-compact}
    Let $\cat U$ be essentially finite. Consider $G \in \cat U$ and $C \in \D{\{G\}}^c$. Then the object $\chi_{G,C}$ is compact in $\D{\cat U}$.
\end{Lem}
\begin{proof}
     Recall from \cref{prop-chi-VandQ}(a) that $\chi_{G,C}\simeq\chi_{G, H_*(C)}$. We note that $H_*(C)$ is finite dimensional as $C$ is compact. Then compactness of $\chi_{G,H_*(C)}$ follows from \cite[Proposition 7.4]{BBPSWstructural}.
\end{proof}

\begin{Prop}\label{prop:spcfinite}
    Let $\cat U$ be essentially finite and consider $X \in \D{\cat{U}}^c$. Then 
        \[
            \thickt{X}=\thickt{\chi_{G,k} \mid G \in \hsupp(X)} \subseteq \D{\cat U}^c.
        \]
        Thus for $Y \in \D{\cat U}^c$, we have $\hsupp(X) \subseteq \hsupp(Y)$ if and only if $X \in \thickt{Y}.$
\end{Prop}
\begin{proof}
    The ``$\supseteq$'' containment holds without the compactness assumption on $X$: if $G \in \hsupp(X)$, then we can use \cref{lem-prop-e_g}(b) to construct a map $e_{G, X(G)} \to X$ which is a quasi-isomorphism at $G$. Tensoring with $\chi_{G,k}$, we obtain a quasi-isomorphism 
    \[
    \chi_{G, X(G)}\coloneqq\chi_{G,k} \otimes e_{G, X(G)} \xrightarrow{\sim} \chi_{G,k} \otimes X,
    \]
    using \cref{def-chi-objects}. Therefore, by \Cref{prop-chi-VandQ}, we have
        \[
            \chi_{G, k} \in \thickt{\chi_{G, X(G)}} \subseteq \thickt{X}.
        \]
    For the other containment, using that $\pi_0\cat U$ is finite, we prove by induction on $n=|\hsupp(X)|$ that $X \in \thickt{\chi_{G,k}\mid G \in \hsupp(X)}$. If $n=0$, then $X\simeq 0$ and the claim is clear. Now let $n\geq 1$ and suppose that the claim holds for all objects $Z \in \D{\cat{U}}^c$ with $|\hsupp(Z)|<n$. Let $\{G_1, \ldots, G_n\}$ be a complete collection of representatives for the isomorphism classes of groups in $\hsupp(X)$ and choose $G_n$ maximal among the $G_i$s with respect to $\gg$. Set $V_n=X(G_n)$. Then we claim that there is a map $f_n\colon \chi_{G_n,V_n}\to X$ which is a quasi-isomorphism at $G_n$. To see this, we start with a map $g_n \colon e_{G_n,V_n}\to X$ which is a quasi-isomorphism at $G_n$, see \cref{lem-prop-e_g}(b). By \cref{lem-chi-eGs} there is a triangle
        \[
            F \to e_{G_n,V_n} \to \chi_{G_n,V_n}
        \]
    with $F \in \loc{e_{H}\mid H \in \ua(\{G_n\}) \setminus \{G_n\}}$. By our choice of $G_n$, we have $\hsupp(X)\cap (\ua(\{G_n\}) \setminus \{G_n\})=\emptyset$. It follows that any map from $F$ to $X$ must be zero, so $g_n$ factors through the desired map $f_n\colon \chi_{G_n,V_n} \to X$. Now let $C=\mathrm{cone}(f_n)$, so that 
    $X \in \thickt{\chi_{G_n,V_n}, C}$. Note that $\hsupp(C)=\hsupp(X)\backslash\{G_n\}$ so by the induction hypothesis 
        \[
            X \in \thickt{\chi_{G_n,V_n}, C}\subseteq\thickt{\chi_{G_n,V_n}, \chi_{G_i,k} \mid 1\leq i < n}.
        \]
    To conclude the proof we apply \cref{prop-chi-VandQ}. The final statement is an immediate consequence of the first claim.
\end{proof}

\begin{Thm}\label{thm:spcfinite}
    Let $\cat U$ be essentially finite and satisfying \cref{hyp2}. Then $\D{\cat{U}}^c$ is standard (in the sense of \cref{def:standardtt}) and the map \eqref{eq:groupprimemap} induces a homeomorphism $\pi_0\cat{U} \cong \Spc(\D{\cat{U}}^c)$. Consequently, $\Spc(\D{\cat{U}}^c)$ is a finite discrete space consisting only of the group primes. 
\end{Thm}
\begin{proof}
    Any thick ideal in $\D{\cat{U}}^c$ is necessarily finitely generated by \Cref{prop:spcfinite} and the fact that the family is essentially finite. The same proposition shows that for any thick ideals $\cat{J}_1,\cat{J}_2$, we have
        \[
            \cat{J}_1 \subseteq \cat{J}_2 \iff \hsupp(\cat{J}_1) \subseteq \hsupp(\cat{J}_2).
        \]
    In particular, $\cat{J}_1$ coincides with its radical as they have the same homological support, so $\D{\cat{U}}^c$ is standard. Moreover, it follows that the pair $(\pi_0\cat{U},\hsupp)$ satisfies the assumptions of \cite[Theorem 16]{BalmerICM}, so that the map $\mathfrakp_{-}$ is a homeomorphism. 
\end{proof}

\begin{Rem}\label{rem:spcfinite}
    More generally, in \cite{Xu2014}, Xu computes the spectrum of the derived category of representations of an essentially finite EI category with coefficients in an arbitrary field $k$; see also \cite{Wang2019} for an alternative proof and \cite{LiuSierra2013} for an analogous result for derived representations of a quiver. Note that their bounded derived categories agree with our categories by \cite[Proposition 7.4]{BBPSWstructural}. As already observed there, these computations in particular demonstrate the failure of the (categorical) structure presheaf on the spectrum to satisfy the sheaf condition. 
\end{Rem}

As a first application of \cref{thm:spcfinite}, we extract a structural property detected by the homological support for arbitrary collections of finite groups (\cref{prop:hsupptt+}). We will begin with two auxiliary lemmas.  

\begin{Lem}\label{lem:upwardhsupp}
    Let $i \colon \cat U \to \cat V$ be the inclusion of a down-closed subcategory and $j \colon \cat V \, \backslash \, \cat{U} \to \cat V$ the inclusion of its complement, which is closed upwards. For $X \in \D{\cat{V}}$, we have:
        \begin{enumerate}
            \item if $\hsupp(X) \subseteq \cat V \, \backslash \, \cat{U}$, then the counit map $j_!j^*X \xrightarrow{\simeq} X$ is an equivalence;
            \item $X \in \loct{e_{G}\mid G \in \ua(\hsupp(X))}$. If $X$ is compact, we may  take the thick ideal instead of the localizing tensor-ideal. 
        \end{enumerate}
\end{Lem}
\begin{proof}
  From \cref{rem-fibre-seq-recollement}, we obtain a cofibre sequence
        \[
            j_!j^*X \to X \to i_*i^*X.
        \]
    By assumption on the homological support and \eqref{eq:hsupprestriction}, we deduce that $i^*X \simeq 0$, hence the counit map $j_!j^*X \to X$ is an equivalence. 

    Now the first claim in (b) follows from (a) applied to $\cat V \, \backslash \, \cat{U} = \ua(\hsupp(X))$, using the fact that $j_!$ preserves tensors (\cref{prop-incl-preserve-compacts}(a)):
        \begin{align*}
            X \simeq j_!j^*X & \in j_!\loct{e_{G}\mid G \in \ua(\hsupp(X))} \\
                & \subseteq \loct{j_!e_{G}\mid G \in \ua(\hsupp(X))} \\
                & = \loct{e_{G}\mid G \in \ua(\hsupp(X))}.
        \end{align*}
    Finally, the claim about compact $X$ is a formal consequence of this and the Neeman--Thomason localization theorem, since the $e_G$s are compact, see for example \cite[Theorem 7.1]{Greenlees2019}.
\end{proof}

\begin{Lem}\label{lem:downwardhsupp}
    Let $\cat{V}\subseteq \cat G$ be a subcategory. Write $i\colon \cat{U} \to \cat{V}$ for the inclusion of some down-closed subcategory. For $Y,Z \in \D{\cat{U}}$, the cofibre of the oplax monoidal structure on $i_!$ satisfies 
        \[
            \mathrm{cof}(i_!(Y \otimes Z) \to i_!(Y) \otimes i_!(Z)) \in \loct{e_G\mid G \in \cat V \, \backslash \, \cat{U}}.
        \]
    In particular, for $X \in \D{\cat{U}}^c$, we have 
        \[
            i_!\thickt{X} \subseteq \thickt{\{i_!X\}\cup\{e_G\mid G\in \cat V \, \backslash \, \cat{U}\}}.
        \]
\end{Lem}
\begin{proof}
    Let $j\colon  \cat V \, \backslash \, \cat{U} \to \cat{V}$ denote the inclusion of the complement. For any $Y,Z \in \D{\cat{U}}$, the oplax monoidal structure on $i_!$ gives a cofibre sequence
        \[
            i_!(Y \otimes Z) \to i_!(Y) \otimes i_!(Z) \to C
        \]
    in $\D{\cat{V}}$. Since $i^*$ is strong monoidal and the unit transformation $\mathrm{id} \to i^*i_!$ is an equivalence, we deduce that $i^*(C) \simeq 0$. Substituting this into the cofibre sequence 
        \[
            j_!j^*C \to C \to i_*i^*C
        \]
    from \cref{rem-fibre-seq-recollement} yields $C \simeq j_!j^*(C) \in \loct{e_G\mid G \in \cat V \, \backslash \, \cat{U}}$, as in \cref{lem:upwardhsupp}(b). In particular, 
    \[
    i_!(X\otimes Z) \in \thick{i_!(X) \otimes i_!(Z), C} \subseteq \thickt{\{i_!X\}\cup\{e_G\mid G\in \cat V \, \backslash \, \cat{U}\}}.
    \]
    The claim about thick ideals follows since $i_!$ is exact.
\end{proof}

This lemma motivates the following notation. Recall that for a subcategory $\cat V\subseteq \cat G$, we write $\cat V_{\leq n}$ (respectively $\cat V_{>n}$) for the subcategory of $\cat V$ of groups of cardinality less than or equal to $n$ (respectively greater than $n$).

\begin{Def}\label{def:ttideal+}
   For $X \in \D{\cat{V}}^c$ and any $n \geq 0$, we write 
   \[
   \ua(\hsupp(X))_{>n} = \{G \in \pi_0\cat{V}_{>n} \mid \exists H \in \hsupp(X)\colon G \gg H\}.
   \]
   We then define an auxiliary thick ideal
        \[
            \mathrm{thick}_{\otimes,n}^{+}\langle X\rangle \coloneqq  
            \thickt{\{X\}\cup\{e_G\mid G\in\ua(\hsupp(X))_{>n}\}}.
        \]
    For varying $n$ these ideals form a nested sequence; set 
    \[
    \mathrm{thick}_{\otimes}^{+}\langle X\rangle \coloneqq \bigcap_{n>0}\mathrm{thick}_{\otimes,n}^{+}\langle X\rangle.
    \]
\end{Def}

\begin{Prop}\label{prop:hsupptt+}
    Let $\cat V\subseteq \cat G$ be a subcategory and consider $X,Y\in\D{\cat{V}}^c$ with $\hsupp(X)\subseteq \hsupp(Y)$.  Then $X\in\mathrm{thick}_{\otimes}^{+}\langle Y \rangle$. 
\end{Prop}
\begin{proof}
    We first prove the claim in the special case $\ua{(\hsupp(Y))} = \cat{V}$. To this end, pick a finite set $\cat{S} \subseteq \cat{V}$ such that $X$ and $Y$ are contained in $\thick{e_{G}\mid G \in \cat{S}}$. Let $n \geq \max\{|G| \mid G \in \cat{S}\}$ and write $i \colon \cat{V}_{\leq n} \to \cat{V}$.  This guarantees that the corresponding counit maps are equivalences: $i_!i^*(X) \simeq X$ and  $i_!i^*(Y) \simeq Y$, as can be checked on the generators $e_G$ for $G \in \cat{S}$. By \eqref{eq:hsupprestriction}, we have $\hsupp(i^*X) \subseteq \hsupp(i^*Y)$, so \cref{prop:spcfinite} implies $i^*X \in \thickt{i^*Y}$. Applying $i_!$ and appealing to \cref{lem:downwardhsupp}, we get
        \begin{align*}
            X \simeq i_!i^*(X) \in i_!\thickt{i^*Y} & \subseteq \thickt{\{i_!i^*Y\}\cup\{e_G\mid G\in \pi_0\cat{V}_{>n}\}} \\
            & = \thickt{\{Y\}\cup\{e_G\mid G\in\ua(\hsupp(Y))_{>n}\}}.
        \end{align*}
    Since $n$ may be taken arbitrarily large, we conclude that $X \in \mathrm{thick}_{\otimes}^{+}\langle Y \rangle$ when $\ua{(\hsupp(Y))} = \cat{V}$.

    The general case can then be deduced as follows: Write $j\colon \ua{(\hsupp(Y))} \to \cat{V}$ for the inclusion. The counit map $j_!j^* \to \mathrm{id}$ is an equivalence (\cref{lem:upwardhsupp}(a)) on $X$ and $Y$. In addition, $j_!$ preserves tensors (\cref{prop-incl-preserve-compacts}(a)), $e_G$s (\cref{rem-restriction-gen}), and homological support \eqref{eq:hsupppushforward}, so
        \[
            j_!\mathrm{thick}_{\otimes,n}^{+}\langle j^*X\rangle \subseteq \mathrm{thick}_{\otimes,n}^{+}\langle j_!j^*X\rangle = \mathrm{thick}_{\otimes,n}^{+}\langle X\rangle
        \]
        for any $n \geq 0$. By \eqref{eq:hsupprestriction}, $\hsupp(j^*X) \subseteq \hsupp(j^*Y)$. Using the claim for $\cat{V} = \hsupp(j^*Y)$ as just established, we thus get
        \[
            X \simeq j_!j^*(X) \in j_!\mathrm{thick}_{\otimes,n}^{+}\langle j^*Y\rangle \subseteq \mathrm{thick}_{\otimes,n}^{+}\langle Y\rangle.
        \]
    Taking the intersection for varying $n$ then gives the desired claim. 
\end{proof}


\section{Embedding group primes}\label{sec:ttembedding}
In this section we give a criterion for verifying if a group prime is isolated in the Balmer spectrum. We then deduce that the group prime map \eqref{eq:groupprimemap} is an open embedding for any downwards closed subcategory of finite $p$-groups. 

\begin{Def}\label{def:downclosure}
    For $G \in \cat{U}$, we define the \emph{down-closure} of $G$ in $\cat U$ by
    \[
    \cat U_{\ll G} \coloneqq \{H \in \cat{U}\mid G \gg H\}
    \]
    and denote its complement by $\cat U_{\not \ll G} \coloneqq \cat U \, \backslash\, \cat U_{\ll G}.$
\end{Def}

The next lemma highlights the relevance of the previous subcategories.

\begin{Lem}\label{lem:lambdaG}
    For any $K \in \cat{U}$, we have
        \[  
            e_K \in \mathfrakp_G \iff K \notin \; \cat U_{\ll G} \iff K \in \; \cat U_{\not \ll G}.
        \]
\end{Lem}
\begin{proof}
    By definition, $e_K\in \mathfrakp_G$ if and only if $e_K(G) = 0$, which holds if and only if $G \not \gg K$. This is equivalent to $K \notin \cat U_{\ll G}$ and to $K \in \cat U_{\not \ll G}$.
\end{proof}
As a consequence we describe the derived category $\D{\{G\}}$ as a Verdier quotient. 

\begin{Prop}\label{prop:groupprimeVerdier}
    For any $G \in \cat{U}$, the evaluation functor
    $\ev_G \colon \D{\cat U} \to \D{\{G\}}$
    induces a symmetric monoidal equivalence
    \[
            \D{\cat{U}}/\loc{\mathfrakp_G} \simeq \D{\{G\}}.
    \]
    After passing to compact objects, there is a non-unital symmetric monoidal equivalence
        \[
            (\D{\cat{U}}^{c}/\mathfrakp_G)^{\natural} \simeq \D{\{G\}}^{c}
        \]
        which is symmetric monoidal if $\cat U$ satisfies \cref{hyp2}.
\end{Prop}
\begin{proof}
      Let us prove the first claim. To this end, let $i \colon \cat U_{\ll G} \to \cat{U}$ and $j \colon \cat U_{\not \ll G} \to \cat U$ denote the inclusions. \Cref{lem:lambdaG} shows that there is a containment  
     \[
     \mathrm{im}(j_!)=\loc{e_K\mid K \in \cat U_{\not \ll G}} \subseteq \loc{\mathfrakp_G}.
     \]
    It follows that the Verdier quotient $\D{\cat U}/\loc{\mathfrakp_G}$ can be calculated in two steps: by first nullifying $\mathrm{im}(j_!)$, and then by nullifying the image of $\loc{\mathfrakp_G}$ in the quotient $\D{\cat U}/\mathrm{im}(j_!)$. Now \cref{cor:verdierquotient} tells us that the nullification of $\mathrm{im}(j_!)$ is equivalent to $\D{\cat U_{\ll G}}$ via the functor $i^*$. Therefore we have a factorization as in the following commutative square 
        \[
            \xymatrix{
            \loc{\mathfrakp_G} \ar[r]\ar[d]^{i^*} &\D{\cat{U}}\ar[r] \ar[d]^{i^*} & \D{\cat{U}}/\loc{\mathfrakp_G} \ar@{=}[d] \\
            \loc{\mathfrakp_G} \ar[r] &\D{\cat{U}_{\ll G}} \ar[r] & \D{\cat{U}_{\ll G}}/\loc{\mathfrakp_G} \ar[r] & \D{\{G\}}.
            }
        \]
   This reduces the claim to $\cat{U}_{\ll G}$ which is essentially finite. In other words, we need to prove that the right most horizontal arrow in the above diagram is an equivalence. Write $\cat{U}_{< G}\coloneqq\cat{U}_{\ll G}\, \backslash \,\{G\}$, and let $k\colon \cat{U}_{< G} \to \cat{U}_{\ll G}$ and $h \colon \{G\}\to \cat U_{\ll G}$ be the inclusions. In light of \cref{cor:verdierquotient}, the functor $h^*$ induces an equivalence 
   \[
   \frac{\D{\cat U_{\ll G}}}{\im(k_*)}\xrightarrow{\sim} \D{\{G\}}
   \]
   so it suffices to verify the equality
   \[
   \loc{\mathfrakp_G}=\mathrm{im}(k_*).
   \]
    Since $k_*$ is given by extension by zero and $\cat{U}_{\ll G}$ is essentially finite so the objects $\chi_{H,k}$s are compact (\cref{lem:chi-compact}), we have 
        \[
            \mathrm{im}(k_*) = \loc{\chi_{H,k}\mid H \in \cat U_{<G}} = \loc{\mathrm{im}(k_*)^c}.
        \]
    The claim then follows because both $\mathfrakp_G$ and $\im(k_*)^c$ agree with 
    \[
    \thickt{\chi_{H,k}\mid H \in \cat U_{<G}}\subseteq \D{\cat U_{\ll G}}^c
    \]
    by \cref{prop:spcfinite}.
    The second claim follows from the first one together with the Neeman--Thomason localization theorem \cite[Theorem 2.1]{Neeman92}. Recall that in general $\D{\cat U}^c$ is only non-unital symmetric monoidal, however under \cref{hyp2} it also admits a unit object.
\end{proof}   

This result leads to a strengthening of \cref{prop:groupprimes}:

\begin{Cor}\label{cor:groupprimes_generic}
    Let $\cat U$ be a subcategory satisfying \cref{hyp2}. For any $G \in \cat{U}$, the group prime $\mathfrakp_G$ is a maximal prime in $\Spc(\D{\cat{U}}^{c})$, that is, if $\mathfrakp \in \Spc(\D{\cat{U}}^{c})$ is such that $\mathfrakp_G \subseteq \mathfrakp$, then $\mathfrakp_G = \mathfrakp$.
\end{Cor}
\begin{proof}
    The Verdier localization $\D{\cat{U}}^{c}\to (\D{\cat{U}}^{c}/\mathfrakp_G)^{\natural}$ induces a bijection between the spectrum of the quotient and those primes $\mathfrakp$ in $\D{\cat{U}}^{c}$ containing $\mathfrak{p}_G$, see \cite[Proposition 3.11]{Balmer2005}. Using \cref{prop:groupprimeVerdier}, we thus get a bijection
        \[
            \Spc(\D{\{G\}}^{c}) \cong \Spc((\D{\cat{U}}^{c}/\mathfrakp_G)^{\natural}) \cong \{\mathfrakp \in \Spc(\D{\cat{U}}^c) \mid \mathfrakp_G \subseteq \mathfrakp\}.
        \]
    The claim follows, because $\Spc(\D{\{G\}}^{c})$ is a point by \cref{thm:spcfinite}.  
\end{proof}
\begin{proof}[Alternative proof]
    More concretely, we could argue as follows.  Consider a compact object $X\notin\mathfrak{p}_G$, and an arbitrary $Y \in \D{\cat{U}}^c$; it suffices to show that $Y$ lies in the thick ideal $\cat{J}$ generated by $\mathfrak{p}_G\cup\{X\}$. By \cref{lem-prop-e_g}(b) there is a canonical map $e_{G,X(G)}\to X$, and we let $X'$ be the cofibre.  By construction we have $X'(G)\simeq 0$ so $X'\in\mathfrak{p}_G$ and $e_{G,X(G)}\in\cat{J}$. 
 We are assuming that $X\notin\mathfrak{p}_G$ so $X(G)\not\simeq 0$ so $e_{G,X(G)}$ generates the same thick ideal as $e_G$ by \cref{cor-eG-eGV}.  We therefore have $e_G\in\cat{J}$, and so $e_{G,V}\in\cat{J}$ for any $V \in \D{\{G\}}^c$.  We have another cofibre sequence $e_{G,Y(G)}\to Y\to Y'$ with $e_{G,Y(G)}\in\cat{J}$ and $Y'\in\mathfrak{p}_G\subseteq\cat{J}$, so $Y\in\cat{J}$ as required.
\end{proof}

\begin{Rem}
    Although all group primes are maximal primes, the converse does not hold in general. Indeed, the spectrum $\Spc(\D{\cat{C}_p}^c)$ of \cref{exa:cyclicp} is Hausdorff, hence all of its points are maximal primes, but $\mathfrakp_{\infty}$ is not a group prime.  
\end{Rem}

Recall that a point $x\in X$ in a topological space is said to be \emph{isolated} if the set $\{x\}$ is open in $X$; when $X$ is non-Hausdorff, this does not imply that $X$ is the coproduct of $\{x\}$ and $X\setminus\{x\}$. We now state our criterion for verifying whether a group prime is isolated in the Balmer spectrum of $\D{\cat{U}}^{c}$. 

\begin{Prop}\label{lem:isolation_criterion}
    Let $\cat U$ be a subcategory satisfying \cref{hyp2} and let $G \in \cat{U}$. If $\pi_0 \cat U_{\not \ll G}$ has finitely many minimal elements under $\gg$, then $\mathfrakp_G \in \Spc(\D{\cat{U}}^{c})$ is isolated. 
\end{Prop}
\begin{proof}
    Let $\{G_1,\ldots, G_n\}$ be a complete list of the minimal elements in $\pi_0 \cat U_{\not \ll G}$ and consider the set $\cat S=\{e_{G_1},\ldots, e_{G_n}\}$. 
    We first claim that 
    \[
    \D{\cat U_{\not \ll G}}^c=\thickt{\cat S}.
    \]
   In fact it will be enough to show that $e_K \in \thickt{\cat S}$ for all $K \in \cat U_{\not \ll G}$. By definition of minimal elements, given $K\in \cat U_{\not \ll G}$ there exists $G_i$ and an epimorphism $K \gg G_i$. Then we know by \cite[Proposition 4.11]{PolStrickland2022} that there exists some representation $W$ so that $e_{K,W}$ is a retract of $e_{K}\otimes e_{G_i}$ (this is because the graph subgroup of the epimorphism $K \to G_i$ is a wide subgroup of $G_i\times K$). Now by \cref{cor-eG-eGV} we know that $e_{K}$ and $e_{K,W}$ generate the same thick ideal so we conclude that $e_K \in \thickt{e_{G_i}} \subseteq \thickt{\cat S}$, verifying our claim. 

    Next, let $i\colon \cat U_{\ll G} \to \cat{U}$ denote the inclusion and write $j\colon\cat U_{\not \ll G} \to \cat{U}$ for the inclusion of the complement. By the previous paragraph we can assume that $\D{\cat U_{\not \ll G}}$ is generated as a thick ideal by a finite set $\cat S$. By \cref{cor:verdierquotient}, there is a Verdier localization
        \[
            i^*\colon \D{\cat{U}}^{c} \to \D{\cat U_{\ll G}}^{c} 
        \]
    with kernel $\thickt{j_!\cat{S}}$. Note that the finiteness of $\cat{S}$ guarantees that the Thomason subset $\supp(j_!\cat{S}) \subseteq \Spc(\D{\cat{U}}^{c})$ is in fact closed. Therefore, $i^*$ induces an \emph{open} embedding $\Spc(\D{\cat U_{\ll G}}^{c}) \hookrightarrow \Spc(\D{\cat{U}}^c)$ on spectra. By \cref{thm:spcfinite}, the space $\Spc(\D{\cat U_{\ll G}}^{c})$ is discrete; in particular, $\mathfrakp_G$ viewed as a point in this space is isolated. It thus follows that $\mathfrakp_G$ is also isolated in $\Spc(\D{\cat{U}}^{c})$, as desired.
\end{proof}

\begin{Rem}\label{rem:isolation_criterion}
    We can make the previous proposition more explicit. To this end, consider an essentially small tt-category $\cat{K}$ , and let $\mathfrakp$ be a point of $\Spc(\cat{K})$. Then we claim that $\mathfrakp$ is isolated if and only if the following conditions hold:
    \begin{enumerate} 
        \item it is a maximal prime ideal in $\Spc(\cat{K})$; and
        \item there is an object $X\in\cat{K}$ with $\mathfrak{p}=\sqrt{\thickt{X}}$.
    \end{enumerate}
Since prime ideals are radical, the second condition is implied by the existence of some object $X$ with $\mathfrak{p}=\thickt{X}$. To prove the claim, we first note that \cite[Proposition 2.14]{Balmer2005} shows that $\mathfrakp$ is isolated if and only if there exists some $X \in \cat{K}$ such that $\{\mathfrakp\}=\Spc(\cat{K})\setminus\supp(\sqrt{\thickt{X}})$. Note that the latter set is always closed upwards under inclusions of prime ideals. Since the complement of $\supp(\mathfrakp)$ is  precisely $\SET{\mathfrakq}{\mathfrakq \supseteq \mathfrakp}$ (see \cite[Lemma 4.6]{Balmer2005}), we thus see that $\mathfrakp$ is isolated if and only if
    \[
        \{\mathfrakp\} = \Spc(\cat{K})\setminus\supp(\sqrt{\thickt{X}}) = \Spc(\cat{K})\setminus\supp(\mathfrakp) = \SET{\mathfrakq}{\mathfrakq \supseteq \mathfrakp}.
    \]
The middle and composite displayed equality translate into Conditions (b) and (a) above, respectively, thereby finishing the proof of the claim. 

Under the assumptions of \cref{lem:isolation_criterion}, we can then specify an explicit generator for the group prime $\mathfrakp_G$: Suppose we have a finite collection of elements $H_1,\dotsc,H_r\in\cat{U}_{\not\leq G}$ such that every $H\in\cat{U}_{\not\leq G}$ admits an epimorphism to some $H_i$.  Let $P_G$ be the cofibre of the evident augmentation $e_{G,k}\to\unit$, then
    \[
        \mathfrak{p}_G=\thickt{P_G \oplus \bigoplus_ie_{H_i}}.
    \]
This gives an alternative approach to \cref{lem:isolation_criterion}.
\end{Rem}

\begin{Rem}
In \cref{exa:cyclicprimes} we saw that the group prime $\mathfrakp_{C_p} \in \Spc(\Cprime)$ is isolated. However $\Cprime_{\not \ll C_p}=\{C_q \mid q \not =p \; \mathrm{prime}\}$ has infinitely many minimal elements. This shows that our criterion only gives a sufficient condition for isolation.   
\end{Rem}


\begin{Cor}\label{prop:pgroup_embedding}
    Let $p$ be a prime number and let $\cat U$ be a downwards closed subcategory of finite $p$-groups. Then the map $\mathfrakp_{-}\colon \pi_0\cat{U} \to \Spc(\D{\cat{U}}^c)$ is an open embedding.
\end{Cor}
\begin{proof}
    We will verify the criterion of \cref{lem:isolation_criterion}. To this end, fix some $G\in \cat U$ and let $K$ be a minimal element in $\pi_0 \cat U_{\not \ll G}$, and note that $K$ must be nontrivial. Standard $p$-group theory tells us that the centre $Z(K)$ is nontrivial and that there is a subgroup $C \leq Z(K)$ of order $p$. As $C \cong C_p$ is central, it is normal and so we have an extension $ C_p \hookrightarrow K \twoheadrightarrow Q$. By minimality of $K$, we must have $Q \in \cat U_{\ll G}$ since $\cat U$ is closed downwards. Therefore to prove that there are only finitely many minimal elements $K$, it suffices to show that:
   \begin{enumerate}
       \item there are finitely many groups $Q\in \pi_0\cat U_{\ll G}$;
       \item for a fixed $Q$ there are only finitely many groups $K \in \pi_0\cat{G}$ which fit into an extension of the type $C_p \hookrightarrow K \twoheadrightarrow Q$.
   \end{enumerate}
   Part (a) is clear since any group in $\cat U_{\ll G}$ must have cardinality less than or equal to $|G|$. For part (b) note that if we consider extensions where the kernel is $C_p$, then they are
 classified by the finite group $H^2(Q;C_p)$.
\end{proof}

\begin{Rem}
    It is conceivable that the hypothesis that $\cat{U}$ is downwards closed in the previous corollary could be relaxed. However, it cannot be removed completely, as the conclusion of the corollary does not hold for some subcategories $\cat U$ of finite $p$-groups. Some examples are given by extraspecial $p$-groups. We demonstrate this in the following explicit example. 

    Let $p=2$, write $Q_8$ for the quaternion group, and let $C$ denote the centre of $Q_8$, which has order $2$. Then set $E_1=Q_8$, $E_2=Q_8 \times_C Q_8$ amalgamated with respect to the diagonal copy of $C$, and $E_n=E_{n-1} \times_C Q_8$ for $n \geq 3$.
    For each $n$, the $2$-group $E_n$ is extraspecial, meaning that the centre $C$ of $E_n$ has order two and the quotient $E_n/C$ is an elementary abelian $2$-group. Let $c \in C$ denote the non-identity element of the centre. If  $a \notin C$, then either $a^2=c$, or we can conjugate $a$ with an element in the first copy of $Q_8$ and multiply with $a$ to obtain $c$. This shows that all non-trivial normal subgroups $\{1\} \neq N \lhd E_n$ contain $C$. Therefore there exist no epimorphisms from $E_n$ to $E_m$ for $n \neq m$, because any non-trivial quotient of $E_n$ is a quotient of the elementary abelian group $E_n/C$, and $E_m$ is non-abelian.

    If we let $\cat{U}$ denote the family formed by the $E_n$'s and the trivial group $1$, then $\cat{U} \setminus \{1\}$ is a groupoid, and the subcategory $\cat{U} \subset \cat{G}$ has the same structure as the category of cyclic groups of prime order and the trivial group of \cref{exa:cyclicprimes}. The resulting spectrum $\Spc(\D{\cat{U}}^{c})$ is homeomorphic to the one shown in \cref{exa:cyclicprimes}, and in this case, the group prime map $\mathfrakp_{-}\colon \pi_0\cat{U} \to \Spc(\D{\cat{U}}^c)$ is neither an embedding nor open.
\end{Rem}

As one application of \cref{prop:pgroup_embedding}, we obtain a sharper version of \cref{thm:spcfinite} when restricting attention to downwards closed families of finite $p$-groups. Without any such constraint, however, \Cref{exa:cyclicprimes} demonstrates that the conclusion of the next corollary fails. 

\begin{Cor}\label{cor:spcfinitep_characterization}
    For a downwards closed family of finite $p$-groups $\cat{U}$, the following conditions are equivalent:
        \begin{enumerate}
            \item $\mathfrakp_{-}\colon \pi_0\cat{U} \to \Spc(\D{\cat{U}}^{c})$ is a surjection;
            \item $\mathfrakp_{-}\colon \pi_0\cat{U} \to \Spc(\D{\cat{U}}^{c})$ is a homeomorphism;
            \item $\cat{U}$ is essentially finite.
        \end{enumerate}
\end{Cor}
\begin{proof}
    By \cref{prop:pgroup_embedding}, $\mathfrakp_{-}$ is an embedding. A surjective embedding is a homeomorphism, so $(a) \Rightarrow (b)$. Condition $(b)$ implies that $\Spc(\D{\cat{U}}^{c})$ is discrete. Since it is always spectral and thus in particular quasi-compact, it must be finite, which gives $(c)$. Finally, the implication $(c) \Rightarrow (a)$ is proven in \cref{thm:spcfinite}. 
\end{proof}

\begin{Rem}
    This result amply demonstrates the failure of the surjectivity criterion of \cite{BCHS2024} in the context of non-rigidly compactly generated tt-categories. Let $\cat{U}$ be a downwards closed family of finite $p$-groups. While the evaluation functors
        \[
            (\mathrm{ev}_{G}\colon \D{\cat{U}} \to \D{\{G\}})_{G \in \pi_0\cat{U}}
        \]
    are jointly conservative, the induced maps on spectra are not jointly surjective, unless $\cat{U}$ is essentially finite. 
\end{Rem}

We conclude this section with a computation of the Balmer spectrum for global representations indexed on the multiplicative global family of elementary abelian $p$-groups $\cat E_p$, for some prime number $p$, and explain the interpretation in terms of derived VI-modules.

\begin{Thm}\label{thm-elementary}\leavevmode
The category $\sD(\cat E_p)^c$ is standard (in the sense of \cref{def:standardtt}) and its spectrum is given as follows:
\begin{enumerate}
    \item The only prime ideals in $\sD(\cat E_p)^c$ are the group primes $\mathfrakp_{(\bbZ/p)^{\times n}}$ for $n \in \bbN$ and the zero ideal $(0)$ which we denote by $\mathfrakp_\infty$. Therefore we may identify the underlying set of the spectrum with $\pi_0\cat E_p \cup \{\mathfrakp_\infty\}$.
    \item A subset $U$ is open in the Balmer topology on $\Spc(\D{\cat{E}}^c)$ if and only if it is contained in $\pi_0\cat E_p$, or is equal to the whole set. Moreover, $U$ is a quasi-compact open if and only if it is a finite subset of $\pi_0\cat E_p$ or equal to the whole set.
 \end{enumerate}
 In other words, the Balmer spectrum of $\D{\cat{E}}^c$ can be depicted in the following way:
	\[
	\begin{tikzcd}
         &            &  (0)           &        &               &       \\
	\mathfrakp_{(\bbZ/p)^{\times 0}} \arrow[urr, rightsquigarrow] & \mathfrakp_{(\bbZ/p)^{\times 1}} \arrow[ur, rightsquigarrow]  & \mathfrakp_{(\bbZ/p)^{\times 2}} 
	\arrow[u, rightsquigarrow] & \ldots & \mathfrakp_{(\bbZ/p)^{\times n}} \arrow[ull, rightsquigarrow]& \ldots 
	\end{tikzcd}
	\]
    Thus, $\Spc(\D{\cat{E}}^c)$ is homeomorphic to the Hochster dual of $\Spec(\bbZ)$.
\end{Thm}
\begin{proof}
    Throughout this proof we will adopt the following notation: Any group in $\cat E_p$ is isomorphic to $(\bbZ/p)^{\times n}$ for some $n$. In what follows we will abbreviate $(\bbZ/p)^{\times n}$ to $n$, and write $e_{n,V}$ instead of $e_{(\bbZ/p)^{\times n}, V}$. Likewise, we denote the corresponding group prime by $\mathfrakp_n$.

    We begin by establishing two auxiliary properties of $\sD(\cat E_p)^c$, which both rely on \cref{thm:nontorsion}:
        \begin{enumerate}%[align=left]
            \item[(1)] $\hsupp(X) \subseteq \hsupp(Y) \implies \thickt{X} \subseteq \thickt{Y}$ for all $X,Y \in \sD(\cat E_p)^c$;
            \item[(2)]
            $\hsupp(X) \subseteq \pi_0\cat E_p$ is cofinite for all $X \in \sD(\cat E_p)^c$ nontrivial.
        \end{enumerate}
    Note that, in particular, (1) shows that $\D{\cat{E}}^c$ is standard: $\hsupp(X) = \hsupp(X \otimes X)$ for any $X \in \D{\cat{E}}^c$, so $X \in \thickt{X \otimes X}$ by (1). This means we can apply Balmer's criterion \cite[Proposition 4.4]{Balmer2005}.

    Let us prove Statement (1). When $n\geq m$, \cite[Remark 4.12]{PolStrickland2022} shows that $e_n$ is a retract of $e_n\otimes e_m$, so $e_n\in\thickt{e_m}$. \Cref{thm:nontorsion} tells us that there exists $n_0$ with $e_{n_0}\in\thickt{Y}$ and so $e_n\in\thickt{Y}$ for all $n\geq n_0$. From this it is clear that when $n \geq n_0$, we have $\mathrm{thick}_{\otimes,n}^{+}\langle Y\rangle = \thickt{Y}$. Therefore $\mathrm{thick}_{\otimes}^{+}\langle Y \rangle = \thickt{Y}$, so we conclude by \cref{prop:hsupptt+}. To see Statement (2), \Cref{thm:nontorsion} again shows that there exists $n_0$ with $e_{n_0}\in\thickt{X}$, so $\hsupp(e_{n_0}) \subseteq \hsupp(X)$. The former subset of $\pi_0\cat E_p$ is cofinite, hence so is the latter.

    Now consider some nonzero prime ideal $\mathfrakq \in \Spc(\sD(\cat E_p)^c)$. We claim that there exists $s \in \bbN$ such that $\mathfrakq = \mathfrakp_s$. Since the zero ideal is prime by \cref{prop:zeroideal}, this determines the underlying set of the spectrum. In order to establish the claim, take some nonzero $X \in \mathfrakq$. By (2), its homological support is cofinite, say $\hsupp(X) = \pi_0\cat E_p \setminus S$ for some finite $S$. Note that $S$ must be non-empty, for otherwise $\hsupp(X) = \hsupp(\unit)$ so that $\unit \in \mathfrakq$ by (1), a contradiction. 

    Put $m_{s}\coloneqq \cof(e_{s, k} \to \unit)$. One calculates that $\hsupp(m_{s})=\pi_0 \cat E_p \setminus \{s\}$. Therefore, 
        \[
            \hsupp(X) = \bigcap_{s\in S}\hsupp(m_s) = \hsupp(\bigotimes_{s \in S}m_s).
        \]
    By (1), this gives $\bigotimes_{s \in S}m_s \in \thickt{X} \subseteq \mathfrakq$, so there exists $s \in S$ with $m_s \in \mathfrakq$ because $\mathfrakq$ is prime. Any $Y \in \mathfrakp_{s}$ satisfies $\hsupp(Y) \subseteq \pi_0 \cat E_p \setminus \{s\} = \hsupp(m_s)$, which implies $Y \in \thickt{m_s}$, again by (1). Combining these statements, we obtain containments
        \[
            \mathfrakp_{s} \subseteq \thickt{m_s} \subseteq \mathfrakq.
        \]
    But group primes are maximal primes by \cref{cor:groupprimes_generic}, so that these containments are in fact equalities, thereby establishing the claim. 

    It remains to determine the topology on $\Spc(\sD(\cat E_p)^c)$. Note that the group primes are isolated (\Cref{prop:pgroup_embedding}) but not closed (as each of them contains $\mathfrakp_\infty$), while the zero prime ideal $\mathfrakp_\infty$ is closed but not isolated (as otherwise all points would be isolated, contradicting quasi-compactness). Now consider an open subset $U$ in $\Spc(\sD(\cat E_p)^c)$. On the one hand, if $U$ does not contain $\mathfrakp_\infty$, then there are no constraints on $U$. On the other hand, if $U$ contains $\mathfrakp_\infty$, then its closed complement must be empty, because every closed subset contains $\mathfrakp_\infty$; hence $U = \Spc(\sD(\cat E_p)^c)$. This also determines the quasi-compact open subsets, thus finishing the proof. 
\end{proof}

\begin{Rem}\label{rem:fingenideals}
    In the course of the proof of \cref{thm-elementary}, we have seen that every prime ideal in $\sD(\cat E_p)^c$ is generated by a single object; in fact, this holds for all thick ideals. An explanation for this phenomenon is given in \cite{ttCohen_pre}. Indeed, for an essentially small tt-category $\cat K$, the following conditions are equivalent:
        \begin{enumerate}
            \item every prime ideal in $\cat K$ is generated by a single object;
            \item every radical ideal in $\cat K$ is generated by a single object;
            \item the Hochster dual of $\Spc(\cat K)$ is Noetherian.
        \end{enumerate}
\end{Rem}

\begin{Rec}\label{rec:VImod}
    Let $\VI$ denote the category of finite-dimensional $\bbF_p$-vector spaces and injective homomorphisms. The symmetric monoidal abelian category of VI-modules is defined as 
        \[
            \VIMod \coloneqq \Fun(\VI,\Mod{k}),
        \]
    equipped with pointwise additive and tensor structure. This category features prominently in representation stability, see for example \cite{PutmanSam2017}. Pontryagin duality furnishes an equivalence of categories $\VI \simeq \cat{E}^{\op}$ and hence a tt-equivalence
        \[
            \sfD(\VIMod) \simeq \sfD(\cat{E}). 
        \]
    Keeping in mind \cref{rem:fingenideals}, we can thus translate \cref{thm-elementary} into a classification of derived VI-modules:
\end{Rec}

\begin{Cor}\label{cor:VImod}
        Homological support induces a bijection
        \[
            \begin{tikzcd}[ampersand replacement=\&,column sep=small]
                {\begin{Bmatrix}
                    \text{principal ideals } \langle M\rangle_{\otimes}\colon \\
                    M \in \sfD(\VIMod)^c
                \end{Bmatrix}}
                    \& 
                {\begin{Bmatrix}
                    \text{cofinite subsets }\\
                    \text{of } \bbN, \text{ or } \emptyset
                \end{Bmatrix}}.
                    \arrow["\sim", from=1-1, to=1-2]
            \end{tikzcd}
        \]
\end{Cor}
\begin{proof}
    The universal support function \eqref{eq:ttclassification} provides a bijection between principal thick ideals of $\sfD(\VIMod)^c$ and the complements of quasi-compact open subsets of $\Spc(\sfD(\VIMod)^c)$. By \cref{thm-elementary}, the latter biject with the collection of cofinite subsets of $\pi_0\cat E_p \cup \{\mathfrakp_{\infty}\}$ containing $\mathfrakp_{\infty}$, together with the empty set. Upon identifying $\pi_0\cat E_p$ with $\bbN$ and unwinding the construction of the homological support function via \eqref{eq:groupprimemap}, we obtain the result. 
\end{proof}

Unwinding the construction of the support function, we recover \cref{thmx:VImod}.



