\begin{Exa}
    If there are no infinite chains of non-injective epimorphisms for groups in $\cat{U}$, then $\cat{U}=\hCU$. In particular this applies to any essentially finite subcategory $\cat U$.
\end{Exa}

\begin{Exa}\label{exa:elabp_completion}
    Let $\cat{U}=\cat{E}_p$ be the family of elementary abelian $p$-groups. We claim that $\widehat{\cat E_p}=\cat E_p$. Indeed, any $G \in \hCG$  surjects continuously onto only finitely many groups in $\cat{E}_p$, and so the limit defining $G \in \widehat{\cat{E}_p}$ stabilizes at a finite stage. Therefore for the family $\cat{E}_p$ there is no difference between profinite group primes and group primes. 
\end{Exa}

\begin{Rem}
 If $G \in \cat U$, then $\cat{N}(G;\cat{U})$ admits 
 a minimal element, so $\cat U \subseteq \hCU$.   
\end{Rem}

\begin{Rem}\label{rem:Uhat_cofinal}
    Note that $\cat{N}(G;\cat{U})$ is cofinal in the filtered set $\cat{N}(G)$, so $\cat{N}(G;\cat{U})$ is itself filtered. 
\end{Rem}

Recall from \cref{hyp} that we always assume that $\cat{U}$ is widely closed. The following shows that the wide closure condition extends to the
profinite context.

\begin{Lem}\label{lem-profinite-wide}
 Let $H_0\xleftarrow{\alpha_0}G\xrightarrow{\alpha_1}H_1$ be morphisms with $G\in\hCU$ and $H_0,H_1\in\cat{U}$. Then the image of the combined morphism
 $G\to H_0\times H_1$ also lies in $\cat{U}$.
\end{Lem}
\begin{proof}
 The group $\ker(\alpha_0)\cap\ker(\alpha_1)$ lies in $\cat{N}(G)$, and
 $G\in\hCU$ so we can choose $N\in\cat{N}(G;\cat{U})$ with
 $N\leq\ker(\alpha_0)\cap\ker(\alpha_1)$.  We now have a diagram
 $H_0\xleftarrow{}G/N\xrightarrow{}H_1$ in $\cat{U}$ to which we can apply the wide
 closure axiom to obtain the desired conclusion.
\end{proof}

We now give the central definition of this section. 

\begin{Def}\label{defn-profinite-groupprimes}
  For $G\in\hCU$ and $X\in\A{\cat{U}}$ we define 
 \[ 
 X(G) \coloneqq \colim_{N\in\cat{N}(G;\cat{U})} X(G/N). 
 \]
 This is a filtered colimit by \cref{rem:Uhat_cofinal}, and so is an exact functor of $X$.  It is
 also clear that $(X\otimes Y)(G)=X(G)\otimes Y(G)$.  Thus, the subcategory 
 \[ 
 \pri_G \coloneqq \{X\in\D{\cat{U}}^c\mid H_*(X)(G) =0\}
 \]
 is a prime thick ideal in $\D{\cat{U}}^c$. In analogy with \cref{def:groupprimes}, we call these \emph{profinite group primes}.
\end{Def}

\begin{Rem}\label{rem-ev-const}
 In many cases of interest, when $X\in\D{\cat{U}}^c$ and $G\in\hCU$, the
 colimit system defining $H_*(X)(G)$ will be eventually
 constant.  See \cref{prop-ev-const}(b) for a result of this type.
\end{Rem}

We next extend the group prime map \eqref{eq:groupprimemap} to the profinite case.

\begin{Cons}\label{cons:hsuppextension}
Let $\cat U$ be a subcategory satisfying \cref{hyp2}.
The construction of profinite group primes provides a map 
\begin{equation}\label{eq-profinite-group-prime-map}
    \mathfrakp_{-}=\mathfrakp_{-}^{\hCU}\colon \pi_0\hCU \to \Spc(\D{\cat{U}}^c), \quad G \mapsto \mathfrakp_G.
\end{equation}
This map extends the group prime map of \eqref{eq:groupprimemap}, in that the diagram
\[
\begin{tikzcd}
    \pi_0\cat{U} \ar[dr, "\mathfrakp_{-}^{\cat{U}}"] \ar[d, hookrightarrow] & \\
    \pi_0\hCU \ar[r, "\mathfrakp_{-}^{\hCU}"'] & \Spc(\D{\cat{U}}^c)
\end{tikzcd}
\]
commutes. Moreover, the homological support (\cref{def:hsupp}) then extends to a well-defined function taking values in subsets of $\pi_0\hCU$, by setting 
    \[
        \hsupp_{\hCU}(X) \coloneqq \{G \in \pi_0\hCU \mid H_*(X)(G) \neq 0\} 
    \]
for all $X \in \D{\cat U}^c$. Since the intersection of  $\hsupp_{\hCU}(X)$ with $\pi_0\cat U$ coincides with the usual homological support $\hsupp(X)$, we will mostly drop the subscript from the notation for the \emph{extended homological support} function.
\end{Cons}

\begin{Rem}\label{rem:exthsupp}
    Note that by definition, for any $X \in \D{\cat U}^c$, we have
        \begin{align*}
            \hsupp_{\hCU}(X) & = \{G \in \pi_0\hCU \mid X \notin \pri_G\} \\ 
                & = \{G \in \pi_0\hCU \mid \pri_G \in \supp(X)\} \\
                & = (\mathfrakp_{-}^{\hCU})^{-1}(\supp(X)),
        \end{align*}
    where $\supp(X)$ denotes the universal support of $X$ (see \eqref{eq:ttclassification}). 
\end{Rem}

The following example shows that in general the profinite group prime map \eqref{eq-profinite-group-prime-map} is not bijective. However, in the following sections we provide conditions on $\cat{U}$ which ensure that it is bijective, and demonstrate that these conditions are satisfied for a wide range of natural examples, see \cref{sec-bounded}. 

\begin{Exa}
    Continuing \cref{exa:elabp_completion}, we saw in \cref{thm-elementary} that the Balmer spectrum of $\D{\cat{E}_p}^c$ contains a prime ideal which is not a group prime, and hence the profinite group prime map \eqref{eq-profinite-group-prime-map} is not surjective in this case.
\end{Exa}


\section{Profinite filtrations}\label{sec-profinite-filtrations}
In this section we introduce a special kind of reflective filtration, which we call \emph{profinite}, in which the reflections are compatible with the profinite extension $\hCU$ of $\cat{U}$. We will show that if $\cat U$ admits such a filtration then its profinite extension admits a concrete description in terms of the inverse limit presentation of \cref{cor-ess-finite-invlim}. In the case that the filtration is $r$-generated and essentially finite, we then equip $\hCU$ with a natural profinite topology. We will use these results in the next section to study the profinite group prime map of \eqref{eq-profinite-group-prime-map} and identify the Balmer spectrum for a large collection of families $\cat{U}$.

\begin{Def}\label{defn-filt-profinite}
 A reflective filtration $\{\cat{U}[n]\}_{n\geq 0}$ of $\cat{U}$ is
 \emph{profinite} if each subcategory $\cat{U}[n]$ is reflective in $\hCU$ (and not just in $\cat{U}$), that is, the inclusion $\cat U[n] \to \hCU$ admits a left adjoint $q_n\colon \hCU \to \cat{U}[n]$.  Note that the restriction of $q_n$ to $\cat{U} \to \cat{U}[n]$ (\cref{rem-nested-reflection}) agrees with the original reflection.
\end{Def}

The profinite condition lets us write any $G\in \hCU$ as a filtered limit of its reflections. 

\begin{Prop}\label{prop-ev-const}
     Let $\{\cat{U}[n]\}_{n\geq 0}$ be a profinite reflective filtration of $\cat{U}$ with reflections $q_n \colon \hCU \to \cat U[n]$ and inclusions $i_n \colon \cat U[n]\to \hCU$.
 \begin{enumerate}
     \item  For any $G\in\hCU$ the groups $\ker(G\to q_n(G))$ are cofinal in
 $\cat{N}(G;\cat{U})$, so $G\cong \lim_nq_n(G)$ and $X(G)\cong \colim_n X(q_n(G))$ 
 for all $X\in\A{\cat{U}}$.
 \item For any $X\in\D{\cat{U}}^c$, there exists $n\geq 0$ such
 that:
 \begin{itemize}
 \item[(i)] the counit map $q_n^*i_n^*X \to X$ is an isomorphism; 
 \item[(ii)] $i_n^*X$ is compact;
 \item[(iii)] $H_*(X)(G)\cong H_*(X)(q_n(G))$ for all $G\in\hCU$.
 \end{itemize}
 In particular, the colimit system defining $H_*(X)(G)$ is eventually constant.
 \end{enumerate}
\end{Prop}
\begin{proof}
    Suppose that $M\in\cat{N}(G;\cat{U})$.  Then $G/M\in\cat{U}$, so for sufficiently
 large $n$ we have $G/M\in\cat{U}[n]$, so the map $G\to G/M$ must factor
 through $q_n(G)$, so $\ker(G\to q_n(G))\leq M$. Part (a) follows
 from this. For part (b), recall that by \cref{prop-counit} there exists an $n$ such that the counit map $q_n^*i_n^*X \to X$ is an isomorphism and $i_n^*X$ is compact. Thus $X$ is in the image of $q_n^*\colon \D{\cat{U}[n]}^c\to\D{\cat{U}}^c$. 
 Using this and the fact that $q_n^*$ is exact and so commutes with passage to homology, 
 we have 
 \[
 H_*(X)(q_m(G)) \cong H_*(q_n^*i_n^*X)(q_m(G)) \cong H_*(X)(i_n q_nq_m(G))
 \] 
 which is the same as $H_*(X)(q_n(G))$ when $m\geq n$, so the colimit system defining $H_*(X)(G)$ is eventually constant with value $H_*(X)(q_n(G))$. 
\end{proof}


Most of the reflective filtrations that we have considered are profinite.  As a first step in proving this, we can do essentially the same construction as in \cref{defn-std-filt}, but with profinite groups:
\begin{Def}\label{defn-std-filt-profinite}
 For any $G\in\hCG$, we put 
 \begin{align*}
  \cat{K}_n(G) & \coloneqq \{N\lhd G\mid |G/N|\leq n\}; \\
  K_n(G) & \coloneqq \bigcap_{N\in\cat{K}_n(G)} N = 
    \ker\left(G \to \prod_{N\in\cat{K}_n(G)} G/N\right). \\
 \end{align*}
\end{Def}
With these definitions in place we are ready to prove the following result.

\begin{Prop}\label{prop-invlim}
 The subgroup $K_n(G)$ is open and normal in $G$, so the quotient
 $G/K_n(G)$ is finite.  Moreover, $G$ is the inverse limit of the groups
 $G/K_n(G)$. 
\end{Prop}
\begin{proof}
 By Cayley's theorem, any group of order at most $n$ embeds in the symmetric group $\Sigma_n$, so every group $N\in\cat{K}_n(G)$ is the kernel of some homomorphism $G\to\Sigma_n$.  As $G$ is finitely generated there are only finitely many such homomorphisms (\cref{rem-hCG}), so $\cat{K}_n(G)$ is finite.  It follows that $K_n(G)$ has finite index (and so is open) in $G$, and it is clearly normal. Now let $U\leq G$ be any open subgroup.  Let $N$ be the kernel of the resulting map from $G$ to the finite group of permutations of the set $G/U$, so $N\leq U$ and $N$ again has finite index.  If the index of $N$ is $n$ then we have $K_n(G)\leq N\leq U$.  This shows that the subgroups $K_n(G)$ are cofinal among open normal subgroups of $G$, so $G\cong\lim_n G/K_n(G)$.
\end{proof}

\begin{Rem}\label{rem-hCU-tower}
 If $G\in\hCU$ then we can take $N_1$ to be any finite index subgroup of $G$ with $G/N_1 \in \cat{U}$ and recursively choose open
 normal subgroups $N_{n}\leq K_{n}(G)\cap N_{n-1}$ with $G/N_{n}\in\cat{U}$ for $n \geq 2$.
 We then find that the sequence of subgroups $N_n$ is cofinal in $\cat{N}(G;\cat{U})$, so
 $G\cong\lim_nG/N_n$ and $X(G)\cong\colim_nX(G/N_n)$ for all $X\in\A{\cat{U}}$.
\end{Rem}

We now turn to verifying that several types of reflective filtration are automatically profinite.
\begin{Lem}\label{lem-profinite-refl}
 If $\cat{U}\subseteq\cat{G}$ and $\cat{U}$ is reflective in $\CFG$, then
 $\cat{U}$ is also reflective in $\hCG$.  Similarly, if $\cat{U}\subseteq\cat{G}\ip{r}$
 and $\cat{U}$ is reflective in $\CFG\ip{r}$, then $\cat{U}$ is also reflective
 in $\hCG\ip{r}$.
\end{Lem}

\begin{proof}
 We will prove the first claim; the proof of the second is essentially the same. Let $q\colon \CFG\to\cat{U}$ be the reflection. Now consider a finitely topologically generated group $G\in\hCG$, which means that for some $r$ we have a homomorphism $\alpha\colon F_r\to G$ from the free group on $r$ elements to $G$ with dense image. The group $q(F_r)\in\cat{U}$ is finite, with order $m$ say.  Consider a surjective homomorphism $\phi\colon G\to H$ with $H\in\cat{U}$.  As $\alpha$ has dense image, the composite $\phi\alpha\colon F_r\to H$ must be surjective, so it must factor through $q(F_r)$ by the adjunction property of $q$. Therefore $|H|\leq|q(F_r)|=m$, so $K_m(G)\leq\ker(\phi)$.  This means that $\phi$ factors through the finite group $G/K_m(G)$, and thus also through the group $q(G/K_m(G))$. We can therefore define a reflection $\widehat{q}\colon \hCG\to\cat{U}$ by $\widehat{q}(G)\coloneqq q(G/K_m(G))$.
\end{proof}

\begin{Prop}\label{prop-essfin-profinite}
    Let $\cat{V}$ be reflective in $\cat U$. If $\cat V$ is essentially finite, then $\cat{V}$ is also reflective in $\hCU$.
\end{Prop}
\begin{proof}
    Write $q \colon \cat U \to \cat V$ for the reflection. Let $n$ be the maximum of the orders of the groups in $\cat{V}$, and let $N$ be any open normal subgroup of $G\in \hCU$ contained in $K_n(G)$ such that $G/N\in\cat{U}$.  It is clear that any surjective homomorphism from $G$ to a group in $\cat{V}$ factors through $G/N$, and thus also through the group $q(G/N)$. We can therefore define a reflection $\widehat{q}\colon \hCU \to \cat V$ by $\widehat{q}(G)\coloneqq q(G/N)$.
\end{proof}

\begin{Cor}\label{cor-std-filt-profinite}
 Suppose that $\{\cat{U}[n]\}_{n\geq 0}$ is a reflective filtration of
 $\cat{U}$.  Suppose that any of the following conditions are satisfied:
 \begin{enumerate}
  \item $\cat{U}[n]$ is reflective in $\CFG$; or
  \item $\cat{U}[n]$ is essentially finite; or
  \item there exists $r$ such that $\cat{U}\subseteq\cat{G}\ip{r}$ and
   $\cat{U}[n]$ is reflective in $\CFG\ip{r}$. 
 \end{enumerate}
 Then the filtration is profinite. 
 In particular, the filtrations provided by \cref{prop-std-filt} are
 profinite. 
\end{Cor}
\begin{proof}
Part (b) follows from \cref{prop-essfin-profinite}, while (a) and (c) follow from \cref{lem-profinite-refl} by restricting the reflection to $\hCU$.
\end{proof}

Now that we have a good amount of examples of profinite reflective filtrations we can discuss some consequences. We start by noting that if $\cat U$ admits a profinite reflective filtration $\{\cat U[n]\}_{n\geq 0}$, then we can combine the reflections into a map  
\[
q\coloneqq (q_n)\colon \pi_0 \hCU \to \lim_n \pi_0 \cat U[n], \quad [G] \mapsto ([q_n G])_n
\] 
which we will show is always injective, see \cref{prop:Uhat-injects-in-a-lim}. We then investigate conditions on $\cat U$ which ensure that the above map is bijective. This culminates in \cref{thm-Uhat-is-a-lim}, which will be a key step in describing the 
Balmer spectrum for $r$-submultiplicative families in the next section. In order to prove injectivity of $q$, it will be important to understand in what sense an element of $\hCU$ is determined by the groups in $\cat U$ which it surjects onto. To this end, we make the following definition:

\begin{Def}\label{defn-quot-set}
 For $G\in\hCU$, we define $\cat{U}_{\ll G}$ to be the set of groups in $\cat{U}$
 that admit a surjective homomorphism from $G$.
\end{Def}

We prove that $\cat{U}_{\ll G}$ characterizes both the existence and behaviour of maps in $\hCU$. 

\begin{Lem}\label{lem-tow-maps}
 Suppose that $G,H\in\hCU$.
 \begin{enumerate}
  \item There is a surjective homomorphism $G\to H$ if and only if $\cat{U}_{\ll G}\supseteq\cat{U}_{\ll H}$.
  \item There is an isomorphism $G\to H$ if and only if $\cat{U}_{\ll G}=\cat{U}_{\ll H}$.
  \item Any endomorphism $G\to G$ in $\hCU$ is an isomorphism.
 \end{enumerate}
\end{Lem}
\begin{proof}
 If there is a surjective homomorphism $G\to H$ then it is clear that
 $\cat{U}_{\ll G}\supseteq\cat{U}_{\ll H}$, and if $G\cong H$ then it is clear that
 $\cat{U}_{\ll G}=\cat{U}_{\ll H}$.

 For the converse, suppose that $\cat{U}_{\ll G}\supseteq\cat{U}_{\ll H}$.  We can
 choose a tower $(H/N_k)_k$ as in \cref{rem-hCU-tower} so that $H \cong \lim_k H/N_k$.  Let
 $\mathrm{Epi}(G,H/N_k)$ denote the set of surjective homomorphisms
 $G\to H/N_k$.  This is non-empty by assumption, and finite because $G$
 is finitely generated and $|H/N_k|<\infty$.  We note that the inverse limit of any tower of finite non-empty sets is again non-empty.  Using this, we can construct a homomorphism
 $\alpha\colon G\to H$ such that each composite $G\to H\to H/N_k$ is
 surjective, or equivalently the image of $\alpha$ is dense. Since $\alpha$ is continuous (see \cref{rem-hCG}) and $G$ is quasi-compact, the image $\alpha(G)\leq H$ is quasi-compact, and so closed (as $H$ is Hausdorff). This shows that $\alpha$ is in fact surjective, proving~(a).

 We next discuss~(c).  Any endomorphism of $G$ is represented by a
 surjective homomorphism $\gamma\colon G\to G$.  From the definition of
 $K_n(G)$ (see \cref{defn-std-filt-profinite}) we see that $\gamma(K_n(G))\leq K_n(G)$ and so $\gamma$ induces a
 surjective endomorphism of the finite quotient group $G/K_n(G)$.
 This must be an isomorphism by counting, and $G\cong \lim_nG/K_n(G)$,
 so $\gamma$ is an isomorphism as claimed.

 Finally, we consider the reverse implication in (b).  If $\cat{U}_{\ll G}=\cat{U}_{\ll H}$ then we can use~(a) to
 obtain morphisms $G\xrightarrow{\alpha}H\xrightarrow{\beta}G$.  Claim~(c) shows that
 $\alpha\beta$ and $\beta\alpha$ must be isomorphisms, and it follows that $\alpha$
 and $\beta$ are isomorphisms, as required.
\end{proof}

\begin{Cor}\label{prop:Uhat-injects-in-a-lim}
    Let $\{\cat U[n]\}_{n\geq 0}$ be a profinite reflective filtration of $\cat U$.
    Then the map induced by the reflections 
    \[
    q\coloneqq (q_n)\colon \pi_0 \hCU \hookrightarrow \lim_n \pi_0 \cat U[n], \quad [G] \mapsto ([q_n G])_n
    \]
    is injective.
\end{Cor}
\begin{proof}
    Notice that $\cat{U}_{\ll q_n(G)}=\cat{U}_{\ll G}\cap\cat{U}[n]$ and hence
 $\cat{U}_{\ll G}=\bigcup_n\cat{U}_{\ll q_n(G)}$. Therefore by \cref{lem-tow-maps}, we see that given $G,H \in \hCU$, there is an isomorphism $G \to H$ if and only if $q_n(G) \cong q_n(H)$ for all $n$. 
\end{proof}

We now turn to proving surjectivity of the map $q$.
In order to do this, we need the following criterion. Recall the definition of wide subgroups from \cref{not-families}.
\begin{Prop}\label{prop-quot-set-props}
 Consider a subset $\cat{X}\subseteq\pi_0\cat{U}$.  There is an object
 $G\in\hCU$ with $\cat{X}=\pi_0\cat{U}_{\ll G}$ if and only if $\cat{X}$ has the following properties:
 \begin{enumerate}
  \item there is a number $r$ with $\cat{X}\subseteq\cat{U}\ip{r}$;
  \item $\cat{X}$ is non-empty, and closed under quotients in $\cat{U}$; and
  \item for any $H,K\in\cat{X}$ there is a wide subgroup 
   $L\leq H\times K$ with $L\in\cat{X}$.
 \end{enumerate}
\end{Prop}
\begin{proof}
 First suppose that $\cat{X}=\pi_0\cat{U}_{\ll G}$ for some $G\in\hCU$.  Then
 $G\in\hCU\ip{r}$ for some $r$, which implies~(a).  Property~(b)
 is clear.  If $H,K\in\cat{X}$ then we can choose surjective
 homomorphisms $H\xleftarrow{\alpha}G\xrightarrow{\beta}K$ and put
 $L=\img(\ip{\alpha,\beta}\colon G\to K\times L)$; then $L$ is a wide subgroup that
 is contained in $\cat{X}$; so property~(c) is also satisfied.

 Conversely, suppose we have a subset $\cat{X}\subseteq\pi_0\cat{U}$ satisfying~(a)
 to~(c).  As $\pi_0\cat{G}$ is countable, we
 can choose a sequence of groups $H_i\in\cat{X}$ containing a representative for each of the isomorphism classes of objects in $\cat{X}$. Take $G_0=H_0$ and then recursively
 choose a wide subgroup $G_{i+1}\leq H_{i+1}\times G_i$ for each $i$, so
 we have projections $G_i\leftarrow G_{i+1}\to H_{i+1}$.
 Let $G$ be the inverse limit of the groups $G_i$.  As
 $G_i\in\cat{X}\subseteq\cat{U}\ip{r}$ for all $i$, by applying \cref{lem-tow-maps}(a) to the profinite completion of $F_r$, the free group on $r$ generators, we deduce that $G\in\hCU\ip{r}$. If $T\in\cat{U}$ is a finite quotient of $G$,
 then the map $G\to T$ must factor through $G_i$ for some $i$. Since
 $G_i\in\cat{X}$ and $\cat{X}$ is closed under quotients in $\cat{U}$ we have $T\in\cat{X}$.
 Conversely, if $T\in\cat{X}$ then $T\cong H_i$ for some $i$ so we have a
 surjective homomorphism $G\to G_i\xrightarrow{q_i}H_i\cong T$ so
 $T\in\cat{U}_{\ll G}$.  We therefore have $\pi_0\cat{U}_{\ll G}=\cat{X}$ as required.
\end{proof}

Using the above results we can give another description of $\pi_0\hCU$ which will be instrumental in calculating the Balmer spectrum for $r$-submultiplicative families. 

\begin{Thm}\label{thm-Uhat-is-a-lim}
    Let $\cat{U} \subseteq \cat{G}$ be a subcategory in which all groups are $r$-generated for a fixed $r \geq 0$, and suppose that $\cat{U}$ has a profinite reflective filtration $\{\cat U[n]\}_{n\geq 0}$.
    Then the map induced by the reflections 
    \[
    q = (q_n)\colon \pi_0 \hCU \xrightarrow{\sim} \lim_n \pi_0 \cat U[n], \quad [G] \mapsto ([q_n G])_n
    \]
    is a bijection.
\end{Thm}
\begin{proof} 
Injectivity holds by \cref{prop:Uhat-injects-in-a-lim}.
To show surjectivity, consider an element $([G_n])_n \in \lim_n \pi_0 \cat U[n]$ so that $q_n(G_{n+1})\cong G_n$. Set $\cat X$ to be the downward closure of $\{G_n \mid n\geq 0 \}$. We now apply \cref{prop-quot-set-props} to this $\cat X$ to obtain $G \in \hCU$ such that $\pi_0\cat{U}_{\ll G}=\cat X$: in order to do this, we need to verify conditions (a)--(c) from \cref{prop-quot-set-props}. Conditions (a) and (b) are clear. For condition (c), given $H, K \in \cat{X}$ there is a natural number $i$ such that $G_i$ surjects onto both $H$ and $K$. The image of the combined homomorphism $G_i \to H \times K$ is then a wide subgroup which lies in $\cat{X}$ (see \cref{eg-implies-widely-closed}) as required. 

We now claim that $q_n(G)\cong G_n$ for all $n$, showing that the above map is surjective. To prove the claim note that $G \gg G_n$ and so by adjunction $q_n(G)\gg G_n$. On the other hand, $G\gg q_n(G)$ and by definition of $\cat X$ there is some $m$ such that $G_m\gg q_n(G)$. Applying $q_n$ to this homomorphism, we obtain that $G_n\cong q_n(G_m)\gg q_n(G)$, and so $q_n(G)\cong G_n$, as claimed.
\end{proof}

\begin{Exa}
    We observe that the previous theorem applies to $r$-submultiplicative families by \cref{cor-std-filt-profinite}.
\end{Exa}

Finally, we use \cref{thm-Uhat-is-a-lim} to endow $\hCU$ with a natural profinite topology under the additional assumption that the filtration on $\cat{U}$ is essentially finite. 

\begin{Def}\label{defn-Uhat-topology}
    Let $\cat{U} \subseteq \cat{G}$ be a subcategory in which all groups are $r$-generated for a fixed $r \geq 0$. Assume in addition that $\cat{U}$ has an essentially finite, reflective filtration $\{\cat U[n]\}_{n\geq 0}$; in particular, the filtration is profinite by \cref{cor-std-filt-profinite}, with reflections $q_n \colon \hCU \to \cat U[n]$. Considering each finite set $\pi_0\CU[n]$ as a discrete space, we give 
        \[
            \pi_0\hCU\xrightarrow{\sim} \lim_n \pi_0\cat{U}[n]
        \]
    the inverse limit topology afforded by \cref{thm-Uhat-is-a-lim}. Explicitly, for every $n$ and $S\subseteq\pi_0\cat{U}[n]$ we have an open set $(\pi_0q_n)^{-1}(S)\subseteq\pi_0\hCU$, and these sets form a basis for the topology on $\pi_0\hCU$. 
\end{Def}

\begin{Rem}\label{rem:profinitetopology}
     In the above context it is clear that every essentially finite subcategory of $\cat U$ is contained in some $\cat U[n]$. From this we see that the induced topology on $\pi_0\hCU$ is independent of the choice of filtration. Moreover, the space $\pi_0\hCU$ is profinite, i.e., quasi-compact, Hausdorff, and totally disconnected.
\end{Rem}

We record some basic features of the topology on $\pi_0\hCU$.
\begin{Lem}\label{lem-hatU-topology}
    Let $\cat{U}$ be as in \cref{defn-Uhat-topology}. 
    \begin{enumerate}
        \item The following are equivalent for a subset $U \subseteq \pi_0\hCU$:
        \begin{itemize}
            \item[(i)] $U$ is clopen (i.e., closed and open);
            \item[(ii)] $U$ is quasi-compact and open;
            \item[(iii)] there exists $n \in \bbN$ and $S \subseteq \pi_0\cat{U}[n]$ such that $U = (\pi_0q_n)^{-1}(S)$.
        \end{itemize}
        \item A subset of $\pi_0\hCU$ is open if and only if it is Thomason, i.e., a union of subsets with quasi-compact open complement.
        \item Every clopen subset of $\pi_0\hCU$ is the closure of its intersection with $\pi_0\cat{U}$. In particular, the subset $\pi_0\cat{U}$ is dense in $\pi_0\hCU$.
    \end{enumerate}
\end{Lem}
\begin{proof}
    Since $\pi_0\hCU$ is a quasi-compact Hausdorff space, a subset is closed if and only if it is quasi-compact, which gives the equivalence of $(i)$ and $(ii)$ of $(a)$. If $S\subseteq\pi_0\cat{U}[n]$ then $(\pi_0q_n)^{-1}(S)$ and $(\pi_0q_n)^{-1}(\pi_0\cat{U}[n] \setminus S)$ are open and complementary, so $(\pi_0q_n)^{-1}(S)$ is clopen.  Conversely, suppose that $U\subseteq\pi_0\hCU$ is quasi-compact and open.  Then $U$ can be written as a finite union of basic open subsets, say $U=\bigcup_{i<m}(\pi_0q_{n_i})^{-1}(S_i)$ for some subsets $S_i\subseteq\pi_0\cat{U}[n_i]$.  Let $n$ be the maximum of the indices $n_i$, let $W_i$ be the preimage of $S_i$ in $\pi_0\cat{U}[n]$, and put $W=\bigcup_{i<m}W_i\subseteq\pi_0\cat{U}[n]$. We then find that $U=(\pi_0q_n)^{-1}(W)$ which completes the proof of (a). Since the quasi-compact opens form a basis for the topology on $\pi_0\hCU$, (a) implies (b).

    For (c), consider a basic open set $U=(\pi_0q_n)^{-1}(S)$ and a point $x\in U$.  We must show that $x$ lies in the closure of $U\cap\pi_0\cat{U}$.  Consider another basic open set $U'=(\pi_0q_{n'})^{-1}(S')$ containing $x$; we must show that $U'\cap U\cap\pi_0\cat{U}$ is nonempty.  Put $m=\max(n,n')$ and $y=q_m(x)\in\pi_0\cat{U}[m]\subseteq\pi_0\cat{U}$.  We then find that $y\in U'\cap U\cap\pi_0\cat{U}$ as required. The density of $\pi_0\cat{U} \subseteq \pi_0\hCU$ follows by taking the clopen subset $\pi_0\hCU$.
\end{proof}

We can recover the asymptotic subsets (\cref{defn-asym}) of $\pi_0\cat{U}$ from the topology on $\pi_0\hCU$ as follows:
\begin{Cor}\label{cor-recover-asym}
    Let $\cat{U}$ be as in \cref{defn-Uhat-topology}. There is an isomorphism of lattices
    \[
            \begin{tikzcd}[ampersand replacement=\&,column sep=small]
                \pi_0\cat{U} \cap -\colon
                {\begin{Bmatrix}
                    \text{clopen subsets} \\
                    \text{of } \pi_0\hCU
                \end{Bmatrix}}
                    \& 
                \asym(\cat{U}).
                    \arrow["\sim", from=1-1, to=1-2]
            \end{tikzcd}
        \]
\end{Cor}
\begin{proof}
    Recall that the reflection $\cat U \to \cat U[n]$ is the restriction of $q_n \colon \hCU \to \cat U[n]$, see \cref{defn-filt-profinite}. It then follows that an asymptotic subset of $\pi_0\cat{U}$ is of the form $(\pi_0q_n)^{-1}(S)\cap\pi_0\cat{U}$ for some $n$ and $S\subseteq\pi_0\cat{U}[n]$. \cref{lem-hatU-topology}(a) then shows that the above map is surjective, while injectivity follows from \cref{lem-hatU-topology}(c).
\end{proof}

As we will show in the next section, the reason to consider the extension from asymptotic subsets of $\pi_0\cat{U}$ to clopen subsets of $\pi_0\hCU$ is that $\pi_0\hCU$ is large enough to accommodate a classification of all thick ideals in terms of their homological support; compare with \cref{rem:spectralclosure}. 


\section{Balmer spectra for \texorpdfstring{$r$}{r}-submultiplicative families}\label{sec-bounded}

Our goal in this section is to describe the Balmer spectrum for families satisfying:

\begin{Hyp}\label{hyp3}
     Let $\cat{U}$ be a subcategory satisfying \cref{hyp2} and in which all groups are $r$-generated for a fixed $r \geq 0$. Assume in addition that $\cat{U}$ has an essentially finite, reflective filtration $\{\cat U[n]\}_{n\geq 0}$; this is moreover profinite by \cref{cor-std-filt-profinite}, with reflections $q_n\colon \hCU \to \cat{U}[n]$.
\end{Hyp}

\begin{Exa}
    By \cref{cor-std-filt-profinite} $r$-submultiplicative families satisfy \cref{hyp3}.
\end{Exa}

We begin with the compatibility of the profinite group prime map with the maps induced by the reflections, which holds in slightly greater generality.

\begin{Lem}\label{lem:groupprimesmaps-compactible}
    Let $\cat U$ be a subcategory satisfying \cref{hyp2} and admitting a profinite reflective filtration $\{\cat{U}[n]\}_{n\geq 0}$. Then the maps \eqref{eq:groupprimemap} and \eqref{eq-profinite-group-prime-map} are compatible in the sense that there is a commutative diagram
      \[
    \begin{tikzcd}[column sep=2cm]
        \pi_0 \widehat{\cat U} \arrow[r,"\mathfrakp_{-}^{\hCU}"] \arrow[d, "q=(q_n)"'] & \Spc(\D{\cat U}^c) \arrow[d,"(\Spc(q_n^*))"]\\
        \lim_n \pi_0 \cat U[n] \arrow[r, "\lim_n\mathfrakp_{-}^{\cat U[n]}"'] & \lim_n \Spc(\D{\cat U[n]}^c).
    \end{tikzcd}
    \]
\end{Lem}
\begin{proof}
    Fix $n\geq 0$ and $G \in\pi_0 \widehat{\cat U}$. Unravelling the definitions and using \cref{prop-ev-const}, we see that
    \begin{align*}
        \Spc(q_n^*)(\mathfrakp_G) & = \{X \mid (q_n^*X)(G)\simeq 0\}\\
                                  & = \{X \mid \colim_m (q_n^*X)(q_m G)\simeq 0\}\\
                                  & = \{X \mid \colim_m X(q_nq_m G)\simeq 0\}\\
                                  & = \{X \mid X(q_n G)\simeq 0\} =\mathfrakp_{q_nG},  
    \end{align*}
    where in the penultimate equality we used that $q_nq_m G\cong q_nG$ for $m\geq n$.  
\end{proof}

We now show that, for $\cat{U}$ with a profinite reflective filtration, the set of profinite group primes injects into the Balmer spectrum, extending \cref{prop:groupprimes}.

\begin{Prop}\label{prop:profinitemap-inj}
    Let $\cat U$ be a subcategory satisfying \cref{hyp2} and admitting a profinite reflective filtration $\{\cat U[n]\}_{n\geq 0}$. Then the map of \eqref{eq-profinite-group-prime-map}
    \[
    \mathfrakp_{-}^{\hCU}\colon \pi_0\hCU \hookrightarrow \Spc(\D{\cat{U}}^c)
    \]
    is injective.
\end{Prop}
\begin{proof}
    Consider the commutative diagram of \cref{lem:groupprimesmaps-compactible}. The left vertical arrow is injective by \cref{prop:Uhat-injects-in-a-lim}, and the right vertical arrow is bijective by \cref{cor-lim-spectra}. The bottom horizontal map is a limit of injective maps by \cref{prop:groupprimes} and so is injective. The claim then follows by the commutativity of the diagram.
\end{proof} 

We now come to the main result of this section:
\begin{Thm}\label{Thm-profinite-rgenerated}
    Let $\cat{U}$ be as in \cref{hyp3}. Then the profinite group map \eqref{eq-profinite-group-prime-map} is a homeomorphism
        \[
            \mathfrakp_{-}\colon \pi_0 \hCU \xrightarrow{\sim} \Spc(\D{\cat{U}}^c) 
        \]
    when we endow $\pi_0 \hCU$ with the inverse limit topology as in \cref{defn-Uhat-topology}. Moreover, $\D{\cat U}^c$ is standard in the sense of \cref{def:standardtt} and the extended homological support (\cref{cons:hsuppextension}) induces bijections
    \begin{align*}
        \{\text{finitely generated thick ideals of } \D{\cat{U}}^c\} & \xrightarrow{\sim} 
        \{\text{clopen subsets of } \pi_0\hCU\} \\
        \{\text{thick ideals of } \D{\cat{U}}^c\} & \xrightarrow{\sim} 
        \{\text{open subsets of } \pi_0\hCU\} \\
        \{\text{prime ideals of } \D{\cat{U}}^c\} & \xrightarrow{\sim} 
        \{\text{complements of points in } \pi_0\hCU\} 
    \end{align*}
    extending the bijection of \cref{thm:fgttideals}. 
\end{Thm}

\begin{proof}
  By \cref{lem:groupprimesmaps-compactible}, there is a commutative diagram 
    \[
    \begin{tikzcd}[column sep=2cm]
        \pi_0 \widehat{\cat U} \arrow[r, "\mathfrakp_{-}^{\hCU}"] \arrow[d, "\sim","q=(q_n)"'] & \Spc(\D{\cat U}^c) \arrow[d,"\sim"',"(\Spc(q_n^*))"]\\
        \lim_n \pi_0 \cat U[n] \arrow[r, "\sim"', "\lim_n \mathfrakp^{\cat U[n]}_{-}"] & \lim_n \Spc(\D{\cat U[n]}^c).
    \end{tikzcd}
    \]
    The right vertical arrow is a homeomorphism by \cref{cor-lim-spectra}, the left vertical map is a homeomorphism by \cref{thm-Uhat-is-a-lim}, and the bottom horizontal map is a homeomorphism by \cref{thm:spcfinite}. Therefore, $\mathfrakp_{-}^{\hCU}$ is a homeomorphism as well. 

    In light of \cref{rem:exthsupp}, this exhibits the pair $(\pi_0\hCU,\hsupp_{\hCU})$ as the universal support datum in the sense of Balmer \cite[Theorem 3.2]{Balmer2005}. Since $\D{\cat{U}}^c$ is standard by \cref{rem-ess-finite-refl-standard}, the general classification theorem \eqref{eq:ttclassification} then establishes bijections
    \begin{align*}
        \{\text{thick ideals of } \D{\cat{U}}^c\} & \xrightarrow{\sim} 
        \{\text{Thomason subsets of } \pi_0\hCU\} \\
        \{\text{finitely generated thick ideals of } \D{\cat{U}}^c\} & \xrightarrow{\sim}
        \{\text{closed Thomason subsets of } \pi_0\hCU\}
    \end{align*}    
    induced by $\hsupp_{\hCU}$. It remains to observe that a subset of $\pi_0\hCU$ is (closed and) Thomason if and only if it is (closed and) open, see \cref{lem-hatU-topology}. Finally, as already observed in \cref{rem:isolation_criterion}, the support of a prime ideal $\mathfrakp$ is in general given by the complement of $\{\mathfrak{q}\mid \mathfrak{q} \supseteq \mathfrakp\}$. Since $\pi_0\hCU$ is Hausdorff, there are no non-trivial containments between prime ideals, so $\{\mathfrak{q}\mid \mathfrak{q} \supseteq \mathfrakp\}$ is a singleton. The classification of prime ideals in terms of the extended homological support follows. 
\end{proof}

\begin{Rem}\label{rem-bad-unions}
    Recall from \cref{thm:fgttideals} that the finitely generated thick ideals in $\D{\cat{U}}^c$ are classified by the asympotic subsets of $\pi_0\cat{U}$ via the homological support, and that these are in bijection with the clopen subsets of $\pi_0\hCU$ by \cref{cor-recover-asym}. Moreover, the open subsets of $\pi_0\hCU$, i.e., the unions of clopen subsets, classify the thick ideals of $\D{\cat{U}}^c$ by the previous theorem. Therefore, one might wonder whether the unions of asymptotic subsets of $\pi_0\cat{U}$ also biject with all thick ideals. This is not the case, as already observed via an explicit counterexample in \cref{rem:spectralclosure}.
\end{Rem}

\begin{Rem}
    One can also give a lattice theoretic approach to the classification of thick ideals in $\D{\cat{U}}^c$ as briefly discussed in \cref{rem:spectralclosure}. From this perspective, it suffices to compute the frame of ideals in the lattice $\asym(\cat{U})$; equivalently by \cref{cor-recover-asym}, the frame of ideals in the lattice of clopen subsets of $\pi_0\hCU$. Let $\mathsf{L}$ be the lattice of clopen sets of $\pi_0\hCU$, let $\mathsf{F}$ be the frame of ideals in $\mathsf{L}$, and let $\mathsf{F}'$ be the frame of open sets of $\pi_0\hCU$: we will show that $\mathsf{F}$ and $\mathsf{F}'$ are isomorphic.  For any ideal $I\subseteq \mathsf{L}$, we note that $I$ is a collection of clopen subsets of $\pi_0\hCU$, and we let $\phi(I)$ be the union of all those sets.  This defines a map $\phi\colon \mathsf{F}\to \mathsf{F}'$. In the opposite direction, given an open subset $U\subseteq\pi_0\hCU$, we define $\psi(U)$ to be the set of clopen subsets of $U$, which is an ideal in $\mathsf{L}$.  As the clopen subsets form a basis for the topology, we have $\phi(\psi(U))=U$.  Conversely, suppose that we start with an ideal $I\subseteq \mathsf{L}$.  It is immediate that $I\leq\psi(\phi(I))$.  In the opposite direction, suppose we have $V\in\psi(\phi(I))$, so $V$ is a quasi-compact open subset and is contained in the union of all the sets in $I$.  By quasi-compactness, $V$ is contained in the union of some finite family of sets in $I$.  As $I$ is an ideal it is closed downwards and under finite unions, so $V\in I$.  This shows that $I=\psi(\phi(I))$, and we conclude that $\phi$ and $\psi$ are mutually inverse isomorphisms of posets and hence also of frames. 
\end{Rem}

We now apply \cref{Thm-profinite-rgenerated} to compute the Balmer spectrum of $\D{\cat{U}}^c$ for various prominent choices of $\cat{U}$.
\begin{Exa}\label{ex-cyclic-groups-prime-order}
    Let $\Cprime$ denote the collection of cyclic groups of prime order together with the trivial group. Every group in this family is $1$-generated, and the family is downwards closed. Thus combining \cref{rem-res-filt} with the filtration from \cref{prop-std-filt}(b) for $\cat U$ the family of cyclic groups, we obtain an essentially finite, reflective filtration for $\Cprime$. Concretely, this reflection for $n\geqslant 1$ satisfies
    \begin{equation}\label{eq-reflection-Cpr}
    \Cprime[n] = \{C \in \Cprime \mid |C| \leq n\} \quad \text{and} \quad
    q_n(C_p)=
    \begin{cases}
    C_p  & \mathrm{if}\; p \leqslant n \\ 
    1  & \mathrm{if} \; p >n.\\
    \end{cases}
    \end{equation}
    As sets, $\widehat{\Cprime}=\Cprime$ because any sequence of groups and non-injective epimorphisms in $\Cprime$ 
    has length less than or equal to two. Therefore, by \cref{Thm-profinite-rgenerated},
    the map 
    \[
    \mathfrakp_{-}  \colon \pi_0\widehat{\Cprime}=\pi_0\Cprime \to \Spc(\D{\Cprime}^c)
    \]
    is a homeomorphism when $\pi_0\Cprime = \pi_0\widehat{\Cprime}$ is given the profinite topology, so it remains to identify this profinite topology.

    A basis of opens for the topology is given by the subsets of the form $(\pi_0q_n)^{-1}(S)\subseteq\pi_0\Cprime$, and these are precisely the clopen subsets in $\pi_0\Cprime$ by \cref{lem-hatU-topology}. Using \eqref{eq-reflection-Cpr} we see that if a subset $A \subseteq \pi_0\Cprime$ is clopen and $1 \in A$ then the complement of $A$ is finite, and if $1 \notin A$ then $A$ is finite. The arbitrary unions of these basis elements are precisely the subsets $U \subseteq \pi_0\Cprime$ that satisfy that if $1 \in U$ then the complement of $U$ is finite. This shows that $\pi_0\Cprime$ with the profinite topology is homeomorphic to the one-point compactification of the infinite discrete set $\pi_0\Cprime\setminus \{1\}$, with $\mathfrakp_1$ as the accumulation point. See \cref{exa:cyclicprimes} for a representation of this space.
\end{Exa}

\begin{Exa}\label{ex:cyclic-p-groups}
    Let $\cat{C}_p$ denote the collection of cyclic $p$-groups for a fixed prime number $p$; this is a $1$-submultiplicative family. For convenience we will use additive notation. As we saw in \cref{Exa-Cyclicp-Uhat}, $\widehat{\cat{C}}_p$ contains $\cat{C}_p$ plus the profinite group $\Z_p$. We apply \cref{Thm-profinite-rgenerated} and obtain a homeomorphism $\pi_0 \widehat{\cat{C}}_p\cong\Spc(\D{\cat{C}_p}^c)$. In order to identify the profinite topology, we note that the reflections and the filtration of \cref{prop-std-filt}(b) satisfy for $n\geqslant 1$ that
    \[
    \cat{C}_p[n]= \{\Z/p^m \mid p^m \leqslant n \} \quad
    q_{p^n}(\Z/p^m)=  \Z/p^{\min(m,n)} \quad \mathrm{and}\quad q_{p^n}(\Z_p)=\Z/p^n
    \]
    for all $m\geq 0$. Thus if a subset $A \subseteq \pi_0\widehat{\cat{C}}_p$ is clopen and $\Z_p \in A$ then the complement of $A$ is finite, and if $\Z_p \notin A$ then $A$ is finite. As in the previous example, this means that the profinite topology on $\pi_0\widehat{\cat{C}}_p$ is the one-point compactification of the discrete space $\pi_0\cat{C}_p$, with $\Z_p$ as the accumulation point. In contrast to the previous example, here the accumulation point is not a group prime, but a profinite group prime instead. See \cref{exa:cyclicp} for a representation of this space.
\end{Exa}

For the next example, let $\bbN^+$ denote the one-point compactification of $\bbN$ with compactification point denoted by $\infty \in \bbN^+$. We extend the linear order of $\bbN$ to $\bbN^+$ by declaring $\infty > n$ for all $n \in \bbN$.

\begin{Thm}\label{Thm-abelian-p-groups-rank-r}
    Fix a prime number $p$ and $r\in \bbN$, and let $\fabprk{r}$ be the family of abelian $p$-groups of $p$-rank at most $r$, or equivalently, the family of $r$-generated finite abelian $p$-groups. The spectrum $\Spc(\sfD(\fabprk{r})^c)$ is homeomorphic to the subspace
\[
\hatS_{\leq r}\coloneqq\{v=(v_1,\ldots, v_r)\in (\bbN^+)^r \mid \infty \geq v_1 \geq \ldots \geq v_r \geq 0\} \subseteq (\bbN^+)^r,
\]
which is profinite.
\end{Thm}
\begin{proof}
The family $\fabprk{r}$ is an $r$-submultiplicative family and the filtration coming from \cref{cor-std-filt-profinite} is given by filtering by $p$-exponent, $\fabprk{r}[p^l]= \fabprk{r}^{\leq l}$, where $\fabprk{r}^{\leq l}$ consists of all those finite abelian $p$-groups of $p$-rank at most $r$ and $p$-exponent less than or equal to $p^l$.
By \cref{Thm-profinite-rgenerated}, the Balmer spectrum of $\D{\fabprk{r}}^c$ is profinite and homeomorphic to $\pi_0 \hfabprk{r} \cong \lim_l \pi_0 \fabprk{r}^{\leq l}$, so we just need to identify the set $\pi_0 \hfabprk{r}$ and its profinite topology.

Set $v = (v_1,\ldots, v_r)$. We consider the discrete subsets of $\hatS_{\leq r}$
\[
\CS_{\leq r}=\{v \in \hatS_{\leq r}\mid v_1 <\infty \} \quad \mathrm{and}\quad
\CS_{\leq r}^{\leq l}=\{v \in \CS_{\leq r} \mid v_1 \leq l\}
\]
and define functions $m_l \colon \hatS_{\leq r}\to \CS_{\leq r}^{\leq l}$ by $m_l(v)_i=\min(l,v_i)$.
We define a map $\phi\colon \CS_{\leq r} \xrightarrow{} \pi_0\fabprk{r}$ by
\[
\phi(v_1,\ldots,v_r) \coloneqq \left[\bigoplus_i \bbZ/{p^{v_i}}\right].
\] 
The restriction $\phi_l$ of $\phi$ to $\CS_{\leq r}^{\leq l}$ induces a bijection $\CS_{\leq r}^{\leq l} \xrightarrow{\cong} \pi_0 \fabprk{r}^{\leq l}$ for each $l \geqslant 0$. For each $s \geqslant l$, the following diagram commutes

\[
    \begin{tikzcd}
        \CS_{\leq r}^{\leq s} \arrow[r, "\cong"', "\phi_s"] \arrow[d,"m_l"'] & \pi_0 \fabprk{r}^{\leq s} \arrow[d,"q_{p^l}"]\\
        \CS_{\leq r}^{\leq l} \arrow[r, "\cong"', "\phi_l"] & \pi_0 \fabprk{r}^{\leq l}.
    \end{tikzcd}
    \]
Therefore by taking limits, the maps $\phi_l$ induce homeomorphisms 
    \[
        \lim_l \CS_{\leq r}^{\leq l} \cong \lim_l \pi_0 \fabprk{r}^{\leq l} \cong \pi_0 \hfabprk{r}
    \]
of profinite spaces. Lastly, the maps $m_l$ induce a map $m \colon \hatS_{\leq r} \to  \lim_l \CS_{\leq r}^{\leq l}$, and we will now show that this map is a homeomorphism to conclude the proof of the theorem.

A point of $\lim_l \CS_{\leq r}^{\leq l}$ is represented by a sequence $b$ of points $b^l = (b^l_1,\ldots, b^l_r) \in \CS_{\leq r}^{\leq l}$ compatible with the maps $m_l$. By looking at each of the $r$ coordinates of the points $b_l$ and of points in $\hatS_{\leq r}$ separately we see that the map $m$ is bijective.

A basis of open sets for the topology of $\bbN^+$ is given by the sets of the form $\{a\}$, and intervals $[a, \infty]$ for each $a \in \bbN$. Thus a basis for the topology of $\hatS_{\leq r}$ is given by sets of the form $A=\hatS_{\leq r} \cap (A_1 \times \dots \times A_r)$, where each $A_i$ is either $\{a_i\}$ or $[a_i, \infty]$. Let $A$ be an element of this basis and let $n$ be the maximum of the $a_i$. We note that $A=m_{n+1}^{-1}(S)$ for some subset $S \subseteq \CS_{\leq r}^{\leq n+1}$, and thus the map $m$ sends $A$ to an open subset of $\lim_l \CS_{\leq r}^{\leq l}$. This shows that the map $m$ is open and continuous, and therefore a homeomorphism.
\end{proof}

The space $\hatS_{\leq r}$ can also be obtained by iterating disjoint unions and one-point compactifications.


\begin{Cor}\label{cor:abelian-p-groups-rank-r}
$\hatS_{\leq 0} = \{*\}$, and for each $r \geqslant 1$, $\hatS_{\leq r} \cong (\coprod_{n \in \bbN} \hatS_{\leq r-1})^+$.
\end{Cor}
\begin{proof}
    For each $r \geqslant 1$, let $\rho \colon \hatS_{\leq r} \to \bbN^+$ denote the projection to the $r$th coordinate of $(\bbN^+)^r$. Then $\rho^{-1}(\infty)$ consists of a single point, $(\infty, \dots, \infty)$. Each other preimage $\rho^{-1}(n)$ for $n \in \bbN$ is both open and closed by continuity. For each $n \in \bbN$, the map 
    \begin{align*}
        \hatS_{\leq r-1} \quad \to & \quad\rho^{-1}(n) \\
        (v_1,\ldots, v_{r-1}) \; \mapsto & \;(v_1+n,\ldots, v_{r-1}+n, n)
    \end{align*}
    is a homeomorphism. This shows that $\hatS_{\leq r} \setminus \{(\infty, \dots, \infty)\}$ is homeomorphic to $\coprod_{n \in \bbN} \hatS_{\leq r - 1}$ and is open in $\hatS_{\leq r}$. Since $\hatS_{\leq r}$ is compact Hausdorff, it is therefore homeomorphic to the one-point compactification of $\hatS_{\leq r} \setminus \{(\infty, \dots, \infty)\}$.
\end{proof}

\begin{Exa}\label{ex-abelian-p-groups-rank-2}
    Let $ \fabprk{2}$ denote the family of abelian $p$-groups of $p$-rank at most $2$. Then the poset associated to the profinite extension $\hfabprk{2}$ can be depicted as in \cref{fig:prk2}. Therefore the Balmer spectrum $\Spc(\D{\fabprk{2}}^c)$, which is homeomorphic to $\pi_0\hfabprk{2}$ by \cref{Thm-profinite-rgenerated}, can be depicted as in \cref{fig:phenomena2}. Under the homeomorphism to $\hatS_{\leq 2}$ of \cref{Thm-abelian-p-groups-rank-r}, the profinite group prime $\mathfrakp_{\Z_p \times \Z/{p^n}}$ corresponds to the point $(\infty, n) \in \hatS_{\leq 2}$, and $\mathfrakp_{\Z_p \times \Z_p}$ corresponds to $(\infty, \infty) \in \hatS_{\leq 2}$.
\end{Exa} 

We can also obtain a description of the Balmer spectrum for the family $\fabrk{r}$ of $r$-generated finite abelian groups, as a product of the spectra that we just computed for a single prime in \cref{Thm-abelian-p-groups-rank-r}.

\begin{Cor}\label{cor-abelian-groups-rank-r}
    For $r\in \bbN$, the Balmer spectrum for the family $\fabrk{r}$ of $r$-generated finite abelian groups is 
        \[
            \Spc(\sfD(\fabrk{r})^c)  \cong \prod_p \Spc(\sfD(\fabprk{r})^c) \cong \prod_p \hatS_{\leq r}.
        \]
\end{Cor}
\begin{proof}
    The family $\fabrk{r}$ is $r$-submultiplicative. Thus, we can apply \cref{Thm-profinite-rgenerated}. For any prime number $p$, we consider the family $\fabprk{r}$ of finite abelian $p$-groups of $p$-rank at most $r$. Note that $\fabrk{r}$ is not equivalent to the product of the categories $\fabprk{r}$ for varying $p$. It is however equivalent to the \emph{weak product} of the $\fabprk{r}$'s, that is, the full subcategory of $\prod_p \fabprk{r}$ of objects whose projection to $\fabprk{r}$ is the trivial group for all but finitely many $p$.

    The reflections $q_n$ constructed in \cref{defn-std-filt} for the families $\fabrk{r}$ and $\fabprk{r}$ commute with the projections $\fabrk{r} \to \fabprk{r}$. The subcategory $\fabprk{r}[n]$ consists of just the trivial group as long as $p > n$. This means that for each $n$, all but finitely many of the terms $\fabprk{r}[n]$ are trivial, and so $\fabrk{r}[n]$ is equivalent to the product $\prod_p \fabprk{r}[n]$, and not just the weak product. Therefore we obtain homeomorphisms
    \begin{align*}
    \label{eq-cyclicSpc}
        \Spc(\D{\fabrk{r}}^c)  & \cong \lim_n \pi_0 \fabrk{r}[n]
                             \cong \lim_n \prod_p \pi_0 \fabprk{r}[n] &\\
                             & \cong \prod_p \lim_n \pi_0 \fabprk{r}[n] 
                             \cong \prod_p \Spc(\D{\fabprk{r}}^c)
                             \cong \prod_p \hatS_{\leq r},
    \end{align*} 
    from \cref{Thm-profinite-rgenerated} and \cref{Thm-abelian-p-groups-rank-r} as desired.
\end{proof}

\begin{Exa}\label{ex-abelian-p-groups-rank-1}
\Cref{cor-abelian-groups-rank-r} applies in particular to the family $\cat{C} = \fabrk{1}$ of finite cyclic groups, yielding $\Spc(\D{\cat{C}}^c) \cong \prod_p \mathbb{N}^+$.
\end{Exa}

\begin{Rem}
    Due to the product topology, in $\Spc(\D{\fabrk{r}}^c)$ the group prime $\mathfrakp_1$ is an accumulation point of the group primes $\mathfrakp_{C_p}$ for varying $p$. This is the same phenomenon that occurred for the subfamily $\Cprime$ as described in \cref{ex-cyclic-groups-prime-order}.
\end{Rem}

\begin{Rem}
    Note that the proof of the last corollary uses the fact that we are restricting to $r$-generated finite abelian groups. In fact, we do not currently know whether the spectrum $\Spc(\sfD(\fab)^c)$ for the family of all finite abelian groups is the product of the spectra $\Spc(\sfD(\fabp)^c)$ for finite abelian $p$-groups.
\end{Rem}


\subsection{Consequences for Cantor--Bendixson rank}\label{ssec:cbrank}

We end this section by showing that the Balmer spectrum for the family of finite abelian $p$-groups has infinite Cantor--Bendixson rank. For convenience, we briefly recall the definition of Cantor--Bendixson rank; for further details, we refer the reader to~\cite[Section 4.3]{DST2019}.

\begin{Rec}\label{rec:CBrank}
    Let $X$ be a topological space. The \emph{Cantor--Bendixson derivative} $\delta X$ of $X$ is defined as the subspace of non-isolated points in $X$. For an ordinal $\alpha$, one then uses transfinite recursion to define $\delta^{\alpha}X$ via
        \[
            \delta^{\alpha}X \coloneqq
                \begin{cases}
                    X & \text{if } \alpha = 0; \\
                    \delta\delta^{\alpha -1}X & \text{if } \alpha \text{ is a successor ordinal}; \\
                    \bigcap_{\beta < \alpha} \delta^{\beta}X & \text{if } \alpha \text{ is a limit ordinal}.
                \end{cases}
        \]
    Finally, the \emph{Cantor--Bendixson rank} of a non-empty space $X$ is defined as
        \[
            \CB(X) \coloneqq 
                \begin{cases}
                    \sup\SET{\alpha}{\delta^{\alpha}X \neq \emptyset} & \text{if the supremum exists}; \\
                    \infty & \text{otherwise},
                \end{cases}
        \]
    while $\CB(\emptyset) \coloneqq -1$ by definition. Here, we use the convention that $\infty$ is larger than any ordinal.
\end{Rec}

As a consequence of \cref{cor:abelian-p-groups-rank-r}, we obtain:

\begin{Cor}\label{cor:CBrank_boundedrank}
    For any $r \geq 0$, the spectrum $\Spc(\D{\fabprk{r}}^c)$ has Cantor--Bendixson rank precisely $r$.
\end{Cor}
\begin{proof}
    We argue by induction on $r$. When $r=0$, the spectrum is a point, thus providing the base of the induction. For the induction step, we use the description of \cref{cor:abelian-p-groups-rank-r} to see that for $r>0$:
        \[
            \CB(\hatS_{\leq r}) = \CB\left (\left (\coprod_{n \in \bbN}\hatS_{\leq r-1}\right )^+\right) = \CB(\hatS_{\leq r-1})+1 = r,
        \]
    by induction hypothesis. This implies the claim in light of \cref{Thm-abelian-p-groups-rank-r}.
\end{proof}


\begin{Cor}\label{coro-CB-rank}
    For any family $\cat U \subset \cat G$ containing the family of all finite abelian $p$-groups $\cat{A}(p)$, the Cantor--Bendixson derivative $\delta^{\omega}\Spc(\D{\cat U}^c) \neq \emptyset$. In particular, $\CB(\Spc(\D{\cat U}^c))\geqslant \omega$.
\end{Cor}
\begin{proof}
     For each $r$, the inclusion $\fabprk{r} \subset \cat{A}(p) \subseteq \cat{U}$ induces a map on Balmer spectra, which is an embedding by \cref{cor:verdierquotient}, as $\fabprk{r}$ is downwards closed. Recall that embeddings of topological spaces give an inequality on Cantor--Bendixson ranks, see~\cite[4.3.2(2)]{DST2019}. \Cref{cor:CBrank_boundedrank} thus implies that $\delta^r\Spc(\D{\cat U}^c) \neq \emptyset$ for all $r \in \bbN$. Since the spectrum is quasi-compact, we deduce that their intersection is non-empty as well, i.e., $\delta^{\omega}\Spc(\D{\cat U}^c) \neq \emptyset$. Therefore, the Cantor--Bendixson rank of $\Spc(\D{\cat{U}}^c)$ is $\geqslant \omega$. 
\end{proof}



