\section{Rational global homotopy theory}\label{appendix}

In this appendix we introduce the $\infty$-category of global spectra following the approach of \cite{LNP} and record some properties that it enjoys. We then introduce the category of rational global spectra as a Verdier quotient and show that this construction agrees with the original definition of Schwede given in \cite{Schwedebook}.

\subsection{Partially lax limits}
The definition of the category of global spectra will make use of the notion of partially lax limit. We will recall some of the key features of this construction and refer the interested reader to \cite{Berman}, \cite{GHN}, \cite{LNP} and \cite{GlobalTMF} for a more detailed account of this material. We will freely use the language of $\infty$-categories as developed in \cite{HTT,HA}.

\begin{Rec}
    Given functors $F,G\colon \cat I \to \Cat_\infty$, there is a notion of lax natural transformation $\eta \colon F \Rightarrow G$. Informally, this is a coherent collection of squares
    \[
    \begin{tikzcd}
        {F(i)} &  {F(j)} \\
        {G(i)} & {G(j)}
        \arrow["\eta_j",from=1-2, to=2-2]
        \arrow["F(f)", from=1-1, to=1-2]
        \arrow["G(f)"', from=2-1, to=2-2]
        \arrow["\eta_i"', from=1-1, to=2-1]
        \arrow["\epsilon", shorten <=7pt, shorten >=7pt, Rightarrow, from=2-1, to=1-2]
    \end{tikzcd}
    \]
    together with 2-morphisms $\epsilon\colon G(f) \circ \eta_i \Rightarrow \eta_j\circ  F(f) $. If the 2-morphisms $\epsilon$ are all equivalences, then $\eta$ defines a natural transformation.
\end{Rec}

\begin{Def}\label{def-laxlim}
    We define the \emph{lax limit} of a functor $F \colon \cat I \to \Cat_\infty$ to be the $\infty$-category of lax cones
    \[
    \laxlim_{\cat I} F \coloneqq \mathrm{Nat}^{\mathrm{lax}}(\Delta(\ast), F),
    \]
   that is, lax natural transformations from the constant functor on the terminal $\infty$-category to $F$. If $\cat I$ is marked by a subcategory $\cat W$, we define the \emph{partially lax limit} of $F$
\[
\laxlimdag_{\cat I,\cat W} F \subset \laxlim_{\cat I} F 
\]
to be the full subcategory spanned by those lax cones whose restriction to $\cat W\subset \cat I$ is strictly natural.
\end{Def}

\begin{Rem}\label{rem-laxlim-sections}
It follows from \cite[Remark 2.7]{GlobalTMF} that there is an equivalence 
\[
\laxlim_{\cat I} F \simeq \Fun_{\cat I}(\cat I,\mathrm{Un}^{\mathrm{co}}{F}).
\]
In other words, the lax limit of $F$ is equivalent to the $\infty$-category of sections of the cocartesian unstraightening of $F$. Furthermore, if $\cat I$ is marked by $\cat W$, then a lax cone is in $\laxlimdag F$ if and only if the associated section sends maps in $\cat W$ to cocartesian edges in $\mathrm{Un}^{\mathrm{co}}{F}$.
\end{Rem}

\begin{Exa}\label{ex-constant-laxlim}
    Consider the constant functor $\Delta(\cat C)\colon \cat I \to \Cat_\infty$ on an $\infty$-category $\cat C$. Its cocartesian unstraightening is given by the projection $\cat C \times \cat I \to \cat C$ and so it follows from \cref{rem-laxlim-sections} that 
    \[
    \laxlim_{\cat I} \Delta(\cat C)=\Fun_{\cat I}(\cat I, \cat C \times \cat I)\simeq\Fun(\cat I, \cat C).
    \]
\end{Exa}
We will also need to discuss how partially lax limits behave with respect to symmetric monoidal structures. 

\begin{Rec}\label{rec-laxlim-sym-mon}
     Given a functor $F \colon \cat I \to \CAlg(\PrL)$ and a subcategory $\cat W\subseteq \cat I$, we can form the partially lax limit marked at $\cat{W}$ 
     \[
     \laxlimdag_{\cat I, \cat W} F\in \CAlg(\PrL),
     \]
     see \cite[Section 5]{LNP}.
     This construction defines a functor 
     \[
      \laxlimdag_{\cat I, \cat W} \colon \Fun(\cat I, \CAlg(\PrL)) \to \CAlg(\PrL).
     \]
     By the discussion in \cite[Remarks 5.1 and 5.2]{LNP}, the symmetric monoidal structure on the partially lax limit has the following universal property: for any $\cat D \in \CAlg(\PrL)$, postcomposition with the projection functors induces an equivalence
     \[
     \Fun^{\mathrm{L},\otimes}(\cat D, \laxlimdag_{\cat I, \cat W}F)\xrightarrow{\sim} \laxlimdag_{i\in \cat I, \cat W} \Fun^{\mathrm{L}, \otimes}(\cat D, F(i)),
     \]
     where $\Fun^{\mathrm{L}, \otimes}$ denotes colimit preserving and symmetric monoidal functors. In particular, the inclusion 
     \begin{equation}\label{eq-inclusions}
     \laxlimdag_{\cat I, \cat W} F \subseteq \laxlim_{\cat I} F
     \end{equation}
     is symmetric monoidal. 
\end{Rec}

\subsection{Global spectra}
We are finally ready to introduce the $\infty$-category of global spectra. Unlike the rest of the paper where we restrict to families of finite groups, several of the definitions and constructions in this appendix work more generally for global families $\cat F$ of compact Lie groups, i.e., collections of compact Lie groups closed under subgroups and quotients, so we will write this appendix in this generality. Throughout all subgroups will be implicitly assumed to be closed.
\begin{Def}\label{def-global-orbits}
Let $\cat F$ be a global family of compact Lie groups.
\begin{enumerate}
\item We let $\Glo{\cat F}$ denote the \emph{global orbit} $\infty$-\emph{category} of \cite[Definition 6.1]{LNP} with isotropy in $\cat F$, whose objects are the groups $G\in\cat F$. In this category, the space of morphisms $ H\to  G$ is the homotopy orbit space $\Hom(H,G)_{hG}$, where $\Hom(H,G)$ is the space of continuous homomorphisms from $H$ to $G$, and $G$ acts on this by conjugation.  
\item We denote by $\Orb{\cat F}\subseteq \Glo{\cat F}$ the wide subcategory spanned by those morphisms which are represented by an injective group homomorphism. 
\end{enumerate}
\end{Def}

\begin{Rem}\label{rem-homotopy-category}
    Given $G,H\in \cat F$, there is a decomposition 
    \[
    \Map_{\Glo{\cat F}}(G,H)\simeq \coprod_{[\alpha]\in\Map_{\cat F}(G,H)} B C(\alpha),
    \]
    where $C(\alpha)$ denotes the centralizer of the image of $\alpha$, see \cite[Proposition 2.5]{Korschgen}. It follows that the morphisms in $\Ho(\Glo{\cat F})$ from $H$ to $G$ are given by conjugacy classes of group homomorphisms $\alpha\colon H\to G$. 
\end{Rem}

\begin{Rec}
    For any compact Lie group $G$, we write $\Sp_G$ for the $\infty$-category of genuine $G$-spectra: for an explicit model we can take the underlying $\infty$-category associated to the category of orthogonal $G$-spectra (indexed on a complete $G$-universe) with the stable model structure, see \cite[Chapter III.4]{MM}. The $\infty$-category $\Sp_G$ is stable and presentably symmetric monoidal with symmetric monoidal structure induced by the smash product of orthogonal $G$-spectra \cite[Chapter II.3]{MM}. We refer the reader to \cite{LMSM} and \cite[Chapter 3]{Schwedebook} for more details on equivariant stable homotopy theory.
\end{Rec}


\begin{Cons}\label{cons-functor-Spbullet}
    By \cite[Proposition 10.4 and Corollary 10.6]{LNP}, there is a functor 
    \[
    \Sp_\bullet \colon \Glo{\cat F}^{\op} \to \CAlg(\PrL)
    \]
    which sends $G$ to the $\infty$-category $\Sp_G$ of genuine $G$-spectra, and a morphism $ \alpha\colon  H \to G$ to the restriction-inflation functor $\alpha^* \colon \Sp_G \to \Sp_H$.
\end{Cons}

\begin{Def}\label{def-global-spectra}
    Let $\cat F$ be a global family of compact Lie groups. We define the $\infty$-category of $\cat F$-\emph{global spectra} $\Spgl{\cat F}$ as the partially lax limit of the functor $\Sp_\bullet$ marked at $\Orb{\cat F}$, and we will write
    \[
    \Spgl{\cat F}\coloneqq \laxlimdag_{\Glo{\cat F}^{\op}, \Orb{\cat F}^{\op}} \Sp_\bullet \in \CAlg(\PrL).
    \]
    Informally, we can think of a global spectrum $X \in\Spgl{\cat F}$ as consisting of the following data: 
    \begin{itemize}
        \item a genuine $G$-spectrum $\res_G X$ for all $G \in \cat F$;
        \item compatible maps $f_\alpha \colon \alpha^* \res_GX \to \res_H X$ in $\Sp_H$ for all continuous group homomorphism $\alpha \colon H \to G$;
    \end{itemize}
    subject to the condition that $f_\alpha$ is an equivalence whenever $\alpha$ is injective. 
\end{Def}

\begin{Rem}\label{rem-agrees-schwede}
    By the main result of \cite{LNP}, this model of global spectra agrees with Schwede's model constructed via the global model structure on orthogonal spectra; also see the remark at the beginning of part II in \cite{LNP}. Therefore we are free to use and cite all the results from \cite{Schwedebook}. We also note that the category of global spectra, with respect to a global family of finite groups, admits a model in terms of spectral Mackey functors, see \cite[Theorem A]{Lenz}.
\end{Rem}

\begin{Rem}\label{rem-symm-mon}
    One of the advantages of describing global spectra as a partially lax limit is that we obtain a symmetric monoidal structure without needing to restrict attention to multiplicative global families. The discussion in \cref{rec-laxlim-sym-mon} shows that the symmetric monoidal structure on $\Spgl{\cat F}$ is such that the projection functors $\Spgl{\cat F}\to \Sp_G$ are symmetric monoidal and colimit preserving for all $G\in \cat F$. 
\end{Rem}

We next relate global spectra to the category of genuine $G$-spectra and then discuss fixed points functors in this setting. We will use this material later to show that the category of global spectra is compactly generated.

\begin{Cons}\label{cons-restrictions}
     We just noted that for any $G \in \cat F$, there is a symmetric monoidal colimit preserving functor
    \[
    \res_G \colon \Spgl{\cat F}\to \Sp_G 
    \]
    with right adjoint denoted by $R_G$.
    As limits in a partially lax limit are calculated pointwise, we deduce that $\res_G$ also preserves all limits, and that it admits a left adjoint $L_G$. We therefore have an adjoint triple
    \[
    \begin{tikzcd}[column sep=large, row sep=large]
        \Spgl{\cat F} \arrow[r,"\res_G" description] & \Sp_G, \arrow[l, yshift=2mm, "L_G"'] \arrow[l, yshift=-2mm, "R_G"]
    \end{tikzcd}
    \]
    where $L_G$ and $R_G$ are canonically oplax and lax symmetric monoidal, respectively. We warn the reader that the functors $L_G$ and $R_G$ are in general not fully faithful. However by \cite[Theorem 4.5.1]{Schwedebook} they are fully faithful if $G$ is the trivial group $1$. 
\end{Cons}

\begin{Cons}\label{cons-geometric-fixed-points}
    Recall that for any compact Lie group $G$, there is a $G$-fixed points functor $(-)^G \colon \Sp_G \to \Sp$ and a $G$-geometric fixed points functor $\Phi^G \colon \Sp_G \to \Sp$, see for instance \cite{MM} and \cite{LMSM}. The latter functor is symmetric monoidal and colimit preserving. We can construct an explicit model as follows.  We let $\mathcal{P}_G$ be the family of proper subgroups of $G$, and recall that there is an essentially unique $G$-space $E\mathcal{P}_G$ such that $(E\mathcal{P}_G)^G=\emptyset$ and $(E\mathcal{P}_G)^H$ is contractible for all $H<G$.  If we write $\widetilde{E}\mathcal{P}_G$ for the unreduced suspension of $E\mathcal{P}_G$, then we have
    \[  \Phi^G X\simeq (X \otimes \widetilde{E}\mathcal{P}_G)^G. \]
    If the group $G$ belongs to our global family $\cat F$, we can consider the composites
    \[
    \Spgl{\cat F} \xrightarrow{\res_G}\Sp_G \xrightarrow{(-)^G} \Sp \;\;\mathrm{and} \;\;\Spgl{\cat F} \xrightarrow{\res_G}\Sp_G \xrightarrow{\Phi^G} \Sp
    \] 
    which by a slight abuse of notation we still denote by $(-)^G$ and $\Phi^G$, respectively. 
\end{Cons}

\begin{Lem}\label{lem-jointly-conservative}
 The following collections of functors are jointly conservative:
  \begin{enumerate}
      \item $\{\res_G \colon \Spgl{\cat F}\to \Sp_G\}_{G \in \cat F}$;
      \item $\{(-)^G\colon \Spgl{\cat F}\to \Sp\}_{G\in \cat F}$;
      \item $\{\Phi^G\colon \Spgl{\cat F}\to \Sp\}_{G \in\cat F}$. 
  \end{enumerate}
\end{Lem}

\begin{proof}
    Part (a) is clear by the definition of partially lax limits. For part (b) assume that $(\res_G X)^G\simeq 0$ for all $G\in\cat F$; we want to show that $X \simeq 0$. By part (a) it suffices to show that $\res_G X \simeq 0$ for all $G\in \cat F$. In other words, we need to prove that $(\res_G X)^H\simeq 0$ for any $G \in \cat F$ and subgroup $i_H \colon H \leq G$.  
    To this end recall from \cref{def-global-spectra} that the global spectrum $X$ has a structure map $f_{i_H}\colon i^*_H \res_G X \xrightarrow{\sim} \res_H X$. Using this and our assumption, we see that
    \[
    (\res_G X)^H \simeq (i^*_H \res_G X)^H \xrightarrow[\sim]{(f_{i_H})^H} (\res_H X)^H \simeq 0,
    \]
    as required. The argument for (c) is similar to that of (b); the key ingredient is that for a fixed $G \in \cat F$, the family of functors $\{\Phi^H \res^G_H \colon \Sp_G \to \Sp_H \to \Sp\}_{H \leq G}$ is jointly conservative, see for instance \cite[Proposition 6.13]{MNN}.
\end{proof}

\begin{Prop}\label{prop-global-compact-generation}
    Let $\cat F$ be a global family of compact Lie groups. Then $\Spgl{\cat F}$ is compactly generated with a set of compact generators given by $\{L_G \unit \mid G \in\cat F\}$.
\end{Prop}

\begin{proof}
    The objects $L_G \unit$ are compact since $\res_G$ preserves all colimits. To show that they generate assume that $0 \simeq \Map_{\Spgl{\cat F}}(L_G \unit, X) \simeq (\res_GX)^G$ for all $G \in \cat F$; we want to show that $X \simeq 0$. This now follows from \cref{lem-jointly-conservative}(b). 
\end{proof}

\subsection{Rational global spectra}
Now we are finally ready to introduce the main category of interest for this section. 
\begin{Def}\label{def-rational-gl-sp}
    For a prime number $p$, write $\unit{\sslash}p\coloneqq\mathrm{cone}(\unit \xrightarrow{\cdot p} \unit ) \in \Spgl{\cat F}$. We define the $\infty$-category of \emph{rational} $\cat F$-\emph{global spectra} $\Spgl{\cat F}^\bbQ$ as the Verdier quotient of $\Spgl{\cat F}$ by the localizing ideal generated by 
    \[
        \{\unit{\sslash}p \mid p\; \mathrm{prime}\}\subseteq \Spgl{\cat F}.
    \]
\end{Def}

\begin{Rem}\label{rem-quotient-monoidal}
    As the $\infty$-category of rational global spectra is defined as a Verdier quotient by a localizing ideal, it follows from \cite[Proposition 2.2.1.9]{HA} that it admits a symmetric monoidal structure making the functor $L_\bbQ \colon \Spgl{\cat F}\to \Spgl{\cat F}^\bbQ$ into a symmetric monoidal functor of presentably symmetric monoidal $\infty$-categories; in particular $\Spgl{\cat F}^\bbQ \in \CAlg(\PrL)$.
\end{Rem}

Schwede in \cite[Theorem 4.5.28]{Schwedebook} defines the category of rational global spectra as the Bousfield localization of $\Spgl{\cat F}$ at the class of \emph{rational} $\cat F$-\emph{global equivalences}, namely those maps $f \colon X \to Y$ such that
\[
\pi_*^G(\res_G(f))\otimes \bbQ \colon \pi_*^G(\res_G(X))\otimes \bbQ \to \pi_*^G(\res_G(Y)) \otimes \bbQ
\]
is an equivalence for all $G \in \cat F$. The next result reconciles the two definitions.

\begin{Prop}\label{prop-Qglsp-bousfield}
    The $\infty$-category $\Spgl{\cat F}^\bbQ$ is the Bousfield localization of $\Spgl{\cat F}$ at the class of rational $\cat F$-global equivalences. In particular $X \in \Spgl{\cat F}$ belongs to $\Spgl{\cat F}^\bbQ$ if and only if $\pi_*^G(\res_G X)$ is rational for all $G \in \cat F$.
\end{Prop}

\begin{proof}
    Set $\cat{L} = \loct{\unit{\sslash}p \mid p \; \mathrm{prime}}$ so that $\Spgl{\cat F}^{\bbQ}\simeq \Spgl{\cat F}/ \cat{L}$, and write $L_\bbQ\colon \Spgl{\cat F}\to \Spgl{\cat F}^\bbQ$ for the quotient functor. Then by~\cite[Proposition 5.6]{BlumbergGepnerTabuada} the $\infty$-category $\Spgl{\cat F}^\bbQ$ is the Bousfield localization of $\Spgl{\cat F}$ at the class $S$ consisting of those maps whose cofibre lies in $\cat{L}$. 

    By definition, an object $Z$ is $S$-local if and only if $\Map_{\Spgl{\cat F}}(L,Z) \simeq 0$ for all $L \in \cat{L}$, if and only if $\iHom(\unit{\sslash}p, Z) \simeq 0$ for all $p$ prime, where $\iHom$ denotes the internal hom in $\Spgl{\cat F}$.  By applying $\iHom(-,Z)$ to the cofibre sequence $\unit\xrightarrow{p}\unit\to\unit{\sslash}p$ we see that $\iHom(\unit{\sslash}p, Z)=\text{fibre}(p \cdot 1_Z)$, and it follows that $Z$ is $S$-local if and only if every prime number $p$ acts invertibly on $\res_G Z$ for all $G \in \cat F$. This shows that $Z$ is $S$-local if and only if $\pi_*^G(\res_G Z)$ is rational for all $G\in \cat F$. Finally note that a map $f \colon X \to Y$ in $\Spgl{\cat F}$ is an $S$-local equivalence if and only if it is sent to an equivalence by $L_\bbQ$, which in turn is equivalent to $\pi_*^G(\mathrm{cone}(f))$ being torsion for all $G \in \cat F$. 
\end{proof}

\begin{Exa}\label{ex-Q-glo-sphere}
    Consider the following colimit
    \[
    \unit_\bbQ\coloneqq \colim (\unit \xrightarrow{2}\unit \xrightarrow{3}\unit \xrightarrow{4} \unit \xrightarrow{5} \unit \to \ldots) \in \Spgl{\cat F}.
    \]
     Since the functor $\pi_*^G(\res_G(-))$ commutes with filtered colimits, we see that 
     \[
     \pi_*^G(\res_G \unit_\bbQ)\cong\pi_*^G(\res_G \unit)\otimes \bbQ.
     \]
     It then follows that $\unit_\bbQ=L_\bbQ(\unit)$, the rationalization of the global sphere. Finally, we observe that $\Phi^G \unit_\bbQ \in \Sp$ is the rational sphere for all $G\in \cat F$.
\end{Exa}

\begin{Cor}\label{cor-smashing+compactly-gen}
    The rationalization functor $L_\bbQ \colon \Spgl{\cat F} \to \Spgl{\cat F}$ is a smashing localization, that is $L_\bbQ(-) \simeq \unit_\bbQ \otimes -$. In particular, the $\infty$-category $\Spgl{\cat F}^\bbQ$ is compactly generated by 
    \[
    \{L_G^\bbQ \unit \coloneqq L_\bbQ L_G \unit \mid G \in \cat F\}.
    \]
\end{Cor}
\begin{proof}
    A similar calculation as in \cref{ex-Q-glo-sphere} shows that $X \otimes \unit_\bbQ$ has rational $G$-homotopy groups for all $G \in \cat F$, and that the canonical map $X \to\unit_\bbQ \otimes X$ is a rational $\cat F$-global equivalence for all $X \in \Spgl{\cat F}$. By the universal property of Bousfield localization, we deduce that $L_\bbQ \simeq \unit_\bbQ \otimes -$. From this we deduce that the inclusion $\Spgl{\cat F}^\bbQ\subseteq \Spgl{\cat F}$ preserves all colimits, and so the left adjoint $L_\bbQ \colon \Spgl{\cat F} \to \Spgl{\cat F}^\bbQ$ preserves compact generators, giving the final claim (see \cref{prop-global-compact-generation}).
\end{proof}

\begin{Lem}\label{lem-geom-fix-rational-eq}
    Consider a map $f \colon X \to Y$ in $\Spgl{\cat F}$. Then $f$ is a rational $\cat F$-global equivalence if and only if $\Phi^G f$ is a rational equivalence for all $G \in \cat F$.
\end{Lem}

\begin{proof}
      Write $C$ for the cone of $f$, so that $f$ is a rational $\cat F$-global equivalence if and only if
      $L_\bbQ C\simeq \unit_\bbQ \otimes C \simeq 0$. Using \cref{lem-jointly-conservative}(b), this is equivalent to $\Phi^G \unit_\bbQ \otimes \Phi^G C \simeq 0$ for all $G \in \cat F$. By \cref{ex-Q-glo-sphere} that $\Phi^G \unit_\bbQ$ is the rational sphere, so $\Phi^G \unit_\bbQ \otimes \Phi^G C \simeq 0$ is equivalent to $\Phi^G C$ being rationally zero for all $G \in \cat F$.
\end{proof}


